MAIN_WEAPONS = ("rail", "ball", "vulcan")
SIDE_WEAPONS = ("missile", "drone")  # "none" is also valid for side_type

MAIN_WEAPON_NAMES = {
    "rail":   "Rail",
    "ball":   "Ball",
    "vulcan": "Vulcan",
}
SIDE_WEAPON_NAMES = {
    "none":    "(none)",
    "missile": "Heatseekers",
    "drone":   "Drone Cells",
}
