# HUD
# =============================================================================

def _panel(surf, x, y, w, h, title=None, fonts=None):
    pygame.draw.rect(surf, (22, 26, 44), (x, y, w, h))
    pygame.draw.rect(surf, (60, 80, 130), (x, y, w, h), 1)
    cap = (110, 160, 220)
    pygame.draw.rect(surf, cap, (x, y, 5, 1))
    pygame.draw.rect(surf, cap, (x + w - 5, y, 5, 1))
    pygame.draw.rect(surf, cap, (x, y + h - 1, 5, 1))
    pygame.draw.rect(surf, cap, (x + w - 5, y + h - 1, 5, 1))
    pygame.draw.rect(surf, cap, (x, y, 1, 5))
    pygame.draw.rect(surf, cap, (x + w - 1, y, 1, 5))
    pygame.draw.rect(surf, cap, (x, y + h - 5, 1, 5))
    pygame.draw.rect(surf, cap, (x + w - 1, y + h - 5, 1, 5))
    if title and fonts:
        t = fonts["tiny"].render(title, False, (160, 200, 240))
        # title chip on the top edge
        chip_w = t.get_width() + 6
        pygame.draw.rect(surf, (22, 26, 44), (x + 6, y - 1, chip_w, 2))
        surf.blit(t, (x + 9, y - 6))


def _panel_gpu(gpu, x, y, w, h, title=None, fonts=None):
    """GPU sibling of _panel (recessed bg + border + corner caps + title chip)."""
    gpu.fill_rect((x, y, w, h), (22, 26, 44))
    gpu.draw_rect((x, y, w, h), (60, 80, 130))
    cap = (110, 160, 220)
    gpu.fill_rect((x, y, 5, 1), cap)
    gpu.fill_rect((x + w - 5, y, 5, 1), cap)
    gpu.fill_rect((x, y + h - 1, 5, 1), cap)
    gpu.fill_rect((x + w - 5, y + h - 1, 5, 1), cap)
    gpu.fill_rect((x, y, 1, 5), cap)
    gpu.fill_rect((x + w - 1, y, 1, 5), cap)
    gpu.fill_rect((x, y + h - 5, 1, 5), cap)
    gpu.fill_rect((x + w - 1, y + h - 5, 1, 5), cap)
    if title and fonts:
        t = fonts["tiny"].render(title, False, (160, 200, 240))
        chip_w = t.get_width() + 6
        gpu.fill_rect((x + 6, y - 1, chip_w, 2), (22, 26, 44))
        gpu.blit(gpu.tex_for(t), pygame.Rect(x + 9, y - 6, t.get_width(), t.get_height()))


def _segbar(surf, x, y, w, h, ratio, color, segments=10):
    cell_w = max(1, (w - (segments - 1)) // segments)
    for i in range(segments):
        cell = pygame.Rect(x + i * (cell_w + 1), y, cell_w, h)
        pygame.draw.rect(surf, DARKER, cell)
        if (i + 0.5) / segments <= ratio:
            pygame.draw.rect(surf, color, cell)


# HUD geometry constants — shared between the chrome builder and the live
# per-frame overlay paths so both agree on where each panel sits.
_HUD_INNER_W = HUD_W - 12
_HUD_PAD_TOP = 12   # gap between panel top border and first content line
_HUD_LINE_H = 14    # vertical step between content lines
_HUD_MISSION_Y = 38
_HUD_STATUS_Y = 84
_HUD_LOADOUT_Y = 150
_HUD_ARMS_Y = 254
_HUD_CONTROL_Y = SCREEN_H - 92


class _HudCache:
    """Cached HUD chrome (panels + semi-static labels). Rebuilt only when
    the (level, loadout, bombs, ability) fingerprint changes. The dynamic
    numbers — time / score / credits / shield bar / ability cd bar — are
    drawn live on top each frame and never go into the cache.

    `dyn_surf` is the per-frame SRCALPHA scratch surface that the dynamic
    layout walker paints into. Allocated once and reused — pygame.Surface
    SRCALPHA allocation was costing ~0.5-1 ms/frame on the mali driver.

    `dyn_records` is a list of `_DynRecord` instances built at flatten
    time. Each record carries every spec field that doesn't depend on
    per-frame template_vars already resolved (font object, color tuple,
    anchor key, format template, alpha, shadow flag, etc.) so the per-
    frame draw skips dict-lookup + type-cast work. The records also
    carry the parent container id so a runtime animation offset on
    `container_offsets` is applied correctly per frame — see comments
    on `container_offsets` below."""
    surface = None
    key = None
    dyn_surf = None
    dyn_records = None
    dyn_records_rev = None
    # Runtime container offsets — keyed by container id, value is (dx, dy).
    # Animation code (anything that wants to shake / slide a panel) can set
    # _HudCache.container_offsets["status_panel"] = (3, 0) and every
    # dynamic item inside that container will draw at the offset position
    # this frame. Unanimated containers stay out of the dict (zero cost).
    # The chrome cache surface does NOT animate — for whole-panel slides
    # the caller should also offset the chrome blit or invalidate the
    # cache; the records system only handles the dynamic items overlay.
    container_offsets = {}


def _hud_cache_key(player, level_name, save=None):
    lo = player.loadout
    side_lvl = lo.side_level() if lo.side_type != "none" else 0
    # Include the per-category unlocked-tier state so the HUD bars rebuild
    # when boss kills change the visible-tier count. Tier state changes
    # only between levels, so the cache still invalidates rarely.
    if save is not None:
        unlocks = (save.unlocked_tier_rail, save.unlocked_tier_ball,
                   save.unlocked_tier_vulcan, save.unlocked_tier_missile,
                   save.unlocked_tier_drone, save.unlocked_tier_shield,
                   save.unlocked_tier_engine)
        rewind_unlocked = bool(getattr(save, "rewind_unlocked", False))
    else:
        unlocks = (5, 5, 5, 5, 5, 5, 5)
        rewind_unlocked = False
    # `rewind_unlocked` flips mid-session the first time the player
    # rewinds — the bomb-row control hint reappears at that moment
    # with label "rewind", so the chrome surface must rebake.
    # _HINT_DEVICE: the control-panel glyphs are device-aware ({btn_*}),
    # so a pad<->keyboard switch must rebake the chrome surface.
    return (level_name, lo.main_type, lo.main_level(),
            lo.side_type, side_lvl, lo.shield, lo.engine,
            lo.bombs, lo.ability, unlocks, rewind_unlocked,
            _HINT_DEVICE, _LAYOUT_REV)


def _hud_panel(id_, x, y, w, h, *, title="", children=()):
    """One HUD chrome panel as a container spec. panel_skin=1 gives the
    bordered look (bg/border/caps/title chip) for free — any of those
    can still be overridden by setting the field explicitly here."""
    return {
        "id": id_, "type": "container",
        "x": x, "y": y, "w": w, "h": h,
        "layout": "free", "padding": 0,
        "panel_skin": 1,
        "title": title,
        "children": list(children),
    }


def _hud_lvl_bar_x_y_w(panel_inner_w, inset=0):
    """Geometry helper for the loadout level pips — keeps the lambdas in
    the spec compact."""
    return 8 + inset, 6 - 1, panel_inner_w - 16 - inset


def _build_shop_panel_spec():
    """Right-side strip on the shop screen — header / balance / DETAIL
    / control. DETAIL replaces the bottom-of-playfield UPGRADE DETAIL
    strip with a tall vertical version, fed by `_side_strip_vars` from
    `_detail_pieces`. DETAIL absorbs the leftover vertical space so
    there's no dead air between it and the CONTROL panel."""
    INNER = HUD_W - 12   # 148
    HEADER_H = 26
    GAP = 8
    TOP = 6
    CONTROL_H = 92
    BALANCE_H = 54

    header_panel = {
        "id": "shop_header_panel", "type": "container",
        "x": 6, "y": TOP, "w": INNER, "h": HEADER_H,
        "layout": "free", "padding": 0,
        "panel_skin": 1,
        "children": [
            {"id": "shop_header_title", "type": "text",
             "x": INNER // 2, "y": 13, "anchor": "c",
             "text": "SHOP", "font": 2, "color": [80, 220, 255]},
        ],
    }
    bal_y = TOP + HEADER_H + GAP
    balance_panel = {
        "id": "shop_balance_panel", "type": "container",
        "x": 6, "y": bal_y, "w": INNER, "h": BALANCE_H,
        "layout": "free", "padding": 0,
        "panel_skin": 1, "title": "BALANCE",
        "children": [
            {"id": "shop_balance_value", "type": "text",
             "x": INNER // 2, "y": BALANCE_H // 2, "anchor": "c",
             "text": "${credits}", "font": 3,
             "color": [255, 220, 80], "dynamic": True},
        ],
    }
    # DETAIL panel — grows to fill the remaining strip height between
    # BALANCE and CONTROL. Cursored row's name + current → next
    # breakdown + cost, all formatted into template vars by the
    # _side_strip_vars helper.
    detail_y = bal_y + BALANCE_H + GAP
    chy = SCREEN_H - CONTROL_H
    detail_h = chy - GAP - detail_y
    detail_panel = {
        "id": "shop_detail_panel", "type": "container",
        "x": 6, "y": detail_y, "w": INNER, "h": detail_h,
        "layout": "free", "padding": 0,
        "panel_skin": 1, "title": "DETAIL",
        "children": [
            # Item name (yellow accent, small font — wraps in narrow
            # column ok; user can rename in the layout editor if needed).
            {"id": "shop_detail_name", "type": "text",
             "x": 8, "y": 12, "anchor": "tl",
             "text": "{detail_name}", "font": 2,
             "color": [255, 220, 80], "dynamic": True},
            # Current level / cap.
            {"id": "shop_detail_cur", "type": "text",
             "x": 8, "y": 30, "anchor": "tl",
             "text": "{detail_cur}", "font": 1,
             "color": [240, 240, 240], "dynamic": True},
            # NOW / NEXT stat table — two columns, no separators. The NOW
            # column (header + values) is left-aligned; the NEXT column is
            # right-aligned to the panel's inner edge. Each row carries its
            # metric name inside the NOW cell ("DMG 120" / "CD 1.00s") so the
            # rows are self-labelling without a third column.
            {"id": "shop_detail_tbl_now", "type": "text",
             "x": 8, "y": 52, "anchor": "tl",
             "text": "NOW", "font": 1, "color": [110, 130, 170]},
            {"id": "shop_detail_tbl_next", "type": "text",
             "x": INNER - 14, "y": 52, "anchor": "tr",
             "text": "NEXT", "font": 1, "color": [130, 200, 255]},
            # Damage row.
            {"id": "shop_detail_dmg_now", "type": "text",
             "x": 8, "y": 66, "anchor": "tl",
             "text": "{detail_now_dmg}", "font": 1,
             "color": [240, 240, 240], "dynamic": True},
            {"id": "shop_detail_dmg_next", "type": "text",
             "x": INNER - 14, "y": 66, "anchor": "tr",
             "text": "{detail_next_dmg}", "font": 1,
             "color": [240, 240, 240], "dynamic": True},
            # Cooldown row.
            {"id": "shop_detail_cd_now", "type": "text",
             "x": 8, "y": 80, "anchor": "tl",
             "text": "{detail_now_cd}", "font": 1,
             "color": [240, 240, 240], "dynamic": True},
            {"id": "shop_detail_cd_next", "type": "text",
             "x": INNER - 14, "y": 80, "anchor": "tr",
             "text": "{detail_next_cd}", "font": 1,
             "color": [240, 240, 240], "dynamic": True},
            # COST section.
            {"id": "shop_detail_cost_hdr", "type": "text",
             "x": 8, "y": 132, "anchor": "tl",
             "text": "COST", "font": 1, "color": [110, 130, 170]},
            # Cost colour stays static — `_layout_draw_text` doesn't
            # resolve template-var colours like tiered_bar does, and
            # the cost STRING already carries "MAX" / "LOCKED" /
            # dollar amount, which is the load-bearing signal.
            {"id": "shop_detail_cost", "type": "text",
             "x": 8, "y": 144, "anchor": "tl",
             "text": "{detail_cost_str}", "font": 3,
             "color": [255, 140, 40], "dynamic": True},
        ],
    }
    control_panel = {
        "id": "shop_control_panel", "type": "container",
        "x": 6, "y": chy, "w": INNER, "h": 92,
        "layout": "free", "padding": 0,
        "panel_skin": 1, "title": "CONTROL",
        # Three face-button hints, context-driven by the cursored row:
        #   fire (South)  = "{shop_go}"   → "buy" on an upgrade, "map" on the
        #                                    CONTINUE entry.
        #   cancel (North)= "{shop_down}" → "hold: downgrade" on an upgrade,
        #                                    blank on CONTINUE.
        #   bomb (East)   = "title" (back).
        # Listed south → north → east. {shop_go}/{shop_down} come from
        # _side_strip_vars (cursor-aware).
        "children": [
            {"id": "shop_ctrl_fire", "type": "btn_icon", "action": "fire",
             "x": 8, "y": 16, "anchor": "tl",
             "h": 13},
            {"id": "shop_ctrl_fire_label", "type": "text",
             "x": 40, "y": 16, "anchor": "tl",
             "text": "{shop_go}", "font": 2, "color": [140, 140, 160]},
            {"id": "shop_ctrl_cancel", "type": "btn_icon", "action": "cancel",
             "x": 8, "y": 40, "anchor": "tl",
             "h": 13},
            {"id": "shop_ctrl_cancel_label", "type": "text",
             "x": 40, "y": 42, "anchor": "tl",
             "text": "{shop_down}", "font": 2, "color": [140, 140, 160]},
            {"id": "shop_ctrl_bomb", "type": "btn_icon", "action": "bomb",
             "x": 8, "y": 64, "anchor": "tl",
             "h": 13},
            {"id": "shop_ctrl_bomb_label", "type": "text",
             "x": 40, "y": 64, "anchor": "tl",
             "text": "title", "font": 2, "color": [140, 140, 160]},
        ],
    }

    return {
        "id": "shop_root", "type": "container",
        "x": HUD_X, "y": 0, "w": HUD_W, "h": SCREEN_H,
        "layout": "free", "padding": 0,
        "panel_skin": 0,   # plain strip — no auto panel chrome
        "bg": [15, 18, 32],   # HUD_BG fills the strip
        "_label": "Shop side panel (right strip)",
        "children": [
            {"id": "shop_left_line", "type": "rect",
             "x": 0, "y": 0, "w": 1, "h": SCREEN_H,
             "color": [40, 48, 80], "alpha": 255},
            header_panel, balance_panel, detail_panel, control_panel,
        ],
    }


def _build_map_panel_spec():
    """Right-side strip on the map screen — header, STATUS readout,
    LOADOUT summary, CONTROL hints. Dynamic: credits, high_score,
    progress_n / ratio, main_name / main_lvl, shield_lvl."""
    INNER = HUD_W - 12

    header_panel = {
        "id": "map_header_panel", "type": "container",
        "x": 6, "y": 6, "w": INNER, "h": 26,
        "layout": "free", "padding": 0,
        "panel_skin": 1,
        "children": [
            {"id": "map_header_title", "type": "text",
             "x": INNER // 2, "y": 13, "anchor": "c",
             "text": "MAP", "font": 2, "color": [80, 220, 255]},
        ],
    }
    # LEVEL panel — live details for the cursored map node (was a West
    # overlay; now always shown here). Balance / loadout that used to sit
    # on the map are shop-only now.
    DET_Y = 40
    DET_H = (SCREEN_H - 98) - 8 - DET_Y
    # (label, value-template, value-color). Colour can be a "{var}" that
    # _side_strip_vars fills (status / boss / replay are colour-coded).
    _VW = [220, 230, 240]
    _det_rows = [
        ("LEVEL", "{detail_level}", _VW),
        ("STATUS", "{detail_status}", "{detail_status_color}"),
        ("BOSS", "{detail_boss}", "{detail_boss_color}"),
        ("DIFF", "{detail_diff}", _VW),
        ("WAVES", "{detail_waves}", _VW),
        ("WINS", "{detail_wins}", _VW),
        ("FAILS", "{detail_fails}", _VW),
        ("REPLAY", "{detail_replay}", "{detail_replay_color}"),
    ]
    det_children = []
    _yy = 14
    for _lbl, _val, _col in _det_rows:
        _k = _lbl.lower()
        det_children.append({"id": f"map_det_{_k}_l", "type": "text",
                             "x": 8, "y": _yy, "anchor": "tl", "text": _lbl,
                             "font": 1, "color": [150, 170, 200]})
        det_children.append({"id": f"map_det_{_k}_v", "type": "text",
                             "x": 60, "y": _yy, "anchor": "tl", "text": _val,
                             "font": 1, "color": _col, "dynamic": True})
        _yy += 17
    status_panel = {
        "id": "map_details_panel", "type": "container",
        "x": 6, "y": DET_Y, "w": INNER, "h": DET_H,
        "layout": "free", "padding": 0,
        "panel_skin": 1, "title": "LEVEL",
        "children": det_children,
    }
    # Mirror the shop CONTROL strip dimensions + layout one-to-one:
    # same chy / height / inner padding / label column. Rows in
    # face-position order south → west → north → east so the column
    # reads PC: A X Y B, RG: B Y X A.
    chy = SCREEN_H - 98
    control_panel = {
        "id": "map_control_panel", "type": "container",
        "x": 6, "y": chy, "w": INNER, "h": 92,
        "layout": "free", "padding": 0,
        "panel_skin": 1, "title": "CONTROL",
        "children": [
            {"id": "map_ctrl_fire", "type": "btn_icon", "action": "fire",
             "x": 8, "y": 14, "anchor": "tl",
             "h": 13},
            {"id": "map_ctrl_fire_label", "type": "text",
             "x": 40, "y": 14, "anchor": "tl",
             "text": "play", "font": 2, "color": "{map_play_color}",
             "dynamic": True},
            {"id": "map_ctrl_ability", "type": "btn_icon", "action": "ability",
             "x": 8, "y": 32, "anchor": "tl",
             "h": 13},
            {"id": "map_ctrl_ability_label", "type": "text",
             "x": 40, "y": 32, "anchor": "tl",
             "text": "replay", "font": 2, "color": "{map_replay_color}",
             "dynamic": True},
            {"id": "map_ctrl_bomb", "type": "btn_icon", "action": "bomb",
             "x": 8, "y": 50, "anchor": "tl",
             "h": 13},
            {"id": "map_ctrl_bomb_label", "type": "text",
             "x": 40, "y": 50, "anchor": "tl",
             "text": "shop", "font": 2, "color": [140, 140, 160]},
        ],
    }

    return {
        "id": "map_root", "type": "container",
        "x": HUD_X, "y": 0, "w": HUD_W, "h": SCREEN_H,
        "layout": "free", "padding": 0,
        "panel_skin": 0,
        "bg": [15, 18, 32],
        "_label": "Map side panel (right strip)",
        "children": [
            {"id": "map_strip_line", "type": "rect",
             "x": 0, "y": 0, "w": 1, "h": SCREEN_H,
             "color": [40, 48, 80], "alpha": 255},
            header_panel, status_panel, control_panel,
        ],
    }


def _build_play_banner_spec():
    """Centre-of-playfield banner used for PAUSED / MISSION COMPLETE /
    SHIP DESTROYED. One container gated by `banner_visible`; the title
    + subtitle text is template-driven (`{banner_title}` /
    `{banner_subtitle}`) so the same spec covers all three states."""
    cy = PLAY_H // 2
    return {
        "id": "play_banner", "type": "container",
        "x": 0, "y": cy - 40, "w": PLAY_W, "h": 80,
        "layout": "free", "padding": 0,
        "panel_skin": 0,
        "bg": [0, 0, 0], "alpha": 160,
        "visible_when": "banner_visible",
        "_label": "centre-screen banner (pause / win / loss)",
        "children": [
            {"id": "play_banner_title", "type": "text",
             "x": PLAY_W // 2, "y": 30, "anchor": "c",
             "text": "{banner_title}", "font": 3,
             "color": [240, 240, 240], "dynamic": True},
            {"id": "play_banner_subtitle", "type": "text",
             "x": PLAY_W // 2, "y": 60, "anchor": "c",
             "text": "{banner_subtitle}", "font": 2,
             "color": [140, 140, 160], "dynamic": True},
        ],
    }


def _build_hud_layout_spec():
    """Programmatic build of the HUD layout tree. Returned as a single
    `hud_root` container containing the six chrome panels (header,
    mission, status, loadout, arms, control) plus per-frame dynamic items
    flagged `dynamic: True`. Everything position / color / text is data-
    driven from here so the layout editor exposes it for direct editing."""
    INNER = _HUD_INNER_W
    PAD = _HUD_PAD_TOP
    LH = _HUD_LINE_H

    header_panel = _hud_panel("header_panel", 6, 6, INNER, 26, children=[
        {"id": "header_title", "type": "text",
         "x": INNER // 2, "y": 13, "anchor": "c",
         "text": "PEWPEW", "font": 2, "color": [80, 220, 255]},
    ])

    mission_panel = _hud_panel("mission_panel", 6, 38, INNER, 38,
                                title="MISSION", children=[
        {"id": "mission_label", "type": "text",
         "x": 8, "y": PAD, "anchor": "tl",
         "text": "{level_short}", "font": 1, "color": [240, 240, 240]},
        {"id": "mission_timer", "type": "text",
         "x": 8, "y": PAD + LH, "anchor": "tl",
         "text": "T {time}s", "font": 1, "color": [140, 140, 160],
         "dynamic": True},
    ])

    # Shield row dropped — shield HP pool is bypassed (one-hit kill
    # in Player.take_damage). Only the credits readout remains.
    status_panel = _hud_panel("status_panel", 6, 84, INNER, 40,
                               title="STATUS", children=[
        {"id": "status_credits", "type": "text",
         "x": 8, "y": PAD, "anchor": "tl",
         "text": "$ {credits}", "font": 1, "color": [255, 220, 80],
         "dynamic": True},
    ])

    # Loadout panel: labels + level-pip bars. Color of the pip bars goes
    # GREEN at max (template_vars carries the resolved color list per row).
    # Side + shield rows are hidden via
    # _HUD_HIDDEN so the panel reads main + engine only.
    loadout_panel = _hud_panel("loadout_panel", 6, 150, INNER, 96,
                                title="LOADOUT", children=[
        {"id": "loadout_main_name", "type": "text",
         "x": 8, "y": PAD, "anchor": "tl",
         "text": "{main_name}", "font": 1, "color": [80, 220, 255]},
        {"id": "loadout_main_bar", "type": "tiered_bar",
         "x": 8, "y": PAD + LH + 1, "h": 8,
         "value": "{main_lvl}", "max": "{main_visible_max}",
         "tiers": "{main_visible_tiers}", "cell_px_w": 24,
         "color": "{main_lvl_color}", "bg_color": [60, 64, 88]},
        # Engine row — the only support upgrade with gameplay
        # effect. Side / shield / bomb / ability rows were dropped
        # along with their mechanics (one-hit kill + rewind ruleset).
        {"id": "loadout_engn_label", "type": "text",
         "x": 8, "y": PAD + LH * 2 + 2, "anchor": "tl",
         "text": "ENGN", "font": 1, "color": [140, 140, 160]},
        {"id": "loadout_engn_bar", "type": "tiered_bar",
         "x": 40, "y": PAD + LH * 2 + 3, "h": 8,
         "value": "{engine_lvl}", "max": "{engine_visible_max}",
         "tiers": "{engine_visible_tiers}", "cell_px_w": 18,
         "color": "{engine_lvl_color}", "bg_color": [60, 64, 88]},
    ])

    # ARMS panel (bomb count + ability + cooldown) dropped — none of
    # those mechanics exist anymore. Its 54px slot is reclaimed; the
    # control_panel below moves up to fill the space.

    # Control hints — fully static.
    control_panel = _hud_panel("control_panel", 6, SCREEN_H - 92, INNER, 86,
                                title="CONTROL", children=[
        {"id": "ctrl_dpad_label", "type": "text",
         "x": 32, "y": PAD, "anchor": "tl",
         "text": "move",    "font": 1, "color": [140, 140, 160]},
        # D-pad icon as a separate child (rendered via {dpad} placeholder
        # in a text item — re-uses the title-screen tip pattern).
        {"id": "ctrl_dpad_icon", "type": "text",
         "x": 8, "y": PAD - 1, "anchor": "tl",
         "text": "{dpad}", "font": 1, "color": [80, 220, 255]},
        {"id": "ctrl_b", "type": "btn_icon", "action": "fire",
         "x": 8, "y": PAD + LH, "anchor": "tl",
         "h": 13},
        {"id": "ctrl_b_label", "type": "text",
         "x": 32, "y": PAD + LH, "anchor": "tl",
         "text": "fire", "font": 1, "color": [140, 140, 160]},
        # ctrl_a = the REWIND row (East button); unlock-gated via _HUD_HIDDEN.
        {"id": "ctrl_a", "type": "btn_icon", "action": "bomb",
         "x": 8, "y": PAD + LH * 2, "anchor": "tl",
         "h": 13},
        {"id": "ctrl_a_label", "type": "text",
         "x": 32, "y": PAD + LH * 2, "anchor": "tl",
         "text": "{ctrl_a_label}", "font": 1, "color": [140, 140, 160]},
        {"id": "ctrl_x", "type": "btn_icon", "action": "ability",
         "x": 8, "y": PAD + LH * 3, "anchor": "tl",
         "h": 13},
        {"id": "ctrl_x_label", "type": "text",
         "x": 32, "y": PAD + LH * 3, "anchor": "tl",
         "text": "ability", "font": 1, "color": [140, 140, 160]},
        {"id": "ctrl_st", "type": "text",
         "x": 8, "y": PAD + LH * 4, "anchor": "tl",
         "text": "ST", "font": 1, "color": [80, 220, 255]},
        {"id": "ctrl_st_label", "type": "text",
         "x": 32, "y": PAD + LH * 4, "anchor": "tl",
         "text": "pause", "font": 1, "color": [140, 140, 160]},
    ])

    return [{
        "id": "hud_root", "type": "container",
        "x": 0, "y": 0, "w": HUD_W, "h": SCREEN_H,
        "layout": "free", "padding": 0,
        # panel_skin=0 = no automatic chrome (no border / caps / title);
        # the explicit bg below still paints the strip black.
        "panel_skin": 0,
        "bg": [15, 18, 32],  # HUD_BG
        "_label": "HUD root container (positioned at HUD_X internally)",
        "children": [
            {"id": "hud_left_line", "type": "rect",
             "x": 0, "y": 0, "w": 1, "h": SCREEN_H,
             "color": [40, 48, 80], "alpha": 255},
            header_panel, mission_panel, status_panel,
            loadout_panel, control_panel,
        ],
    }]


def _hud_chrome_vars(level_name, lo, save=None):
    """Vars referenced by non-dynamic HUD items (cached chrome). Resolved
    at chrome-bake time — when these change, the chrome cache fingerprint
    invalidates and the chrome surface gets re-rendered.

    When `save` is provided, the visible-tier counts for each weapon are
    included so HUD/map bars can shrink/grow with boss-gated unlocks
    instead of always showing all 5 tiers."""
    parts = level_name.split()
    slot = parts[-1] if parts and "/" in parts[-1] else ""
    short = parts[0].upper() if parts else ""
    if slot:
        short = f"{short} {slot}"
    main_lvl = lo.main_level()
    side_lvl = lo.side_level() if lo.side_type != "none" else 0
    g = list(GREEN); w_ = list(WHITE)
    # Visible tiers per upgrade — defaults to fully-unlocked (5) if save
    # isn't supplied (keeps backward compat for callers that don't pass it).
    if save is not None:
        mtier = getattr(save, f"unlocked_tier_{lo.main_type}", 5)
        stier = (getattr(save, f"unlocked_tier_{lo.side_type}", 5)
                 if lo.side_type != "none" else 0)
        shtier = getattr(save, "unlocked_tier_shield", 5)
        entier = getattr(save, "unlocked_tier_engine", 5)
    else:
        mtier = 5; stier = 5; shtier = 5; entier = 5
    # Main weapon: 4 sub-levels per tier. Others: 1.
    main_visible_max = mtier * 4
    side_visible_max = stier * 1
    return {
        "level_short": short,
        "main_name": MAIN_WEAPON_NAMES[lo.main_type].upper(),
        "main_lvl": main_lvl, "main_max": MAIN_WEAPON_MAX,
        "main_visible_tiers": mtier, "main_visible_max": main_visible_max,
        "main_lvl_color": g if main_lvl >= MAIN_WEAPON_MAX else w_,
        "side_name": SIDE_WEAPON_NAMES[lo.side_type].upper(),
        "side_lvl": side_lvl, "side_max": SIDE_WEAPON_MAX,
        "side_visible_tiers": stier, "side_visible_max": side_visible_max,
        "side_lvl_color": g if side_lvl >= SIDE_WEAPON_MAX else w_,
        "side_visible": lo.side_type != "none",
        "shield_lvl": lo.shield, "shield_max": MAX_LEVELS["shield"],
        "shield_visible_tiers": shtier, "shield_visible_max": shtier,
        "shield_lvl_color": g if lo.shield >= MAX_LEVELS["shield"] else w_,
        "engine_lvl": lo.engine, "engine_max": MAX_LEVELS["engine"],
        "engine_visible_tiers": entier, "engine_visible_max": entier,
        "engine_lvl_color": g if lo.engine >= MAX_LEVELS["engine"] else w_,
        "bombs": lo.bombs,
        "ability_name": ABILITY_NAMES.get(lo.ability, "?").upper(),
        # Text-only {btn_start}/{btn_select}. The four FACE tokens
        # ({btn_fire} etc.) are NOT here — they survive to the renderer and
        # draw as inline position glyphs (see _draw_text_with_icons).
        **button_label_vars(),
        # Bomb-button row labels its action as
        # "rewind" once the player has unlocked the ability; before
        # that the row is hidden entirely (see
        # _hud_item_hidden). "bomb" fallback never reaches the screen.
        "ctrl_a_label": ("rewind"
                         if (save is not None
                             and getattr(save, "rewind_unlocked", False))
                         else "bomb"),
    }


def _side_strip_vars(app, shop_screen=None, map_screen=None):
    """Template vars for the map + shop right-side strip.

    Map sidebar reads everything in the dict (STATUS chip + the
    LOADOUT panel's per-weapon bars / side row / shield + engine /
    ability + bombs). Shop sidebar uses a subset — `credits` + the
    `detail_*` keys (cursored row name + cur → next breakdown + cost).
    Passing `shop_screen` makes the helper call the screen's
    `_detail_pieces` so we don't duplicate the cur/next formatting.

    Per-weapon main colour is full-saturation when the weapon is the
    currently-active main (`loadout.main_type`), dimmed × 3/5 when
    it's not — gives the active row visual weight without an extra
    glyph cluttering the column.
    """
    save = app.save
    lo = save.loadout
    progress_n = sum(1 for k in save.completed if k.startswith("L"))
    out = {
        "credits": save.credits,
        "high_score": save.high_score,
        "progress_n": progress_n,
        "progress_ratio": progress_n / 100.0,
        # Control-hint label colours. A hint reads at full strength when its
        # action is usable and dims when it isn't (the button icon itself
        # never changes). Defaults assume usable; the map branch dims them.
        "map_play_color": list(_CTRL_HINT_ON),
        "map_replay_color": list(_CTRL_HINT_ON),
        **button_label_vars(),
    }
    # Map LEVEL panel — live details for the cursored node (replaces the
    # old West-triggered overlay). Distinct detail_* keys from the shop's.
    if map_screen is not None:
        cur = getattr(map_screen, "cursor", None)
        level = app.levels.get(cur) if cur else None
        if level is not None:
            stats = (getattr(save, "level_stats", None) or {}).get(cur, {})
            wins = int(stats.get("wins", 0))
            fails = int(stats.get("fails", 0))
            mc = float(stats.get("max_clear", 0.0))
            has_boss = bool(getattr(level, "has_boss", False))
            try:
                _ln = int(str(cur)[1:])
                _sec = (_ln - 1) // 10 + 1
                _slot = (_ln - 1) % 10 + 1
                out["detail_level"] = (f"{_sec}.BOSS" if has_boss
                                       else f"{_sec}.{_slot}")
            except Exception:
                out["detail_level"] = str(cur)
            out["detail_boss"] = "yes" if has_boss else "no"
            out["detail_boss_color"] = [255, 90, 90] if has_boss else [220, 230, 240]
            out["detail_diff"] = f"x{getattr(level, 'difficulty', 1.0):.2f}"
            out["detail_waves"] = str(len(getattr(level, "timeline", []) or []))
            out["detail_wins"] = str(wins)
            out["detail_fails"] = str(fails)
            if cur in save.completed:
                out["detail_status"], out["detail_status_color"] = "CLEARED", [90, 230, 120]
            elif cur in save.unlocked:
                out["detail_status"], out["detail_status_color"] = "READY", [80, 220, 255]
            else:
                out["detail_status"], out["detail_status_color"] = "LOCKED", [140, 140, 160]
            _has_rep = has_saved_replay(cur, app.profile_name)
            out["detail_replay"] = "saved" if _has_rep else "-"
            out["detail_replay_color"] = [120, 230, 150] if _has_rep else [140, 140, 160]
            # CONTROL hints dim when their action can't fire for this node:
            # PLAY needs the level unlocked, REPLAY needs a saved recording.
            out["map_play_color"] = list(
                _CTRL_HINT_ON if cur in save.unlocked else _CTRL_HINT_OFF)
            out["map_replay_color"] = list(
                _CTRL_HINT_ON if _has_rep else _CTRL_HINT_OFF)
    # Per-main-weapon level / visible-tier breakdown + name colour.
    for wt in ("rail", "vulcan", "ball"):
        lvl = getattr(lo, f"main_{wt}")
        vt = getattr(save, f"unlocked_tier_{wt}", 5)
        out[f"main_{wt}_lvl"] = lvl
        out[f"main_{wt}_visible_tiers"] = vt
        out[f"main_{wt}_visible_max"] = vt * 4
        base = SHOP_MAIN_NAME_COLOR[wt]
        if lo.main_type == wt:
            out[f"main_{wt}_color"] = list(base)
        else:
            out[f"main_{wt}_color"] = [c * 3 // 5 for c in base]
    # Side weapon row.
    if lo.side_type == "none":
        out["side_name"] = "—"
        out["side_lvl"] = 0
        out["side_visible_tiers"] = 5
        out["side_visible_max"] = 5
    else:
        out["side_name"] = lo.side_type
        out["side_lvl"] = getattr(lo, f"side_{lo.side_type}")
        st = getattr(save, f"unlocked_tier_{lo.side_type}", 5)
        out["side_visible_tiers"] = st
        out["side_visible_max"] = st
    # Shield + engine bars.
    out["shield_lvl"] = lo.shield
    out["shield_max"] = MAX_LEVELS["shield"]
    out["shield_visible_tiers"] = getattr(save, "unlocked_tier_shield", 5)
    out["shield_visible_max"] = out["shield_visible_tiers"]
    out["engine_lvl"] = lo.engine
    out["engine_max"] = MAX_LEVELS["engine"]
    out["engine_visible_tiers"] = getattr(save, "unlocked_tier_engine", 5)
    out["engine_visible_max"] = out["engine_visible_tiers"]
    # Arsenal.
    out["ability_name"] = ABILITY_NAMES.get(lo.ability, lo.ability)
    out["bombs_str"] = (f"x{lo.bombs} MAX" if lo.bombs >= BOMB_MAX
                        else f"x{lo.bombs}")
    # Shop DETAIL fields — only populated when the helper is called
    # from the shop side (it has cursor context). The cursor can also land on
    # the CONTINUE entry (index == len(items)); there the South hint becomes
    # "map" and the downgrade hint blanks, and DETAIL shows a leave prompt.
    if shop_screen is not None:
        on_continue = shop_screen.cursor >= len(shop_screen.items)
        out["shop_go"] = "map" if on_continue else "buy"
        out["shop_down"] = "" if on_continue else "SELL"
        if on_continue:
            out["detail_name"] = "CONTINUE"
            out["detail_cur"] = ""
            out["detail_cur_effect"] = "Launch to the map."
            out["detail_next_effect"] = ""
            out["detail_now_dmg"] = ""
            out["detail_next_dmg"] = ""
            out["detail_now_cd"] = ""
            out["detail_next_cd"] = ""
            out["detail_cost_str"] = ""
            out["detail_cost_color"] = list(WHITE)
        else:
            try:
                key = shop_screen.items[shop_screen.cursor][0]
                label = shop_screen.items[shop_screen.cursor][1]
                cost = shop_screen._item_cost(key)
                cur_str, cur_eff, next_eff, cost_str, cost_col = (
                    shop_screen._detail_pieces(key, cost))
                now_dmg, next_dmg, now_cd, next_cd = (
                    shop_screen._detail_stats(key))
            except Exception:
                label = ""
                cur_str = cur_eff = next_eff = cost_str = ""
                now_dmg = next_dmg = now_cd = next_cd = ""
                cost_col = WHITE
            out["detail_now_dmg"] = now_dmg
            out["detail_next_dmg"] = next_dmg
            out["detail_now_cd"] = now_cd
            out["detail_next_cd"] = next_cd
            # `_detail_pieces` formats f"${cost}" even when cost is
            # None (locked-tier row) — surface that as "LOCKED" so the
            # sidebar doesn't read "Cost $None".
            if "$None" in cost_str:
                cost_str = "LOCKED"
            out["detail_name"] = label.upper()
            out["detail_cur"] = cur_str
            out["detail_cur_effect"] = cur_eff
            out["detail_next_effect"] = next_eff
            out["detail_cost_str"] = cost_str
            out["detail_cost_color"] = list(cost_col)
    return out


# Side-strip entry animation. Panels stream in from the right of the
# screen, staggered top-to-bottom; inside each panel the child rows do
# the same with a tighter slide. Each panel renders through an off-
# screen SRCALPHA surface so the whole-panel alpha fade is uniform
# regardless of which element types it contains.
#
# Two motion profiles live side-by-side so we can A/B them on the
# device (currently MAP uses "bouncy", SHOP uses "slow"):
#
#   slow   — v0.9.45 shape: full-strip slide, cubic ease, no bounce,
#            position + alpha progress identically. Inner rows just
#            slide (panel alpha covers their visibility).
#   bouncy — v0.9.47 shape: short slide, alpha leads position, position
#            uses ease-out-back (~10% overshoot then settles). Inner
#            rows also fade per-row (via scratch sub-surface so
#            tiered_bar respects alpha).
_SIDE_STRIP_BACK_OVERSHOOT = 1.0

_SIDE_STRIP_PROFILES = {
    "slow": {
        "panel_dur": 0.40,
        "panel_stagger": 0.08,
        "inner_dur": 0.32,
        "inner_stagger": 0.025,
        "bg_fade": 0.50,
        # None → use root width (HUD_W) so panel comes from full off-screen.
        "panel_slide_px": None,
        "inner_slide_px": 36,
        "alpha_lead": 1.0,        # alpha tracks position, no lead
        "pos_ease": "cubic",
        "alpha_ease": "cubic",
        "per_row_alpha": False,   # whole-panel alpha only
    },
    "bouncy": {
        "panel_dur": 0.40,
        "panel_stagger": 0.03,
        "inner_dur": 0.20,
        "inner_stagger": 0.01,
        "bg_fade": 0.20,
        "panel_slide_px": 120,
        "inner_slide_px": 22,
        "alpha_lead": 0.80,       # alpha hits 1.0 at 80% of duration
        "pos_ease": "back",
        "alpha_ease": "quad",
        "per_row_alpha": True,    # rows fade individually
    },
    # In-game HUD variant. Same shape as "bouncy" but timed so the
    # whole sequence settles precisely when the takeoff cinematic
    # ends. Math (PlayState.life_t timebase, 6 panels):
    #   life_t = 0.0  — player just left the map
    #   [0.0, 0.5)    — strip bg lerps black → HUD_BG (`_HUD_ANIM_DELAY`)
    #   life_t = 0.5  — panel 0 (header) starts arriving
    #   panel i starts at 0.5 + i * panel_stagger
    #   panel i settles (chrome) at 0.5 + i * 0.30 + 0.40
    #   panel 5 settles at 0.5 + 1.50 + 0.40 = 2.40
    #   life_t = 2.40 — player gains control (`self.intro_t` hits 0).
    "hud": {
        "panel_dur": 0.40,
        "panel_stagger": 0.30,
        "inner_dur": 0.20,
        "inner_stagger": 0.01,
        "bg_fade": 0.20,
        "panel_slide_px": 120,
        "inner_slide_px": 22,
        "alpha_lead": 0.35,
        "pos_ease": "back",
        "alpha_ease": "quad",
        "per_row_alpha": True,
    },
}


def _ease_out_cubic(x):
    x = 0.0 if x < 0.0 else (1.0 if x > 1.0 else x)
    return 1.0 - (1.0 - x) ** 3


def _ease_out_quad(x):
    x = 0.0 if x < 0.0 else (1.0 if x > 1.0 else x)
    return 1.0 - (1.0 - x) * (1.0 - x)


def _ease_out_back(x, overshoot=_SIDE_STRIP_BACK_OVERSHOOT):
    """ease-out-back: settles past 1.0 and bounces back. At t=1 returns
    exactly 1.0; peak near t≈0.75 sits at ~1 + overshoot * 0.15."""
    x = 0.0 if x < 0.0 else (1.0 if x > 1.0 else x)
    c1 = overshoot
    c3 = c1 + 1.0
    u = x - 1.0
    return 1.0 + c3 * u * u * u + c1 * u * u


_EASE_FNS = {
    "cubic": _ease_out_cubic,
    "quad": _ease_out_quad,
    "back": _ease_out_back,
}


# Conservative upper-bound settle time per profile, used by callers
# (e.g. hud_draw) to decide when to bypass the animated render path
# entirely and fall back to the cached fast path. Computed assuming up
# to ~30 panels and up to ~30 rows per panel (the play HUD's
# loadout_panel has the highest row count). The animation function
# itself does an exact per-call short-circuit based on actual tree
# shape; this table just lets callers gate at a coarser level.
def _profile_max_settle(prof, max_panels=30, max_rows=30):
    return ((max_panels - 1) * prof["panel_stagger"]
            + (max_rows - 1) * prof["inner_stagger"]
            + max(prof["panel_dur"], prof["inner_dur"]))


_SIDE_STRIP_ANIM_SETTLE = {
    name: _profile_max_settle(prof)
    for name, prof in _SIDE_STRIP_PROFILES.items()
}


def _draw_animated_side_strip(surf, root_spec, fonts, assets, tvars, anim_t,
                              mode="bouncy", x_offset=0, skip_bg=False):
    """Render the map / shop / hud right-side strip with an entry animation.

    `mode` selects a profile from `_SIDE_STRIP_PROFILES` ("slow",
    "bouncy", "hud"); unknown names fall back to bouncy. `x_offset` is
    added to root_spec.x for the final blit position — used by the HUD
    whose `hud_root.x` is HUD-local (0) but blits at HUD_X on screen.
    `skip_bg`: when True, skip rendering the root container's `bg` fill
    and treat the non-container chrome (e.g. left hairline) as fully
    opaque. Caller owns painting the strip backdrop — the HUD path
    sets this so its own pre-anim black→HUD_BG fade governs the bg.
    Past the last element's settle time the function short-circuits
    to plain `_layout_draw_item` (skip_bg still respected via shallow
    copy that drops the spec's bg field).
    """
    prof = _SIDE_STRIP_PROFILES.get(mode) or _SIDE_STRIP_PROFILES["bouncy"]
    panel_dur = prof["panel_dur"]
    panel_stag = prof["panel_stagger"]
    inner_dur = prof["inner_dur"]
    inner_stag = prof["inner_stagger"]
    bg_fade = prof["bg_fade"]
    panel_slide_cfg = prof["panel_slide_px"]
    inner_slide = prof["inner_slide_px"]
    alpha_lead = prof["alpha_lead"]
    pos_ease = _EASE_FNS.get(prof["pos_ease"], _ease_out_cubic)
    alpha_ease = _EASE_FNS.get(prof["alpha_ease"], _ease_out_cubic)
    per_row_alpha = prof["per_row_alpha"]

    if anim_t is None:
        anim_t = 999.0
    # `root_x` is the on-screen X for all blits. For map/shop the spec
    # already carries x=HUD_X; for the in-game HUD the spec has x=0 and
    # the caller passes x_offset=HUD_X.
    root_x = int(root_spec.get("x", 0)) + int(x_offset)
    root_w = int(root_spec.get("w", HUD_W))
    root_h = int(root_spec.get("h", SCREEN_H))
    panel_slide = root_w if panel_slide_cfg is None else int(panel_slide_cfg)

    children = list(root_spec.get("children") or ())
    panels = [c for c in children if c.get("type") == "container"]
    chrome_kids = [c for c in children if c.get("type") != "container"]

    # Settle-time check: account for inner-row stagger inside the last
    # panel so the short-circuit doesn't kick in early.
    max_inner_children = max((len(p.get("children") or ()) for p in panels),
                             default=0)
    last_end = ((len(panels) - 1) * panel_stag
                + max(0, max_inner_children - 1) * inner_stag
                + max(panel_dur, inner_dur))
    if anim_t >= last_end:
        # Past the animation window: straight render. Re-root via
        # shallow copy when an x_offset or skip_bg is in play so the
        # static-path output matches the animated-path one.
        if x_offset or skip_bg:
            rs = dict(root_spec)
            rs["x"] = root_x
            if skip_bg:
                rs.pop("bg", None)
            _layout_draw_item(surf, rs, fonts, assets, tvars)
        else:
            _layout_draw_item(surf, root_spec, fonts, assets, tvars)
        return

    # 1. Strip background — root container's `bg` at fade alpha. Skipped
    # when the caller is painting the strip backdrop itself.
    if not skip_bg:
        bg = root_spec.get("bg")
        bg_alpha = int(255 * _ease_out_cubic(anim_t / bg_fade))
        if bg is not None and bg_alpha > 0:
            bg_surf = pygame.Surface((root_w, root_h), pygame.SRCALPHA)
            bg_surf.fill((int(bg[0]), int(bg[1]), int(bg[2]), bg_alpha))
            surf.blit(bg_surf, (root_x, 0))
    else:
        bg_alpha = 255   # chrome (next section) renders at full opacity.

    # 2. Non-container chrome (left hairline) fades with bg.
    if bg_alpha > 0:
        for ch in chrome_kids:
            cd = dict(ch)
            cd["x"] = root_x + int(ch.get("x", 0))
            cd["alpha"] = int(int(ch.get("alpha", 255)) * (bg_alpha / 255.0))
            try:
                _layout_draw_item(surf, cd, fonts, assets, tvars)
            except Exception:
                pass

    # 3. Each panel rendered to its own SRCALPHA surface, blitted with
    # x slide offset + uniform set_alpha.
    MARGIN_TOP = 8
    MARGIN_BOT = 8   # room for negative inner slide / bounce overshoot
    for i, panel in enumerate(panels):
        panel_t = (anim_t - i * panel_stag) / panel_dur
        if panel_t <= 0:
            continue
        alpha_t = panel_t / alpha_lead
        panel_alpha = int(255 * alpha_ease(alpha_t))
        pos_p = pos_ease(panel_t)
        slide_off = int(round((1.0 - pos_p) * panel_slide))

        panel_w = int(panel.get("w", root_w))
        panel_h = int(panel.get("h", 0))
        panel_y = int(panel.get("y", 0))
        if panel_h <= 0 or panel_w <= 0:
            continue
        surf_h = panel_h + MARGIN_TOP + MARGIN_BOT
        ps = pygame.Surface((root_w, surf_h), pygame.SRCALPHA)

        # Inner-row stagger inside this panel.
        local_t = anim_t - i * panel_stag
        per_child = []   # list of (resolved_child_spec, child_alpha)
        for j, ch in enumerate(panel.get("children") or ()):
            inner_t = (local_t - j * inner_stag) / inner_dur
            if inner_t <= 0:
                continue
            inner_pos = pos_ease(inner_t)
            inner_x_off = int(round((1.0 - inner_pos) * inner_slide))
            if per_row_alpha:
                inner_alpha_t = inner_t / alpha_lead
                inner_alpha = int(255 * alpha_ease(inner_alpha_t))
            else:
                inner_alpha = 255
            cd = dict(ch)
            cd["x"] = int(panel.get("x", 0)) + int(ch.get("x", 0)) + inner_x_off
            cd["y"] = MARGIN_TOP + int(ch.get("y", 0))
            per_child.append((cd, inner_alpha))

        # Render the panel chrome (bg/border/title) alone — children
        # are drawn separately below so the per-row alpha path (when
        # active) can apply uniformly via a scratch sub-surface.
        panel_chrome = dict(panel)
        panel_chrome["x"] = int(panel.get("x", 0))
        panel_chrome["y"] = MARGIN_TOP
        panel_chrome["children"] = ()
        try:
            _layout_draw_item(ps, panel_chrome, fonts, assets, tvars)
        except Exception:
            continue

        scratch = None
        ps_w, ps_h = ps.get_size()
        for cd, ca in per_child:
            if ca >= 255 or not per_row_alpha:
                try:
                    _layout_draw_item(ps, cd, fonts, assets, tvars)
                except Exception:
                    pass
                continue
            if ca <= 0:
                continue
            if scratch is None:
                scratch = pygame.Surface((ps_w, ps_h), pygame.SRCALPHA)
            else:
                scratch.fill((0, 0, 0, 0))
            try:
                _layout_draw_item(scratch, cd, fonts, assets, tvars)
            except Exception:
                continue
            scratch.set_alpha(ca)
            ps.blit(scratch, (0, 0))

        if panel_alpha < 255:
            ps.set_alpha(panel_alpha)
        surf.blit(ps, (root_x + slide_off, panel_y - MARGIN_TOP))


def _draw_animated_side_strip_gpu(gpu, root_spec, fonts, assets, tvars, anim_t,
                                  mode="bouncy", x_offset=0, skip_bg=False):
    """GPU sibling of _draw_animated_side_strip — the map/shop right-strip entry
    animation (the original perf complaint). Native: the bg-fade is a fill_rect,
    chrome kids + the settled static render go through _layout_draw_item_gpu, and
    each sliding/fading panel composites to a cached render-target texture (so
    panel_alpha fades the whole panel — border+title+bg+rows — uniformly, exactly
    like the software set_alpha on the panel surface) which is then blitted with
    the slide offset + panel_alpha. Per-row inner alpha folds into each child's
    alpha (rows don't overlap, so this matches the software scratch-surface).
    Past the settle time it short-circuits to the plain native dispatcher."""
    prof = _SIDE_STRIP_PROFILES.get(mode) or _SIDE_STRIP_PROFILES["bouncy"]
    panel_dur = prof["panel_dur"]
    panel_stag = prof["panel_stagger"]
    inner_dur = prof["inner_dur"]
    inner_stag = prof["inner_stagger"]
    bg_fade = prof["bg_fade"]
    panel_slide_cfg = prof["panel_slide_px"]
    inner_slide = prof["inner_slide_px"]
    alpha_lead = prof["alpha_lead"]
    pos_ease = _EASE_FNS.get(prof["pos_ease"], _ease_out_cubic)
    alpha_ease = _EASE_FNS.get(prof["alpha_ease"], _ease_out_cubic)
    per_row_alpha = prof["per_row_alpha"]
    if anim_t is None:
        anim_t = 999.0
    root_x = int(root_spec.get("x", 0)) + int(x_offset)
    root_w = int(root_spec.get("w", HUD_W))
    root_h = int(root_spec.get("h", SCREEN_H))
    panel_slide = root_w if panel_slide_cfg is None else int(panel_slide_cfg)
    children = list(root_spec.get("children") or ())
    panels = [c for c in children if c.get("type") == "container"]
    chrome_kids = [c for c in children if c.get("type") != "container"]
    max_inner_children = max((len(p.get("children") or ()) for p in panels),
                             default=0)
    last_end = ((len(panels) - 1) * panel_stag
                + max(0, max_inner_children - 1) * inner_stag
                + max(panel_dur, inner_dur))
    if anim_t >= last_end:
        if x_offset or skip_bg:
            rs = dict(root_spec)
            rs["x"] = root_x
            if skip_bg:
                rs.pop("bg", None)
            _layout_draw_item_gpu(gpu, rs, fonts, assets, tvars)
        else:
            _layout_draw_item_gpu(gpu, root_spec, fonts, assets, tvars)
        return
    # 1. Strip background fade.
    if not skip_bg:
        bg = root_spec.get("bg")
        bg_alpha = int(255 * _ease_out_cubic(anim_t / bg_fade))
        if bg is not None and bg_alpha > 0:
            gpu.fill_rect((root_x, 0, root_w, root_h),
                          (int(bg[0]), int(bg[1]), int(bg[2]), bg_alpha))
    else:
        bg_alpha = 255
    # 2. Non-container chrome (left hairline) fades with bg.
    if bg_alpha > 0:
        for ch in chrome_kids:
            cd = dict(ch)
            cd["x"] = root_x + int(ch.get("x", 0))
            cd["alpha"] = int(int(ch.get("alpha", 255)) * (bg_alpha / 255.0))
            try:
                _layout_draw_item_gpu(gpu, cd, fonts, assets, tvars)
            except Exception:
                pass
    # 3. Each panel → cached render-target → blit with slide + panel_alpha.
    MARGIN_TOP = 8
    MARGIN_BOT = 8
    targets = getattr(gpu, "_strip_targets", None)
    if targets is None:
        targets = gpu._strip_targets = {}
    saved_target = gpu.get_target()
    for i, panel in enumerate(panels):
        panel_t = (anim_t - i * panel_stag) / panel_dur
        if panel_t <= 0:
            continue
        panel_alpha = int(255 * alpha_ease(panel_t / alpha_lead))
        if panel_alpha <= 0:
            continue
        pos_p = pos_ease(panel_t)
        slide_off = int(round((1.0 - pos_p) * panel_slide))
        panel_w = int(panel.get("w", root_w))
        panel_h = int(panel.get("h", 0))
        panel_y = int(panel.get("y", 0))
        if panel_h <= 0 or panel_w <= 0:
            continue
        surf_h = panel_h + MARGIN_TOP + MARGIN_BOT
        tkey = (root_w, surf_h)
        tgt = targets.get(tkey)
        if tgt is None:
            tgt = targets[tkey] = gpu.make_target((root_w, surf_h))
        gpu.set_target(tgt)
        gpu.begin((0, 0, 0, 0))
        # Panel chrome (bg/border/title), children empty — drawn at panel-local
        # coords inside the target (matches the software `ps` sub-surface).
        panel_chrome = dict(panel)
        panel_chrome["x"] = int(panel.get("x", 0))
        panel_chrome["y"] = MARGIN_TOP
        panel_chrome["children"] = ()
        try:
            _layout_draw_item_gpu(gpu, panel_chrome, fonts, assets, tvars)
        except Exception:
            gpu.set_target(saved_target)
            continue
        local_t = anim_t - i * panel_stag
        for j, ch in enumerate(panel.get("children") or ()):
            inner_t = (local_t - j * inner_stag) / inner_dur
            if inner_t <= 0:
                continue
            inner_pos = pos_ease(inner_t)
            inner_x_off = int(round((1.0 - inner_pos) * inner_slide))
            inner_alpha = (int(255 * alpha_ease(inner_t / alpha_lead))
                           if per_row_alpha else 255)
            if inner_alpha <= 0:
                continue
            cd = dict(ch)
            cd["x"] = int(panel.get("x", 0)) + int(ch.get("x", 0)) + inner_x_off
            cd["y"] = MARGIN_TOP + int(ch.get("y", 0))
            cd["alpha"] = int(int(ch.get("alpha", 255)) * (inner_alpha / 255.0))
            try:
                _layout_draw_item_gpu(gpu, cd, fonts, assets, tvars)
            except Exception:
                pass
        gpu.set_target(saved_target)
        gpu.blit(tgt, pygame.Rect(root_x + slide_off, panel_y - MARGIN_TOP,
                                  root_w, surf_h), alpha=panel_alpha)


def _hud_dyn_vars(player, save, score, time_left, credits_earned=0):
    """Per-frame vars referenced by `dynamic: True` HUD items."""
    sh_ratio = (max(0, player.shield_hp / player.shield_max)
                if player.shield_max > 0 else 0.0)
    cd_ratio = clamp(1 - player.ability_cd / 18.0, 0, 1)
    return {
        "time": max(0, int(time_left)),
        "shield_ratio": sh_ratio,
        "score": int(score),
        # save.credits is the banked total carried in from the title /
        # shop / previous levels; credits_earned is what this PlayState
        # has picked up since spawning. Sum so the live HUD reads the
        # full current wallet, while rewinds restore only the
        # credits_earned half (save.credits stays untouched per-frame).
        "credits": save.credits + credits_earned,
        "ability_ready": player.ability_cd <= 0,
        "ability_cd_ratio": cd_ratio,
        "ability_cd_color": (list(ORANGE) if cd_ratio >= 1
                             else [130, 80, 40]),
    }


def _build_hud_chrome(fonts, level_name, lo, save=None):
    """Render the static (cached) HUD chrome from the layout tree. Walks
    LAYOUT_ELEMENTS["hud"] with dynamic_filter=False; dynamic items are
    skipped here and painted per-frame by hud_draw()."""
    surf = pygame.Surface((HUD_W, SCREEN_H))
    surf.fill(HUD_BG)
    tvars = _hud_chrome_vars(level_name, lo, save)
    for it in resolved_layout_tree("hud"):
        _layout_draw_item(surf, it, fonts, None, tvars,
                          dynamic_filter=False)
    try:
        return surf.convert()
    except pygame.error:
        return surf


_LAYOUT_PATH = Path(__file__).resolve().parent / "art" / "layout.json"
_LAYOUT_CACHE = None
_LAYOUT_REV = 0     # bumped on every reload — cache keys use it to invalidate
_LAYOUT_SCREENS = ("title", "map", "shop", "play", "hud")


def _layout_load():
    global _LAYOUT_CACHE
    if _LAYOUT_CACHE is not None:
        return _LAYOUT_CACHE
    data = {}
    if _LAYOUT_PATH.exists():
        try:
            data = json.loads(_LAYOUT_PATH.read_text(encoding="utf-8"))
        except Exception as e:
            print(f"layout.json load failed: {e}")
            data = {}
    screens = data.get("screens") or {}
    out = {s: (screens.get(s) or {}).get("items") or [] for s in _LAYOUT_SCREENS}
    _LAYOUT_CACHE = out
    return out


def reload_layout():
    """Drop the cache so the next draw picks up edits from disk."""
    global _LAYOUT_CACHE, _LAYOUT_REV
    _LAYOUT_CACHE = None
    _LAYOUT_REV += 1


def _layout_collect_deep_ids(items):
    """Set of ids that appear *nested* inside any container's children
    at any depth — top-level items don't count. Used to detect builtins
    that the layout editor has carried into a non-root container; the
    spec for such ids should not render at root (would duplicate the
    moved copy)."""
    out = set()
    def _walk(its):
        for it in its:
            rid = it.get("id")
            if rid:
                out.add(rid)
            children = it.get("children")
            if children:
                _walk(children)
    for it in items or ():
        children = it.get("children")
        if children:
            _walk(children)
    return out


_RESOLVED_TREE_CACHE = {}   # {screen_name: (rev, tree)}


def resolved_layout_tree(screen_name):
    """Apply layout.json overrides on top of LAYOUT_ELEMENTS for `screen_name`.
    For each spec entry, an override with the matching id wins for every
    non-id/type field (children inclusive — the editor saves the whole
    modified subtree). User-added items (no matching spec id) append at the
    end so they render on top.

    Result is cached per (screen_name, _LAYOUT_REV) — the layout doesn't
    change during gameplay (only the editor mutates it via reload_layout()
    which bumps _LAYOUT_REV). The HUD path used to re-resolve this every
    frame, costing meaningful ms inside hud_draw on the RG35XX Pro."""
    cached = _RESOLVED_TREE_CACHE.get(screen_name)
    if cached is not None and cached[0] == _LAYOUT_REV:
        return cached[1]
    spec = LAYOUT_ELEMENTS.get(screen_name) or []
    overrides_list = _layout_load().get(screen_name) or []
    overrides = {it.get("id"): it for it in overrides_list if it.get("id")}
    # Builtins whose override has been moved into a child container are
    # skipped here — the engine will draw them at their new location via
    # the container walk; rendering the spec at root too would duplicate.
    moved_deep = _layout_collect_deep_ids(overrides_list)
    out = []
    spec_ids = set()
    for spec_item in spec:
        sid = spec_item.get("id")
        spec_ids.add(sid)
        if sid and sid in moved_deep:
            continue
        ov = overrides.get(sid)
        if ov:
            merged = dict(spec_item)
            for k, v in ov.items():
                if k in ("id", "type"):
                    continue
                merged[k] = v
            out.append(merged)
        else:
            out.append(spec_item)
    for it in overrides_list:
        if it.get("id") not in spec_ids:
            out.append(it)
    _RESOLVED_TREE_CACHE[screen_name] = (_LAYOUT_REV, out)
    return out


_LAYOUT_ANCHOR_AX = {"tl":0,"t":0.5,"tr":1,"l":0,"c":0.5,"r":1,"bl":0,"b":0.5,"br":1}
_LAYOUT_ANCHOR_AY = {"tl":0,"t":0,"tr":0,"l":0.5,"c":0.5,"r":0.5,"bl":1,"b":1,"br":1}


def _layout_anchor_offset(anchor, w, h):
    ax = _LAYOUT_ANCHOR_AX.get(anchor, 0.0)
    ay = _LAYOUT_ANCHOR_AY.get(anchor, 0.0)
    return int(round(-w * ax)), int(round(-h * ay))


def _resolve_layout_font(fonts, it, default_scale=3):
    """Look up the font for a layout item. `font` is the integer scale
    (clamped 1..7 for 5x7, 1..4 for 7x9); `font_family` selects the
    glyph set (default = 5x7, "7x9" = the mid-size family). Falls
    back to the integer key and finally to "big" so any item still
    renders even if its desired font cell isn't loaded."""
    fam = (it.get("font_family") or "").strip()
    scale = int(it.get("font", default_scale))
    # Keyboard hint tokens (Num1/Space/Bksp) are multi-char where pad glyphs
    # are one letter; an element can carry a smaller `kbd_font` used only
    # while keyboard hints are active so they fit the same column.
    if _HINT_DEVICE == "kbd" and "kbd_font" in it:
        scale = int(it["kbd_font"])
    if fam == "7x9":
        scale = max(1, min(4, scale))
        return (fonts.get((fam, scale))
                or fonts.get(scale)
                or fonts.get("big"))
    scale = max(1, min(7, scale))
    return fonts.get(scale) or fonts.get("big")


def _layout_draw_text(surf, it, fonts, template_vars=None):
    text = str(it.get("text") or "")
    if not text:
        return
    # Resolve color through _resolve_var so callers can pass a template
    # like "{main_rail_color}" — matches the tiered_bar behaviour.
    raw_col = _resolve_var(it.get("color"), template_vars or {}, None)
    if raw_col is None:
        raw_col = (240, 240, 240)
    try:
        color = tuple(int(c) for c in raw_col)[:3]
    except (TypeError, ValueError):
        color = (240, 240, 240)
    alpha = int(it.get("alpha", 255))
    font = _resolve_layout_font(fonts, it)
    img = font.render(text, False, color)
    ox, oy = _layout_anchor_offset(it.get("anchor", "tl"),
                                   img.get_width(), img.get_height())
    if it.get("shadow"):
        sh = font.render(text, False, (0, 0, 0))
        sh.set_alpha(min(alpha, 180))
        surf.blit(sh, (int(it.get("x", 0)) + ox + 1,
                       int(it.get("y", 0)) + oy + 1))
    if alpha < 255:
        img = img.copy()
        img.set_alpha(alpha)
    surf.blit(img, (int(it.get("x", 0)) + ox, int(it.get("y", 0)) + oy))


def _layout_draw_rect(surf, it):
    color = tuple(it.get("color") or (60, 80, 120))[:3]
    alpha = int(it.get("alpha", 200))
    outline = int(it.get("outline", 0))
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    w = max(1, int(it.get("w", 10)))
    h = max(1, int(it.get("h", 10)))
    if alpha >= 255:
        if outline > 0:
            pygame.draw.rect(surf, color, (x, y, w, h), outline)
        else:
            pygame.draw.rect(surf, color, (x, y, w, h))
        return
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    col = (color[0], color[1], color[2], alpha)
    if outline > 0:
        pygame.draw.rect(s, col, (0, 0, w, h), outline)
    else:
        s.fill(col)
    surf.blit(s, (x, y))


def _layout_draw_rect_gpu(gpu, it):
    """GPU sibling of _layout_draw_rect (fill / outline rect with alpha).
    Thick outlines = nested 1px draw_rects (SDL has no rect outline width)."""
    color = tuple(it.get("color") or (60, 80, 120))[:3]
    alpha = int(it.get("alpha", 200))
    outline = int(it.get("outline", 0))
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    w = max(1, int(it.get("w", 10)))
    h = max(1, int(it.get("h", 10)))
    col = (color[0], color[1], color[2], alpha)
    if outline > 0:
        for i in range(outline):
            if w - 2 * i > 0 and h - 2 * i > 0:
                gpu.draw_rect((x + i, y + i, w - 2 * i, h - 2 * i), col)
    else:
        gpu.fill_rect((x, y, w, h), col)


def _layout_sprite_lookup(assets, name):
    if not name or not assets:
        return None
    img = assets.get(name)
    if img is not None:
        return img
    # Fall back to the on-disk sprite (covers names not in the runtime asset
    # dict, e.g. backdrops or UI-only sprites).
    path = _LAYOUT_PATH.parent / "sprites" / f"{name}.png"
    if not path.exists():
        return None
    try:
        return pygame.image.load(str(path)).convert_alpha()
    except Exception:
        return None


def _layout_draw_image(surf, it, assets):
    name = it.get("sprite")
    img = _layout_sprite_lookup(assets, name)
    if img is None:
        return
    scale = float(it.get("scale", 1.0))
    if abs(scale - 1.0) > 0.001:
        sw, sh = img.get_size()
        img = pygame.transform.smoothscale(
            img, (max(1, int(sw * scale)), max(1, int(sh * scale))))
    alpha = int(it.get("alpha", 255))
    if alpha < 255:
        img = img.copy()
        img.set_alpha(alpha)
    ox, oy = _layout_anchor_offset(it.get("anchor", "tl"),
                                   img.get_width(), img.get_height())
    surf.blit(img, (int(it.get("x", 0)) + ox, int(it.get("y", 0)) + oy))


def _layout_draw_image_gpu(gpu, it, assets):
    """GPU sibling of _layout_draw_image: scale via dstrect (free) + alpha +
    anchor. (smoothscale's bilinear → the renderer's scale-quality hint.)"""
    name = it.get("sprite")
    img = _layout_sprite_lookup(assets, name)
    if img is None:
        return
    scale = float(it.get("scale", 1.0))
    sw, sh = img.get_size()
    if abs(scale - 1.0) > 0.001:
        dw, dh = max(1, int(sw * scale)), max(1, int(sh * scale))
    else:
        dw, dh = sw, sh
    alpha = int(it.get("alpha", 255))
    ox, oy = _layout_anchor_offset(it.get("anchor", "tl"), dw, dh)
    gpu.blit(gpu.tex_for(img),
             pygame.Rect(int(it.get("x", 0)) + ox, int(it.get("y", 0)) + oy, dw, dh),
             alpha=alpha)


def _resolve_var(val, template_vars, default):
    """Type-preserving template lookup. If `val` is the literal "{name}"
    reference, return template_vars[name] (a list / int / float survives
    intact). If the key isn't in template_vars, fall back to `default`
    (silently — beats spamming the console with KeyErrors when the editor
    previews a screen without the engine's full template_vars dict).
    Otherwise return val unchanged."""
    if (isinstance(val, str) and len(val) >= 3
            and val.startswith("{") and val.endswith("}")
            and "{" not in val[1:-1]):
        key = val[1:-1]
        if template_vars and key in template_vars:
            return template_vars[key]
        return default
    return val if val is not None else default


def _layout_draw_tiered_bar(surf, it, template_vars):
    """Weapon-level progress bar with tier+sub-level shape.

    Tier segments are laid out horizontally; each segment fills vertically
    bottom-up by sub-level. Thin separators across each segment mark the
    sub-level divisions — they vanish when the segment is fully filled,
    so a maxed tier reads as a solid block.

    Fields:
      x, y, w, h
      value          current level (1..max)
      max            max level (e.g. 20 for main, 12 for side)
      tiers          number of tier segments (default 5)
      cell_px_w      OPTIONAL fixed pixel width per tier cell — if set,
                     overrides `w` and derives total bar width from
                     `tiers * cell_px_w + (tiers - 1) gap`. Keeps cell
                     width uniform across rows even as tier count shrinks
                     (e.g. while bosses are locked).
      color          fill color
      bg_color       empty-segment color
      sep_color      thin sub-level separator color (default dim)
    """
    tvars = template_vars or {}
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    h = max(2, int(it.get("h", 10)))
    tiers = max(1, int(_resolve_var(it.get("tiers", 5), tvars, 5)))
    cell_px_raw = _resolve_var(it.get("cell_px_w"), tvars, None)
    if cell_px_raw not in (None, ""):
        try:
            cell_w_fixed = max(1, int(float(cell_px_raw)))
        except (TypeError, ValueError):
            cell_w_fixed = None
    else:
        cell_w_fixed = None
    if cell_w_fixed is not None:
        # Bar width derived from uniform cell width.
        w = cell_w_fixed * tiers + max(0, tiers - 1)
    else:
        w = max(1, int(it.get("w", 60)))
    color_raw = _resolve_var(it.get("color"), tvars, (80, 220, 255))
    bg_raw    = _resolve_var(it.get("bg_color"), tvars, (40, 46, 70))
    sep_raw   = _resolve_var(it.get("sep_color"), tvars, (20, 26, 44))
    color = tuple(color_raw)[:3] if color_raw else (80, 220, 255)
    bg    = tuple(bg_raw)[:3]    if bg_raw    else (40, 46, 70)
    sep   = tuple(sep_raw)[:3]   if sep_raw   else (20, 26, 44)

    val_raw = _resolve_var(it.get("value", 0), tvars, 0)
    if isinstance(val_raw, str) and "{" in val_raw:
        try: val_raw = val_raw.format(**tvars)
        except (KeyError, IndexError, ValueError): val_raw = 0
    try: val = int(float(val_raw))
    except (TypeError, ValueError): val = 0

    mx_raw = _resolve_var(it.get("max", 20), tvars, 20)
    try: mx = max(1, int(float(mx_raw)))
    except (TypeError, ValueError): mx = 20

    subs = max(1, mx // tiers)
    if cell_w_fixed is not None:
        cell_w = cell_w_fixed
    else:
        cell_w = max(1, (w - (tiers - 1)) // tiers)

    for t in range(tiers):
        cx = x + t * (cell_w + 1)
        # Background
        pygame.draw.rect(surf, bg, (cx, y, cell_w, h))
        seg_min = t * subs
        seg_max = (t + 1) * subs
        if val >= seg_max:
            sub_filled = subs
        elif val > seg_min:
            sub_filled = val - seg_min
        else:
            sub_filled = 0
        if sub_filled > 0:
            fill_h = h * sub_filled // subs
            if sub_filled == subs:
                fill_h = h
            pygame.draw.rect(surf, color, (cx, y + h - fill_h, cell_w, fill_h))
        # Sub-level separators — only on tiers that aren't completely full.
        if sub_filled < subs:
            for s in range(1, subs):
                sep_y_px = y + h - (h * s // subs) - 1
                if y < sep_y_px < y + h:
                    pygame.draw.line(surf, sep,
                                     (cx, sep_y_px),
                                     (cx + cell_w - 1, sep_y_px))


def _layout_draw_progress_bar(surf, it, template_vars):
    """Segmented bar primitive (mirrors the hand-rolled _segbar used by the
    HUD). Fields:
      x, y, w, h         - bar rect
      value              - current value (number or "{name}" template)
      max                - max value (default 1.0; accepts "{name}")
      color              - filled-segment color (accepts "{name}")
      bg_color           - empty-segment color (default dark)
      segments           - segment count (default 10; accepts "{name}")
      alpha              - 0..255 (default 255)"""
    tvars = template_vars or {}
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    w = max(1, int(it.get("w", 60)))
    h = max(1, int(it.get("h", 6)))
    segments = max(1, int(_resolve_var(it.get("segments", 10), tvars, 10)))
    color_raw = _resolve_var(it.get("color"), tvars, (80, 220, 255))
    bg_raw = _resolve_var(it.get("bg_color"), tvars, (40, 46, 70))
    color = tuple(color_raw)[:3] if color_raw else (80, 220, 255)
    bg = tuple(bg_raw)[:3] if bg_raw else (40, 46, 70)
    alpha = int(it.get("alpha", 255))
    val_raw = _resolve_var(it.get("value", 0), tvars, 0)
    if isinstance(val_raw, str) and "{" in val_raw:
        try:
            val_raw = val_raw.format(**tvars)
        except (KeyError, IndexError, ValueError):
            val_raw = 0
    try:
        val = float(val_raw)
    except (TypeError, ValueError):
        val = 0.0
    mx_raw = _resolve_var(it.get("max", 1.0), tvars, 1.0)
    try:
        mx = float(mx_raw) or 1.0
    except (TypeError, ValueError):
        mx = 1.0
    ratio = max(0.0, min(1.0, val / mx if mx > 0 else 0.0))

    cell_w = max(1, (w - (segments - 1)) // segments)
    target_surf = surf
    if alpha < 255:
        target_surf = pygame.Surface((w, h), pygame.SRCALPHA)
        cell_rect_x = 0
        cell_rect_y = 0
    else:
        cell_rect_x = x
        cell_rect_y = y
    for i in range(segments):
        cell = pygame.Rect(cell_rect_x + i * (cell_w + 1), cell_rect_y, cell_w, h)
        pygame.draw.rect(target_surf, bg, cell)
        if (i + 0.5) / segments <= ratio:
            pygame.draw.rect(target_surf, color, cell)
    if alpha < 255:
        target_surf.set_alpha(alpha)
        surf.blit(target_surf, (x, y))


# Panel-skin registry — each entry is the chrome defaults applied to a
# container whose `panel_skin` field matches the index. Explicit chrome
# fields on the container override the skin defaults. Skin 0 = no
# automatic chrome (the container still honours any explicit bg/border
# fields it carries). Skin 1 = the HUD panel look (recessed bg, border,
# corner caps, title chip). Add new entries here when more skins land.
_PANEL_SKIN_FIELDS = (
    "bg", "border", "border_width",
    "caps", "caps_color", "caps_length",
    "title_color", "title_font",
)
_PANEL_SKINS = {
    0: {},
    1: {
        "bg": [22, 26, 44],
        "border": [60, 80, 130],
        "border_width": 1,
        "caps": True,
        "caps_color": [110, 160, 220],
        "caps_length": 5,
        "title_color": [160, 200, 240],
        "title_font": 1,
    },
}


def _container_chrome(it):
    """Merge the panel skin's defaults with the container's explicit
    chrome fields. Explicit values win — set bg/border/etc. on the dict
    to customise without changing the skin. Returns a dict that the
    chrome-rendering code can read uniformly via .get()."""
    skin = int(it.get("panel_skin", 0))
    chrome = dict(_PANEL_SKINS.get(skin, {}))
    for k in _PANEL_SKIN_FIELDS:
        if k in it:
            chrome[k] = it[k]
    chrome["title"] = it.get("title")
    return chrome


def _layout_draw_container(surf, it, fonts, assets, template_vars, draw_one,
                            chrome_filter=None):
    """Render a container: optional bg + border + clipped recursive draw of
    children. Children sit at (container.x + child.x, container.y + child.y)
    when layout=free; layout=stack auto-positions them along an axis with
    gap. layout=grid uses anchor-aware cell placement.

    `draw_one` is the per-item dispatcher (passed in to keep the recursion
    cycle-free).

    `chrome_filter`: when given, only render this container's own chrome
    (bg/border/caps/title) when bool(it.get("dynamic")) == chrome_filter.
    Children are always recursed so a non-dynamic container can still
    expose dynamic children inside (e.g. HUD per-frame fields)."""
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    w = max(0, int(it.get("w", 0)))
    h = max(0, int(it.get("h", 0)))
    pad = int(it.get("padding", 0))
    layout = (it.get("layout") or "free").lower()
    alpha = int(it.get("alpha", 255))
    # Chrome (bg / border / caps / title) is selected by panel_skin and
    # then overridden by any explicit field on the item dict.
    chrome = _container_chrome(it)
    bg = chrome.get("bg")
    border = chrome.get("border")
    border_w = int(chrome.get("border_width", 1)) if border else 0

    render_chrome = (chrome_filter is None
                     or bool(it.get("dynamic")) == chrome_filter)

    # Background + border (only when sized — w/h > 0).
    if render_chrome and w > 0 and h > 0:
        if bg is not None:
            col = (bg[0], bg[1], bg[2], alpha) if alpha < 255 else bg[:3]
            if alpha < 255:
                bg_surf = pygame.Surface((w, h), pygame.SRCALPHA)
                bg_surf.fill(col)
                surf.blit(bg_surf, (x, y))
            else:
                pygame.draw.rect(surf, col, (x, y, w, h))
        if border is not None and border_w > 0:
            pygame.draw.rect(surf, border[:3], (x, y, w, h), border_w)
        # Decorative corner caps + title chip (matches the HUD _panel look).
        if chrome.get("caps") and bg is not None and border is not None:
            cap = tuple(chrome.get("caps_color") or (110, 160, 220))[:3]
            cap_len = int(chrome.get("caps_length", 5))
            # 4 horizontal segments (top + bottom edges, both sides)
            pygame.draw.rect(surf, cap, (x, y, cap_len, 1))
            pygame.draw.rect(surf, cap, (x + w - cap_len, y, cap_len, 1))
            pygame.draw.rect(surf, cap, (x, y + h - 1, cap_len, 1))
            pygame.draw.rect(surf, cap, (x + w - cap_len, y + h - 1, cap_len, 1))
            # 4 vertical segments
            pygame.draw.rect(surf, cap, (x, y, 1, cap_len))
            pygame.draw.rect(surf, cap, (x + w - 1, y, 1, cap_len))
            pygame.draw.rect(surf, cap, (x, y + h - cap_len, 1, cap_len))
            pygame.draw.rect(surf, cap, (x + w - 1, y + h - cap_len, 1, cap_len))
        title = chrome.get("title")
        if title and fonts:
            if "{" in title and template_vars:
                title = _safe_format(title, template_vars)
            t_color = tuple(chrome.get("title_color") or (160, 200, 240))[:3]
            t_font_scale = max(1, min(7, int(chrome.get("title_font", 1))))
            t_font = fonts.get(t_font_scale) or fonts.get("tiny")
            t_img = t_font.render(title, False, t_color)
            # Clip the panel border behind the chip so text reads cleanly.
            if bg is not None:
                pygame.draw.rect(surf, bg[:3],
                                 (x + 6, y - 1, t_img.get_width() + 6, 2))
            surf.blit(t_img, (x + 9, y - 6))

    children = it.get("children") or ()
    if not children:
        return

    inner_x = x + pad
    inner_y = y + pad
    if layout == "stack":
        direction = (it.get("direction") or "vertical").lower()
        gap = int(it.get("gap", 0))
        cursor_x = inner_x
        cursor_y = inner_y
        for child in children:
            # Stack uses each child's w/h (with sensible defaults). The
            # child's own x/y is ignored — the stack positions it.
            child = dict(child)
            cw = int(child.get("w", w - pad * 2 if w else 0) or 0)
            ch = int(child.get("h", h - pad * 2 if h else 0) or 0)
            child["x"] = cursor_x
            child["y"] = cursor_y
            draw_one(surf, child, fonts, assets, template_vars)
            if direction == "horizontal":
                cursor_x += cw + gap
            else:
                cursor_y += ch + gap
        return

    if layout == "grid":
        rows = max(1, int(it.get("rows", 1)))
        cols = max(1, int(it.get("cols", 1)))
        gap_x = int(it.get("gap_x", it.get("gap", 0)))
        gap_y = int(it.get("gap_y", it.get("gap", 0)))
        inner_w = max(0, w - pad * 2)
        inner_h = max(0, h - pad * 2)
        cell_w = (inner_w - (cols - 1) * gap_x) // cols if cols else inner_w
        cell_h = (inner_h - (rows - 1) * gap_y) // rows if rows else inner_h
        cell_w = max(1, cell_w)
        cell_h = max(1, cell_h)
        max_cells = rows * cols
        for idx, child in enumerate(children):
            if idx >= max_cells:
                break  # extra children silently skipped — UI feedback in editor
            r = idx // cols
            c = idx % cols
            cell_x = inner_x + c * (cell_w + gap_x)
            cell_y = inner_y + r * (cell_h + gap_y)
            cell_child = dict(child)
            # The child's own anchor selects which point inside the cell it
            # latches to (anchor=tl → top-left, c → center, br → bottom-right).
            # Child's x/y stay as fine-tune offsets on top of that anchor point.
            anchor = child.get("anchor", "tl")
            ax = _LAYOUT_ANCHOR_AX.get(anchor, 0.0)
            ay = _LAYOUT_ANCHOR_AY.get(anchor, 0.0)
            cell_child["x"] = cell_x + int(cell_w * ax) + int(child.get("x", 0))
            cell_child["y"] = cell_y + int(cell_h * ay) + int(child.get("y", 0))
            # Default the child's size to fill its cell so progress bars /
            # rects / nested containers slot in cleanly without manual sizing.
            if "w" not in child: cell_child["w"] = cell_w
            if "h" not in child: cell_child["h"] = cell_h
            draw_one(surf, cell_child, fonts, assets, template_vars)
        return

    # Default: free positioning. Children's x/y are relative to inner_x/y.
    for child in children:
        offset_child = dict(child)
        offset_child["x"] = inner_x + int(child.get("x", 0))
        offset_child["y"] = inner_y + int(child.get("y", 0))
        draw_one(surf, offset_child, fonts, assets, template_vars)


# ---------------------------------------------------------------------------
# Built-in (chrome) element registry
# ---------------------------------------------------------------------------
# Each entry is the *default* spec for one chrome element on a screen. The
# screen's draw code calls get_element(screen, id) to fetch the merged
# (defaults + layout.json override) values and renders accordingly. This
# keeps the position/font/color/text of every label editable through the
# layout editor without changing how the engine actually composes the
# screen (menus still respond to game state, blinks still blink, etc.).

LAYOUT_ELEMENTS = {
    "title": [
        {"id": "logo", "type": "image",
         "x": 320, "y": 130, "anchor": "c",
         "sprite": "title", "scale": 1.0, "alpha": 255,
         "_label": "PEWPEW logo (with gloss sweep)"},
        {"id": "menu", "type": "menu",
         "x": 320, "y": 260, "align": "center",
         "font": 3, "color": [240, 240, 240],
         "selected_color": [255, 220, 80],
         "selected_decor": ">  {opt}  <",
         "unselected_decor": "   {opt}   ",
         "line_height": 44, "alpha": 255,
         "_label": "main menu list (Continue / New Game / SOUND / MUSIC / Quit; SOUND + MUSIC are sliders nudged ±2% by D-pad left/right)",
         "_preview_options": ["Continue", "New Game",
                              "SOUND 100%", "MUSIC 100%", "Quit"]},
        {"id": "tip", "type": "text",
         "x": 320, "y": 420, "anchor": "c",
         "text": "{btn_fire} confirm  |  {dpad:UD} select",
         "font": 2, "color": [140, 140, 160], "alpha": 255,
         "shadow": False, "blink": False,
         "_label": "controls hint ({btn_*}/{dpad} = pictograms)",
         "_preview_vars": {}},
        {"id": "profile", "type": "text",
         "x": 320, "y": 20, "anchor": "t",
         "text": "< L1   {profile_name}   R1 >",
         "font": 2, "color": [160, 200, 240], "alpha": 255,
         "_label": "active player profile (L1/R1 cycle through 5 slots)",
         "_preview_vars": {"profile_name": "ANDROMEDA"}},
    ],
    "map": [
        {"id": "nav_hint_l", "type": "text",
         "x": 12, "y": 8, "anchor": "tl",
         "text": "< L", "font": 2,
         "color": [255, 196, 64], "alpha": 255,
         "visible_when": "has_prev",
         "_label": "previous-sector hint (visible when sector > 0); L1 or L2"},
        {"id": "nav_hint_r", "type": "text",
         "x": 468, "y": 8, "anchor": "tr",
         "text": "R >", "font": 2,
         "color": [255, 196, 64], "alpha": 255,
         "visible_when": "has_next",
         "_label": "next-sector hint (visible when more sectors unlocked); R1 or R2"},
        {"id": "sector_title", "type": "text",
         "x": 240, "y": 57, "anchor": "c",
         "text": "{sector_name}", "font": 3,
         "color": [255, 196, 64], "alpha": 255,
         "_label": "current sector name banner"},
        {"id": "sector_subtitle", "type": "text",
         "x": 240, "y": 72, "anchor": "c",
         "text": "SECTOR {sector_n}/10  -  CLEARED {progress}/100",
         "font": 1, "color": [140, 140, 160], "alpha": 255,
         "_label": "sector progress sub-banner"},
        {"id": "all_clear", "type": "text",
         "x": 240, "y": 470, "anchor": "c",
         "text": "ALL CLEAR", "font": 2,
         "color": [90, 230, 120], "alpha": 255,
         "visible_when": "all_clear",
         "_label": "100% completion banner"},
    ],
    "shop": [
        {"id": "hangar_title", "type": "text",
         "x": HUD_X // 2, "y": 18, "anchor": "t",
         "text": "UPGRADES", "font": 3,
         "color": [80, 220, 255], "alpha": 255,
         "_label": "left panel header (centered)"},
    ],
    # (gameover screen removed v0.9.292 — a loss now drops into the shop.)
    # HUD: built programmatically because the tree is large and references
    # screen-geometry constants. The result is a single `hud_root`
    # container with six chrome panels + dynamic items (timer / score /
    # credits / shield bar / ability cd / ability-ready highlight).
    "hud": _build_hud_layout_spec(),
}

# Shop and Map share the right-strip layout idea with the HUD — same
# panel_skin chrome, dynamic credits/etc. Built the same way and appended
# to the existing per-screen item lists so the strip renders alongside
# whatever standalone items already live on those screens.
LAYOUT_ELEMENTS["shop"].append(_build_shop_panel_spec())
LAYOUT_ELEMENTS["map"].append(_build_map_panel_spec())
LAYOUT_ELEMENTS["play"] = [_build_play_banner_spec()]

# Override flag: when True, get_element returns None for every lookup so
# the screen draw skips its built-in chrome. _smoke uses this to capture
# "naked" backdrops for the layout editor preview (chrome-free reference
# image so the editor can re-render elements at edited positions without
# visual ghosting of the originals).
_RENDER_NAKED = False


def _layout_overrides_for(screen_name):
    """Map id -> override item from layout.json for this screen."""
    out = {}
    for it in _layout_load().get(screen_name) or ():
        rid = it.get("id")
        if rid:
            out[rid] = it
    return out


def get_element(screen_name, element_id, **template_vars):
    """Return the merged spec (defaults + layout.json override) for one
    built-in chrome element, or None if naked-render mode is active.
    Interpolates `{name}` placeholders in the text field using template_vars."""
    if _RENDER_NAKED:
        return None
    spec = None
    for el in LAYOUT_ELEMENTS.get(screen_name, ()):
        if el.get("id") == element_id:
            spec = dict(el)
            break
    if spec is None:
        return None
    overrides_list = _layout_load().get(screen_name) or []
    # If this builtin's override has been carried into a child container
    # (any depth), the engine draws it via the container walk — skip the
    # inline spec render so the moved copy isn't paired with a duplicate.
    if element_id in _layout_collect_deep_ids(overrides_list):
        return None
    override = _layout_overrides_for(screen_name).get(element_id)
    if override:
        # Allow override of any field except id/type — type is fixed by
        # the registry (a text element can't suddenly become a rect).
        for k, v in override.items():
            if k in ("id", "type"):
                continue
            spec[k] = v
    text = spec.get("text")
    if text and template_vars:
        spec["text"] = _safe_format(str(text), template_vars)
    return spec


def _is_builtin_id(screen_name, item_id):
    if not item_id:
        return False
    for el in LAYOUT_ELEMENTS.get(screen_name, ()):
        if el.get("id") == item_id:
            return True
    return False


# ── Inline controller pictograms in text ────────────────────────────────
# A "rich" string may embed position-glyph tokens that render inline at the
# font's height instead of as letters:
#   {btn_fire} {btn_bomb} {btn_ability} {btn_cancel}  -> face glyph (device-
#       aware: a 4-circle diamond on pad, a key-cap on keyboard)
#   {dpad}            -> full d-pad cross  ("move / any direction")
#   {dpad:UD}/{dpad:LR}/{dpad:U}…  -> only the named arms light up
# The glyph inherits the surrounding text colour. Used by both the layout
# text path (_draw_text_with_icons) and the ad-hoc banner path
# (draw_rich_text), so controller buttons NEVER show a silk letter.
_FACE_TOKENS = {"btn_fire": "fire", "btn_bomb": "bomb",
                "btn_ability": "ability", "btn_cancel": "cancel"}


def _rich_has_tokens(text):
    return ("{btn_" in text) or ("{dpad" in text)


def _iter_rich(text):
    """Yield ('text', s) | ('face', action) | ('dpad', dirs) segments in
    order. Non-icon braces (e.g. unresolved {foo}) pass through as text."""
    i, n, buf = 0, len(text), []
    while i < n:
        if text[i] == "{":
            j = text.find("}", i + 1)
            if j != -1:
                tok = text[i + 1:j]
                seg = None
                if tok in _FACE_TOKENS:
                    seg = ("face", _FACE_TOKENS[tok])
                elif tok == "dpad":
                    seg = ("dpad", "UDLR")
                elif tok.startswith("dpad:"):
                    dirs = "".join(c for c in tok[5:].upper() if c in "UDLR")
                    seg = ("dpad", dirs or "UDLR")
                if seg is not None:
                    if buf:
                        yield ("text", "".join(buf)); buf = []
                    yield seg
                    i = j + 1
                    continue
        buf.append(text[i])
        i += 1
    if buf:
        yield ("text", "".join(buf))


def _measure_rich(text, fonts, font):
    """Total inline width of a rich string at `font`."""
    h = font.get_height()
    scale = _dpad_scale_for_font(font)
    w = 0
    for kind, val in _iter_rich(text):
        if kind == "text":
            w += font.size(val)[0] if val else 0
        elif kind == "dpad":
            w += 7 * scale
        else:
            w += _button_icon_width(val, h, fonts)
    return w


def _blit_rich(surf, x, y, text, fonts, font, color, alpha=255):
    """Draw a rich string left-to-right from top-left (x, y). Glyphs are
    vertically centred on the text line. Returns the drawn width."""
    h = font.get_height()
    scale = _dpad_scale_for_font(font)
    cx = x
    for kind, val in _iter_rich(text):
        if kind == "text":
            if not val:
                continue
            img = font.render(val, False, color)
            if alpha < 255:
                img = img.copy(); img.set_alpha(alpha)
            surf.blit(img, (cx, y + (h - img.get_height()) // 2))
            cx += img.get_width()
        elif kind == "dpad":
            _draw_dpad_icon(surf, cx, y + (h - 7 * scale) // 2,
                            scale=scale, color=color, dirs=val)
            cx += 7 * scale
        else:  # face
            cx += _draw_button_icon(surf, cx, y, h, val, fonts, color=color)
    return cx - x


def draw_rich_text(surf, x, y, text, fonts, font, color, anchor="tl", alpha=255):
    """Render `text` at (x, y) with inline controller pictograms for any
    {btn_*}/{dpad[:DIRS]} tokens, anchored per `_layout_anchor_offset`
    (e.g. 'c' centres on (x, y)). Returns the drawn pygame.Rect. The
    one-call drop-in for ad-hoc `font.render(...)+blit` hint renders."""
    if not _rich_has_tokens(text):
        img = font.render(text, False, color)
        if alpha < 255:
            img = img.copy(); img.set_alpha(alpha)
        ox, oy = _layout_anchor_offset(anchor, img.get_width(), img.get_height())
        surf.blit(img, (x + ox, y + oy))
        return pygame.Rect(x + ox, y + oy, img.get_width(), img.get_height())
    w = _measure_rich(text, fonts, font)
    h = font.get_height()
    ox, oy = _layout_anchor_offset(anchor, w, h)
    if alpha < 255:
        # Composite to a temp surface so the inline GLYPHS fade with the
        # text (per-glyph alpha isn't applied by _blit_rich directly).
        tmp = pygame.Surface((max(1, w), max(1, h)), pygame.SRCALPHA)
        _blit_rich(tmp, 0, 0, text, fonts, font, color, 255)
        tmp.set_alpha(alpha)
        surf.blit(tmp, (x + ox, y + oy))
    else:
        _blit_rich(surf, x + ox, y + oy, text, fonts, font, color, alpha)
    return pygame.Rect(x + ox, y + oy, w, h)


def draw_float_rich(surf, fonts, font, text, color, topleft=None, midtop=None):
    """Drop-shadowed rich text (1px black shadow) with inline {btn_*}/{dpad}
    pictograms — the glyph-aware sibling of PlayScreen._float_text, for
    floating hints over the busy playfield. Returns the drawn pygame.Rect."""
    w = _measure_rich(text, fonts, font)
    h = font.get_height()
    if midtop is not None:
        x, y = midtop[0] - w // 2, midtop[1]
    else:
        x, y = topleft
    _blit_rich(surf, x + 1, y + 1, text, fonts, font, (0, 0, 0))
    _blit_rich(surf, x, y, text, fonts, font, color)
    return pygame.Rect(x, y, w, h)


def _draw_text_with_icons(surf, it, fonts, template_vars=None):
    """Render a layout text element, replacing inline {dpad[:DIRS]} and
    {btn_fire|bomb|ability|cancel} tokens with position pictograms. Falls
    back to plain text rendering when no tokens are present."""
    text = str(it.get("text") or "")
    if not _rich_has_tokens(text):
        _layout_draw_text(surf, it, fonts, template_vars)
        return
    font = _resolve_layout_font(fonts, it)
    color = tuple(it.get("color") or (240, 240, 240))[:3]
    alpha = int(it.get("alpha", 255))
    w = _measure_rich(text, fonts, font)
    h = font.get_height()
    ox, oy = _layout_anchor_offset(it.get("anchor", "tl"), w, h)
    base_x = int(it.get("x", 0)) + ox
    base_y = int(it.get("y", 0)) + oy
    _blit_rich(surf, base_x, base_y, text, fonts, font, color, alpha)


# Back-compat alias: the old name handled only {dpad}; callers unchanged.
_draw_text_with_dpad = _draw_text_with_icons


def _layout_draw_menu(surf, it, fonts, options=None):
    """Render a menu element: option list stacked vertically. The first
    option's vertical centre sits at (x, y); each subsequent option steps
    down by line_height. `align` controls each line's horizontal anchor:
      "center" — line centered on x (default)
      "left"   — line's left edge at x
      "right"  — line's right edge at x
    Selected option uses selected_color + selected_decor."""
    opts = options if options is not None else (it.get("_preview_options") or [])
    if not opts:
        return
    font = _resolve_layout_font(fonts, it)
    color = tuple(it.get("color") or (240, 240, 240))[:3]
    sel_color = tuple(it.get("selected_color") or color)[:3]
    sel_decor = it.get("selected_decor") or ">  {opt}  <"
    unsel_decor = it.get("unselected_decor") or "   {opt}   "
    line_h = int(it.get("line_height", 44))
    alpha = int(it.get("alpha", 255))
    align = (it.get("align") or "center").lower()
    cursor = it.get("_preview_cursor", 0)
    cx = int(it.get("x", 0))
    y = int(it.get("y", 0))
    for i, opt in enumerate(opts):
        sel = (i == cursor)
        text = (sel_decor if sel else unsel_decor).replace("{opt}", str(opt))
        c = sel_color if sel else color
        img = font.render(text, False, c)
        if alpha < 255:
            img = img.copy(); img.set_alpha(alpha)
        line_y = y + i * line_h
        if align == "left":
            rect = img.get_rect(midleft=(cx, line_y))
        elif align == "right":
            rect = img.get_rect(midright=(cx, line_y))
        else:
            rect = img.get_rect(center=(cx, line_y))
        surf.blit(img, rect)


def _layout_draw_item(surf, it, fonts, assets, template_vars, dynamic_filter=None):
    """Per-item dispatcher used by both the top-level overlay path and
    container recursion. template_vars is the {name: value} dict for
    {placeholder} interpolation in text + progress_bar.value.

    dynamic_filter (optional):
      None  → render everything (default; editor + overlay use this)
      False → render only items NOT marked `dynamic`: True (chrome bake)
      True  → render only items marked `dynamic`: True (per-frame overlay)
    Containers are always recursed into — only their children are filtered."""
    kind = it.get("type")
    if dynamic_filter is not None and kind != "container":
        if bool(it.get("dynamic")) != dynamic_filter:
            return
    # Conditional rendering: `visible_when` names a key in template_vars
    # whose truthiness gates the draw. Lets us swap the dim/bright ability-
    # name overlays without a full conditional expression language.
    vw = it.get("visible_when")
    if vw and template_vars is not None:
        if not template_vars.get(vw):
            return
    # HUD hides bomb / ability / shield slots — their mechanics
    # are disabled, so the labels just confuse. Static chrome bake +
    # editor preview + user-overlay all flow through this dispatch, so
    # one check covers them. (Dynamic-record HUD path filters separately
    # — see hud_draw.)
    if _hud_item_hidden(it.get("id")):
        return
    try:
        if kind == "text":
            txt = str(it.get("text") or "")
            if "{" in txt and template_vars:
                copy = dict(it)
                copy["text"] = _safe_format(txt, template_vars)
                it = copy
            _draw_text_with_dpad(surf, it, fonts, template_vars)
        elif kind == "rect":
            _layout_draw_rect(surf, it)
        elif kind == "image":
            _layout_draw_image(surf, it, assets)
        elif kind == "menu":
            _layout_draw_menu(surf, it, fonts)
        elif kind == "progress_bar":
            _layout_draw_progress_bar(surf, it, template_vars)
        elif kind == "tiered_bar":
            _layout_draw_tiered_bar(surf, it, template_vars)
        elif kind == "btn_icon":
            _bcol = tuple(it["color"])[:3] if it.get("color") else None
            _draw_button_icon(surf, int(it.get("x", 0)), int(it.get("y", 0)),
                              int(it.get("h", 13)), it.get("action", ""), fonts,
                              color=_bcol)
        elif kind == "container":
            _layout_draw_container(
                surf, it, fonts, assets, template_vars,
                lambda *a: _layout_draw_item(*a, dynamic_filter=dynamic_filter),
                chrome_filter=dynamic_filter)
    except Exception as e:
        print(f"layout draw {kind} failed: {e}")


# ---------------------------------------------------------------------------
# Native GPU siblings of the layout drawers. Same dispatch + math as the
# software path; primitives go to the Renderer (fill_rect/draw_rect/line) and
# text/images composite as cached textures. Static labels (font.render result
# is cached, tex_for caches by surface identity) cost ONE upload then are pure
# quad draws — so menus stop re-rendering the whole tree per frame. Freshly
# built per-frame surfaces (rich pictogram text, baked button icons) go via
# blit_dynamic (a keyed streaming texture) to avoid leaking a texture per
# frame. Mirrors the software helpers exactly so output is pixel-identical.
# ---------------------------------------------------------------------------
def _layout_draw_text_gpu(gpu, it, fonts, template_vars=None):
    text = str(it.get("text") or "")
    if not text:
        return
    raw_col = _resolve_var(it.get("color"), template_vars or {}, None)
    if raw_col is None:
        raw_col = (240, 240, 240)
    try:
        color = tuple(int(c) for c in raw_col)[:3]
    except (TypeError, ValueError):
        color = (240, 240, 240)
    alpha = int(it.get("alpha", 255))
    font = _resolve_layout_font(fonts, it)
    x, y = int(it.get("x", 0)), int(it.get("y", 0))
    anchor = it.get("anchor", "tl")
    if _rich_has_tokens(text):
        # Inline {btn_*}/{dpad} pictograms — bake the line, stream-upload it
        # (keyed by content so static hints reuse one texture). Pad the bake:
        # face-glyph circles poke ~1px past the measured (w,h) box, which a
        # tight surface would clip on the left/top edge (anchor math still uses
        # the logical w,h; the pad just blits back offset).
        w = _measure_rich(text, fonts, font)
        h = font.get_height()
        ox, oy = _layout_anchor_offset(anchor, w, h)
        PAD = _face_glyph_pad(h)
        sw, sh = max(1, w) + 2 * PAD, max(1, h) + 2 * PAD
        surf = pygame.Surface((sw, sh), pygame.SRCALPHA)
        _blit_rich(surf, PAD, PAD, text, fonts, font, color, 255)
        gpu.blit_dynamic("lt:%s:%s" % (text, color), surf,
                         pygame.Rect(x + ox - PAD, y + oy - PAD, sw, sh),
                         alpha=alpha)
        return
    img = font.render(text, False, color)
    ox, oy = _layout_anchor_offset(anchor, img.get_width(), img.get_height())
    bx, by = x + ox, y + oy
    if it.get("shadow"):
        sh = font.render(text, False, (0, 0, 0))
        gpu.blit(gpu.tex_for(sh),
                 pygame.Rect(bx + 1, by + 1, sh.get_width(), sh.get_height()),
                 alpha=min(alpha, 180))
    gpu.blit(gpu.tex_for(img),
             pygame.Rect(bx, by, img.get_width(), img.get_height()), alpha=alpha)


def _layout_draw_tiered_bar_gpu(gpu, it, template_vars):
    """GPU sibling of _layout_draw_tiered_bar (fill_rect cells + sep lines)."""
    tvars = template_vars or {}
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    h = max(2, int(it.get("h", 10)))
    tiers = max(1, int(_resolve_var(it.get("tiers", 5), tvars, 5)))
    cell_px_raw = _resolve_var(it.get("cell_px_w"), tvars, None)
    if cell_px_raw not in (None, ""):
        try:
            cell_w_fixed = max(1, int(float(cell_px_raw)))
        except (TypeError, ValueError):
            cell_w_fixed = None
    else:
        cell_w_fixed = None
    if cell_w_fixed is not None:
        w = cell_w_fixed * tiers + max(0, tiers - 1)
    else:
        w = max(1, int(it.get("w", 60)))
    color_raw = _resolve_var(it.get("color"), tvars, (80, 220, 255))
    bg_raw = _resolve_var(it.get("bg_color"), tvars, (40, 46, 70))
    sep_raw = _resolve_var(it.get("sep_color"), tvars, (20, 26, 44))
    color = tuple(color_raw)[:3] if color_raw else (80, 220, 255)
    bg = tuple(bg_raw)[:3] if bg_raw else (40, 46, 70)
    sep = tuple(sep_raw)[:3] if sep_raw else (20, 26, 44)
    val_raw = _resolve_var(it.get("value", 0), tvars, 0)
    if isinstance(val_raw, str) and "{" in val_raw:
        try: val_raw = val_raw.format(**tvars)
        except (KeyError, IndexError, ValueError): val_raw = 0
    try: val = int(float(val_raw))
    except (TypeError, ValueError): val = 0
    mx_raw = _resolve_var(it.get("max", 20), tvars, 20)
    try: mx = max(1, int(float(mx_raw)))
    except (TypeError, ValueError): mx = 20
    subs = max(1, mx // tiers)
    cell_w = cell_w_fixed if cell_w_fixed is not None else max(1, (w - (tiers - 1)) // tiers)
    for t in range(tiers):
        cx = x + t * (cell_w + 1)
        gpu.fill_rect((cx, y, cell_w, h), bg)
        seg_min = t * subs
        seg_max = (t + 1) * subs
        if val >= seg_max:
            sub_filled = subs
        elif val > seg_min:
            sub_filled = val - seg_min
        else:
            sub_filled = 0
        if sub_filled > 0:
            fill_h = h if sub_filled == subs else h * sub_filled // subs
            gpu.fill_rect((cx, y + h - fill_h, cell_w, fill_h), color)
        if sub_filled < subs:
            for s in range(1, subs):
                sep_y_px = y + h - (h * s // subs) - 1
                if y < sep_y_px < y + h:
                    gpu.line((cx, sep_y_px), (cx + cell_w - 1, sep_y_px), sep)


def _layout_draw_progress_bar_gpu(gpu, it, template_vars):
    """GPU sibling of _layout_draw_progress_bar (segmented fill_rects; alpha
    folded into the cell colour instead of a temp-surface set_alpha)."""
    tvars = template_vars or {}
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    w = max(1, int(it.get("w", 60)))
    h = max(1, int(it.get("h", 6)))
    segments = max(1, int(_resolve_var(it.get("segments", 10), tvars, 10)))
    color_raw = _resolve_var(it.get("color"), tvars, (80, 220, 255))
    bg_raw = _resolve_var(it.get("bg_color"), tvars, (40, 46, 70))
    color = tuple(color_raw)[:3] if color_raw else (80, 220, 255)
    bg = tuple(bg_raw)[:3] if bg_raw else (40, 46, 70)
    alpha = int(it.get("alpha", 255))
    val_raw = _resolve_var(it.get("value", 0), tvars, 0)
    if isinstance(val_raw, str) and "{" in val_raw:
        try: val_raw = val_raw.format(**tvars)
        except (KeyError, IndexError, ValueError): val_raw = 0
    try: val = float(val_raw)
    except (TypeError, ValueError): val = 0.0
    mx_raw = _resolve_var(it.get("max", 1.0), tvars, 1.0)
    try: mx = float(mx_raw) or 1.0
    except (TypeError, ValueError): mx = 1.0
    ratio = max(0.0, min(1.0, val / mx if mx > 0 else 0.0))
    cell_w = max(1, (w - (segments - 1)) // segments)
    bg_c = bg if alpha >= 255 else (bg[0], bg[1], bg[2], alpha)
    fg_c = color if alpha >= 255 else (color[0], color[1], color[2], alpha)
    for i in range(segments):
        cx = x + i * (cell_w + 1)
        gpu.fill_rect((cx, y, cell_w, h), bg_c)
        if (i + 0.5) / segments <= ratio:
            gpu.fill_rect((cx, y, cell_w, h), fg_c)


def _layout_draw_menu_gpu(gpu, it, fonts, options=None):
    """GPU sibling of _layout_draw_menu (rows of cached-texture text)."""
    opts = options if options is not None else (it.get("_preview_options") or [])
    if not opts:
        return
    font = _resolve_layout_font(fonts, it)
    color = tuple(it.get("color") or (240, 240, 240))[:3]
    sel_color = tuple(it.get("selected_color") or color)[:3]
    sel_decor = it.get("selected_decor") or ">  {opt}  <"
    unsel_decor = it.get("unselected_decor") or "   {opt}   "
    line_h = int(it.get("line_height", 44))
    alpha = int(it.get("alpha", 255))
    align = (it.get("align") or "center").lower()
    cursor = it.get("_preview_cursor", 0)
    cx = int(it.get("x", 0))
    y = int(it.get("y", 0))
    for i, opt in enumerate(opts):
        sel = (i == cursor)
        text = (sel_decor if sel else unsel_decor).replace("{opt}", str(opt))
        c = sel_color if sel else color
        img = font.render(text, False, c)
        iw, ih = img.get_width(), img.get_height()
        line_y = y + i * line_h
        if align == "left":
            bx, by = cx, line_y - ih // 2
        elif align == "right":
            bx, by = cx - iw, line_y - ih // 2
        else:
            bx, by = cx - iw // 2, line_y - ih // 2
        gpu.blit(gpu.tex_for(img), pygame.Rect(bx, by, iw, ih), alpha=alpha)


def _draw_button_icon_gpu(gpu, x, y, h, action, fonts, color=None):
    """GPU sibling of _draw_button_icon: bake the pictogram once (keyed by
    action/size/color/device) and stream it. Returns the drawn width.

    The face-glyph circles poke ~1px past their declared (w,h) box (the active
    circle is drawn at rc+1, the west circle's left edge lands at box-x - 1).
    On a big software surface that's harmless, but a tight bake would clip the
    left/top edge — so pad the bake and blit it back offset by the pad, keeping
    the logical box at (x, y, w, h)."""
    w = _button_icon_width(action, h, fonts)
    if w <= 0:
        return 0
    PAD = _face_glyph_pad(h)
    sw, sh = w + 2 * PAD, h + 2 * PAD
    key = "btn:%s:%s:%s:%s" % (_HINT_DEVICE, action, h, color)
    surf = pygame.Surface((sw, sh), pygame.SRCALPHA)
    _draw_button_icon(surf, PAD, PAD, h, action, fonts, color=color)
    gpu.blit_dynamic(key, surf, pygame.Rect(x - PAD, y - PAD, sw, sh))
    return w


def _layout_draw_container_gpu(gpu, it, fonts, assets, template_vars, draw_one,
                               chrome_filter=None):
    """GPU sibling of _layout_draw_container — chrome via fill_rect/draw_rect,
    same free/stack/grid child placement, recursion through draw_one."""
    x = int(it.get("x", 0))
    y = int(it.get("y", 0))
    w = max(0, int(it.get("w", 0)))
    h = max(0, int(it.get("h", 0)))
    pad = int(it.get("padding", 0))
    layout = (it.get("layout") or "free").lower()
    alpha = int(it.get("alpha", 255))
    chrome = _container_chrome(it)
    bg = chrome.get("bg")
    border = chrome.get("border")
    border_w = int(chrome.get("border_width", 1)) if border else 0
    render_chrome = (chrome_filter is None
                     or bool(it.get("dynamic")) == chrome_filter)
    if render_chrome and w > 0 and h > 0:
        if bg is not None:
            col = (bg[0], bg[1], bg[2], alpha) if alpha < 255 else tuple(bg[:3])
            gpu.fill_rect((x, y, w, h), col)
        if border is not None and border_w > 0:
            bcol = tuple(border[:3])
            for i in range(border_w):
                if w - 2 * i > 0 and h - 2 * i > 0:
                    gpu.draw_rect((x + i, y + i, w - 2 * i, h - 2 * i), bcol)
        if chrome.get("caps") and bg is not None and border is not None:
            cap = tuple(chrome.get("caps_color") or (110, 160, 220))[:3]
            cap_len = int(chrome.get("caps_length", 5))
            gpu.fill_rect((x, y, cap_len, 1), cap)
            gpu.fill_rect((x + w - cap_len, y, cap_len, 1), cap)
            gpu.fill_rect((x, y + h - 1, cap_len, 1), cap)
            gpu.fill_rect((x + w - cap_len, y + h - 1, cap_len, 1), cap)
            gpu.fill_rect((x, y, 1, cap_len), cap)
            gpu.fill_rect((x + w - 1, y, 1, cap_len), cap)
            gpu.fill_rect((x, y + h - cap_len, 1, cap_len), cap)
            gpu.fill_rect((x + w - 1, y + h - cap_len, 1, cap_len), cap)
        title = chrome.get("title")
        if title and fonts:
            if "{" in title and template_vars:
                title = _safe_format(title, template_vars)
            t_color = tuple(chrome.get("title_color") or (160, 200, 240))[:3]
            t_font_scale = max(1, min(7, int(chrome.get("title_font", 1))))
            t_font = fonts.get(t_font_scale) or fonts.get("tiny")
            t_img = t_font.render(title, False, t_color)
            if bg is not None:
                gpu.fill_rect((x + 6, y - 1, t_img.get_width() + 6, 2), tuple(bg[:3]))
            gpu.blit(gpu.tex_for(t_img),
                     pygame.Rect(x + 9, y - 6, t_img.get_width(), t_img.get_height()))
    children = it.get("children") or ()
    if not children:
        return
    inner_x = x + pad
    inner_y = y + pad
    if layout == "stack":
        direction = (it.get("direction") or "vertical").lower()
        gap = int(it.get("gap", 0))
        cursor_x = inner_x
        cursor_y = inner_y
        for child in children:
            child = dict(child)
            cw = int(child.get("w", w - pad * 2 if w else 0) or 0)
            ch = int(child.get("h", h - pad * 2 if h else 0) or 0)
            child["x"] = cursor_x
            child["y"] = cursor_y
            draw_one(gpu, child, fonts, assets, template_vars)
            if direction == "horizontal":
                cursor_x += cw + gap
            else:
                cursor_y += ch + gap
        return
    if layout == "grid":
        rows = max(1, int(it.get("rows", 1)))
        cols = max(1, int(it.get("cols", 1)))
        gap_x = int(it.get("gap_x", it.get("gap", 0)))
        gap_y = int(it.get("gap_y", it.get("gap", 0)))
        inner_w = max(0, w - pad * 2)
        inner_h = max(0, h - pad * 2)
        cell_w = (inner_w - (cols - 1) * gap_x) // cols if cols else inner_w
        cell_h = (inner_h - (rows - 1) * gap_y) // rows if rows else inner_h
        cell_w = max(1, cell_w)
        cell_h = max(1, cell_h)
        max_cells = rows * cols
        for idx, child in enumerate(children):
            if idx >= max_cells:
                break
            r = idx // cols
            c = idx % cols
            cell_x = inner_x + c * (cell_w + gap_x)
            cell_y = inner_y + r * (cell_h + gap_y)
            cell_child = dict(child)
            anchor = child.get("anchor", "tl")
            ax = _LAYOUT_ANCHOR_AX.get(anchor, 0.0)
            ay = _LAYOUT_ANCHOR_AY.get(anchor, 0.0)
            cell_child["x"] = cell_x + int(cell_w * ax) + int(child.get("x", 0))
            cell_child["y"] = cell_y + int(cell_h * ay) + int(child.get("y", 0))
            if "w" not in child: cell_child["w"] = cell_w
            if "h" not in child: cell_child["h"] = cell_h
            draw_one(gpu, cell_child, fonts, assets, template_vars)
        return
    for child in children:
        offset_child = dict(child)
        offset_child["x"] = inner_x + int(child.get("x", 0))
        offset_child["y"] = inner_y + int(child.get("y", 0))
        draw_one(gpu, offset_child, fonts, assets, template_vars)


def _layout_draw_item_gpu(gpu, it, fonts, assets, template_vars, dynamic_filter=None):
    """GPU sibling of _layout_draw_item — same gating + per-kind dispatch."""
    kind = it.get("type")
    if dynamic_filter is not None and kind != "container":
        if bool(it.get("dynamic")) != dynamic_filter:
            return
    vw = it.get("visible_when")
    if vw and template_vars is not None:
        if not template_vars.get(vw):
            return
    if _hud_item_hidden(it.get("id")):
        return
    try:
        if kind == "text":
            txt = str(it.get("text") or "")
            if "{" in txt and template_vars:
                copy = dict(it)
                copy["text"] = _safe_format(txt, template_vars)
                it = copy
            _layout_draw_text_gpu(gpu, it, fonts, template_vars)
        elif kind == "rect":
            _layout_draw_rect_gpu(gpu, it)
        elif kind == "image":
            _layout_draw_image_gpu(gpu, it, assets)
        elif kind == "menu":
            _layout_draw_menu_gpu(gpu, it, fonts)
        elif kind == "progress_bar":
            _layout_draw_progress_bar_gpu(gpu, it, template_vars)
        elif kind == "tiered_bar":
            _layout_draw_tiered_bar_gpu(gpu, it, template_vars)
        elif kind == "btn_icon":
            _bcol = tuple(it["color"])[:3] if it.get("color") else None
            _draw_button_icon_gpu(gpu, int(it.get("x", 0)), int(it.get("y", 0)),
                                  int(it.get("h", 13)), it.get("action", ""), fonts,
                                  color=_bcol)
        elif kind == "container":
            _layout_draw_container_gpu(
                gpu, it, fonts, assets, template_vars,
                lambda *a: _layout_draw_item_gpu(*a, dynamic_filter=dynamic_filter),
                chrome_filter=dynamic_filter)
    except Exception as e:
        print(f"layout draw_gpu {kind} failed: {e}")


def draw_layout_overlay_gpu(gpu, screen_name, fonts, assets=None,
                            template_vars=None):
    """GPU sibling of draw_layout_overlay."""
    items = _layout_load().get(screen_name)
    if not items:
        return
    tvars = template_vars or {}
    for it in items:
        if _is_builtin_id(screen_name, it.get("id")):
            continue
        _layout_draw_item_gpu(gpu, it, fonts, assets, tvars)


def draw_layout_overlay(surf, screen_name, fonts, assets=None,
                        template_vars=None):
    """Render user-editable overlay items for the named screen. Skips
    items whose id matches a built-in element — those are rendered inline
    by the screen draw via get_element(). User-added items + previews of
    built-ins (used by the editor) flow through here.

    template_vars (optional) is the dict used to interpolate {name}
    placeholders in text + progress_bar values."""
    items = _layout_load().get(screen_name)
    if not items:
        return
    tvars = template_vars or {}
    for it in items:
        if _is_builtin_id(screen_name, it.get("id")):
            continue
        _layout_draw_item(surf, it, fonts, assets, tvars)


class _DynRecord:
    """Pre-resolved per-frame draw plan for one dynamic layout item.

    Built once at flatten time. Per-frame draw uses the attributes
    directly — no dict.get with defaults, no font lookup branching, no
    color tuple conversion, no anchor key string ops. Anchor offset for
    text is recomputed per frame because the rendered text size depends
    on the live template-formatted content. The parent container id is
    carried through so any per-frame container offset registered in
    `_HudCache.container_offsets` is applied — enabling whole-panel
    animations (shake, slide, etc.) without invalidating the cache.

    `fallback_spec` lets us route exotic items we don't have a fast path
    for (image, menu, alpha < 255 progress bars, etc.) through the
    original `_layout_draw_item` dispatcher with the resolved (x, y)."""
    __slots__ = ("kind", "id", "container_id", "x", "y", "visible_when",
                 # Text fields
                 "font", "color", "alpha", "anchor", "shadow",
                 "text_template", "text_has_braces", "text_has_dpad",
                 # Progress-bar fields
                 "w", "h", "value_raw", "max_raw", "segments_raw",
                 "color_raw", "bg_color_raw",
                 # Rect fields (reuse w, h, color, alpha + outline)
                 "outline",
                 # Fallback spec for kinds we don't fast-path
                 "fallback_spec")

    def __init__(self):
        # All fields default to None; the resolver fills in what's needed
        # per kind. Slots can't take per-attr defaults so we do it here.
        for slot in self.__slots__:
            setattr(self, slot, None)


def _resolve_dynamic_item(it, abs_x, abs_y, container_id, fonts):
    """Build a _DynRecord for a leaf item. `abs_x`/`abs_y` are the item's
    final on-surface position (after parent container offsets), and
    `container_id` is the immediate parent's id (or None) so a runtime
    container_offsets entry can shift the draw at frame time."""
    r = _DynRecord()
    r.x = abs_x
    r.y = abs_y
    r.id = it.get("id")
    r.container_id = container_id
    r.visible_when = it.get("visible_when")
    kind = it.get("type")
    if kind == "text":
        text = str(it.get("text") or "")
        r.kind = "text"
        r.font = _resolve_layout_font(fonts, it, default_scale=3)
        col = it.get("color")
        r.color = tuple(col)[:3] if col else (240, 240, 240)
        r.alpha = int(it.get("alpha", 255))
        r.anchor = it.get("anchor", "tl")
        r.shadow = bool(it.get("shadow"))
        r.text_template = text
        r.text_has_braces = "{" in text
        r.text_has_dpad = _rich_has_tokens(text)   # {dpad…} or {btn_*} -> cold path
    elif kind == "progress_bar":
        r.kind = "progress_bar"
        r.w = max(1, int(it.get("w", 60)))
        r.h = max(1, int(it.get("h", 6)))
        r.alpha = int(it.get("alpha", 255))
        r.value_raw = it.get("value", 0)
        r.max_raw = it.get("max", 1.0)
        r.segments_raw = it.get("segments", 10)
        r.color_raw = it.get("color")
        r.bg_color_raw = it.get("bg_color")
    elif kind == "rect":
        r.kind = "rect"
        r.w = max(0, int(it.get("w", 0)))
        r.h = max(0, int(it.get("h", 0)))
        col = it.get("color")
        r.color = tuple(col)[:3] if col else (60, 80, 120)
        r.alpha = int(it.get("alpha", 200))
        r.outline = int(it.get("outline", 0))
    else:
        # Image / menu / container / future kinds — keep the original
        # spec dict with absolute coords so the slow path can render it.
        r.kind = "fallback"
        fallback = dict(it)
        fallback["x"] = abs_x
        fallback["y"] = abs_y
        r.fallback_spec = fallback
    return r


def _flatten_dynamic_items(items, fonts, ox=0, oy=0, parent_id=None,
                           out=None):
    """Walk a layout subtree once and collect every item flagged
    `dynamic: True` into a flat list of pre-resolved _DynRecord
    instances. Container offsets are baked into the absolute (x, y) and
    each record remembers its parent container id so runtime animation
    can shift just that container's children. Only `free`-layout
    containers are fully flattened; `stack` / `grid` containers fall
    back to the per-frame walker. The HUD spec uses only `free`."""
    if out is None:
        out = []
    for it in items:
        kind = it.get("type")
        if kind == "container":
            layout = (it.get("layout") or "free").lower()
            if layout != "free":
                # Signal to caller: render this subtree via the walker.
                sentinel = _DynRecord()
                sentinel.kind = "needs_walker"
                out.append(sentinel)
                continue
            pad = int(it.get("padding", 0))
            inner_x = int(it.get("x", 0)) + ox + pad
            inner_y = int(it.get("y", 0)) + oy + pad
            _flatten_dynamic_items(it.get("children") or (), fonts,
                                   inner_x, inner_y,
                                   it.get("id") or parent_id, out)
        elif it.get("dynamic"):
            abs_x = int(it.get("x", 0)) + ox
            abs_y = int(it.get("y", 0)) + oy
            out.append(_resolve_dynamic_item(it, abs_x, abs_y, parent_id,
                                             fonts))
    return out


def _format_template(template, has_braces, tvars):
    """Cheap shortcut for the common "no placeholders" case so we skip
    str.format on static-text dynamic items entirely."""
    if not has_braces:
        return template
    return _safe_format(template, tvars)


def _fast_draw_text_record(surf, rec, tvars, ox, oy):
    text = _format_template(rec.text_template, rec.text_has_braces, tvars)
    if not text:
        return
    if rec.text_has_dpad and _rich_has_tokens(text):
        # Cold path: inline pictogram(s). The full helper handles it.
        spec = {
            "x": rec.x + ox, "y": rec.y + oy, "anchor": rec.anchor,
            "text": text, "font": 1, "color": list(rec.color),
            "alpha": rec.alpha,
        }
        _draw_text_with_icons(surf, spec, {"tiny": rec.font, 1: rec.font})
        return
    # Fast path: opaque + no shadow → look the rendered (text, color)
    # up in BitmapFont._render_cache and blit the cached surface in one
    # call. The pre-v0.9.185 path called BitmapFont.draw() (N per-glyph
    # blits per dynamic field per frame), which bypassed the cache —
    # ~3.8 ms of `game hud` steady-state was just per-glyph blit churn
    # for HUD fields whose (text, color) tuple barely changes
    # (score, timer, credits, weapon labels). render() is FIFO-bounded
    # at 256 entries so dynamic strings can't grow it unbounded; on a
    # cache miss it builds the surface, populates the cache, and we
    # blit. Render-time only — no game-state mutation, so rewind
    # rewind + replay paths are unaffected (the cache is rebuilt
    # naturally as scrub passes back over the same strings).
    if rec.alpha >= 255 and not rec.shadow:
        font = rec.font
        col = rec.color
        cache = font._render_cache
        cache_key = (text, col[0], col[1], col[2])
        img = cache.get(cache_key)
        if img is None:
            # Miss — render() handles cache insertion + FIFO eviction.
            img = font.render(text, False, col)
        anchor = rec.anchor
        if anchor == "tl":
            ax = ay = 0
        else:
            ax, ay = _layout_anchor_offset(
                anchor, img.get_width(), img.get_height())
        surf.blit(img, (rec.x + ox + ax, rec.y + oy + ay))
        return
    # Cold path: alpha < 255 or shadow needed → render() buffer so we can
    # use per-surface set_alpha. Centered text still recomputes anchor
    # from the rendered image size.
    img = rec.font.render(text, False, rec.color)
    anchor = rec.anchor
    if anchor == "tl":
        ax = ay = 0
    else:
        ax, ay = _layout_anchor_offset(anchor,
                                       img.get_width(), img.get_height())
    px = rec.x + ox + ax
    py = rec.y + oy + ay
    if rec.shadow:
        sh = rec.font.render(text, False, (0, 0, 0))
        sh.set_alpha(min(rec.alpha, 180))
        surf.blit(sh, (px + 1, py + 1))
    if rec.alpha < 255:
        img = img.copy()
        img.set_alpha(rec.alpha)
    surf.blit(img, (px, py))


def _fast_draw_progress_bar_record(surf, rec, tvars, ox, oy):
    # Resolve color / value / max / segments — most are plain numbers but
    # the spec also allows "{name}" templates that evaluate per frame.
    val_raw = _resolve_var(rec.value_raw, tvars, 0)
    if isinstance(val_raw, str) and "{" in val_raw:
        try:
            val_raw = val_raw.format(**tvars)
        except (KeyError, IndexError, ValueError):
            val_raw = 0
    try:
        val = float(val_raw)
    except (TypeError, ValueError):
        val = 0.0
    mx_raw = _resolve_var(rec.max_raw, tvars, 1.0)
    try:
        mx = float(mx_raw) or 1.0
    except (TypeError, ValueError):
        mx = 1.0
    ratio = max(0.0, min(1.0, val / mx if mx > 0 else 0.0))
    segments = max(1, int(_resolve_var(rec.segments_raw, tvars, 10)))
    color_raw = _resolve_var(rec.color_raw, tvars, (80, 220, 255))
    bg_raw = _resolve_var(rec.bg_color_raw, tvars, (40, 46, 70))
    color = tuple(color_raw)[:3] if color_raw else (80, 220, 255)
    bg = tuple(bg_raw)[:3] if bg_raw else (40, 46, 70)
    w = rec.w
    h = rec.h
    cell_w = max(1, (w - (segments - 1)) // segments)
    x = rec.x + ox
    y = rec.y + oy
    if rec.alpha >= 255:
        for i in range(segments):
            cell = pygame.Rect(x + i * (cell_w + 1), y, cell_w, h)
            pygame.draw.rect(surf, bg, cell)
            if (i + 0.5) / segments <= ratio:
                pygame.draw.rect(surf, color, cell)
    else:
        target = pygame.Surface((w, h), pygame.SRCALPHA)
        for i in range(segments):
            cell = pygame.Rect(i * (cell_w + 1), 0, cell_w, h)
            pygame.draw.rect(target, bg, cell)
            if (i + 0.5) / segments <= ratio:
                pygame.draw.rect(target, color, cell)
        target.set_alpha(rec.alpha)
        surf.blit(target, (x, y))


def _fast_draw_rect_record(surf, rec, tvars, ox, oy):
    x = rec.x + ox
    y = rec.y + oy
    if rec.alpha >= 255:
        if rec.outline > 0:
            pygame.draw.rect(surf, rec.color, (x, y, rec.w, rec.h),
                             rec.outline)
        else:
            pygame.draw.rect(surf, rec.color, (x, y, rec.w, rec.h))
    else:
        s = pygame.Surface((rec.w, rec.h), pygame.SRCALPHA)
        col = (rec.color[0], rec.color[1], rec.color[2], rec.alpha)
        if rec.outline > 0:
            pygame.draw.rect(s, col, (0, 0, rec.w, rec.h), rec.outline)
        else:
            s.fill(col)
        surf.blit(s, (x, y))


def _draw_main_swap_hints(surf, fonts, assets, player):
    """Bottom-corner labels showing the left/right shoulder hold-to-swap
    binds plus a glyph of the projectile they fire. Painted on top of the
    HUD so the currently-active main is highlighted in real time. Labels
    are just "L" / "R" because either physical shoulder (L1 OR L2 / R1
    OR R2) triggers the swap-and-fire shortcut."""
    lo = player.loadout
    active = lo.main_type
    glyphs = getattr(Bullet, "_glyphs", {}) or {}
    font = fonts.get(1) or fonts.get("tiny")
    # Left corner: L hint (Rail). Right corner: R hint (Ball).
    # Symmetric layout — text outside, glyph inside.
    bottom_y = PLAY_H - 4
    pad = 4
    for slot, kind, label in (("left", "rail", "L"),
                              ("right", "ball", "R")):
        color = MAIN_BULLET_STYLE[kind]["color"]
        is_active = (active == kind)
        text_color = color if is_active else (110, 120, 140)
        # Glyph asset still uses the legacy "pulse" filename — BMPs aren't
        # auto-pushed by the in-game updater, so renaming the asset on disk
        # would break visuals on existing devices until a full SD redeploy.
        glyph_key = "glyph_pulse" if kind == "rail" else f"glyph_{kind}"
        glyph = glyphs.get(glyph_key)
        # Render text first to measure.
        text_surf = font.render(label, False, text_color)
        tw = text_surf.get_width()
        th = text_surf.get_height()
        gw = glyph.get_width() if glyph is not None else 6
        gh = glyph.get_height() if glyph is not None else 8
        block_w = tw + 3 + gw
        if slot == "left":
            bx = pad
            text_x = bx
            glyph_x = bx + tw + 3
        else:
            bx = PLAY_W - pad - block_w
            text_x = bx
            glyph_x = bx + tw + 3
        ty = bottom_y - th
        gy = bottom_y - gh
        # Small backing plate so the labels stay legible over busy art.
        bg = pygame.Surface((block_w + 4, max(th, gh) + 2), pygame.SRCALPHA)
        bg.fill((10, 14, 22, 170))
        surf.blit(bg, (bx - 2, bottom_y - max(th, gh) - 1))
        surf.blit(text_surf, (text_x, ty))
        if glyph is not None:
            if is_active:
                surf.blit(glyph, (glyph_x, gy))
            else:
                # Dim the inactive glyph by drawing through a black overlay.
                dim = glyph.copy()
                dim.fill((0, 0, 0, 140), special_flags=pygame.BLEND_RGBA_MULT)
                surf.blit(dim, (glyph_x, gy))
        else:
            pygame.draw.rect(surf, color, (glyph_x, gy, gw, gh))


_HUD_ANIM_DELAY = 0.5   # bg fades black → HUD_BG over this window before
                        # the panels start animating in.


def hud_draw(surf, fonts, assets, player, save, level_name, score, time_left,
             level_t=None, credits_earned=0):
    """Render the in-game HUD strip.

    `level_t` (optional) is seconds since the level started. When
    supplied AND still within the bg-fade + bouncy-stagger window, the
    HUD renders via a two-phase entry:

      level_t ∈ [0, _HUD_ANIM_DELAY)  — strip bg lerps black → HUD_BG,
                                        no panels visible yet.
      level_t ≥ _HUD_ANIM_DELAY       — bg is solid; the 6 chrome
                                        panels stream in using the
                                        "hud" profile.

    Once past the combined settle time (or when `level_t is None`), the
    cached-chrome + fast-dynamic path takes over with zero per-frame
    animation overhead.
    """
    # Compute tvars once — used by both the animated and fast paths.
    chrome_vars = _hud_chrome_vars(level_name, player.loadout, save)
    tvars = {**chrome_vars,
             **_hud_dyn_vars(player, save, score, time_left, credits_earned)}

    if level_t is not None:
        anim_t = max(0.0, level_t - _HUD_ANIM_DELAY)
        anim_settle = _SIDE_STRIP_ANIM_SETTLE.get("hud", 99.0)
        if anim_t < anim_settle:
            # Pre-anim + animation paint always covers the strip area
            # so the playfield never bleeds through. Start with a
            # solid fill from black to HUD_BG keyed off level_t; the
            # animation function then draws panels on top with
            # skip_bg=True (its own bg fade is bypassed).
            bg_progress = max(0.0, min(1.0, level_t / _HUD_ANIM_DELAY))
            bg_col = (int(HUD_BG[0] * bg_progress),
                      int(HUD_BG[1] * bg_progress),
                      int(HUD_BG[2] * bg_progress))
            pygame.draw.rect(surf, bg_col, (HUD_X, 0, HUD_W, SCREEN_H))
            for it in resolved_layout_tree("hud"):
                _draw_animated_side_strip(surf, it, fonts, assets, tvars,
                                          anim_t, mode="hud",
                                          x_offset=HUD_X, skip_bg=True)
            # User overlay items still draw on top (matches the post-
            # anim path below).
            draw_layout_overlay(surf, "hud", fonts, assets, template_vars=tvars)
            return

    # 1) Cached chrome (rebuilt only on loadout / tier-unlock / mission
    # / layout change — unlock state is in the cache key now so newly
    # unlocked tiers grow the weapon bars next frame).
    key = _hud_cache_key(player, level_name, save)
    if key != _HudCache.key or _HudCache.surface is None:
        _HudCache.surface = _build_hud_chrome(fonts, level_name,
                                              player.loadout, save)
        _HudCache.key = key
    surf.blit(_HudCache.surface, (HUD_X, 0))

    # 2) Per-frame dynamic items via pre-resolved records. The records
    # cache invalidates only when the editor bumps _LAYOUT_REV — during
    # gameplay it's a constant single-list iteration with no dict.get
    # lookups and no font/color resolution per frame.
    #
    # Dynamic items draw DIRECTLY onto `surf` (the screen) at +HUD_X,
    # not into an intermediate SRCALPHA scratch surface. The chrome blit
    # above just repainted the HUD region, so any old dynamic pixels are
    # already cleared. Skipping dyn_surf saves a per-frame 160x480
    # SRCALPHA fill + alpha blit (~1 ms on the mali driver).
    # `tvars` was already built at the top for the animation gate.
    if (_HudCache.dyn_records is None
            or _HudCache.dyn_records_rev != _LAYOUT_REV):
        _HudCache.dyn_records = _flatten_dynamic_items(
            resolved_layout_tree("hud"), fonts)
        _HudCache.dyn_records_rev = _LAYOUT_REV
    records = _HudCache.dyn_records
    # If a stack/grid container was encountered the first record will be
    # a "needs_walker" sentinel; bail to the full tree walk for safety.
    if records and records[0].kind == "needs_walker":
        # Walker path still needs a scratch surface — it expects HUD-
        # local coords. Pre-allocate once and reuse.
        dyn_surf = _HudCache.dyn_surf
        if dyn_surf is None:
            dyn_surf = pygame.Surface((HUD_W, SCREEN_H), pygame.SRCALPHA)
            _HudCache.dyn_surf = dyn_surf
        dyn_surf.fill((0, 0, 0, 0))
        for it in resolved_layout_tree("hud"):
            _layout_draw_item(dyn_surf, it, fonts, assets, tvars,
                              dynamic_filter=True)
        surf.blit(dyn_surf, (HUD_X, 0))
    else:
        offsets = _HudCache.container_offsets
        # Bake HUD_X into the per-record offset so coords map straight
        # to the screen surface.
        for rec in records:
            if rec.visible_when and not tvars.get(rec.visible_when):
                continue
            if _hud_item_hidden(rec.id):
                continue
            cox, coy = (offsets.get(rec.container_id, (0, 0))
                        if offsets else (0, 0))
            ox = cox + HUD_X
            oy = coy
            kind = rec.kind
            if kind == "text":
                _fast_draw_text_record(surf, rec, tvars, ox, oy)
            elif kind == "progress_bar":
                _fast_draw_progress_bar_record(surf, rec, tvars, ox, oy)
            elif kind == "rect":
                _fast_draw_rect_record(surf, rec, tvars, ox, oy)
            elif kind == "fallback":
                # Fallback spec carries HUD-local x/y; translate to
                # screen coords for direct draw.
                spec = dict(rec.fallback_spec)
                spec["x"] = int(spec.get("x", 0)) + ox
                spec["y"] = int(spec.get("y", 0)) + oy
                _layout_draw_item(surf, spec, fonts, assets, tvars)

    # 3) User overlay items (any items in layout.json["hud"] that don't
    #    match a built-in id — same as for every other screen).
    draw_layout_overlay(surf, "hud", fonts, assets, template_vars=tvars)


# =============================================================================
# PLAY STATE
# =============================================================================

def _prepare_station_start(img):
    """Scale 2x and rotate 180° — the launch pad sits at the bottom with its
    docking arm pointing up, so the player visibly lifts out of it."""
    big = pygame.transform.scale2x(img)
    return pygame.transform.rotate(big, 180)


def _prepare_station_end(img):
    """Scale 2x — the destination station hangs at the top in normal
    orientation, docking arm pointing down toward the arriving ship."""
    return pygame.transform.scale2x(img)


# ──────────────────────────────────────────────────────────────────────────
# NOHIT rewind: snapshot/restore helpers + ring buffer
# ──────────────────────────────────────────────────────────────────────────
# Per-frame snapshot of mutable play-state so the East button can scrub
# game time backwards through the play loop. pygame.Rect fields are
# serialised as a tagged 5-tuple so _restore_obj can rebuild them
# in-place; shared refs (asset dicts, surfaces) are stored shallow
# because they aren't mutated per frame.

_REWIND_RECT_TAG = "__rect__"

# Per-class cache of the deduplicated __slots__ names across the MRO. A
# class's slot layout is immutable, so we walk the MRO once per class
# instead of on every _snap_obj call (this snapshot runs for every live
# object every forward frame, so it was the single hottest reflection
# path in the rewind capture).
_SNAP_SLOTS_CACHE = {}


def _snap_slot_names(cls):
    names = _SNAP_SLOTS_CACHE.get(cls)
    if names is None:
        ordered = []
        seen = set()
        for klass in cls.__mro__:
            slots = getattr(klass, "__slots__", ())
            if isinstance(slots, str):
                slots = (slots,)
            for k in slots:
                if k not in seen:
                    seen.add(k)
                    ordered.append(k)
        names = tuple(ordered)
        _SNAP_SLOTS_CACHE[cls] = names
    return names


def _snap_obj(obj, skip=()):
    """Capture both __dict__ entries AND every __slots__ declared anywhere
    in the MRO. A subclass without its own __slots__ inherits its parent's
    slots AND gains a __dict__ (Spark(Particle), Missile(Bullet)) — taking
    only one branch would silently miss the actual data. The slot-name list
    per class is cached (see _snap_slot_names); slot attrs never collide
    with __dict__ keys, so a key already in `out` came from the dict and is
    skipped."""
    out = {}
    d = getattr(obj, "__dict__", None)
    if d:
        for k, v in d.items():
            if k in skip:
                continue
            if isinstance(v, pygame.Rect):
                out[k] = (_REWIND_RECT_TAG, v.x, v.y, v.w, v.h)
            else:
                out[k] = v
    for k in _snap_slot_names(type(obj)):
        if k in skip or k in out:
            continue
        try:
            v = getattr(obj, k)
        except AttributeError:
            continue
        if isinstance(v, pygame.Rect):
            out[k] = (_REWIND_RECT_TAG, v.x, v.y, v.w, v.h)
        else:
            out[k] = v
    return out


def _restore_obj(obj, snap):
    for k, v in snap.items():
        # `==` (not `is`): a saved-replay round-trip through pickle yields a
        # distinct "__rect__" string object, so identity would miss it.
        if (isinstance(v, tuple) and len(v) == 5
                and v[0] == _REWIND_RECT_TAG):
            cur = getattr(obj, k, None)
            if isinstance(cur, pygame.Rect):
                cur.x, cur.y, cur.w, cur.h = v[1], v[2], v[3], v[4]
            else:
                try:
                    setattr(obj, k, pygame.Rect(v[1], v[2], v[3], v[4]))
                except (AttributeError, TypeError):
                    pass
        else:
            try:
                setattr(obj, k, v)
            except AttributeError:
                pass


# Shared static references that must NEVER be captured in a per-frame snapshot:
# `_assets` is the whole game-assets dict (surfaces), held by every Enemy and
# some Bullets. It's identical every frame and reconstructable on restore, but
# the streamed-per-frame replay format re-serialises it once PER ENTITY PER
# FRAME (no cross-frame pickle memoisation) — ~7 KB each, which ballooned a
# single level's replay to 24 MB compressed / 258 MB decompressed and OOM'd the
# RG on load. Stripped here, re-attached in _restore_snapshot. (Pre frame-locked
# rewind it was kept to identify entities; index+recompute restore makes it
# redundant now.) The player's `assets` is dropped via _PLAYER_SKIP instead
# (the player is always restored in place, so it keeps its live reference).
_REWIND_ASSET_SKIP = ("_assets",)


def _snap_list(items):
    return [(type(it), _snap_obj(it, skip=_REWIND_ASSET_SKIP)) for it in items]


def _restore_list(live_list, snap_list):
    while len(live_list) > len(snap_list):
        live_list.pop()
    for i, (cls, sn) in enumerate(snap_list):
        if i < len(live_list):
            it = live_list[i]
            if type(it) is not cls:
                new_it = cls.__new__(cls)
                _restore_obj(new_it, sn)
                live_list[i] = new_it
            else:
                _restore_obj(it, sn)
        else:
            new_it = cls.__new__(cls)
            _restore_obj(new_it, sn)
            live_list.append(new_it)


def _stable_wave_seed_base(level_key):
    """Hash level_key to a stable 32-bit integer. Used as the base for
    per-wave seeds — each timeline_idx gets `base ^ (idx * GOLDEN)` so
    waves within a level get distinct streams while the level's overall
    "shape" is reproducible across runs.

    hashlib.md5 instead of Python's hash() because the latter is salted
    per-process (PYTHONHASHSEED) and would give a different stream each
    launch — pre-rolling the same wave for rewind+replay needs the seed
    to be process-independent."""
    key = str(level_key or "").encode("utf-8")
    return int.from_bytes(hashlib.md5(key).digest()[:4], "big")


def _wave_seed(base, idx):
    return (base ^ ((idx + 1) * 0x9E3779B9)) & 0xFFFFFFFF


# ── Replay "ghost branch" overlay tuning ──────────────────────────────────
# When the player rewinds and resumes, the abandoned future is salvaged and
# replayed as translucent animated copies of the entity field. Only the
# divergence is drawn — ghost entities sitting on the exact same pixel as a
# kept-timeline entity are skipped (most enemies follow player-independent
# paths and would otherwise just double-image at 0.4 alpha).
_GHOST_ALPHA = 153            # 0.6 * 255
_GHOST_SHATTER_ALPHA = 204    # 0.8 * 255 — the death shatter rides brighter
                              # than the rest of the ghost field (it's the
                              # climax, ramped up so the split reads clearly)
_GHOST_FRAME_BUDGET = 24000   # cap on total salvaged frames (~400 s @ 60 fps);
                              # over budget, the most-redundant interior
                              # branch drops (endpoints protected) so a
                              # rewind-happy run thins by spread, not the
                              # level start, without unbounded growth.
_GHOST_LIST_NAMES = ("bullets", "balls", "enemies", "pickups", "sparks",
                     "lasers", "rays", "explosions", "float_texts")


# Ghost-entity glitch: a stripped-down, much subtler take on the rewind CRT
# effect (tears + scanlines only — no chroma flash, no vsync bar) applied to
# the translucent abandoned-branch ghosts so they read as "rewound" timelines.
# Dedicated tuning, separate from the in-game _CRT_PROFILE_PLAY.
@dataclass(frozen=True)
class GhostGlitchProfile:
    enabled: bool = True
    tears: float = 1.9          # ~expected tear bands per frame (+20%)
    tear_h_min: int = 2
    tear_h_max: int = 8
    tear_shift_max: int = 5     # +20% displacement
    scanline_step: int = 3      # darken every Nth row
    scanline_dim: int = 120     # alpha removed on scanline rows (darker)


_GHOST_GLITCH = GhostGlitchProfile()
_GHOST_SCANLINE_CACHE = {}
# Dedicated RNG for the tear animation, advanced every RENDER frame regardless
# of the restored sim RNG — so the glitch keeps shimmering even when the replay
# is paused (the sim RNG is restored to the same state each paused frame).
_GHOST_GLITCH_RNG = random.Random()
# A ghost dissolves over the last _GHOST_DEATH_DUR seconds of its branch:
# glitch + scanlines ramp to 2× and alpha fades to 0 (see _draw_ghosts).
_GHOST_DEATH_DUR = 0.2


def _ghost_scanline_mask(w, h, dim_mul=1.0):
    """White mask whose alpha is full except every Nth row, which is dimmed by
    scanline_dim*dim_mul. BLEND_RGBA_MULT'd onto the ghost layer it scanlines
    ONLY the ghost pixels (transparent gaps stay transparent). Cached per
    (w, h, dim)."""
    p = _GHOST_GLITCH
    dim = min(255, int(round(p.scanline_dim * dim_mul)))
    key = (w, h, dim)
    m = _GHOST_SCANLINE_CACHE.get(key)
    if m is None:
        m = pygame.Surface((w, h), pygame.SRCALPHA)
        m.fill((255, 255, 255, 255))
        a = max(0, 255 - dim)
        for y in range(0, h, p.scanline_step):
            m.fill((255, 255, 255, a), (0, y, w, 1))
        _GHOST_SCANLINE_CACHE[key] = m
    return m


def _ghost_scanline_mod(w, h, dim_mul=1.0):
    """RGB sibling of _ghost_scanline_mask for the GPU path: white everywhere
    except every Nth row, dimmed to (255-dim). MOD-blended (SDL_BLENDMODE_MOD,
    dstRGB*=srcRGB/255, dstA untouched) onto the ghost target it dims the ghost
    pixels' brightness on scanline rows WITHOUT touching alpha — so transparent
    gaps stay transparent and the result composites identically to the software
    alpha-mask look. Opaque (no SRCALPHA): MOD ignores source alpha."""
    p = _GHOST_GLITCH
    dim = min(255, int(round(p.scanline_dim * dim_mul)))
    v = max(0, 255 - dim)
    s = pygame.Surface((w, h))
    s.fill((255, 255, 255))
    if v < 255:
        for y in range(0, h, p.scanline_step):
            s.fill((v, v, v), (0, y, w, 1))
    return s


def _apply_ghost_glitch(surf, glitch_mul=1.0, scanline_mul=1.0, do_scanline=True):
    """Subtle rewind-style glitch on the ghost layer: a few short in-place
    horizontal tear-scrolls + per-row scanline dimming. No chroma / vsync.
    Operates on the SRCALPHA ghost surface so only ghost pixels are affected
    (the scanline mask multiplies alpha; tears just scroll existing pixels).
    `glitch_mul` scales the tear count + displacement, `scanline_mul` the
    scanline darkness — both 2× during a ghost's end-of-branch dissolve.
    `do_scanline=False` applies only the tears (the GPU path does the scanline
    + fade + composite as GPU passes instead — see _draw_ghosts_gpu)."""
    p = _GHOST_GLITCH
    if not p.enabled or glitch_mul <= 0.0:
        return
    rng = _GHOST_GLITCH_RNG     # advances per render frame → animates when paused
    w, h = surf.get_size()
    n = int(p.tears * glitch_mul + rng.random())
    shift_max = max(1, int(round(p.tear_shift_max * glitch_mul)))
    for _ in range(n):
        if h <= p.tear_h_max + 1:
            break
        ty = rng.randint(0, h - p.tear_h_max - 1)
        th = rng.randint(p.tear_h_min, p.tear_h_max)
        shift = rng.randint(-shift_max, shift_max)
        if shift:
            try:
                surf.subsurface(pygame.Rect(0, ty, w, th)).scroll(shift, 0)
            except (ValueError, pygame.error):
                pass
    if do_scanline:
        surf.blit(_ghost_scanline_mask(w, h, scanline_mul), (0, 0),
                  special_flags=pygame.BLEND_RGBA_MULT)


# Replay shuttle: up/down is a jog/shuttle on PLAYBACK SPEED, not a seek.
# Holding in the SAME direction as the current motion accelerates gently
# (_SHUTTLE_ACCEL — the "hold longer = faster" ramp toward ±_SHUTTLE_MAX);
# pushing the OPPOSITE way brakes snappily at _SHUTTLE_BRAKE (same fast rate as
# releasing) through zero, then resumes the gentle ramp into reverse — so
# reversing from full speed doesn't crawl. Releasing decays toward the rest
# speed (0 when paused, else 1×) at _SHUTTLE_RELEASE.
_SHUTTLE_MAX = 8.0
_SHUTTLE_ACCEL = 2.0       # ×/sec, gentle ramp when reinforcing motion
_SHUTTLE_BRAKE = 16.0      # ×/sec, fast decel when the stick opposes motion
_SHUTTLE_RELEASE = 16.0    # ×/sec decay toward rest on release (8 → 0 in 0.5 s)
_SHUTTLE_DEADZONE = 0.06

# Mouse-wheel seek acceleration: consecutive same-direction scrolls walk an
# explicit step table (seconds), holding at the last entry. The slow head is
# deliberate, so the player can nudge back and forth around a single event
# without overshooting; sustained scrolling ramps up to a fast 4 s/scroll for
# travel. A flick the OTHER way OR an idle gap past _SEEK_WINDOW resets to the
# head, so direction changes stay fine-grained. Separate tables per direction:
# forward (scroll-up, toward level end) gets a fine 0.1 s head for precise
# pin-pointing; backward (scroll-down, rewind) is coarser at a 0.5 s head.
# Timed in real wall-clock (accumulated frame dt); Particle._sim_t is frozen
# in replay.
_SEEK_STEPS_FWD = (0.1, 0.1, 0.1, 0.2, 0.4, 1.0, 2.0, 4.0)   # cap 4 s, held
_SEEK_STEPS_BACK = (0.5, 0.5, 0.5, 1.0, 2.0, 4.0)            # cap 4 s, held
_SEEK_WINDOW = 0.25

# Replay timeline bar geometry — a vertical bar that FLOATS over the right
# edge of the (now full-screen) play area. Bottom = level start, top = end
# (the ship flies upward). Thickness swells where ghost branches overlap.
_REPLAY_BAR_TOP = 42
_REPLAY_BAR_BOT = SCREEN_H - 70    # leave room below for control hints
_REPLAY_BAR_BASE_W = 6             # bar thickness with no ghost branches
_REPLAY_BAR_PER_BRANCH = 4         # extra px per overlapping ghost branch
_REPLAY_BAR_MAX_W = 30
_REPLAY_BAR_AREA_W = 40            # width of the bar scratch surface
_REPLAY_BAR_X = SCREEN_W - _REPLAY_BAR_AREA_W   # blit x (right-edge flush)


# ──────────────────────────────────────────────────────────────────────────
# Saved mission replay (de)serialisation — faithful full-buffer, zlib.
# ──────────────────────────────────────────────────────────────────────────
# The rewind buffer + ghost branches reference live pygame.Surfaces and class
# objects that can't be pickled. We map every surface to a stable key (its
# path in the asset tree, which make_assets rebuilds identically each launch)
# and every class to its name, then pickle + zlib the primitive result. On
# load the keys/names resolve through the new session's assets/classes. Sim-
# only object refs (weakrefs, enemy refs) are dropped — playback only restores
# + draws, never simulates.
MREPLAY_DIR = SAVE_PATH.parent / "mission_replays"
MREPLAY_VERSION = 4   # v4: per-frame snapshots are delta-from-base compressed
                      # in the live buffer + packed RNG (see RewindBuffer /
                      # _snapshot). New saves use the `.zr4` extension so OLD
                      # `.zrp` recordings (legacy shared + per-profile v3) are
                      # simply not found -> invisible on the map, left on disk
                      # (not converted). v3 header metadata layout is unchanged.
_MREPLAY_MIN_VERSION = 2   # oldest version still loadable
MREPLAY_VERSION_V2 = 2
_MREPLAY_SURF_TAG = "\x00S"
_MREPLAY_CLS_TAG = "\x00C"
_MREPLAY_CLASSES = None


def _mreplay_surface_registry(assets):
    """(by_id, by_key) over every Surface reachable from the asset tree plus
    the Bullet glyph / ExplosionRing fx class caches. Rebuilt per call so a
    fresh session (new Surface objects) maps the same keys to its own live
    surfaces."""
    by_id, by_key = {}, {}

    def walk(obj, path):
        if isinstance(obj, pygame.Surface):
            by_id[id(obj)] = path
            by_key.setdefault(path, obj)
            return
        if isinstance(obj, dict):
            for k, v in obj.items():
                walk(v, f"{path}.{k}" if path else str(k))
        elif isinstance(obj, (list, tuple)):
            for i, v in enumerate(obj):
                walk(v, f"{path}[{i}]")

    walk(assets, "")
    for cls, attr in ((Bullet, "_glyphs"), (ExplosionRing, "_fx")):
        d = getattr(cls, attr, None)
        if isinstance(d, dict):
            walk(d, f"@{cls.__name__}.{attr}")
    return by_id, by_key


def _mreplay_classes():
    global _MREPLAY_CLASSES
    if _MREPLAY_CLASSES is None:
        reg = {}

        def add(c):
            reg[c.__name__] = c
            for s in c.__subclasses__():
                add(s)

        for base in (Bullet, Particle, Pickup, Enemy, Laser, Ray,
                     ExplosionRing, FloatText, Ball):
            add(base)
        _MREPLAY_CLASSES = reg
    return _MREPLAY_CLASSES


def _mreplay_encode(v, by_id):
    if isinstance(v, pygame.Surface):
        return (_MREPLAY_SURF_TAG, by_id.get(id(v)))
    if v is None or isinstance(v, (int, float, bool, str)):
        return v
    if isinstance(v, type):
        return (_MREPLAY_CLS_TAG, v.__name__)
    if isinstance(v, tuple):
        return tuple(_mreplay_encode(x, by_id) for x in v)
    if isinstance(v, list):
        return [_mreplay_encode(x, by_id) for x in v]
    if isinstance(v, dict):
        return {k: _mreplay_encode(x, by_id) for k, x in v.items()}
    # Unknown object (weakref, entity ref, function) — sim-only, drop it.
    return None


def _mreplay_decode(v, by_key, classes):
    if isinstance(v, tuple):
        if len(v) == 2 and v[0] == _MREPLAY_SURF_TAG:
            return by_key.get(v[1])
        if len(v) == 2 and v[0] == _MREPLAY_CLS_TAG:
            return classes.get(v[1], Bullet)
        return tuple(_mreplay_decode(x, by_key, classes) for x in v)
    if isinstance(v, list):
        return [_mreplay_decode(x, by_key, classes) for x in v]
    if isinstance(v, dict):
        return {k: _mreplay_decode(x, by_key, classes) for k, x in v.items()}
    return v


def _snap_pos_key(objdict):
    """EXACT position signature of an ENTITY SNAPSHOT dict — mirror of the live
    `_ghost_pos_key` (float x,y when present, no pixel rounding). Used to prune
    branch entities that sit exactly where a kept-timeline entity does."""
    x = objdict.get("x")
    if x is not None:
        r = objdict.get("rect")
        if isinstance(r, tuple) and len(r) == 5 and r[0] == _REWIND_RECT_TAG:
            return (x, objdict.get("y", 0.0), r[3], r[4])
        return (x, objdict.get("y", 0.0))
    r = objdict.get("rect")
    if isinstance(r, tuple) and len(r) == 5 and r[0] == _REWIND_RECT_TAG:
        return (r[1], r[2], r[3], r[4])
    x0 = objdict.get("x0")
    if x0 is not None:
        return (x0, objdict.get("y0", 0.0),
                objdict.get("x1", 0.0), objdict.get("y1", 0.0))
    return None


def _prune_branches(snaps, branches):
    """Return copies of the ghost branches with every entity (and the player)
    that sits exactly where the MAIN timeline has one at the same sim-time
    removed — the saved equivalent of the draw-time divergence-skip. Only the
    divergence is kept, which on a typical (similar-path) rewind is a small
    fraction of the frame. Live in-memory branches are NOT touched; this only
    slims the on-disk copy. A frame whose player matches main stores
    player=None so the loaded ghost knows not to draw the ship that frame."""
    if not snaps:
        return branches
    # Per-frame sim-times. A _CompressedFrames buffer precomputes them (`.times`),
    # so use that instead of decoding every frame here (the keycache still decodes
    # only the handful of main frames that branch frames actually align to).
    _t = getattr(snaps, "times", None)
    main_elapsed = list(_t) if _t is not None and len(_t) == len(snaps) \
        else [s["scalars"][2] for s in snaps]
    keycache = {}

    def main_keys(mi):
        ks = keycache.get(mi)
        if ks is None:
            m = snaps[mi]
            ks = {cat: {k for k in (_snap_pos_key(e[1])
                                    for e in m.get(cat, ())) if k is not None}
                  for cat in _GHOST_LIST_NAMES}
            ks["__player__"] = _snap_pos_key(m.get("player") or {})
            keycache[mi] = ks
        return ks

    out = []
    for br in branches:
        pframes = []
        for f in br["frames"]:
            t = f["scalars"][2]
            mi = bisect.bisect_left(main_elapsed, t)
            if mi >= len(snaps):
                mi = len(snaps) - 1
            elif (mi > 0
                    and abs(main_elapsed[mi - 1] - t) < abs(main_elapsed[mi] - t)):
                mi -= 1
            ks = main_keys(mi)
            nf = dict(f)
            for cat in _GHOST_LIST_NAMES:
                seen = ks[cat]
                nf[cat] = [e for e in f.get(cat, ())
                           if _snap_pos_key(e[1]) not in seen]
            pk = _snap_pos_key(f.get("player") or {})
            if pk is not None and pk == ks["__player__"]:
                nf["player"] = None
            pframes.append(nf)
        out.append({"anchor_t": br["anchor_t"], "frames": pframes})
    return out


def _proc_rss_mb():
    """Process resident-set size in MB (Linux /proc/self/statm), else 0. Cheap
    diagnostic for spotting a memory leak/thrash in last_run.log; never raises."""
    try:
        with open("/proc/self/statm") as fh:
            pages = int(fh.read().split()[1])   # resident pages
        return pages * (os.sysconf("SC_PAGE_SIZE") if hasattr(os, "sysconf") else 4096) // (1024 * 1024)
    except Exception:
        return 0


def _mem_available_mb():
    """System available memory in MB (Linux /proc/meminfo MemAvailable), or None
    if it can't be read (non-Linux / unavailable → caller skips the guard)."""
    try:
        with open("/proc/meminfo") as fh:
            for line in fh:
                if line.startswith("MemAvailable:"):
                    return int(line.split()[1]) // 1024   # kB -> MB
    except Exception:
        pass
    return None


# Abort a replay LOAD (which decodes the whole buffer into RAM) before it
# exhausts memory and thrashes the device into an unrecoverable freeze. A long
# rewind-heavy run can decode to hundreds of MB; on a ~1 GB handheld that OOMs.
# Failing the load cleanly (back to the map) is far better than wedging the box.
_MREPLAY_LOAD_MIN_MB = 110


class _MreplayTooBig(Exception):
    """Raised to abort a replay load when free memory drops too low."""


def _mreplay_profile_dir(profile):
    """Per-profile subdir keyed by profile INDEX (p0..pN), not name — stable if
    the star names are ever renamed/reordered. Accepts a name (resolved through
    PROFILE_NAMES) or an int index; unknown → p0."""
    if isinstance(profile, int):
        idx = profile
    else:
        try:
            idx = PROFILE_NAMES.index((profile or "").upper())
        except ValueError:
            idx = 0
    return f"p{idx}"


def _mreplay_path(level_key, profile):
    """Per-profile replay path: mission_replays/<p_idx>/<level>.zr4. The `.zr4`
    extension is the v4 format gate — old `.zrp` recordings (legacy shared AND
    per-profile v3) don't match it, so they're invisible WITHOUT a header read
    and stay on disk untouched (not converted). Each profile keeps its own
    recording; there is NO cross-profile or legacy fallback."""
    return MREPLAY_DIR / _mreplay_profile_dir(profile) / f"{level_key}.zr4"


def _resolve_mreplay_path(level_key, profile):
    """The path to LOAD from — strictly the profile's own v4 file. No legacy /
    cross-profile fallback (that was the bug where one profile's replay showed
    as available for every profile)."""
    return _mreplay_path(level_key, profile)


def has_saved_replay(level_key, profile):
    """True only if THIS profile has a v4 replay for the level. Old `.zrp`
    files (any profile / legacy) are intentionally invisible."""
    try:
        return _mreplay_path(level_key, profile).is_file()
    except Exception:
        return False


def _ease_progress(disp, target, dt, rate=8.0):
    """Ease a *displayed* progress fraction toward its reported `target` so the
    monolithic encode / pickle / zlib milestones glide instead of snapping —
    the worker reports in coarse jumps (a 26% leap across pickle.dumps), but the
    bar the player sees climbs smoothly. Monotonic while rising; snaps directly
    to `target` if it drops (a fresh save/load resetting to 0)."""
    if target <= disp:
        return target
    disp += (target - disp) * min(1.0, rate * dt)
    return target if target - disp < 0.004 else disp


def save_mreplay(level_key, profile, snaps, branches, assets, progress=None):
    """Serialise the buffer + ghost branches for `level_key` under `profile`'s
    own folder (overwriting any prior one for that profile). Returns True on
    success. `progress`, if given, is called with a 0..1 fraction as the
    (encode-heavy) work proceeds."""
    def report(p):
        if progress:
            try: progress(p)
            except Exception: pass
    by_id, _ = _mreplay_surface_registry(assets)
    # Prune each branch frame down to just what diverges from the main
    # timeline at the same sim-time (the saved form of the draw-time skip).
    branches = _prune_branches(snaps, branches)
    # Single constant-speed progress bar: report (frames written so far) / TOTAL
    # frames (snapshots + pruned branch frames), uniform across both phases, so
    # it fills at a steady rate instead of racing to 50% then jumping.
    n_snaps = len(snaps)
    total_work = max(1, n_snaps + sum(len(br["frames"]) for br in branches))
    try:
        dest = _mreplay_path(level_key, profile)
        dest.parent.mkdir(parents=True, exist_ok=True)
        tmp = dest.with_suffix(".tmp")
        co = zlib.compressobj(6)
        # Stream each frame encode -> pickle -> zlib -> disk, one at a time, so
        # peak RAM is a single encoded frame (not a second full copy of the
        # buffer + the whole pickle + the whole blob). The old build-it-all path
        # tripled the buffer in RAM and OOM-hung low-RAM handhelds (975 MB, no
        # swap) mid-encode. Per-frame pickles (fresh memo each) keep memory flat;
        # they're read back one at a time by load_mreplay.
        with open(tmp, "wb") as fh:
            def emit(obj):
                cb = co.compress(pickle.dumps(obj, protocol=4))
                if cb:
                    fh.write(cb)
            # v3: compute the per-frame metadata the loader needs UP FRONT (at
            # save) and put it in the header — snap sim-times, and per branch its
            # end time + death frame/position + ship-sprite key. The loader then
            # reads it straight from the header instead of decoding every frame
            # on the main thread at replay start (that stalled the loop >10s).
            _st = getattr(snaps, "times", None)
            if _st is not None and len(_st) == len(snaps):
                snap_times = list(_st)        # _CompressedFrames: no decode
            else:
                snap_times = []
                for sn in snaps:
                    try:
                        snap_times.append(sn["scalars"][2])
                    except Exception:
                        snap_times.append(0.0)
            branch_metas = []
            for br in branches:
                frames = br["frames"]
                end_t = br.get("anchor_t", 0.0)
                died = False
                dt = dx = dy = 0.0
                ship_key = None
                for f in frames:
                    try:
                        end_t = f["scalars"][2]
                    except Exception:
                        pass
                    pd = f.get("player")
                    if pd is not None:
                        if ship_key is None:
                            img = pd.get("image")
                            if isinstance(img, pygame.Surface):
                                ship_key = by_id.get(id(img))
                        if not died and not pd.get("alive", True):
                            died = True
                            dt = end_t
                            dx = float(pd.get("x", 0.0))
                            dy = float(pd.get("y", 0.0))
                span = max(1e-3, end_t - dt) if died else 0.0
                branch_metas.append({"anchor_t": br["anchor_t"],
                                     "n_frames": len(frames), "end_t": end_t,
                                     "death": [died, dt, dx, dy, span],
                                     "ship_key": ship_key})
            emit({"v": MREPLAY_VERSION, "level": level_key,
                  "n_snaps": len(snaps), "n_branches": len(branches),
                  "snap_times": snap_times, "branches": branch_metas})
            # Frames stream after the header (no inline branch separators — the
            # header's n_frames give the boundaries). Two phases mirrored on the
            # SAVING screen: snapshots 0->0.5, then ghost branches 0.5->1.0; BOTH
            # report per-FRAME so each half fills smoothly.
            _comp = hasattr(snaps, "pickle_bytes")
            for i in range(len(snaps)):
                if _comp:
                    # Reuse the buffer's pre-encoded blob bytes verbatim — they
                    # ARE pickle.dumps(_mreplay_encode(snap_minus_rng)), identical
                    # to the else branch's output, so no decode + re-encode.
                    cb = co.compress(snaps.pickle_bytes(i))
                    if cb:
                        fh.write(cb)
                else:
                    # Strip rng: playback never sims, so it's dead weight on disk —
                    # and the packed-array rng would encode to a broken (v, None, g)
                    # that _restore can't setstate. (Ghost-branch frames already
                    # drop it via f.pop("rng"); the LIVE buffer keeps it for resume.)
                    emit(_mreplay_encode({k: v for k, v in snaps[i].items() if k != "rng"}, by_id))
                if (i & 63) == 0:
                    report(i / total_work)
            done = 0
            for br in branches:
                for f in br["frames"]:
                    emit(_mreplay_encode(f, by_id))
                    done += 1
                    if (done & 63) == 0:
                        report((n_snaps + done) / total_work)
            tail = co.flush()
            if tail:
                fh.write(tail)
        report(0.999)
        tmp.replace(dest)
        report(1.0)
        return True
    except Exception as e:
        print(f"[mreplay] save failed for {level_key}: {e}")
        return False


class _ZlibReader:
    """Read-only file-like that zlib-decompresses an underlying binary stream on
    the fly, so pickle.load can pull objects one at a time without ever holding
    the whole decompressed pickle in RAM. Implements the read(n)/readline() the
    pickle Unpickler uses. Pairs with save_mreplay's streamed per-frame format."""
    def __init__(self, fh, chunk=1 << 16):
        self._fh = fh
        self._d = zlib.decompressobj()
        self._buf = bytearray()
        self._chunk = chunk
        self._eof = False

    def _fill(self, need):
        while len(self._buf) < need and not self._eof:
            raw = self._fh.read(self._chunk)
            if raw:
                self._buf += self._d.decompress(raw)
            else:
                self._buf += self._d.flush()
                self._eof = True

    def read(self, n=-1):
        if n is None or n < 0:
            while not self._eof:
                self._fill(len(self._buf) + self._chunk)
            out = bytes(self._buf); self._buf.clear(); return out
        self._fill(n)
        out = bytes(self._buf[:n]); del self._buf[:n]; return out

    def readline(self):
        while True:
            nl = self._buf.find(b"\n")
            if nl >= 0:
                out = bytes(self._buf[:nl + 1]); del self._buf[:nl + 1]; return out
            if self._eof:
                out = bytes(self._buf); self._buf.clear(); return out
            self._fill(len(self._buf) + self._chunk)


class _LazyFrames:
    """A list-like view over a loaded replay's per-frame pickle byte-ranges,
    decoding a frame (pickle.loads + _mreplay_decode) only on access and caching
    the last few (LRU). Lets a saved replay live in RAM as ~its decompressed
    bytes (one shared `buf`) instead of every frame fully decoded — the decoded
    form (~25KB/frame) OOM'd 1GB handhelds mid-playback; the bytes are ~6× less.
    Supports the access the replay viewer needs: len(), [i] (incl. negative),
    iteration, reversed(). Read-only (a loaded replay is never appended to)."""
    __slots__ = ("_buf", "_ranges", "_by_key", "_classes", "_cache", "_cap",
                 "times")

    def __init__(self, buf, ranges, by_key, classes, cache=96):
        self._buf = buf
        self._ranges = ranges
        self._by_key = by_key
        self._classes = classes
        self._cache = {}
        self._cap = cache
        # Precomputed per-frame sim-times (scalars[2]), filled by load_mreplay
        # during the byte-range scan so _build_replay_bar doesn't have to decode
        # every frame on the MAIN thread (that stalled the loop >10s on the slow
        # Mali CPU). None for live-buffer frame lists, which decode cheaply.
        self.times = None

    def __len__(self):
        return len(self._ranges)

    def __getitem__(self, i):
        n = len(self._ranges)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        ent = self._cache.get(i)
        if ent is not None:
            del self._cache[i]            # move to MRU end
            self._cache[i] = ent
            return ent
        s, e = self._ranges[i]
        fr = _mreplay_decode(pickle.loads(self._buf[s:e]), self._by_key, self._classes)
        self._cache[i] = fr
        if len(self._cache) > self._cap:
            del self._cache[next(iter(self._cache))]   # evict LRU
        return fr

    def __iter__(self):
        for i in range(len(self._ranges)):
            yield self[i]


def load_mreplay(level_key, profile, assets, progress=None, allow_v2=False):
    """Return (snaps, branches) for `level_key` under `profile` (falling back to
    a legacy shared recording), or None if missing/bad. `progress`, if given, is
    called with a 0..1 fraction (decode-heavy). The GAME only supports v3 — old
    v2 files must be migrated (load with allow_v2=True, then re-save). `allow_v2`
    is the migration-only escape hatch that still reads v2 to re-save it as v3."""
    def report(p):
        if progress:
            try: progress(p)
            except Exception: pass
    path = _resolve_mreplay_path(level_key, profile)
    if not path.is_file():
        return None
    try:
        report(0.02)
        _, by_key = _mreplay_surface_registry(assets)
        classes = _mreplay_classes()

        def _mem_guard():
            ma = _mem_available_mb()
            if ma is not None and ma < _MREPLAY_LOAD_MIN_MB:
                raise _MreplayTooBig(
                    "only %dMB free (< %dMB) decoding replay"
                    % (ma, _MREPLAY_LOAD_MIN_MB))
        # LAZY LOAD: decompress the whole stream once, then SCAN the per-frame
        # pickle byte-ranges WITHOUT keeping the decoded objects (decode-and-
        # discard just advances the cursor). snaps/branch-frames become
        # _LazyFrames views that decode a frame on access with a small LRU. This
        # holds only the ~decompressed bytes in RAM (e.g. 24MB for L007) instead
        # of every frame fully decoded (~150MB) — the fully-decoded form OOM'd
        # 1GB handhelds mid-playback. The upfront scan costs ~the same as the old
        # full decode; the win is steady-state memory.
        raw = zlib.decompress(path.read_bytes())
        buf = io.BytesIO(raw)
        head = pickle.load(buf)
        v = head.get("v") if isinstance(head, dict) else None
        _ok = (v == MREPLAY_VERSION) or (allow_v2 and v == MREPLAY_VERSION_V2)
        if not _ok:
            # The game only loads v3; v2 is readable solely for migration.
            if v == MREPLAY_VERSION_V2:
                print(f"[mreplay] {level_key}: v2 replay needs migration to v3")
            return None
        n_snaps = int(head.get("n_snaps", 0))
        n_branches = int(head.get("n_branches", 0))
        total = max(1, n_snaps)
        # v3 carries snap_times + per-branch metadata in the header; v2 has none,
        # so we harvest it from the primitive frames during the byte-range scan.
        hdr_snap_times = head.get("snap_times") if v == MREPLAY_VERSION else None
        hdr_branches = head.get("branches") if v == MREPLAY_VERSION else None
        # Snapshots: scan byte ranges (decode-and-discard); for v2 also collect
        # each snap's sim-time so _build_replay_bar needn't decode on the main
        # thread.
        snap_ranges = []
        snap_times = None if hdr_snap_times is not None else []
        for i in range(n_snaps):
            s = buf.tell()
            obj = pickle.load(buf)
            snap_ranges.append((s, buf.tell()))
            if snap_times is not None:
                try:
                    snap_times.append(obj["scalars"][2])
                except Exception:
                    snap_times.append(0.0)
            if (i & 63) == 0:
                report(0.02 + 0.48 * i / total)
                _mem_guard()
        snaps = _LazyFrames(raw, snap_ranges, by_key, classes)
        snaps.times = hdr_snap_times if hdr_snap_times is not None else snap_times
        branches = []
        bf = 0
        # Total branch frames, so the 0.5->1.0 bar fills smoothly PER FRAME — the
        # old per-branch (every-8th) report left it stuck at 0.5 for replays with
        # <8 branches (the bar "fills only half" then jumps).
        if v == MREPLAY_VERSION:
            total_bf = max(1, sum(int(bm.get("n_frames", 0)) for bm in hdr_branches))
        else:
            total_bf = max(1, n_snaps)   # v2 migration only; bar not user-facing
        for b in range(n_branches):
            if v == MREPLAY_VERSION:
                # v3: counts + metadata from the header; just scan byte ranges.
                bm = hdr_branches[b]
                n_frames = int(bm.get("n_frames", 0))
                anchor_t = bm.get("anchor_t", 0.0)
                end_t = bm.get("end_t", anchor_t)
                death_info = tuple(bm.get("death", (False, 0.0, 0.0, 0.0, 0.0)))
                ship_sprite = (by_key.get(bm["ship_key"])
                               if bm.get("ship_key") else None)
                fr_ranges = []
                # Harvest each frame's sim-time during the (already-happening)
                # decode-and-discard scan so _seek_ghost can position the ghost
                # cursor WITHOUT decoding frames. Rewinding a ghost branch back
                # into range used to seek a fresh cursor=0 to the branch END,
                # decoding every frame on the way -> a big spike; forward entry
                # (cursor 0 -> anchor) decoded ~nothing, which is why it only
                # spiked backwards.
                fr_times = []
                for _ in range(n_frames):
                    s = buf.tell()
                    obj = pickle.load(buf)
                    fr_ranges.append((s, buf.tell()))
                    try:
                        fr_times.append(obj["scalars"][2])
                    except Exception:
                        fr_times.append(anchor_t)
                    bf += 1
                    if (bf & 63) == 0:
                        report(0.5 + 0.5 * bf / total_bf)
                        _mem_guard()
            else:
                # v2: inline {anchor_t, n_frames} meta then harvest metadata while
                # scanning (the pre-v3 streamed format).
                meta = pickle.load(buf)
                n_frames = int(meta.get("n_frames", 0))
                anchor_t = meta["anchor_t"]
                fr_ranges = []
                fr_times = []
                ship_sprite = None
                died = False
                dt = dx = dy = 0.0
                end_t = anchor_t
                for _ in range(n_frames):
                    s = buf.tell()
                    obj = pickle.load(buf)
                    fr_ranges.append((s, buf.tell()))
                    try:
                        end_t = obj["scalars"][2]
                    except Exception:
                        pass
                    fr_times.append(end_t)
                    pd = obj.get("player") if isinstance(obj, dict) else None
                    if pd is not None:
                        if ship_sprite is None:
                            img = pd.get("image")
                            if (isinstance(img, tuple) and len(img) == 2
                                    and img[0] == _MREPLAY_SURF_TAG):
                                ship_sprite = by_key.get(img[1])
                        if not died and not pd.get("alive", True):
                            died = True
                            dt = end_t
                            rect = pd.get("rect")
                            if (isinstance(rect, tuple) and len(rect) == 5
                                    and rect[0] == _REWIND_RECT_TAG):
                                dx = rect[1] + rect[3] / 2.0
                                dy = rect[2] + rect[4] / 2.0
                            else:
                                dx = float(pd.get("x", 0.0))
                                dy = float(pd.get("y", 0.0))
                    bf += 1
                    if (bf & 63) == 0:
                        report(0.5 + 0.5 * bf / total_bf)
                        _mem_guard()
                span = max(1e-3, end_t - dt) if died else 0.0
                death_info = (died, dt, dx, dy, span)
            bframes = _LazyFrames(raw, fr_ranges, by_key, classes)
            bframes.times = fr_times   # decode-free cursor seeks (see _seek_ghost)
            branches.append({"anchor_t": anchor_t,
                             "frames": bframes,
                             "end_t": end_t,
                             "death_info": death_info,
                             "ship_sprite": ship_sprite})
        report(1.0)
        return snaps, branches
    except _MreplayTooBig as e:
        print(f"[mreplay] load ABORTED for {level_key}: {e} — replay too large "
              f"for this device's RAM; freeing and returning to map.")
        return None
    except Exception as e:
        print(f"[mreplay] load failed for {level_key}: {e}")
        return None


# ── Rewind RNG: dedup + pack ────────────────────────────────────────────────
# The rewind snapshot used to store random.getstate() EVERY frame — the full
# 625-int Mersenne-Twister state, ~24 KB in RAM as 625 boxed Python ints, and
# the single biggest per-frame cost (it dominated a long-session OOM on the 1 GB
# handheld). Two measured facts let us shrink it ~80x with NO behaviour change:
#   1. The global RNG is UNCHANGED on ~88% of frames (gameplay draws ~3/frame,
#      median 0 — most randomness is bursty cosmetic particles). So we re-pack
#      only when it actually changed and SHARE one packed object across the
#      unchanged run, so a long stretch of identical frames costs one array.
#   2. The 625 words pack into a ~2.5 KB array('I') instead of ~24 KB of ints.
# `_RNG_EPOCH` is bumped by a thin wrapper on every global-RNG state-mutating op
# (draw / seed / setstate); _snapshot_rng re-packs only when the epoch moved.
_RNG_EPOCH = 0


def _pack_rng_state(st):
    """random.getstate() -> (version, array('I', words), gauss_next): the 625
    boxed ints become a compact C array (~2.5 KB vs ~24 KB)."""
    return (st[0], array.array('I', st[1]), st[2])


def _unpack_rng_state(packed):
    """Inverse of _pack_rng_state. Tolerant of the LEGACY form (older saved
    replays stored the raw getstate() tuple) — its [1] is already a tuple."""
    words = packed[1]
    if isinstance(words, array.array):
        words = tuple(words)
    return (packed[0], words, packed[2])


def _install_rng_epoch_counter():
    """Wrap the global random module's state-mutating ops so `_RNG_EPOCH`
    advances whenever the global RNG state MIGHT change. Idempotent; each
    wrapper returns the original result unchanged (only a counter bump), so
    seeded determinism (bot / replay) is fully preserved."""
    _MUT = ("random", "randint", "uniform", "choice", "choices", "randrange",
            "getrandbits", "shuffle", "sample", "gauss", "normalvariate",
            "betavariate", "expovariate", "triangular", "randbytes",
            "vonmisesvariate", "paretovariate", "weibullvariate",
            "lognormvariate", "gammavariate", "seed", "setstate")

    def _wrap(fn):
        def w(*a, **k):
            global _RNG_EPOCH
            _RNG_EPOCH += 1
            return fn(*a, **k)
        w._pw_epoch = True
        return w

    for nm in _MUT:
        f = getattr(random, nm, None)
        if f is not None and not getattr(f, "_pw_epoch", False):
            setattr(random, nm, _wrap(f))


_install_rng_epoch_counter()


class _CompressedFrames:
    """The live rewind buffer, stored COMPRESSED in RAM. Each pushed snapshot is
    encode+pickle+zlib'd — the EXACT form the saved replay uses — and decoded on
    access with a small LRU. ~14x less RAM than holding decoded dicts (the long-
    session OOM driver), at ~0.12 ms/push on host. List-like (append / pop / [i]
    / len / iter) so RewindBuffer + save + the in-play replay use it unchanged.

    `_mreplay_encode` DROPS the packed-RNG array (an "unknown object"), so the RNG
    is kept OUT of the blob in a parallel `_rngs` list of shared refs — preserving
    both the v0.9.422 cross-frame dedup AND rewind+resume determinism (the blob
    would otherwise lose random.setstate's seed). Everything else round-trips
    EXACTLY (snapshots carry the only sim-only ref, stuck_to, as a `_spawn_idx`
    int; last_ricochet_enemy drops to None — identical to today's post-rewind
    stale-ref behaviour), so every consumer sees byte-identical data."""
    __slots__ = ("_blobs", "_rngs", "times", "_by_id", "_by_key", "_classes",
                 "_cache", "_cap")

    def __init__(self, cap=96):
        self._blobs = []
        self._rngs = []          # parallel shared-ref RNG (deduped, see v0.9.422)
        self.times = []          # per-frame sim-time (scalars[2]); no decode to read
        self._by_id = self._by_key = self._classes = None
        self._cache = {}
        self._cap = cap

    def set_codec(self, assets):
        by_id, by_key = _mreplay_surface_registry(assets)
        self._by_id, self._by_key = by_id, by_key
        self._classes = _mreplay_classes()

    def append(self, snap):
        body = {k: v for k, v in snap.items() if k != "rng"}
        self._blobs.append(zlib.compress(
            pickle.dumps(_mreplay_encode(body, self._by_id), 4), 1))
        self._rngs.append(snap.get("rng"))
        try:
            self.times.append(snap["scalars"][2])
        except Exception:
            self.times.append(0.0)

    def _materialise(self, i):
        body = _mreplay_decode(pickle.loads(zlib.decompress(self._blobs[i])),
                               self._by_key, self._classes)
        body["rng"] = self._rngs[i]
        return body

    def pickle_bytes(self, i):
        """Raw encoded+pickled per-frame body bytes (rng-excluded) — EXACTLY what
        save_mreplay's `emit` produces, so the save path can stream them straight
        to disk without decoding+re-encoding (no spike, faster than the original)."""
        return zlib.decompress(self._blobs[i])

    def snapshot_view(self):
        """Cheap read-only copy for the save worker: shares the immutable blob
        bytes + rng refs (just copies the list pointers — O(n), no decode, no
        spike) but decouples from concurrent push/scrub on the live buffer."""
        v = _CompressedFrames(self._cap)
        v._blobs = list(self._blobs)
        v._rngs = list(self._rngs)
        v.times = list(self.times)
        v._by_id, v._by_key, v._classes = self._by_id, self._by_key, self._classes
        return v

    def __len__(self):
        return len(self._blobs)

    def __getitem__(self, i):
        n = len(self._blobs)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        ent = self._cache.get(i)
        if ent is not None:
            del self._cache[i]; self._cache[i] = ent
            return ent
        fr = self._materialise(i)
        self._cache[i] = fr
        if len(self._cache) > self._cap:
            del self._cache[next(iter(self._cache))]
        return fr

    def __iter__(self):
        for i in range(len(self._blobs)):
            yield self[i]

    def pop(self):
        i = len(self._blobs) - 1
        fr = self._materialise(i)
        self._blobs.pop(); self._rngs.pop(); self.times.pop()
        self._cache.pop(i, None)
        return fr

    def clear(self):
        self._blobs.clear(); self._rngs.clear(); self.times.clear()
        self._cache.clear()


class RewindBuffer:
    """Per-frame snapshot stack. push() during forward sim, scrub() while
    rewinding. Snapshots are stored COMPRESSED (see _CompressedFrames) — ~14x
    less RAM than decoded dicts, the long-session OOM driver; materialised
    transparently on access. Ghost-branch frames stay as decoded dicts (drained
    via pop()) since they're bounded by _GHOST_FRAME_BUDGET."""

    def __init__(self):
        self.snaps = _CompressedFrames()
        self._scrub_accum = 0.0
        # Snapshots popped by the current (uninterrupted) rewind, newest
        # first. Drained by PlayState when forward sim resumes to form a
        # "ghost branch" — the abandoned future the player rewound out of,
        # shown as a translucent replay overlay (see _drain_popped).
        self._popped = []

    def set_codec(self, assets):
        if isinstance(self.snaps, _CompressedFrames):
            self.snaps.set_codec(assets)

    def push(self, snap):
        self.snaps.append(snap)

    def scrub(self, snaps_to_pop):
        """Pop `snaps_to_pop` (float) snapshots, accumulating the fractional
        part across calls. Returns the snapshot now at the top of the stack
        (i.e. the one to restore to), or None if the buffer is empty.
        Popped snapshots are staged on `_popped` (newest-first) so the
        abandoned branch can be salvaged for the replay ghost overlay."""
        self._scrub_accum += snaps_to_pop
        n = int(self._scrub_accum)
        if n > 0:
            self._scrub_accum -= n
            for _ in range(n):
                if len(self.snaps) <= 1:
                    break
                self._popped.append(self.snaps.pop())
        return self.snaps[-1] if self.snaps else None

    def drain_popped(self):
        """Return the snapshots popped since the last drain in FORWARD
        chronological order, and clear the stage. Empty unless a rewind
        just happened."""
        if not self._popped:
            return []
        out = self._popped[::-1]
        self._popped = []
        return out

    def clear(self):
        try:
            self.snaps.clear()
        except AttributeError:
            self.snaps = _CompressedFrames()
        self._scrub_accum = 0.0
        self._popped = []

    def __len__(self):
        return len(self.snaps)


# ──────────────────────────────────────────────────────────────────────────
# CRT-glitch helper — shared by PlayState (dead-pause / rewind overlay) and
# TitleScreen (logo + sweep distortion on title)
# ──────────────────────────────────────────────────────────────────────────
# Every tunable lives on CRTProfile. The two module-level instances
# (_CRT_PROFILE_PLAY for the in-game overlay, _CRT_PROFILE_TITLE for the
# title logo distortion) start identical so behavior is unchanged after
# the split — diverge them by editing fields on either instance.

@dataclass(frozen=True)
class CRTProfile:
    # Tear bands: in-place horizontal row scrolls.
    tears_base: int = 2
    tears_per_intensity: float = 6.0
    tear_h_min: int = 3
    tear_h_max: int = 18
    tear_shift_max: int = 12
    # Coloured chroma flash band (occasional). chroma_chance=0 disables
    # the band entirely; chroma_alpha is a 0..1 opacity (1.0 = solid fill
    # via pygame.draw.rect; < 1.0 routes through an SRCALPHA blit).
    chroma_chance: float = 0.25
    chroma_alpha: float = 1.0
    chroma_h_min: int = 2
    chroma_h_max: int = 6
    chroma_colors: tuple = ((180, 30, 60), (40, 200, 230), (220, 220, 90))
    # Static scanline overlay (alpha + row pattern).
    scanline_alpha: int = 180
    scanline_dark_alpha: int = 120
    scanline_faint_alpha: int = 60
    scanline_step: int = 3
    # Rolling vsync-drift bar. vsync_enabled=False skips it entirely.
    vsync_enabled: bool = True
    vsync_speed: float = 0.07  # px / ms
    vsync_color: tuple = (220, 240, 255)
    vsync_alpha: int = 75
    vsync_h_min: int = 3
    vsync_h_extra: int = 3
    vsync_h_div: int = 100


# In-game dead-pause / rewind overlay — punchier: shorter tears, dimmer
# chroma flashes, darker scanlines, faster + thinner + brighter vsync bar.
_CRT_PROFILE_PLAY = CRTProfile(
    tear_shift_max=8,
    tear_h_max=12,
    chroma_alpha=0.25,
    scanline_dark_alpha=180,   # 120 × 1.5  ("50 % darker")
    scanline_faint_alpha=90,   # 60  × 1.5
    vsync_speed=0.14,          # 2× faster drift
    vsync_alpha=25,            # 0.1 opacity at full intensity
    vsync_h_min=2,
    vsync_h_extra=0,           # bar settles around half the prior thickness
)

# Title-screen logo distortion — subtler: tiny short tears, no coloured
# chroma flash, no rolling drift bar; only the scanlines + tears remain
# so the logo reads clearly under the gloss sweep.
_CRT_PROFILE_TITLE = CRTProfile(
    tear_shift_max=6,
    tear_h_min=4,
    tear_h_max=10,
    chroma_chance=0.0,
    vsync_enabled=False,
)


def _build_crt_scanline_overlay(w, h, profile=_CRT_PROFILE_PLAY):
    """Cached scanline overlay built per (w, h, profile). The cached
    instance encodes profile.scanline_step / dark_alpha / faint_alpha;
    profile.scanline_alpha modulates the whole overlay's blit alpha
    per frame in _apply_crt_glitch."""
    ov = pygame.Surface((w, h), pygame.SRCALPHA)
    for y in range(0, h, profile.scanline_step):
        pygame.draw.line(ov, (0, 0, 0, profile.scanline_dark_alpha),
                         (0, y), (w, y))
        if y + 1 < h:
            pygame.draw.line(ov, (0, 0, 0, profile.scanline_faint_alpha),
                             (0, y + 1), (w, y + 1))
    return ov


_CRT_VSYNC_BAR_CACHE = {}

# Per-overlay cache of the "alpha baked in" scanline surface. Blitting a
# per-pixel-alpha (SRCALPHA) surface that ALSO carries a surface-level
# set_alpha is SDL's slowest blit path — full-screen it costs ~10 ms on the
# RGB10 Max 3, which alone pushes a rewind frame over the 60 fps budget.
# At steady intensity (held rewind / dead-pause sits pinned at 1.0) we instead
# bake the global scanline_alpha straight into the per-pixel alpha ONCE and
# blit with no surface set_alpha — the fast per-pixel-only path (~3.5 ms),
# pixel-identical output. Keyed by the source overlay's identity; the source
# overlays are long-lived (built once per screen and cached on the caller),
# so id() is stable and a strong ref is held here.
_CRT_PREBAKED_SCANLINE_CACHE = {}


def _crt_prebaked_scanlines(overlay, scanline_alpha):
    """Copy of `overlay` with `scanline_alpha` multiplied into its per-pixel
    alpha, so it blits with no surface set_alpha (SDL's fast path). Built once
    per (overlay, scanline_alpha) and cached."""
    key = (id(overlay), int(scanline_alpha))
    baked = _CRT_PREBAKED_SCANLINE_CACHE.get(key)
    if baked is None:
        baked = pygame.Surface(overlay.get_size(), pygame.SRCALPHA)
        src = overlay.copy()
        src.set_alpha(int(scanline_alpha))
        baked.blit(src, (0, 0))   # composites perpixel*surface alpha into baked
        _CRT_PREBAKED_SCANLINE_CACHE[key] = baked
    return baked


def _crt_vsync_bar(w, h):
    """Reusable SRCALPHA strip for the rolling vsync-drift bar. Caller
    re-fills each frame with the current colour + alpha."""
    key = (w, h)
    bar = _CRT_VSYNC_BAR_CACHE.get(key)
    if bar is None:
        bar = pygame.Surface((w, h), pygame.SRCALPHA)
        _CRT_VSYNC_BAR_CACHE[key] = bar
    return bar


def _apply_crt_glitch(surf, rect, intensity,
                      profile=_CRT_PROFILE_PLAY, scanline_cache=None,
                      draw_scanlines=True):
    """Old-TV CRT glitch over a rectangular region of `surf`. Intensity is
    [0, 1] — 1.0 is the full effect. Cheap: in-place row scrolls for
    tearing (no allocation), an occasional coloured chroma band, the
    cached darken-every-N-rows scanline overlay, and a rolling vsync-
    drift bar.

    `rect` is (x, y, w, h). `scanline_cache` is a pre-built overlay
    matched to (w, h, profile); built ad-hoc if None (slower)."""
    if intensity <= 0.01:
        return
    p = profile
    rx, ry, rw, rh = rect
    n_tears = int(p.tears_base + intensity * p.tears_per_intensity)
    for _ in range(n_tears):
        if rh <= 4:
            break
        ty = random.randint(ry, ry + rh - 4)
        th = min(random.randint(p.tear_h_min, p.tear_h_max), ry + rh - ty)
        tx_shift = random.randint(-p.tear_shift_max, p.tear_shift_max)
        try:
            band = surf.subsurface(pygame.Rect(rx, ty, rw, th))
            band.scroll(tx_shift, 0)
        except (pygame.error, ValueError):
            pass
    if (p.chroma_chance > 0.0 and rh > 6
            and random.random() < p.chroma_chance * intensity):
        ty = random.randint(ry, ry + rh - 6)
        th = random.randint(p.chroma_h_min, p.chroma_h_max)
        c = random.choice(p.chroma_colors)
        if p.chroma_alpha >= 0.99:
            pygame.draw.rect(surf, c, (rx, ty, rw, th))
        else:
            cb = pygame.Surface((rw, th), pygame.SRCALPHA)
            cb.fill((c[0], c[1], c[2], int(255 * p.chroma_alpha)))
            surf.blit(cb, (rx, ty))
    if draw_scanlines:
        ov = scanline_cache
        if ov is None:
            ov = _build_crt_scanline_overlay(rw, rh, p)
        if intensity >= 0.99:
            # Steady state (held rewind / dead-pause): fast per-pixel-only blit
            # of the pre-baked overlay — same pixels as the set_alpha path below
            # at full intensity, ~2.8x faster (see _crt_prebaked_scanlines).
            surf.blit(_crt_prebaked_scanlines(ov, p.scanline_alpha), (rx, ry))
        else:
            # Ramp-in (the ~0.17 s fade as the glitch rises): scale via surface
            # alpha. Brief, so the slower combined-alpha blit is fine here.
            ov.set_alpha(int(p.scanline_alpha * intensity))
            surf.blit(ov, (rx, ry))
    # Rolling CRT vsync-drift bar.
    if p.vsync_enabled and rh > 8:
        bar_h = max(p.vsync_h_min, rh // p.vsync_h_div + p.vsync_h_extra)
        period = rh + bar_h * 2
        bar_y = int(pygame.time.get_ticks() * p.vsync_speed) % period - bar_h
        bar = _crt_vsync_bar(rw, bar_h)
        col3 = p.vsync_color[:3]
        bar.fill((col3[0], col3[1], col3[2],
                  int(p.vsync_alpha * intensity)))
        y_start = max(ry, ry + bar_y)
        y_end = min(ry + rh, ry + bar_y + bar_h)
        if y_start < y_end:
            src_top = y_start - (ry + bar_y)
            src_h = y_end - y_start
            surf.blit(bar, (rx, y_start),
                      area=pygame.Rect(0, src_top, rw, src_h))


# Runtime-mutable: drop named pieces of the GPU CRT glitch present
# ("tears", "chroma", "scanline", "vsync"). Seeded from PEWPEW_GLITCH_SKIP.
# DEFAULT empty — the glitch was NOT the black-background cause (it was the
# oversized backdrop-texture blit to the multi-pass frame target on Mali, fixed
# in BackgroundRibbon.draw_gpu). Kept as a diagnostic knob.
_GLITCH_SKIP = set(x for x in os.environ.get("PEWPEW_GLITCH_SKIP", "").split(",") if x)


def _apply_crt_glitch_gpu(gpu, frame_tex, rect, intensity,
                          profile=_CRT_PROFILE_PLAY, scanline_cache=None,
                          draw_base=True, draw_scanlines=True):
    """GPU sibling of _apply_crt_glitch: a present-time pass that draws the
    composed-scene texture `frame_tex` to the current output with the CRT
    effects. Tears = redraw shifted sub-rect bands of the frame (the gap shows
    the base draw underneath — close to the software in-place scroll-with-wrap).
    Chroma/vsync = translucent fill_rects. Scanlines = the baked scanline
    surface as a texture. Seed `random` the same as the software path for a
    matching tear pattern. `draw_base=False` skips the initial full-frame blit —
    for callers that have already drawn the base (e.g. the transition's 2×
    contrast pre-pass) and only want the tears/scanline/chroma overlay."""
    rx, ry, rw, rh = rect
    # base frame
    if draw_base:
        gpu.blit(frame_tex, pygame.Rect(rx, ry, rw, rh))
    if intensity <= 0.01:
        return
    p = profile
    n_tears = int(p.tears_base + intensity * p.tears_per_intensity)
    if "tears" not in _GLITCH_SKIP:
        for _ in range(n_tears):
            if rh <= 4:
                break
            # ty is a screen-space band top; the source sub-rect is FRAME-LOCAL
            # (origin 0,0), so subtract the dest offset (rx,ry) when sampling —
            # otherwise a non-zero shake/parallax offset reads out of the texture.
            ty = random.randint(ry, ry + rh - 4)
            th = min(random.randint(p.tear_h_min, p.tear_h_max), ry + rh - ty)
            tx_shift = random.randint(-p.tear_shift_max, p.tear_shift_max)
            gpu.blit(frame_tex, pygame.Rect(rx + tx_shift, ty, rw, th),
                     src=pygame.Rect(0, ty - ry, rw, th))
    if ("chroma" not in _GLITCH_SKIP and p.chroma_chance > 0.0 and rh > 6
            and random.random() < p.chroma_chance * intensity):
        ty = random.randint(ry, ry + rh - 6)
        th = random.randint(p.chroma_h_min, p.chroma_h_max)
        c = random.choice(p.chroma_colors)
        a = 255 if p.chroma_alpha >= 0.99 else int(255 * p.chroma_alpha)
        gpu.fill_rect((rx, ty, rw, th), (c[0], c[1], c[2], a))
    if draw_scanlines and "scanline" not in _GLITCH_SKIP:
        ov = scanline_cache
        if ov is None:
            ov = _build_crt_scanline_overlay(rw, rh, p)
        if intensity >= 0.99:
            gpu.blit(gpu.tex_for(_crt_prebaked_scanlines(ov, p.scanline_alpha)),
                     pygame.Rect(rx, ry, rw, rh))
        else:
            gpu.blit(gpu.tex_for(ov), pygame.Rect(rx, ry, rw, rh),
                     alpha=int(p.scanline_alpha * intensity))
    if "vsync" not in _GLITCH_SKIP and p.vsync_enabled and rh > 8:
        bar_h = max(p.vsync_h_min, rh // p.vsync_h_div + p.vsync_h_extra)
        period = rh + bar_h * 2
        bar_y = int(pygame.time.get_ticks() * p.vsync_speed) % period - bar_h
        col3 = p.vsync_color[:3]
        a = int(p.vsync_alpha * intensity)
        y_start = max(ry, ry + bar_y)
        y_end = min(ry + rh, ry + bar_y + bar_h)
        if y_start < y_end:
            gpu.fill_rect((rx, y_start, rw, y_end - y_start), (col3[0], col3[1], col3[2], a))


def _composite_ghost_gpu(gpu, tex, rect, glitch_mul, alpha):
    """Composite the (already scanlined) ghost-layer target texture `tex` onto
    the current output at `alpha` (the _GHOST_ALPHA fade), with the ghost tear
    glitch as GPU shifted-band redraws — the GPU sibling of _apply_ghost_glitch's
    tears. The ghost layer is translucent, so a torn band reads as a faint
    shifted echo (the intended rewind shimmer) rather than the software scroll's
    pixel move. `src` is frame-local (origin 0,0) because `tex` is the PLAY_W
    ghost target. Seeds off the shared _GHOST_GLITCH_RNG so it animates while
    paused, matching the software path's cadence."""
    rx, ry, rw, rh = rect
    gpu.blit(tex, pygame.Rect(rx, ry, rw, rh), alpha=alpha)
    p = _GHOST_GLITCH
    if not p.enabled or glitch_mul <= 0.0:
        return
    rng = _GHOST_GLITCH_RNG
    n = int(p.tears * glitch_mul + rng.random())
    shift_max = max(1, int(round(p.tear_shift_max * glitch_mul)))
    for _ in range(n):
        if rh <= p.tear_h_max + 1:
            break
        ty = rng.randint(0, rh - p.tear_h_max - 1)
        th = rng.randint(p.tear_h_min, p.tear_h_max)
        shift = rng.randint(-shift_max, shift_max)
        if shift:
            gpu.blit(tex, pygame.Rect(rx + shift, ry + ty, rw, th),
                     src=pygame.Rect(0, ty, rw, th), alpha=alpha)


def _prewarm_glitch_textures(gpu):
    """Bake the glitch/scanline GPU textures ONCE at launch so neither the first
    in-play rewind frame nor the first replay-ghost frame pays the build+upload
    cost (the ~20 ms first-ghost-frame hitch we measured). Shared by both paths:
    the ghost scanline MOD ladder (mul 1.0→2.0, the quantised dims the replay
    compositor requests) and the playfield CRT scanline overlay used by
    _apply_crt_glitch_gpu for rewind. Best-effort: a build failure just means
    the lazy path rebuilds on first use, as before."""
    for q in range(5):                       # mul 1.0, 1.25, 1.5, 1.75, 2.0
        mul = 1.0 + q / 4.0
        dim = min(255, int(round(_GHOST_GLITCH.scanline_dim * mul)))
        try:
            t = gpu.baked(("ghostscan", PLAY_W, PLAY_H, dim),
                          lambda d=dim: _ghost_scanline_mod(
                              PLAY_W, PLAY_H, d / _GHOST_GLITCH.scanline_dim))
            t.blend_mode = 4
        except Exception:
            pass
    try:
        ov = _build_crt_scanline_overlay(PLAY_W, PLAY_H, _CRT_PROFILE_PLAY)
        gpu.tex_for(ov)
        gpu.tex_for(_crt_prebaked_scanlines(ov, _CRT_PROFILE_PLAY.scanline_alpha))
    except Exception:
        pass


# Static full-playfield / full-screen colour overlays (bomb flash, hit flashes,
# outro fade-to-black) shared across PlayState instances, keyed by (size,color).
# They're write-once fills used read-only at draw time (only `set_alpha` per
# frame, and just one PlayState is ever live), so rebuilding + .convert()-ing
# them on every level entry (~12 ms of the ctor) is pure waste.
_PLAY_OVERLAY_CACHE = {}


def _play_overlay(size, color):
    key = (size, color)
    s = _PLAY_OVERLAY_CACHE.get(key)
    if s is None:
        try:
            s = pygame.Surface(size).convert()
        except pygame.error:
            s = pygame.Surface(size)
        s.fill(color)
        _PLAY_OVERLAY_CACHE[key] = s
    return s


class PlayState:
    def __init__(self, app, level, replay_view=None, replay_load=None):
        # `replay_view`, when given, is a (snaps, branches) pair already loaded
        # from a saved mission replay. `replay_load` is a level key to load on
        # a background thread (showing a LOADING % screen) before viewing.
        # Either way the PlayState boots into a view-only replay (no live play,
        # exit returns to the map). See the tail of __init__.
        # Declared up-front because the DMZ + rewind blocks below both
        # read it AND the late sync near the end re-binds it; without
        # the `global` here, Python's parser rejects the function for
        # using the name prior to its global declaration.
        self.app = app
        self.level = level
        self.assets = app.assets
        self.player = Player(app.assets, app.save.loadout)
        self.bullets = []
        self.balls = []            # in-flight Ball projectiles (red weapon)
        self.enemies = []
        self.pickups = []
        self.particles = []
        # Live-particle window: `self.particles` is append-only (oldest first),
        # so once an entry dies it stays dead going forward — [0, _part_cursor)
        # are all dead and the update/draw sweeps skip them. Advanced each frame
        # (_advance_particle_cursor), recomputed exactly in _restore_snapshot for
        # the backward/rewind case, reset to 0 on a level reset.
        self._part_cursor = 0
        # Queue of (cx, cy, visual_r, sprite_colors, is_boss) tuples
        # captured by _on_kill. Flushed at the end of _update so the
        # death-FX particle budget is SHARED across every enemy that
        # died this frame — 1 death gets the full per-kill burst, 3
        # deaths split it three ways. Drops the spike when a Ball-blast
        # cascades 5+ kills in a single frame without changing the look
        # of a solo kill. Append-only queue, drained per frame; the
        # rewind buffer captures the post-flush particles list length
        # so the closed-form Particle determinism still applies.
        self._kill_fx_queue = []
        self.float_texts = []      # in-world floating numbers (e.g. "+$25")
        self.lasers = []
        self.rays = []             # railgun hitscan-fade visuals
        self.score = 0
        self.elapsed = 0
        self.timeline_idx = 0
        # Run-history denominators: actual enemies that spawned from the
        # timeline this attempt, and how many of them the player killed.
        # Counted via `len(self.enemies)` delta around each spawner call
        # (so DMZ wave-reductions and boss-summoned minions fall out
        # naturally on both sides of the ratio). Feeds the post-play
        # `progress` value the map "CLEAR" stat displays.
        self.enemies_spawned = 0
        self.enemies_killed = 0
        # Win-hold state: after the docking outro completes we freeze on
        # the MISSION COMPLETE banner instead of transitioning straight
        # to the shop, letting the player see the clear % and pick
        # between "continue" (fire) and "retry" (ability — only offered
        # when held_progress < 1.0). _held_progress is captured the
        # moment the outro finishes so the banner shows a stable number.
        self._win_held = False
        self._held_progress = 0.0
        # MISSION COMPLETE "replay" mode. North (cancel) on a full-clear
        # banner re-plays the whole level at 1× straight out of the rewind
        # buffer — which already holds one snapshot per forward frame, so
        # the entire run is sitting in memory. It's purely cosmetic: no sim
        # runs during playback, so no money is re-collected and the outcome
        # can't change. The win is committed to the save the moment replay
        # starts (see _enter_replay → _commit_win) so however the player
        # then leaves — fire to the shop, or a pause-abort — the progress
        # they already earned is already on disk.
        self._replay_active = False
        self._replay_cursor = 0.0   # float frame index into the buffer
        self._replay_saved = None    # banner state to drop back onto
        self._win_committed = False
        self._committed_stolen_time = None
        self._pending_unlocks = []
        # Cumulative seconds the player has spent in negative time-speed
        # (any rewind, anywhere — active sim, outro, banner). Lower is
        # better. Captured into save.level_stats[key]["stolen_times"] at
        # _commit_win and surfaced as the headline "STOLEN TIME: X.XX s"
        # on the MISSION COMPLETE banner. INTENTIONALLY NOT in the
        # snapshot scalars — if it were, a player could rewind back to
        # before the rewind happened and zero the metric. The accumulator
        # only grows during the lifetime of this PlayState instance.
        self.stolen_time = 0.0
        # Ghost branches: every time the player rewinds and resumes, the
        # future they abandoned is salvaged here as (anchor_snap, [frames]).
        # In the replay these play back as translucent animated copies of
        # the whole entity field, in sync from the frame the rewind landed
        # on — so you see the timeline you didn't keep. Populated during
        # play by _add_ghost_branch; consumed by the replay overlay.
        self._ghost_branches = []
        self._ghost_frame_budget = _GHOST_FRAME_BUDGET
        # Per-branch GPU death-FX bundles (shards/ship textures), built at
        # replay start by _prepare_ghost_death_gpu; transient, never pickled.
        self._ghost_death_gpu = {}
        # Per-replay render state (built in _enter_replay).
        self._ghost_pool = {}
        self._active_ghosts = []
        self._ghost_surf = None
        self._ghost_death_surf = None
        self._ghost_shatter_surf = None
        # Lazily-built render caches for the CRT/black-hole power-off: a 1px-
        # wide vertical alpha gradient (scaled to width for the feathered line)
        # and a base accretion-halo disc (dark core + bright rim, scaled per
        # frame).
        self._crt_line_grad = None
        self._crt_halo = None
        self._play_speed = 1.0
        # View-only replay (launched from the map to watch a saved replay):
        # no win commit, no banner; exit goes back to the map.
        self._replay_view_only = False
        # Threaded saved-replay load state (replay_load path).
        self._mreplay_loading = False
        self._mreplay_load_pct = 0.0          # raw target from the load thread
        self._mreplay_load_disp = 0.0         # eased value the bar actually shows
        self._mreplay_load_result = None
        self._mreplay_load_applied = True
        # Game-fully-complete state. Activated by _begin_game_won when
        # the player's win on this level finishes the last of the 100
        # levels for the first time. While True:
        #   * docking outro is skipped (ship keeps flying free)
        #   * `_win_particles` hosts the fireworks (FireworkSpark) —
        #     intentionally separate from self.particles so the Ghost-
        #     Mode snapshot/rewind doesn't capture or undo them
        #     (rewinding takes the player back into the boss fight;
        #     the celebration stays out of the recorded record)
        #   * player keeps full control (move + fire) — `weapons_locked`
        #     is cleared in _begin_game_won
        #   * START dismisses to title; save was already committed
        self._game_won = False
        self._game_won_t = 0.0
        self._firework_t = 0.0
        self._win_particles = []
        self.stars = ParallaxStars(PLAY_W, PLAY_H)
        self.nebula = Nebula(level.nebula)
        # Native aspect, mirror-tiled 3x wide + vertical-mirror seamless wrap,
        # then drift DOWN (counter to forward motion). Shared cache: the heavy
        # build runs once per theme, reused across Map/Play/Title (see
        # _cached_ribbon).
        self.bg_ribbon = _cached_ribbon(level.theme,
                                        width=PLAY_W + 2 * PLAY_MARGIN)
        self.bg_ribbon.speed = -abs(self.bg_ribbon.speed)
        self.difficulty = level.difficulty
        # Adaptive per-level difficulty knob. Each death decrements; each
        # finish bumps +5 (capped at 0). Negative values bias the level
        # easier via _adjusted_spawn / _effective_shield_chance /
        # _biased_drop_kind. Bot sessions use a fresh SaveData so the
        # dict is empty -> adj = 0 baseline.
        adj_map = getattr(app.save, "level_difficulty_adjust", None) or {}
        # The stored value is a FLOAT (decrements scale with how far the
        # player got into the level before dying); the live runtime knob
        # is the truncated-toward-zero integer floor, so -0.5 -> 0 (no
        # DMZ (per-level adaptive-difficulty knob) is permanently
        # disabled — rewind replaces the death-bias safety net, so the
        # adaptive adjust always sits at 0. The stored floats in
        # save.level_difficulty_adjust are kept on disk for any legacy
        # save that has them, but ignored here.
        self.difficulty_adjust = 0
        # Per-wave modifier table: each entry is timeline_idx -> (downgrade
        # steps, count reduction). Count reductions are distributed worst-
        # wave-first (so -1 hits the single highest-HP wave, -2 hits the
        # two worst, etc.). Type downgrades follow as a second pass (1
        # per -5 units), also worst-first.
        self.wave_modifiers = _compute_wave_modifiers(self)
        # Per-wave deterministic RNG states. Each timeline entry gets a
        # stable seed derived from (level.key, timeline_idx); the spawn
        # loop swaps in this stream for the duration of `fn(self)` so the
        # wave's enemy attrs (Asteroid drift, shield rolls, Scout speed,
        # Boss._next_shield_color, etc.) are determined ONLY by the seed.
        # Independent of the main rng means eased forward-replay after a
        # rewind reproduces the same wave even though dt drift + player-
        # input rng consumption shifted the main rng state by then.
        # Re-seed (rather than persist) on every fire so a rewind-past-
        # spawn replays from the same stream start.
        self._wave_seed_base = _stable_wave_seed_base(level.key)
        self.flash = 0
        self.shake = 0
        # Lateral camera that lerps toward an offset proportional to the
        # player's horizontal distance from the centre of the playfield.
        # Applied to the playfield blit at draw time so bg_ribbon, stars and
        # every entity drift opposite to the player's input — giving the
        # impression of a slightly bigger play area panning under the ship.
        self.parallax_x = 0.0
        self.is_boss_fight = False
        self.boss_spawned = False
        self.outcome = None
        self.pause = False
        self.message = None
        self.boss_intro_t = 0.0   # seconds remaining of intro
        self.explosions = []      # list of ExplosionRing
        self.sparks = []          # impact sparks (Particle subclass)
        self.message_timer = 0
        self.credits_earned = 0
        self.scrap_drop_factor = 1.0
        # Dev/test cheat: L2+R2 instantly resolves the level (kills every
        # enemy with drops, collects every pickup) and shows a 3-second
        # summary in the middle of the screen.
        self._cheat_summary = None
        self._cheat_summary_t = 0.0
        self._cheat_l2r2_was_held = False
        # Cinematic level transitions: launch from a wide platform, dock at a station.
        n = int(level.key[1:]) if level.key.startswith("L") and level.key[1:].isdigit() else 1
        sec_here = (n - 1) // 10
        sec_next = min(9, n // 10)   # next sector index, capped for L100
        # Prefer the AI-generated station art if available (one per sector);
        # fall back to procedural shapes otherwise.
        stations = self.assets.get("_stations", {})
        pads = self.assets.get("_launch_pads", {})
        if sec_here in pads:
            self.station_start = pads[sec_here]
        else:
            self.station_start = make_launch_pad(sector_idx=sec_here)
        if sec_next in stations:
            self.station_end = stations[sec_next]
        else:
            self.station_end = make_station(seed=n * 71 + 137, sector_idx=sec_next)
        # Bases are rendered twice as big, with the launch pad rotated 180°
        # so its docking arm points up at the lifting ship.
        self.station_start = _prepare_station_start(self.station_start)
        self.station_end = _prepare_station_end(self.station_end)
        self.intro_t = 2.4
        self.outro_t = 0.0
        self._outro_start_y = float(self.player.y)
        # Wind-down clock: ticks up between the moment the win condition
        # first fires (boss dead + no pickups, or time-limit reached + no
        # enemies) and the actual outro start. Weapons are locked, the
        # field gets a chance to clear of rays / float-texts / friendly
        # bullets so they don't trail into the dock cinematic.
        self._win_pending_t = 0.0

        # Life clock — seconds since this PlayState was constructed
        # (i.e. since the player left the map). Distinct from
        # `self.elapsed`, which only starts incrementing after the
        # 2.4 s takeoff cinematic ends. The HUD entry animation uses
        # `life_t` so it lines up with the takeoff: the last chrome
        # panel settles at exactly the moment `self.intro_t` hits 0
        # and the player gains control.
        self.life_t = 0.0
        # Index of the next per-panel "activate" chirp to fire. Each
        # tick of _update checks if life_t has crossed the panel's
        # arrival time and plays the sound once.
        self._hud_chirp_idx = 0
        # Panel arrival times keyed off the same math the HUD profile
        # uses: bg-fade delay + panel index × panel_stagger. Kept here
        # rather than re-derived per frame so the trigger loop stays
        # branch-free.
        _hud_prof = _SIDE_STRIP_PROFILES["hud"]
        self._hud_chirp_times = tuple(
            _HUD_ANIM_DELAY + i * _hud_prof["panel_stagger"]
            for i in range(6)
        )

        # Pre-allocated per-frame surfaces. Allocating a 480x480 Surface every
        # frame for the playfield + a fresh overlay for each white/red/cyan
        # flash showed up in profiles as ~1 ms of pure malloc/free on device.
        # Reuse the same surfaces and just set_alpha on the overlays.
        # Playfield surface is wider than PLAY_W so bg_ribbon fills the
        # ±PLAY_MARGIN region that lateral parallax + shake reveal on each
        # side. Entities draw on a centred subsurface so their world-coord
        # logic doesn't need to know about the margin.
        full_w = PLAY_W + 2 * PLAY_MARGIN
        try:
            self._playfield_full = pygame.Surface((full_w, PLAY_H)).convert()
        except pygame.error:
            self._playfield_full = pygame.Surface((full_w, PLAY_H))
        self._playfield = self._playfield_full.subsurface(
            (PLAY_MARGIN, 0, PLAY_W, PLAY_H))
        # Reusable PLAY_W x PLAY_H surface for the cinematic background
        # composite (bg_ribbon + nebula + stars) that gets zoomed during
        # intro / outro. Allocated once so the 144 cinematic frames per
        # level don't churn the GC.
        try:
            self._cinematic_bg_surf = pygame.Surface((PLAY_W, PLAY_H)).convert()
        except pygame.error:
            self._cinematic_bg_surf = pygame.Surface((PLAY_W, PLAY_H))
        def _solid(color, w=full_w):
            return _play_overlay((w, PLAY_H), color)
        # Bomb / flash overlays cover the FULL playfield surface so a
        # screen-wide flash still fills the margins exposed by parallax.
        # Shared, cached (read-only at draw, only set_alpha per frame).
        self._bomb_overlay = _solid(WHITE)
        self._flash_overlay_red = _solid(RED)
        self._flash_overlay_cyan = _solid(CYAN)
        # Full-screen black overlay reused by the post-dock fade so the
        # per-frame ramp doesn't allocate. Covers the whole screen (not
        # just the playfield) so the HUD fades along with everything.
        self._outro_fade_overlay = _play_overlay((SCREEN_W, SCREEN_H), BLACK)
        # Overlay cycles via R3. 0 = debug banner (test-only info),
        # 1 = perf summary, 2 = perf detail, 3 = off. Starts off in every
        # play state — test mode overrides to start at debug below.
        self._test_overlay_mode = 3
        # Ship starts sitting in the launch bay of the platform.
        self.player.y = PLAY_H - 30
        self.player.rect.center = (int(self.player.x), int(self.player.y))
        self.player.cinematic = True
        self.player.cinematic_scale = 0.35  # small until takeoff scales it back up

        # ---- Hidden test-mission setup (SELECT+Y on the title) -------------
        self.is_test = getattr(level, "is_test", False)
        if self.is_test:
            # Load the persisted test-mode loadout (per-profile). Clone
            # via the dataclass round-trip so pickups / bomb spends
            # during play don't mutate the saved copy — we explicitly
            # save back when the pause-menu closes.
            saved_test_lo = getattr(app.save, "test_loadout", None) or Loadout()
            self.player.loadout = Loadout(**asdict(saved_test_lo))
            self.player.shield_max = SHIELD_MAX[self.player.loadout.shield]
            self.player.shield_hp = self.player.shield_max
            # Station parade is temporarily disabled — jump straight into
            # the enemy / boss timeline. The parade state vars are still
            # initialised below so any path that pokes at them (skip
            # logic, draw helpers, cinematic-zoom check) sees a "done"
            # state instead of AttributeError.
            self.intro_t = 0
            self.player.cinematic = False
            self.player.cinematic_scale = 1.0
            self.player.y = PLAY_H - 60
            self.player.rect.center = (int(self.player.x), int(self.player.y))
            stations_raw = self.assets.get("_stations", {})
            self._test_stations_start = {
                idx: _prepare_station_start(img)
                for idx, img in stations_raw.items()
            }
            self._test_stations_end = {
                idx: _prepare_station_end(img)
                for idx, img in stations_raw.items()
            }
            self._test_parade_idx = 0
            self._test_parade_sub = "takeoff"   # "takeoff" -> "play" -> "landing"
            self._test_parade_sub_duration = 2.0
            self._test_parade_play_duration = 4.0
            self._test_parade_t = self._test_parade_sub_duration
            self._test_parade_done = True
            self._test_parade_landing_start_y = float(PLAY_H - 60)
            # Right-stick X edge detector (qx, _). Only the X axis is
            # used now — wave/boss prev/next.
            self._test_rstick_prev = (0, 0)
            self._test_action_msg = ""        # last manual action, shown in banner
            self._test_action_t = 0.0
            # Diagnostic snapshots: last button index pressed + live axes.
            # Lets the user see what indices their controller actually emits
            # if the default L2/R2/L3 mappings don't match.
            self._test_last_btn = None
            self._test_last_btn_t = 0
            self._test_diag_axes = ()
            self._test_diag_n_btn = 0
            # Debug/perf overlay starts OFF (mode 3) in test too — the
            # user opted in to a clean default; R3 cycles to the test-
            # specific banner if they want it.
            self._test_overlay_mode = 3
            # Wave count on the timeline. Bosses live in the state
            # machine (_test_maybe_spawn_next_boss), not the timeline.
            self._test_waves_end = 6
            # Index of the NEXT boss to spawn (0..10). The state machine
            # spawns boss `_test_boss_idx` when there's no boss alive and
            # all waves have fired, then increments.
            self._test_boss_idx = 0
            # Pause-menu cursor row (0..7) + edge-tracker for the unified
            # up/down/left/right held-state used by the menu navigator.
            self._test_menu_cursor = 0
            self._test_menu_dirs_prev = (False, False, False, False)

        # NOHIT-mode rewind state. The buffer accumulates one snapshot per
        # forward frame; East-held scrubs back through them at a ramping
        # speed (-0.1 → -1.0 over 1 s). When the player dies the playfield
        # holds at speed=0 with a glitch overlay until East is pressed to
        # rewind out of the hit; West (ability) acknowledges defeat and
        # exits to game-over.
        # Mirror save.rewind_unlocked into the module-level flag
        # profile's flag so Player / Particle classes can branch without
        # carrying an App back-reference. Updates if the player toggled
        # the mode while we were on the title screen. (`global` is
        # already declared at the top of __init__.)
        # Mirror save.rewind_unlocked into the module-level flag the
        # HUD dispatch consults — the chrome cache also keys on this
        # so it rebakes when the flag flips mid-level.
        global _REWIND_UNLOCKED
        _REWIND_UNLOCKED = bool(getattr(app.save, "rewind_unlocked", False))
        self._rewind = RewindBuffer()
        self._rewind.set_codec(app.assets)   # live buffer stores compressed frames
        # Rewind RNG dedup state — the last packed global-RNG snapshot and the
        # _RNG_EPOCH it was taken at. _snapshot_rng re-packs only when the epoch
        # moved (RNG changed), so unchanged frames share one packed object.
        self._rng_epoch = -1
        self._rng_packed = None
        # GC: the per-frame snapshot push churns hundreds of small dicts +
        # tuples, which pressures gen-0 → cascades into gen-1 → and a
        # gen-2 sweep lands every ~5–10 s as a ~10–30 ms stutter on the
        # RG mali path. Suspend automatic GC for the duration of a
        # level — the snapshot graph has no reference cycles
        # (flat dicts of tuples + entity refs) so the cycle detector
        # has nothing to do here. A manual collect on level exit
        # reclaims whatever's accumulated.
        self._gc_was_enabled = None
        if gc.isenabled():
            self._gc_was_enabled = True
            gc.disable()
        self._time_speed = 1.0
        # Duty-cycle accumulator for fixed-timestep forward stepping: we add
        # the perceived speed each frame and step a whole `dt` tick whenever it
        # crosses 1.0, so the sim clock only ever lands on tick boundaries.
        self._fwd_acc = 0.0
        self._rewind_active = False
        self._dead_paused = False
        # Player-death shatter state. Driven by `_death_t` (sim time of death,
        # or None) which is a LIVE field — NOT snapshotted — so it survives a
        # scrub and is cleared on _restore_snapshot whenever the restored frame
        # has the player alive (death undone / not yet happened). Everything
        # the FX needs is rebuilt closed-form from the age (elapsed-_death_t),
        # so no snapshot-format change → old saved replays stay loadable.
        self._death_t = None
        self._death_pos = (0.0, 0.0)
        self._death_shards = []
        self._death_sil = None
        self._glitch_t = 0.0
        # Persistent glitch effect surface, allocated on first need.
        self._glitch_overlay = None
        # Sound state for the rewind whir loop + edge detectors for the
        # hit / release one-shots.
        self._rewind_channel = None
        self._prev_rewinding = False
        self._prev_dead_paused = False
        self._music_paused = False

        # View-only saved replay: load the buffer + ghost branches into place
        # and boot straight into the replay scrubber. Skip the cinematic
        # intro so the first frame shows the recorded run.
        if replay_view is not None:
            snaps, branches = replay_view
            self._replay_view_only = True
            self._rewind.snaps = list(snaps)
            self._ghost_branches = list(branches)
            self.intro_t = 0.0
            self.player.cinematic = False
            self.player.cinematic_scale = 1.0
            self._enter_replay()
        elif replay_load is not None:
            # Load the saved replay on a daemon thread; _run_replay_view shows
            # a LOADING % screen until it's ready, then enters the scrubber.
            self._replay_view_only = True
            self._mreplay_loading = True
            self._mreplay_load_pct = 0.0
            self._mreplay_load_disp = 0.0
            self._mreplay_load_applied = False
            self.intro_t = 0.0
            self.player.cinematic = False
            self.player.cinematic_scale = 1.0
            key = replay_load
            assets = self.assets
            profile = self.app.profile_name

            def _lprog(p):
                self._mreplay_load_pct = p

            def _lworker():
                try:
                    self._mreplay_load_result = load_mreplay(
                        key, profile, assets, progress=_lprog)
                finally:
                    self._mreplay_loading = False

            try:
                threading.Thread(target=_lworker, daemon=True).start()
            except Exception:
                self._mreplay_loading = False

    def run(self, events, controls):
        dt = 1.0 / FPS
        # View-only saved replay launched from the map: pure scrubber, no
        # live play / win flow. Exit returns to the map.
        if self._replay_view_only:
            return self._run_replay_view(dt, controls)
        # Logical actions for the menu-like dispatch (pause / banners /
        # replay). Live ship control + the weapon state machine read the
        # raw fields directly in Player.update (hot path).
        menu = MenuInput(controls)
        # While paused, the primary "confirm" (South / O / Num1 / LMB → menu.go)
        # also RESUMES — so a mouse player can left-click to un-pause, and the
        # test-mode loadout menu still closes on South. Only fires when already
        # paused, so it never opens the menu.
        close_via_south = (self.pause and menu.go)
        # START toggles the pause menu — and that is the ONLY thing START does
        # anywhere now (menus, banners and replay never read it). It's gated
        # off while a result banner, the dead-pause prompt, the YOU WIN screen,
        # or a replay is up — those use NORTH to leave/dismiss, so without the
        # gate START would be double-mapped (toggle pause AND hit that handler).
        toggle_pause = ((menu.start or close_via_south)
                        and not self._game_won
                        and not self._win_held
                        and not self._dead_paused
                        and not self._replay_active)
        if toggle_pause:
            was_paused = self.pause
            self.pause = False if close_via_south else (not self.pause)
            # When the test-mode upgrade menu opens, snap the cursor to
            # the top so the player isn't surprised by stale selection.
            if self.is_test and self.pause and not was_paused:
                self._test_menu_cursor = 0
                self._test_menu_dirs_prev = (False, False, False, False)
            # When the menu closes, persist the test loadout to disk so
            # the next test-mode entry resumes with the same dials.
            elif self.is_test and was_paused and not self.pause:
                self._save_test_loadout()

        # Music follows pause-menu state: silence the track while the
        # player is in the menu, resume on close. Sync every frame so
        # bomb-abort (sets outcome without flipping pause) and any other
        # state change is covered.
        self._sync_pause_music(self.pause)

        # Pause-only abort: NORTH exits to the map without confirmation —
        # same button as "give up" on the MISSION FAILED banner, so North =
        # "leave this run" consistently. Distinct from "loss": the dumnezeu
        # knob isn't decremented and no level-end shop is shown. No confirm
        # needed — it takes Start (to pause) then North, and levels are short.
        if (self.pause and menu.north and self.outcome is None
                and not self._replay_active):
            # Test-mode aborts ALSO persist the loadout so a quick exit
            # doesn't lose what the player just dialled in.
            if self.is_test:
                self._save_test_loadout()
            self.outcome = "abort"

        # East rewinds straight out of a pause break: holding it resumes the
        # sim (so _nohit_step's rewind path takes over the same frame) — no
        # hint needed, it's the natural rewind reflex. Only when rewind is
        # actually available, so a reflex press pre-unlock can't end the break.
        if (self.pause and controls.bomb_held and self.outcome is None
                and not self._replay_active
                and getattr(self.app.save, "rewind_unlocked", False)):
            self.pause = False

        # R3 cycles the debug/perf overlay in every play state, not just the
        # test mission — the test mode just has an extra "debug" mode that
        # would show test-only info on a regular run.
        self._handle_overlay_toggle(events)

        if self.is_test:
            self._handle_test_inputs(events, controls)
            if self._test_action_t > 0:
                self._test_action_t = max(0.0, self._test_action_t - dt)
            if self.pause:
                self._handle_test_menu_input(events, controls)

        # MISSION COMPLETE replay: West on a full clear re-plays the level
        # from the start out of the rewind buffer (West = "do the level
        # again" — replay on COMPLETE, retry on FAILED). Only on a clean
        # 100% banner, and only when there's actually a recording to play.
        just_entered_replay = False
        if (self._win_held and self.outcome is None and not self._replay_active
                and self._held_progress >= 1.0
                and (menu.west or controls.rmb_pressed)
                and len(self._rewind) > 1):
            self._enter_replay()
            just_entered_replay = True

        if self._replay_active:
            # Skip the step on the entry frame so the same north-press that
            # started the replay isn't re-read as an exit by _replay_step.
            if not just_entered_replay:
                self._replay_step(dt, controls)
        elif not self.pause:
            # _nohit_step runs every frame — even during _win_held —
            # so the player can hold East to rewind out of the MISSION
            # COMPLETE banner if they want to go back and clean up a
            # missed enemy / pickup. The forward _update branch inside
            # _nohit_step gates on _win_held so the world still freezes
            # when nobody's rewinding.
            self._nohit_step(dt, controls)
        # Win-hold dismiss: fire commits the win (→ shop), ability retries
        # the level (only when the clear was < 100%). The world is frozen
        # above so the player can dwell on the banner indefinitely.
        # Win condition tightens: anything under 100% is
        # NOT a win — confirm becomes "give up" and routes to "loss"
        # (skips the unlock cascade in _record_play_outcome, then drops
        # into the shop like any level end).
        if self._win_held and self.outcome is None:
            if self._held_progress >= 1.0:
                # MISSION COMPLETE — GO commits the win -> shop. (North =
                # replay-level, handled above; East-hold = rewind via
                # _nohit_step.)
                if menu.go:
                    # Win already recorded to disk if a replay was saved —
                    # route to shop WITHOUT a second post_play record.
                    self.outcome = "win_committed" if self._win_committed else "win"
            else:
                # MISSION FAILED — South is intentionally UNMAPPED so the
                # player has to *choose* (no reflexive give-up on the
                # primary button). West = retry, North = give up,
                # East-hold = rewind back into the run.
                if menu.west or controls.rmb_pressed:   # RMB = "safe back"
                    self.outcome = "retry"
                elif menu.north:
                    self.outcome = "loss"   # give up
        # Game-fully-complete YOU WIN screen — ship keeps flying, the
        # player can move + fire (handled by the normal _update path
        # above), fireworks tick independently of the snapshot system.
        # Save was already committed in _begin_game_won. START dismisses
        # to title once a small grace window has passed (so the same
        # fire-press that killed the final boss doesn't immediately
        # close the celebration).
        if self._game_won:
            self._game_won_t += dt
            self._tick_fireworks(dt)
            if (self.outcome is None
                    and menu.north
                    and self._game_won_t > 0.5):
                self.outcome = "game_won"
        self._draw(controls)
        if self.outcome is not None:
            # Commit the level's earned credits to the persistent save
            # NOW — kept off save.credits per-frame so the rewind buffer
            # can restore credits_earned cleanly. Same baking on every
            # outcome path (win / loss / retry / abort / game_won) so
            # the player always keeps what they actually picked up;
            # retry then immediately re-earns from a fresh PlayState
            # which is the same net result as the old in-frame mutation.
            if self.credits_earned > 0:
                self.app.save.credits += self.credits_earned
                self.credits_earned = 0
            # Always unpause music on level exit (abort from pause menu
            # leaves self.pause = True, so the per-frame sync above would
            # otherwise leak a paused channel into the next screen).
            self._sync_pause_music(False)
            # Re-enable GC + sweep the level's snapshot graph before
            # handing back to App — the buffer otherwise lives until
            # PlayState is dereffed and the next gen-2 sweep, which is
            # likely the shop screen and would carry the stutter there.
            if self._gc_was_enabled:
                self._gc_was_enabled = None
                try:
                    gc.enable()
                except Exception:
                    pass
                # NOTE: the expensive gc.collect() sweep of the rewind-buffer
                # snapshot graph is NOT done here any more — it ran on this
                # (visible) exit frame and caused the ~0.2 s hitch the player saw
                # on MISSION COMPLETE → shop. The App transition fade now runs it
                # at FULL BLACK between the fade-out and fade-in (see _fx_tick),
                # so the stutter is hidden.
            return self.outcome
        return None

    # ──────────────────────────────────────────────────────────────────
    # NOHIT rewind methods
    # ──────────────────────────────────────────────────────────────────
    def _nohit_step(self, dt, controls):
        """Time-control wrapper around _update. Forward sim at +speed pushes
        a snapshot per frame; rewind at -speed pops snapshots restoring
        prior frames; speed=0 pauses (used during dead-paused glitch).

        Proactive rewind (East held while still alive) is gated by
        the per-save `rewind_unlocked` flag — fresh saves can't
        rewind until they've actually demonstrated the ability once.
        Two teaching paths qualify:
          - the dead-pause prompt after a death, and
          - the partial-clear MISSION FAILED win-banner (held progress
            < 1.0, level finished),
        both of which honour East regardless of the unlock so the
        player can discover rewind from either failure surface. The
        first successful East-press out of those states flips the
        unlock and persists."""
        rewind_held = GameInput(controls).rewind  # WEST now
        sounds = self.app.sounds

        # Detect first frame after death and acknowledge-defeat input.
        if not self.player.alive and not self._dead_paused:
            self._dead_paused = True
        # On the edge of entering dead_pause, play the hit cue.
        if self._dead_paused and not self._prev_dead_paused:
            s = sounds.get("rewind_hit") if sounds else None
            if s is not None:
                try: s.play()
                except Exception: pass
        if self._dead_paused and MenuInput(controls).north:
            # Accept the run is over (NORTH = "give up", same button that
            # leaves the MISSION FAILED banner and aborts the pause menu —
            # East stays free for rewind, which is what the prompt teaches).
            self._stop_rewind_whir()
            self.outcome = "loss"
            return

        # Gate: East-while-alive only rewinds AFTER the player has
        # earned the ability. Three states allow East to start a
        # rewind regardless of the unlock flag:
        #   - dead-paused (the player needs the prompt to recover);
        #   - partial-clear MISSION FAILED win-banner (so a player
        #     who survived to the end with <100% kills can rewind
        #     back into sim and clean up instead of being forced to
        #     retry from scratch);
        #   - already unlocked.
        unlocked = bool(getattr(self.app.save, "rewind_unlocked", False))
        ghost_fail_win_held = (self._win_held
                               and self._held_progress < 1.0)
        rewind_active_in = rewind_held and (unlocked
                                         or self._dead_paused
                                         or ghost_fail_win_held)

        # State transitions on East press/release edges.
        if rewind_active_in and not self._rewind_active:
            self._rewind_active = True
            # Start rewind at -0.2× regardless of prior speed.
            self._time_speed = -0.2
            # First-ever rewind on this save: unlock proactive rewind
            # and persist so future runs (and a quit-mid-level) keep
            # the ability the player just discovered. Also flip the
            # module-level mirror so the HUD chrome's cache key
            # changes this frame and the "rewind" control row
            # reappears on the next chrome bake.
            if not unlocked:
                self.app.save.rewind_unlocked = True
                global _REWIND_UNLOCKED
                _REWIND_UNLOCKED = True
                try: self.app.save.save()
                except Exception: pass
        elif not rewind_active_in and self._rewind_active:
            self._rewind_active = False
            # Snap to 0 so the forward ease begins from a clean zero.
            if self._time_speed < 0:
                self._time_speed = 0.0

        # Continuous easing.
        if self._rewind_active:
            # Accelerate -0.2 → -4.0 over 4.0 s = 0.95 units/sec. Holding
            # East longer keeps speeding up; release snaps to 0 (above).
            self._time_speed = max(-4.0, self._time_speed - 0.95 * dt)
        else:
            target = 0.0 if self._dead_paused else 1.0
            if self._time_speed < target:
                self._time_speed = min(target, self._time_speed + 1.0 * dt)
            elif self._time_speed > target:
                self._time_speed = max(target, self._time_speed - 1.0 * dt)

        # Glitch intensity tracks (dead_paused OR currently rewinding).
        glitch_target = 1.0 if (self._dead_paused
                                or self._time_speed < -0.05) else 0.0
        if self._glitch_t < glitch_target:
            self._glitch_t = min(glitch_target,
                                 self._glitch_t + dt * 6.0)
        elif self._glitch_t > glitch_target:
            self._glitch_t = max(glitch_target,
                                 self._glitch_t - dt * 2.0)
        # Music ducking — drop track volume with glitch intensity so the
        # rewind / death pause reads cinematically. Always-set is safe;
        # when glitch_t returns to 0 the multiplier returns to 1.
        mc = getattr(self.app, "music_channel", None)
        if mc is not None:
            try:
                mbg = (self.app.music_bus.gain
                       * self.app.master_bus.gain)
                duck = 1.0 - 0.75 * self._glitch_t
                mc.set_volume(mbg * duck)
            except Exception:
                pass

        # Rewind-whir loop + release one-shot, edge-detected on the
        # "speed is currently negative" flag.
        is_rewinding_now = self._time_speed < -0.05
        if is_rewinding_now and not self._prev_rewinding:
            s = sounds.get("rewind_whir") if sounds else None
            if s is not None:
                try: self._rewind_channel = s.play(loops=-1)
                except Exception: self._rewind_channel = None
        if is_rewinding_now and self._rewind_channel is not None:
            try:
                # Volume curve: |speed|^1.3 so the ramp from -0.2 to -1.0
                # feels accelerating rather than linear. Ceiling 0.85 so
                # we don't trample SFX.
                mag = abs(self._time_speed)
                vol = min(0.85, (mag ** 1.3) * 0.95)
                self._rewind_channel.set_volume(vol)
            except Exception:
                pass
        if not is_rewinding_now and self._prev_rewinding:
            self._stop_rewind_whir()
            # Only play the release tone when actually returning to
            # forward time — not when transitioning into dead_pause's
            # speed=0 hold (the hit cue covers that case).
            if not self._dead_paused:
                s = sounds.get("rewind_release") if sounds else None
                if s is not None:
                    try: s.play()
                    except Exception: pass

        # Apply current time direction.
        if self._time_speed > 0.05:
            # Forward sim runs only when we're NOT sitting on the
            # MISSION COMPLETE banner — _win_held freezes the world for
            # the player's dwell, but rewind (the elif below) still
            # works so they can scrub back into active play.
            if not self._win_held:
                # Forward sim just resumed: if a rewind preceded this, the
                # frames it abandoned are still on the buffer's _popped
                # stage. Salvage them into a ghost branch anchored at the
                # frame we rewound back to (the current buffer top, which
                # the new forward sim builds on) before pushing this frame.
                if self._rewind is not None:
                    popped = self._rewind.drain_popped()
                    if popped and self._rewind.snaps:
                        self._add_ghost_branch(self._rewind.snaps[-1], popped)
                # FIXED TIMESTEP + duty cycle. _time_speed is the smoothly
                # ramped *perceived* speed (ease-back from rewind, death
                # slow-mo); we consume it through an accumulator and advance
                # only WHOLE `dt` ticks — never a partial tick. So every
                # snapshot lands on the same tick grid as the recorded ghosts
                # (no between-tick drift), which keeps the ghost-vs-kept
                # position dedupe exact. <1x trips the accumulator every few
                # render frames (perceived slow-mo by holding frames); 1x is
                # one tick per frame.
                self._fwd_acc += self._time_speed
                while self._fwd_acc >= 1.0:
                    self._fwd_acc -= 1.0
                    self._update(dt, controls)
                    if self._rewind is not None:
                        self._rewind.push(self._snapshot())
        elif self._time_speed < -0.05:
            self._fwd_acc = 0.0
            # snaps_per_frame = |speed| * (dt * FPS) — at the design
            # 60 fps render, dt*FPS ≈ 1.0 so this matches the original
            # "pop |speed| snaps per frame" behaviour. When render fps
            # drops (heavy restore work + glitch overlay), dt*FPS > 1
            # and we pop proportionally more snaps so the player still
            # gets the full -4× wall-clock rewind speed. _restore_
            # snapshot still runs once per frame — only the deepest
            # popped snap is restored, so the extra pops are O(1) list
            # operations with no extra restore cost.
            self.app.perf.start("rewind.scrub")
            snap = self._rewind.scrub(abs(self._time_speed) * dt * FPS)
            self.app.perf.end("rewind.scrub")
            if snap is not None:
                self.app.perf.start("rewind.restore")
                self._restore_snapshot(snap)
                self.app.perf.end("rewind.restore")
            # If we rewound to a frame where the player is alive again,
            # clear the dead-paused latch — the death has been undone.
            if self.player.alive:
                self._dead_paused = False
            # Stolen time — cumulative seconds spent in negative time
            # speed. Sim-seconds equivalent (|speed| × dt), so a -4×
            # rewind held for 1 wall-clock second adds 4 s to the score.
            # Counts during active sim AND outro (any rewind before
            # _commit_win locks the score). Never decreases.
            self.stolen_time += abs(self._time_speed) * dt
        else:
            # speed ≈ 0 (dead_pause hold) — no sim, no snapshot, no particle
            # tick. Particles freeze along with the rest of the playfield,
            # hidden by the CRT glitch overlay. Reset the duty-cycle accumulator
            # so the next forward resume starts clean on a tick boundary.
            self._fwd_acc = 0.0

        # Particle clock — kept in sync with self.elapsed so new spawns
        # this frame capture the right spawn_t AND so the recompute on
        # the next restore reflects the current sim time.
        Particle._sim_t = self.elapsed

        self._prev_rewinding = is_rewinding_now
        self._prev_dead_paused = self._dead_paused

    def _stop_rewind_whir(self):
        if self._rewind_channel is not None:
            try: self._rewind_channel.stop()
            except Exception: pass
            self._rewind_channel = None

    def _sync_pause_music(self, should_pause):
        """Pause/unpause the menu music channel to match pause-menu state.
        Tracks our own bool so we don't double-pause (pygame.Channel.pause
        is sticky but unpause-without-pause is harmless; the bool keeps
        the call count tidy)."""
        mc = getattr(self.app, "music_channel", None)
        if mc is None:
            return
        if should_pause and not self._music_paused:
            try: mc.pause()
            except Exception: pass
            self._music_paused = True
        elif not should_pause and self._music_paused:
            try: mc.unpause()
            except Exception: pass
            self._music_paused = False

    # Fields on Player whose value mutates per frame but which we'd corrupt
    # if we shared the same Loadout reference across snapshots — the live
    # game mutates Loadout in place when picking up coins/upgrades, so we
    # snapshot its fields separately and restore in place.
    _PLAYER_SKIP = ("loadout", "assets")

    def _snapshot(self):
        ps = _snap_obj(self.player, skip=self._PLAYER_SKIP)
        ps["__loadout_state"] = dict(self.player.loadout.__dict__)
        balls = _snap_list(self.balls)
        # Make the snapshot ref-free so the live buffer can compress it losslessly
        # (_mreplay_encode drops unknown object refs): a Ball.stuck_to holds a live
        # Enemy ref — store the host's `_spawn_idx` int instead. _resync_stuck_balls
        # already re-binds the live host by `_spawn_idx` after every restore.
        for _cls, _d in balls:
            _st = _d.get("stuck_to")
            if _st is not None and not isinstance(_st, int):
                _d["stuck_to"] = getattr(_st, "_spawn_idx", None)
        return {
            "player": ps,
            "bullets": _snap_list(self.bullets),
            "balls": balls,
            "enemies": _snap_list(self.enemies),
            "pickups": _snap_list(self.pickups),
            "sparks": _snap_list(self.sparks),
            "lasers": _snap_list(self.lasers),
            "rays": _snap_list(self.rays),
            "explosions": _snap_list(self.explosions),
            "float_texts": _snap_list(self.float_texts),
            # Particles store only `len(self.particles)`. The list is
            # append-only during forward sim and each Particle knows its
            # own spawn_t + initial state, so restore is "truncate to N,
            # then recompute() each survivor's live state from sim_t".
            "particle_len": len(self.particles),
            # intro_t / outro_t are the gates on the cinematic _update
            # branches — without them, rewinding past intro restored
            # cinematic_scale ≈ 0.35 but left intro_t = 0, so the intro
            # never replayed and the ship stayed tiny. life_t +
            # _hud_chirp_idx are similar: rewinding through the takeoff
            # HUD entry chirps would replay them otherwise.
            "scalars": (self.score, self.credits_earned, self.elapsed,
                        self.timeline_idx, self.flash, self.shake,
                        self.parallax_x, self.is_boss_fight,
                        self.boss_spawned,
                        self.intro_t, self.outro_t, self.life_t,
                        self._hud_chirp_idx, self._win_pending_t,
                        self._win_held, self._held_progress,
                        # Clear % counters — rewinding past a wave
                        # without these would double-count the second
                        # forward pass and under-report a clean clear.
                        self.enemies_spawned, self.enemies_killed),
            "rng": self._snapshot_rng(),
        }

    def _snapshot_rng(self):
        """Packed global-RNG state for this frame — RE-PACKED only when the RNG
        actually changed since the last snapshot (unchanged on ~88% of frames).
        Unchanged frames return the SAME packed object, so a run of them costs a
        single ~2.6 KB array instead of ~24 KB of boxed ints each."""
        if _RNG_EPOCH != self._rng_epoch:
            self._rng_packed = _pack_rng_state(random.getstate())
            self._rng_epoch = _RNG_EPOCH
        return self._rng_packed

    def _restore_snapshot(self, snap):
        player_snap = snap["player"]
        loadout_state = player_snap.get("__loadout_state", {})
        for k, v in player_snap.items():
            if k == "__loadout_state":
                continue
            if (isinstance(v, tuple) and len(v) == 5
                    and v[0] == _REWIND_RECT_TAG):
                cur = getattr(self.player, k, None)
                if isinstance(cur, pygame.Rect):
                    cur.x, cur.y, cur.w, cur.h = v[1], v[2], v[3], v[4]
                else:
                    try:
                        setattr(self.player, k,
                                pygame.Rect(v[1], v[2], v[3], v[4]))
                    except (AttributeError, TypeError):
                        pass
            else:
                try:
                    setattr(self.player, k, v)
                except AttributeError:
                    pass
        for k, v in loadout_state.items():
            setattr(self.player.loadout, k, v)
        _restore_list(self.bullets, snap["bullets"])
        _restore_list(self.balls, snap["balls"])
        _restore_list(self.enemies, snap["enemies"])
        _restore_list(self.pickups, snap["pickups"])
        _restore_list(self.sparks, snap["sparks"])
        _restore_list(self.lasers, snap["lasers"])
        _restore_list(self.rays, snap["rays"])
        _restore_list(self.explosions, snap["explosions"])
        _restore_list(self.float_texts, snap["float_texts"])
        # Re-attach the shared `_assets` reference stripped from the snapshot
        # (see _REWIND_ASSET_SKIP). Newly-created enemies (cls.__new__ in
        # _restore_list) would otherwise lack it; in-place-restored ones keep
        # theirs. Only enemies (incl Boss) carry it — for hitbox/dummy lookups.
        _assets = self.assets
        for _e in self.enemies:
            _e._assets = _assets
        # Particles: truncate to the recorded length, then derive each
        # remaining particle's live state from its spawn_t + the now-
        # restored sim clock.
        plen = snap.get("particle_len", len(self.particles))
        if plen < len(self.particles):
            del self.particles[plen:]
        (self.score, self.credits_earned, self.elapsed,
         self.timeline_idx, self.flash, self.shake,
         self.parallax_x, self.is_boss_fight,
         self.boss_spawned,
         self.intro_t, self.outro_t, self.life_t,
         self._hud_chirp_idx, self._win_pending_t,
         self._win_held, self._held_progress,
         self.enemies_spawned, self.enemies_killed) = snap["scalars"]
        Particle._sim_t = self.elapsed
        # Background ribbon scroll is NOT in the snapshot and bg_ribbon.update()
        # only runs during forward sim — so it froze during replay/rewind. Derive
        # it DETERMINISTICALLY from the sim clock instead (no extra saved data):
        # forward play accumulates scroll += speed*dt from 0, which is exactly
        # speed*elapsed (mod tile_h), so this matches the live position and keeps
        # the backdrop scrolling smoothly as the replay plays / scrubs.
        rib = self.bg_ribbon
        if rib is not None and rib.tile_h:
            rib.scroll = (rib.speed * self.elapsed) % rib.tile_h
        # Same for the parallax starfield's vertical scroll (each layer's
        # scroll_y also accumulates speed*dt from 0 in forward sim, and freezes
        # in replay) — derive it deterministically from the sim clock so the
        # stars keep drifting. (The lateral lean already follows via the restored
        # parallax_x applied at draw time.)
        st = getattr(self, "stars", None)
        if st is not None and getattr(st, "height", 0):
            for _L in st.layers:
                _L["scroll_y"] = (_L["speed"] * self.elapsed) % st.height
        # Recompute every survivor's live state from the restored clock, and
        # pick up the first-alive index for the live-particle window in the same
        # pass (rewind revives dead leading particles, so the cursor can move
        # backward here — found exactly, for free).
        cur = -1
        elapsed = self.elapsed
        for i, p in enumerate(self.particles):
            p.recompute(elapsed)
            if cur < 0 and p.life > 0:
                cur = i
        self._part_cursor = cur if cur >= 0 else len(self.particles)
        # Death shatter marker: a restored frame with the player alive means
        # we've scrubbed back to before the hit (or the death was undone), so
        # drop _death_t — the FX renders only while it's set and the frame is
        # dead. (Re-dying on a fresh forward pass re-stamps it.)
        if self.player.alive:
            self._death_t = None
        _rng = snap.get("rng")
        if _rng is not None:
            # Live-buffer frames carry the packed rng (for rewind+resume);
            # loaded-replay frames have it stripped (playback never sims). Guard
            # against a malformed/partial rng so a stray frame can't crash restore.
            try:
                random.setstate(_unpack_rng_state(_rng))
            except (TypeError, ValueError, IndexError):
                pass
        # Stuck balls: the snapshot's stuck_to slot held a Python
        # reference to whatever Enemy was hosting the bomb at snap
        # time. _restore_list rebuilds the enemies list by index, so
        # if the live list was filtered between snap-time and now
        # (an enemy died, got culled) the snap-stored ref is pointing
        # at the ORPHAN copy of that enemy — not the freshly-rebuilt
        # one now in self.enemies. Walk every stuck ball, validate
        # the host ref, snap the ball's world position cleanly to
        # the live host's centre (so no per-frame drift across many
        # rewind steps), and detach orphaned hosts so manual detonate
        # still pops the ball at its current parked position.
        self._resync_stuck_balls()

    # ──────────────────────────────────────────────────────────────────
    # MISSION COMPLETE replay (forward playback of the rewind buffer)
    # ──────────────────────────────────────────────────────────────────
    def _commit_win(self):
        """Persist this level's win to the save right now (stats, completed
        list, unlock cascade, disk flush) and remember the pending unlock
        celebration for the shop. Idempotent — safe to call more than once.
        Credits are NOT baked here; they ride on credits_earned and are
        baked by the outcome handler in run() on exit, so the banner still
        shows the right '+N credits' when replay returns to it.

        The committed stolen_time is also snapshotted into
        self._committed_stolen_time so the banner can read it without
        re-querying the save (and so a subsequent rewind that grows the
        live counter doesn't change the on-banner number)."""
        if self._win_committed:
            return
        self._win_committed = True
        self._committed_stolen_time = float(self.stolen_time)
        try:
            self._pending_unlocks = self.app._record_play_outcome(
                self.score, self.level.key, True, self._held_progress,
                stolen_time=self._committed_stolen_time) or []
        except Exception:
            self._pending_unlocks = []

    def _add_ghost_branch(self, anchor, frames):
        """Salvage an abandoned-future branch (the frames a rewind popped)
        as a ghost anchored by the SIM-TIME the rewind landed on. Drops the
        per-frame RNG state — ghosts only ever reconstruct entity lists +
        player for drawing, never random.setstate — and enforces a global
        frame budget so a rewind-happy run can't grow ghosts without bound.

        Anchoring by elapsed (not the anchor snapshot's identity) means the
        branch still fires in replay even if a later, deeper rewind popped
        that anchor snapshot out of the kept buffer — it spawns whenever the
        kept replay's clock reaches the branch point.

        Over-budget eviction THINS WHILE PRESERVING SPREAD: it drops the
        branch sitting closest to a neighbour in sim-time (the most
        redundant one, in the densest cluster), rather than always nuking
        the earliest — otherwise heavy rewinding would strip every ghost
        from the START of the level and you'd only ever see them later on."""
        for f in frames:
            f.pop("rng", None)
        self._ghost_branches.append(
            {"anchor_t": anchor["scalars"][2], "frames": frames})
        self._ghost_frame_budget -= len(frames)
        while self._ghost_frame_budget < 0 and len(self._ghost_branches) > 1:
            order = sorted(self._ghost_branches, key=lambda b: b["anchor_t"])
            if len(order) <= 2:
                # Can't thin the interior — give up the lighter endpoint.
                drop = (order[0] if len(order[0]["frames"])
                        <= len(order[-1]["frames"]) else order[-1])
            else:
                # Protect the two endpoints (so coverage still spans from
                # the start of the level to the end) and drop the INTERIOR
                # branch whose removal closes the smallest sim-time gap —
                # i.e. the most redundant one. Repeated, this decimates
                # dense clusters uniformly instead of eating the beginning.
                drop, best = None, None
                for i in range(1, len(order) - 1):
                    span = order[i + 1]["anchor_t"] - order[i - 1]["anchor_t"]
                    if best is None or span < best:
                        best, drop = span, order[i]
            self._ghost_frame_budget += len(drop["frames"])
            self._ghost_branches.remove(drop)

    def _enter_replay(self):
        """Begin cosmetic playback of the recorded run from frame 0."""
        if self._replay_view_only:
            # Watching a saved replay from the map — no win to commit and no
            # banner to drop back onto; exit returns to the map.
            self._replay_saved = None
        else:
            # Lock the win in first so the earned progress survives any exit.
            self._commit_win()
            # Stash the live banner state to drop back onto when playback ends
            # or the player bails out.
            self._replay_saved = self._snapshot()
        self._replay_active = True
        self._replay_cursor = 0.0
        # Kill any held-rewind state / whir so playback starts clean.
        self._rewind_active = False
        self._stop_rewind_whir()
        # Pre-render the timeline bar (thickness profile + glow) — static for
        # the run, so the per-frame HUD draw is just a few blits.
        self._build_replay_bar()
        # Ghost overlay: queue branches by anchor sim-time so each spawns
        # when the kept replay's clock reaches its branch point — robust to
        # a deeper rewind having popped the original anchor snapshot.
        # Per-branch reconstruction pool, keyed by id(branch). Ghosts are
        # (re)activated by SIM-TIME each frame (not a one-way spawn cursor),
        # so scrubbing back into a branch's range rebuilds it from the pool.
        self._ghost_pool = {}
        self._active_ghosts = []
        # Transient (NOT pickled) per-branch caches for the death-branch
        # shatter replay, keyed by id(branch): the deterministic shard set +
        # silhouette, and the (died, death_t, death_x, death_y, span) info that
        # anchors the shatter to the RECORDED death frame/position.
        self._ghost_death_bursts = {}
        self._ghost_death_info_cache = {}
        # Pre-bake the GPU death send-off textures (per-branch shards/ship +
        # shared ring/halo/line/star) NOW, at replay start — so the first ghost
        # send-off doesn't build+upload mid-playback. No-op on software.
        self._prepare_ghost_death_gpu()
        self._play_speed = 1.0
        self._replay_east_held = False   # edge latch for the East rewind ramp
        # Mouse-wheel seek accelerator (see _SEEK_STEPS_FWD/_BACK): index into
        # the step table, real-time since the last scroll, last scroll dir.
        self._seek_step_i = 0
        self._seek_idle_t = 0.0
        self._seek_dir = 0
        # Replay-save (West) state — saving runs on a background thread so the
        # ~seconds-long encode+pickle+zlib doesn't freeze the replay.
        self._mreplay_saving = False
        self._mreplay_save_result = None
        self._mreplay_prev_saving = False
        self._mreplay_msg_t = 0.0
        self._mreplay_save_pct = 0.0          # raw target from the save thread
        self._mreplay_save_disp = 0.0         # eased value the bar actually shows
        if self._ghost_surf is None:
            # PLAY_W (not playfield_full width): the parallax margin isn't needed
            # on the ghost layer (it's composited into the playfield centre),
            # and the per-frame full-surface glitch/fade blits scale with area.
            # Drawn at offset 0, composited onto the wider target at PLAY_MARGIN.
            self._ghost_surf = pygame.Surface((PLAY_W, PLAY_H), pygame.SRCALPHA)
            self._ghost_death_surf = None   # dying ghosts now share _ghost_surf
            # The death shatter accumulates here so it can composite at its own
            # brighter _GHOST_SHATTER_ALPHA, separate from the steady field.
            self._ghost_shatter_surf = pygame.Surface(
                (PLAY_W, PLAY_H), pygame.SRCALPHA)

    def _exit_replay(self):
        """Stop playback. For a live post-win replay, restore the MISSION
        COMPLETE banner state; for a view-only saved replay, signal a return
        to the map."""
        self._replay_active = False
        self._active_ghosts = []
        self._ghost_pool = {}
        self._ghost_death_bursts = {}
        self._ghost_death_info_cache = {}
        self._ghost_death_gpu = {}
        if self._replay_view_only:
            self.outcome = "replay_done"
            return
        if self._replay_saved is not None:
            self._restore_snapshot(self._replay_saved)
            self._replay_saved = None

    def _run_replay_view(self, dt, controls):
        """Run loop for a view-only saved replay (map → watch → map). Shows a
        LOADING % screen while the file decodes on its thread, then the replay
        scrubber + pause; no live play, no win flow."""
        # Threaded load phase. Stay on the LOADING screen until the worker is
        # done AND the eased bar has visibly reached 100% — otherwise the moment
        # the thread flips _mreplay_loading False we'd skip straight to applying
        # the result, abandoning the lagging bar at ~95% (it never gets the
        # frames to catch up to its target). Once the thread is done we drive the
        # display the rest of the way to 1.0.
        if self._mreplay_loading or self._mreplay_load_disp < 0.999:
            target = self._mreplay_load_pct if self._mreplay_loading else 1.0
            self._mreplay_load_disp = _ease_progress(
                self._mreplay_load_disp, target, dt)
            self._draw_mreplay_loading(self.app.screen)
            return None
        if not self._mreplay_load_applied:
            self._mreplay_load_applied = True
            res = self._mreplay_load_result
            if not res:
                # Missing / corrupt file → straight back to the map.
                self.outcome = "replay_done"
                return self.outcome
            snaps, branches = res
            self._rewind.snaps = snaps
            self._ghost_branches = branches
            self._enter_replay()
        self._sync_pause_music(self.pause)
        if self._replay_active:
            self._replay_step(dt, controls)
        self._draw(controls)
        if self.outcome is not None:
            self._sync_pause_music(False)
            return self.outcome
        return None

    def _draw_replay_progress(self, screen, raw, title, phase1, phase2,
                              title_col, fill1, fill2, border, single=False):
        """Shared REPLAY title + progress bar(s). SAVE uses TWO bars (one per
        write phase: snapshots 0->0.5, branches 0.5->1.0), stacked 1px apart,
        both visible from the start, with switched colours. LOAD is now a SINGLE
        bar (`single=True`) — v3 has no slow 'processing' branch-decode anymore,
        so a lone bar fills 0->1. Each fill is a vertical gradient (full at the
        middle row, 40% darker toward top + bottom); the step name is centred ON
        the bar. The whole block sits 2px below centre. Callers paint their own
        backdrop and pass their palette (cyan load / amber save)."""
        fonts = self.app.fonts
        big = fonts.get("big") or fonts.get("small") or fonts.get(2)
        small = fonts.get("small") or fonts.get(2)
        cx, cy = SCREEN_W // 2, SCREEN_H // 2
        t = big.render(title, False, title_col)
        bw = t.get_rect().width            # bar spans exactly the title width
        bh = small.get_height() + 12
        bxp = cx - bw // 2
        raw = max(0.0, min(1.0, raw))
        DOWN = 2                           # nudge the whole block 2px down
        if single:
            y1 = cy - bh // 2 + DOWN
            tr = t.get_rect(center=(cx, y1 - t.get_height() // 2 - 6))
            screen.blit(t, tr)
            self._draw_progress_bar(screen, small, bxp, y1, bw, bh,
                                    phase1, raw, fill1, border)
            return
        # SAVE — two stacked bars centred on cy (+DOWN); title just above.
        total = bh * 2 + 1
        y1 = cy - total // 2 + DOWN
        y2 = y1 + bh + 1
        tr = t.get_rect(center=(cx, y1 - t.get_height() // 2 - 6))
        screen.blit(t, tr)
        f1 = min(1.0, raw / 0.5)           # phase1 fills 0->1 over raw 0->0.5
        f2 = max(0.0, (raw - 0.5) / 0.5)   # phase2 fills 0->1 over raw 0.5->1
        # Colours switched: the top (phase1) bar takes the SECOND palette colour
        # and the bottom (phase2) bar takes the first.
        self._draw_progress_bar(screen, small, bxp, y1, bw, bh, phase1, f1, fill2, border)
        self._draw_progress_bar(screen, small, bxp, y2, bw, bh, phase2, f2, fill1, border)

    @staticmethod
    def _draw_progress_bar(screen, font, x, y, bw, bh, label, fill, col, border):
        """One progress bar: dark track + border, a vertical-gradient fill (full
        `col` at the centre row, 40% darker at top/bottom), and the step name
        centred on it (white + 1px shadow so it reads over filled/empty)."""
        pygame.draw.rect(screen, (12, 16, 24), (x, y, bw, bh))   # track
        pygame.draw.rect(screen, border, (x, y, bw, bh), 1)
        fw = int((bw - 2) * max(0.0, min(1.0, fill)))
        if fw > 0:
            ih = bh - 2
            for row in range(ih):
                d = abs((row + 0.5) / ih - 0.5) * 2.0     # 0 centre -> 1 edge
                g = 1.0 - 0.4 * d                         # 1.0 centre, 0.6 edge
                c = (int(col[0] * g), int(col[1] * g), int(col[2] * g))
                pygame.draw.rect(screen, c, (x + 1, y + 1 + row, fw, 1))
        lb = font.render(label, False, (245, 250, 255))
        sh = font.render(label, False, (0, 0, 0))
        rc = lb.get_rect(center=(x + bw // 2, y + bh // 2))
        screen.blit(sh, (rc.x + 1, rc.y + 1))
        screen.blit(lb, rc)

    def _draw_mreplay_loading(self, screen):
        """Title LOAD REPLAY + a SINGLE cyan bar while a saved replay loads on
        its thread. v3 loads have no slow branch-decode 'processing' phase, so
        one bar fills 0->1."""
        screen.fill(BLACK)
        self._draw_replay_progress(
            screen, self._mreplay_load_disp, "LOAD REPLAY",
            "LOADING", "",
            title_col=(140, 230, 255), fill1=(90, 200, 255),
            fill2=(70, 120, 235), border=(40, 60, 90), single=True)

    def _replay_step(self, dt, controls):
        """Interactive playback of the rewind buffer via a JOG/SHUTTLE on
        playback speed. up/down (analog stick magnitude; d-pad/keys = full)
        accelerates play_speed toward ±8× at 2×/sec, passing through zero into
        reverse; releasing decays back to the rest speed (0 paused, 0.5× while
        ghosts linger, else 1×) in ~0.5s. Live view in the game area; no sim
        runs, so nothing is re-collected and the recorded outcome is untouched.

        Controls — South (fire): play/pause toggle. East (bomb): held = same
        as D-pad Down (reverse scrub). West (ability): save the replay. North
        (cancel) / mouse RMB: quit the replay. Mouse WHEEL seeks the cursor,
        consecutive same-direction scrolls walking the per-direction step table
        (forward 0.1 s head, backward 0.5 s, both up to a 4 s cap); a direction
        flip or a 0.25 s gap resets to the head, and every step is 10x finer
        while paused for frame-hunting. Both ends HOLD (no auto-exit)
        so you can shuttle freely. Playback
        freezes while a save is encoding (it steals a core on the RG) and
        auto-resumes when done."""
        # Surface the "SAVED" / "FAILED" flash when the save thread finishes.
        if self._mreplay_prev_saving and not self._mreplay_saving:
            self._mreplay_msg_t = 2.0
        self._mreplay_prev_saving = self._mreplay_saving
        if self._mreplay_msg_t > 0.0:
            self._mreplay_msg_t = max(0.0, self._mreplay_msg_t - dt)
        # MODAL while a save encodes: the zlib+pickle of the whole buffer
        # steals a core on the RG, so the replay is frozen AND input-locked —
        # no quit, scrub, pause toggle, or seek until it finishes (the
        # _draw_mreplay_saving overlay covers the screen). Auto-resumes,
        # cursor untouched, the moment the save thread clears the flag. Ease
        # the displayed bar toward the worker's coarse target so it glides.
        if self._mreplay_saving:
            self._play_speed = 0.0
            self._mreplay_save_disp = _ease_progress(
                self._mreplay_save_disp, self._mreplay_save_pct, dt)
            return
        menu = MenuInput(controls)
        # North = QUIT the replay. A post-win replay ends like any level end —
        # straight to the SHOP (the win was committed at replay entry, so this
        # routes via "win_committed" → shop_win with the unlock celebration). A
        # view-only saved replay (watched from the map) has no win, so it just
        # returns to the map.
        if menu.north or controls.rmb_pressed:   # RMB = "safe back" = quit
            self._replay_active = False
            self.outcome = ("replay_done" if self._replay_view_only
                            else "win_committed")
            return
        # South = play / pause toggle (rest speed drops to 0 when paused; the
        # shuttle below still lets you jog from a frozen frame and coast back).
        if menu.go:
            self.pause = not self.pause
        # West = save this replay (one file per level, overwrites).
        if menu.west:
            self._save_replay()
        snaps = self._rewind.snaps
        maxc = max(0, len(snaps) - 1)
        # Restore + sync ghosts at the CURRENT position first, so the rest
        # speed reflects the ghosts actually on screen now.
        idx = int(self._replay_cursor)
        if idx > maxc:
            idx = maxc
        self._restore_snapshot(snaps[idx])
        self._advance_ghosts(snaps[idx]["scalars"][2])
        # Jog/shuttle on playback speed. up/down (analog) drives play_speed:
        # reinforcing the current motion ramps gently (_SHUTTLE_ACCEL), but
        # pushing OPPOSITE brakes fast (_SHUTTLE_BRAKE) through zero so you can
        # reverse from full speed without a long crawl. Releasing decays to the
        # rest speed (0 when paused, else 1×).
        rest = 0.0 if self.pause else 1.0
        if controls.bomb_held:
            # East = rewind, ramped EXACTLY like the in-game rewind (see
            # _nohit_step): snap to -0.2× on the press edge, then accelerate
            # toward the -4× floor at 0.95 units/sec for as long as it's held.
            if not self._replay_east_held:
                self._play_speed = -0.2
                self._replay_east_held = True
            else:
                self._play_speed = max(-4.0, self._play_speed - 0.95 * dt)
        else:
            self._replay_east_held = False
            # Up/down jog/shuttle on playback speed: reinforcing the current
            # motion ramps gently (_SHUTTLE_ACCEL); pushing OPPOSITE brakes
            # fast (_SHUTTLE_BRAKE) through zero. Releasing decays to rest.
            s = controls.scrub_y
            if abs(s) > _SHUTTLE_DEADZONE:
                rate = (_SHUTTLE_BRAKE if self._play_speed * s < 0
                        else _SHUTTLE_ACCEL)
                self._play_speed = max(-_SHUTTLE_MAX, min(
                    _SHUTTLE_MAX, self._play_speed + rate * s * dt))
            elif self._play_speed > rest:
                self._play_speed = max(
                    rest, self._play_speed - _SHUTTLE_RELEASE * dt)
            elif self._play_speed < rest:
                self._play_speed = min(
                    rest, self._play_speed + _SHUTTLE_RELEASE * dt)
        self._replay_cursor = min(float(maxc), max(
            0.0, self._replay_cursor + self._play_speed * dt * FPS))
        # Mouse wheel = accelerating discrete seek (independent of the
        # jog/shuttle above). Consecutive same-direction scrolls walk the
        # per-direction step table (forward 0.1s head, backward 0.5s head, both
        # → 4s cap); an idle gap past _SEEK_WINDOW or a flick the other way
        # resets to the head, keeping back-and-forth nudging fine-grained.
        self._seek_idle_t += dt
        if self._seek_idle_t > _SEEK_WINDOW:
            self._seek_step_i = 0
            self._seek_dir = 0
        if controls.wheel_y:
            direction = 1 if controls.wheel_y > 0 else -1
            steps = _SEEK_STEPS_FWD if direction > 0 else _SEEK_STEPS_BACK
            if direction == self._seek_dir:
                self._seek_step_i += 1
            else:
                self._seek_step_i = 0
            self._seek_step_i = min(self._seek_step_i, len(steps) - 1)
            self._seek_dir = direction
            self._seek_idle_t = 0.0
            jump = steps[self._seek_step_i]
            # While paused the player is frame-hunting, so make every step 10x
            # finer for precise pin-pointing (0.1s head → 0.01s, etc.).
            if self.pause:
                jump *= 0.1
            self._replay_cursor = min(float(maxc), max(
                0.0, self._replay_cursor + direction * jump * FPS))

    # ── Replay ghost overlay (abandoned rewind branches) ────────────────
    def _make_ghost(self, branch):
        return {"branch": branch, "cursor": 0,
                "lists": {n: [] for n in _GHOST_LIST_NAMES},
                "player": Player.__new__(Player),
                "loadout": Loadout(),
                # False on frames whose player matched main (pruned to None in
                # a saved replay) so we don't draw the ship at a stale spot.
                "player_visible": True}

    def _advance_ghosts(self, main_t):
        """Recompute the set of ghost branches active at sim-time `main_t`
        and seek each to its matching frame.

        Direction-AGNOSTIC: a branch is active whenever
        `anchor_t <= main_t <= last_frame_t`, derived fresh every frame
        rather than via a one-way spawn cursor — so auto-play AND scrubbing
        in either direction both work. Aligning by sim-time (not frame
        index) is what makes the ghost line up with the kept timeline: both
        pass through the post-rewind slow-motion ramp together, so enemies —
        deterministic in elapsed — sit on the same pixels in both branches
        and get suppressed by _draw_ghosts; only the genuine divergence (your
        ship, your shots, enemies you killed differently) is left to draw.
        Reconstruction state is pooled per branch (`_ghost_pool`) so
        scrubbing back into a branch's range doesn't re-allocate."""
        pool = self._ghost_pool
        active = []
        for br in self._ghost_branches:
            frames = br["frames"]
            # end_t from the loaded branch metadata (decode-free); live in-play
            # branches have no end_t so fall back to the (cheap, plain-dict) last
            # frame — never decode a lazy frame just for the range check.
            end_t = br.get("end_t")
            if end_t is None:
                end_t = frames[-1]["scalars"][2]
            if br["anchor_t"] <= main_t <= end_t:
                g = pool.get(id(br))
                if g is None:
                    g = self._make_ghost(br)
                    pool[id(br)] = g
                self._seek_ghost(g, main_t)
                active.append(g)
        # Release pooled ghosts that fell out of range (frees their lists).
        if len(pool) > len(active):
            keep = {id(g["branch"]) for g in active}
            for bid in [b for b in pool if b not in keep]:
                del pool[bid]
        self._active_ghosts = active

    def _seek_ghost(self, g, main_t):
        """Point a ghost at the branch frame nearest `main_t`, scanning from
        its current cursor in whichever direction is needed (cheap for
        back-and-forth scrubbing). Branch frames are sorted by elapsed.

        The scan reads per-frame sim-times from the precomputed `times` array
        (loaded replays) so it NEVER decodes a lazy frame just to position the
        cursor — only the final chosen frame is decoded (in _reconstruct_ghost).
        Without this, a ghost (re)activated while REWINDING starts at cursor=0
        and scans to the branch end, decoding every frame on the way — the big
        backward-only spike. Live in-play branches have no `times`; their frames
        are plain dicts, so the fallback scan is already cheap."""
        frames = g["branch"]["frames"]
        times = getattr(frames, "times", None)
        n = len(frames)
        c = g["cursor"]
        if c >= n:
            c = n - 1
        if times is not None:
            while c + 1 < n and times[c + 1] <= main_t:
                c += 1
            while c > 0 and times[c] > main_t:
                c -= 1
            if c + 1 < n and abs(times[c + 1] - main_t) < abs(times[c] - main_t):
                c += 1
        else:
            while c + 1 < n and frames[c + 1]["scalars"][2] <= main_t:
                c += 1
            while c > 0 and frames[c]["scalars"][2] > main_t:
                c -= 1
            if c + 1 < n and (abs(frames[c + 1]["scalars"][2] - main_t)
                              < abs(frames[c]["scalars"][2] - main_t)):
                c += 1
        g["cursor"] = c
        self._reconstruct_ghost(g, frames[c])

    def _reconstruct_ghost(self, g, frame):
        """Rebuild a ghost's entity lists + player from one branch frame,
        reusing the live restore helpers (objects are recycled in place
        across frames, so no per-frame allocation churn)."""
        lists = g["lists"]
        for name in _GHOST_LIST_NAMES:
            _restore_list(lists[name], frame[name])
        # Re-attach the shared asset refs stripped from snapshots
        # (_REWIND_ASSET_SKIP): ghost entities are rebuilt fresh from branch
        # frames, so they'd otherwise miss them and crash on draw
        # (current_sprite reads self.assets / self._assets).
        _assets = self.assets
        for e in lists["enemies"]:
            e._assets = _assets
        pdict = frame.get("player")
        # player=None ⇒ this frame's ship matched main and was pruned from a
        # saved replay; leave the ghost ship hidden for the frame.
        g["player_visible"] = pdict is not None
        if pdict is not None:
            gp = g["player"]
            _restore_obj(gp, pdict)   # sets every field (loadout was skipped)
            gp.assets = _assets       # re-attach (stripped from the snapshot)
            lo = g["loadout"]
            for k, v in pdict.get("__loadout_state", {}).items():
                setattr(lo, k, v)
            gp.loadout = lo

    @staticmethod
    def _ghost_pos_key(e):
        """EXACT position signature used to suppress ghost copies that sit
        exactly where a kept-timeline entity is. No pixel rounding: the fixed-
        timestep sim makes non-divergent entities bit-identical (same tick
        grid, deterministic motion), so only true duplicates match and any real
        divergence shows. Float (x, y) [+ rect size] when available, else the
        rect, else ray endpoints."""
        x = getattr(e, "x", None)
        if x is not None:
            r = getattr(e, "rect", None)
            if r is not None:
                return (x, getattr(e, "y", 0.0), r.w, r.h)
            return (x, getattr(e, "y", 0.0))
        r = getattr(e, "rect", None)
        if r is not None:
            return (r.x, r.y, r.w, r.h)
        return (getattr(e, "x0", 0.0), getattr(e, "y0", 0.0),
                getattr(e, "x1", 0.0), getattr(e, "y1", 0.0))

    def _blit_one_ghost(self, target, g, main_keys, player_key, m,
                        draw_player=True):
        """Draw a single ghost's divergent entities (+ player when
        `draw_player`) onto `target`; entities/player sitting exactly where a
        kept-timeline one does are skipped. `draw_player=False` leaves the ship
        out so the caller can give it its own send-off (the death shatter or
        the CRT-off teleport). Returns True if anything was drawn."""
        key = self._ghost_pos_key
        drew = False
        lists = g["lists"]
        for name in _GHOST_LIST_NAMES:
            seen = main_keys.get(name, ())
            for e in lists[name]:
                if key(e) in seen:
                    continue
                e.draw(target, offset_x=m)
                drew = True
        if draw_player:
            gp = g["player"]
            if (g.get("player_visible", True)
                    and getattr(gp, "alive", False) and key(gp) != player_key):
                gp.draw(target, offset_x=m, sidebar_alpha=0.0,
                        sidebar_fill_override=None)
                drew = True
        return drew

    def _ghost_death_frac(self, g):
        """0 outside the dissolve, ramping 0→1 over the last _GHOST_DEATH_DUR
        seconds of the ghost's branch (sim-time, so it pauses/rewinds)."""
        frames = g["branch"]["frames"]
        remaining = frames[-1]["scalars"][2] - frames[g["cursor"]]["scalars"][2]
        if remaining >= _GHOST_DEATH_DUR:
            return 0.0
        return max(0.0, min(1.0, 1.0 - remaining / _GHOST_DEATH_DUR))

    @staticmethod
    def _ghost_branch_died(branch):
        """True if this abandoned branch ended in the player's death — the
        last frame that still carries a (non-pruned) player has alive=False.
        That's exactly the future the player rewound away from after a hit, so
        its dissolve should be a death explosion rather than a plain fade."""
        info = branch.get("death_info")          # precomputed at load (lazy)
        if info is not None:
            return info[0]
        for f in reversed(branch["frames"]):     # live-buffer branch: scan
            pd = f.get("player")
            if pd is not None:
                return not pd.get("alive", True)
        return False

    def _ghost_death_shatter(self, branch, sprite):
        """Lazily build + cache the ship-shatter shards + white-flash
        silhouette for a death branch, from the GHOST's own ship sprite. Seeded
        off the branch anchor so it's identical every draw (stable while the
        replay is paused or scrubbed). Cached in a transient dict keyed by
        id(branch) so the surfaces never get pickled into a saved replay.
        (The snapshot only carries the neutral `image`, so a ghost shatter uses
        the un-banked sprite — the live death uses the bank-aware one.)"""
        cached = self._ghost_death_bursts.get(id(branch))
        if cached is None:
            seed = int(branch["anchor_t"] * 997.0)
            cached = (build_ship_shards(sprite, seed), make_silhouette(sprite))
            self._ghost_death_bursts[id(branch)] = cached
        return cached

    @staticmethod
    def _branch_ship_sprite(branch):
        """The ghost ship sprite for a branch: the neutral `image` from the
        first player-bearing frame (loaded replays resolve surface tags to real
        Surfaces at decode, live replays carry them directly). Same ship for
        every ghost of a run, so it doubles as the live-ship texture source."""
        if "ship_sprite" in branch:              # precomputed at load (lazy)
            return branch["ship_sprite"]
        for f in branch["frames"]:               # live-buffer branch: scan
            pd = f.get("player")
            if pd is not None:
                img = pd.get("image")
                if isinstance(img, pygame.Surface):
                    return img
        return None

    def _gpu_ghost_death_target(self, gpu):
        """Cached PLAY_W render-target texture for the GPU death send-off layer
        (shatter / CRT power-off), composited brighter than the steady ghost
        field at _GHOST_SHATTER_ALPHA."""
        t = getattr(self, "_gpu_ghost_death_tex", None)
        if t is None:
            t = self._gpu_ghost_death_tex = gpu.make_target((PLAY_W, PLAY_H))
        return t

    def _ghost_death_gpu_bundle(self, branch):
        """Build (once, cached) the per-branch GPU death bundle: for a death
        branch the shard slice + additive-white-hot textures + the silhouette;
        for a rewound-alive branch the ship + white-ship textures the CRT
        power-off scales. All reuse gpu.tex_for (shared textures). Returns {} if
        no GPU or no sprite (the software path stays in use then)."""
        b = self._ghost_death_gpu.get(id(branch))
        if b is not None:
            return b
        b = {}
        gpu = getattr(self.app, "gpu", None)
        sprite = self._branch_ship_sprite(branch)
        if gpu is None or sprite is None:
            self._ghost_death_gpu[id(branch)] = b
            return b
        # upload_tex (NOT tex_for): these per-branch textures are owned by the
        # bundle and destroyed when _exit_replay clears self._ghost_death_gpu.
        # tex_for would cache them by surface-id in gpu._dyn and never free them
        # — a replay (esp. one with many death branches) would leak hundreds of
        # GPU textures permanently, exhausting GPU memory across sessions.
        if self._ghost_branch_died(branch):
            seed = int(branch["anchor_t"] * 997.0)
            shards = build_ship_shards(sprite, seed)
            sgpu = []
            for sh in shards:
                sl = sh.slice
                wsl = make_silhouette(sl)
                sgpu.append((sh, gpu.upload_tex(sl), gpu.upload_tex(wsl),
                             (sl.get_width(), sl.get_height())))
            sil = make_silhouette(sprite)
            b["shards"] = sgpu
            b["sil_tex"] = gpu.upload_tex(sil)
            b["sil_w"] = sil.get_width()
            b["sil_h"] = sil.get_height()
        else:
            wsp = make_silhouette(sprite)
            b["ship_tex"] = gpu.upload_tex(sprite)
            b["white_ship_tex"] = gpu.upload_tex(wsp)
            b["ship_w"] = sprite.get_width()
            b["ship_h"] = sprite.get_height()
        self._ghost_death_gpu[id(branch)] = b
        return b

    def _prepare_ghost_death_gpu(self):
        """At replay START (not first dissolve): pre-bake every branch's death
        bundle + the shared ring/halo/line/star/glow textures, so the first
        ghost send-off doesn't pay the build+upload hitch mid-playback. No-op on
        the software renderer (it uses the procedural software path)."""
        self._ghost_death_gpu = {}
        gpu = getattr(self.app, "gpu", None)
        if gpu is None:
            return
        for k, builder in (("ghd_ring", _build_ghd_ring),
                           ("ghd_line", _build_ghd_line),
                           ("ghd_star", _build_ghd_star),
                           ("ghd_starglow", _build_ghd_starglow),
                           ("ghd_halo", self._crt_halo_surf)):
            try:
                gpu.baked(k, builder)
            except Exception:
                pass
        for branch in self._ghost_branches:
            try:
                self._ghost_death_gpu_bundle(branch)
            except Exception:
                pass

    def _ghost_death_info(self, branch):
        """(died, death_t, death_x, death_y, span) for a branch, cached.
        death_t/pos come from the FIRST frame whose player is present and
        alive=False — the ACTUAL death frame — not "branch end minus 0.2 s".
        That's what makes the ghost's split fire at the right moment and sit at
        the right spot (the old frac-driven anchor lagged by the dead-pause
        tail and tracked the drifting current frame). `span` is that tail:
        death_t → branch end, what the shatter plays across."""
        info = branch.get("death_info")          # precomputed at load (lazy)
        if info is not None:
            return info
        info = self._ghost_death_info_cache.get(id(branch))
        if info is None:
            frames = branch["frames"]
            died = False
            dt = dx = dy = 0.0
            for f in frames:
                pd = f.get("player")
                if pd is not None and not pd.get("alive", True):
                    died = True
                    dt = f["scalars"][2]
                    rect = pd.get("rect")
                    if (isinstance(rect, tuple) and len(rect) == 5
                            and rect[0] == _REWIND_RECT_TAG):
                        dx = rect[1] + rect[3] / 2.0   # topleft + half = centre
                        dy = rect[2] + rect[4] / 2.0
                    else:
                        dx = float(pd.get("x", 0.0))
                        dy = float(pd.get("y", 0.0))
                    break
            span = max(1e-3, frames[-1]["scalars"][2] - dt) if died else 0.0
            info = (died, dt, dx, dy, span)
            self._ghost_death_info_cache[id(branch)] = info
        return info

    def _draw_ghost_shatter(self, surf, g, info, t, m):
        """Draw the death-branch ship shatter, anchored to the RECORDED death
        frame/position (info), returning True if it painted. Plays from age 0
        (the white flash, exactly on the death frame) as the ghost's playback
        time `t` crosses death_t, mapping the dead-pause tail span → a full
        1.2 s shatter so it's extinguished by branch end (no pop). Drawn on the
        brighter _GHOST_SHATTER_ALPHA layer: the player ghost becomes the blast,
        fixed in place, not dissolving and not tracking the current frame."""
        died, dt, dx, dy, span = info
        sprite = getattr(g["player"], "image", None)
        if sprite is None:
            return False
        age = max(0.0, min(1.0, (t - dt) / span)) * 1.2
        if age > _DEATH_FX_DUR:
            return False
        shards, sil = self._ghost_death_shatter(g["branch"], sprite)
        blit_death_fx(surf, shards, sil, dx, dy, age, offset_x=m)
        return True

    # CRT / black-hole power-off tuning. Fraction of the branch-end window the
    # ship spends squashing to a streak (while widening toward the line).
    _CRT_OFF_VFRAC = 0.64

    def _crt_line_surf(self, w, h, alpha):
        """A feathered horizontal line: full-bright in the middle rows, alpha
        falling off smoothly to transparent at top and bottom (so it's a soft
        glowing band, not a hard rectangle). Built from a cached 1px-wide
        vertical gradient scaled to `w`, then masked to `alpha`."""
        grad = self._crt_line_grad
        if grad is None or grad.get_height() != h:
            grad = pygame.Surface((1, h), pygame.SRCALPHA)
            for y in range(h):
                d = abs((y + 0.5) / h - 0.5) * 2.0    # 0 centre → 1 edge
                fa = max(0.0, 1.0 - d * d)             # smooth (parabolic) feather
                grad.set_at((0, y), (255, 255, 255, int(255 * fa)))
            self._crt_line_grad = grad
        line = pygame.transform.scale(grad, (max(1, w), h)).copy()
        line.fill((255, 255, 255, alpha), special_flags=pygame.BLEND_RGBA_MULT)
        return line

    def _crt_halo_surf(self):
        """Cached base halo: a soft bluish-white GLOW, brightest at the centre
        and feathering to transparent at the edge (full inside — no dark core).
        Built once; the caller scales it per frame."""
        halo = self._crt_halo
        if halo is None:
            D = 96
            hh = D // 2
            halo = pygame.Surface((D, D), pygame.SRCALPHA)
            # Paint big→small so each filled circle leaves a smooth radial
            # gradient: alpha peaks at the centre, fades to 0 at the rim.
            for rr in range(hh, 0, -1):
                t = rr / hh                       # 1 = edge, 0 = centre
                a = int(235 * (1.0 - t) ** 1.7)   # bright core → transparent
                pygame.draw.circle(halo, (185, 220, 255, a), (hh, hh), rr)
            self._crt_halo = halo
        return halo

    def _draw_ghost_crt_off(self, surf, g, frac, m):
        """Send-off for a ghost the player REWOUND away from while still alive
        (a non-death branch): instead of a plain alpha dissolve, the ship gets
        sucked into a BLACK HOLE. It squashes to a streak fast, a dark accretion
        core + bright rim swell up and swallow it, and a big feathered hot line
        stretches across (the matter spaghettified into the disc) before the
        whole thing pinches to a point and flashes out. Driven by the dissolve
        `frac` (0→1 over the last _GHOST_DEATH_DUR), so it's sim-timed and
        rewind/scrub-safe. Drawn straight onto `surf`."""
        gp = g["player"]
        sprite = getattr(gp, "image", None)
        r = getattr(gp, "rect", None)
        if (sprite is None or r is None
                or not g.get("player_visible", True)
                or not getattr(gp, "alive", False)):
            return False
        cx = int(r.centerx + m)
        cy = int(r.centery)
        w0, h0 = sprite.get_width(), sprite.get_height()
        s = frac
        # Overall opacity: hold, then fade the last sliver so nothing pops.
        a = 235 if s < 0.85 else int(235 * (1.0 - (s - 0.85) / 0.15))
        vc = self._CRT_OFF_VFRAC
        LL = w0 * 2.0                              # full hot-line length
        # Halo glow: rises, holds, gone by ~0.90 (75% of the old diameter).
        env_halo = min(clamp(s / 0.30, 0.0, 1.0),
                       clamp((0.90 - s) / 0.30, 0.0, 1.0))
        # Line length: ramps in, stays LONG, only starts shrinking once the
        # halo is almost gone (~0.78), pinched out by ~0.96.
        line_env = min(clamp(s / 0.30, 0.0, 1.0),
                       clamp((0.96 - s) / 0.18, 0.0, 1.0))

        # 1. The squashing ship — 2× slower vertical collapse, and it WIDENS as
        #    it flattens (toward ~0.9× the line) so it stretches into the line.
        vp = clamp(s / vc, 0.0, 1.0)
        if a > 0 and vp < 1.0:
            sh_h = max(1, int(round(h0 * (1.0 - vp))))
            sh_w = max(1, int(round(w0 + (LL * 0.9 - w0) * vp)))
            img = pygame.transform.scale(sprite, (sh_w, sh_h)).copy()
            wv = int(220 * s)
            if wv > 0:
                img.fill((wv, wv, wv, 0), special_flags=pygame.BLEND_RGB_ADD)
            img.fill((255, 255, 255, a), special_flags=pygame.BLEND_RGBA_MULT)
            surf.blit(img, img.get_rect(center=(cx, cy)))

        # 2. Halo glow — full-inside bluish glow, swelling over the ship then
        #    fading out.
        hr = int(w0 * 1.065 * env_halo)
        if a > 0 and hr > 2:
            halo = pygame.transform.scale(
                self._crt_halo_surf(), (hr * 2, hr * 2)).copy()
            halo.fill((255, 255, 255, int(a * 0.92)),
                      special_flags=pygame.BLEND_RGBA_MULT)
            surf.blit(halo, halo.get_rect(center=(cx, cy)))

        # 3. Big feathered hot line — thin, held long, on top.
        lw = int(LL * line_env)
        if a > 0 and lw > 2:
            line = self._crt_line_surf(lw, 4, a)
            surf.blit(line, line.get_rect(center=(cx, cy)))

        # 4. Final X-sparkle — a quick little diagonal 4-point star flash once
        #    the collapse is essentially done. Drawn 3× supersampled then
        #    smoothscaled down so the rays are soft/anti-aliased (not hard
        #    polygon edges), with a faint glow behind.
        if s > 0.86:
            fa = math.sin(clamp((s - 0.86) / 0.14, 0.0, 1.0) * math.pi)
            if fa > 0.03:
                L = max(2, int(w0 * 0.33 * (0.6 + 0.4 * fa)))   # 60% of prior
                sa_ = int(255 * fa)
                bw = 1.0 + 2.0 * fa
                pad = max(3, int(L * 0.5))
                D = L * 2 + pad * 2
                c = D / 2.0
                ss = 3
                big = pygame.Surface((D * ss, D * ss), pygame.SRCALPHA)
                cb = c * ss
                col = (255, 255, 255, sa_)
                for dx, dy in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                    nx, ny = dx * 0.70711, dy * 0.70711   # ray unit (diagonal)
                    px, py = -ny, nx                       # perpendicular unit
                    pygame.draw.polygon(big, col, [
                        (cb + px * bw * ss, cb + py * bw * ss),
                        (cb + nx * L * ss, cb + ny * L * ss),
                        (cb - px * bw * ss, cb - py * bw * ss)])
                pygame.draw.circle(big, col, (int(cb), int(cb)),
                                   max(1, int(3 * fa * ss)))
                spark = pygame.transform.smoothscale(big, (D, D))
                # Soft glow behind the star for extra feathering.
                gr = int(L * 0.7)
                if gr > 1:
                    glow = pygame.Surface((gr * 2, gr * 2), pygame.SRCALPHA)
                    for rr in range(gr, 0, -1):
                        t = rr / gr
                        ga = int(sa_ * 0.30 * (1.0 - t) ** 2)
                        pygame.draw.circle(glow, (200, 225, 255, ga),
                                           (gr, gr), rr)
                    surf.blit(glow, glow.get_rect(center=(cx, cy)))
                surf.blit(spark, spark.get_rect(center=(cx, cy)))
        return True

    def _draw_ghost_shatter_gpu(self, gpu, bundle, g, info, t, off):
        """GPU sibling of _draw_ghost_shatter — same age mapping, draws the
        shatter onto the current target (the death layer) via blit_death_fx_gpu.
        Returns True if it painted."""
        died, dt, dx, dy, span = info
        if not bundle.get("shards"):
            return False
        age = max(0.0, min(1.0, (t - dt) / span)) * 1.2
        if age > _DEATH_FX_DUR:
            return False
        blit_death_fx_gpu(gpu, bundle, dx, dy, age, offset_x=off)
        return True

    def _draw_ghost_crt_off_gpu(self, gpu, bundle, g, frac, off):
        """GPU sibling of _draw_ghost_crt_off — the black-hole power-off, drawn
        onto the current target (the death layer). Envelope math copied verbatim;
        each software surface op maps to a GPU blit: scaled dst rect = scale,
        additive white-ship = white-hot wash, baked halo/line/star textures
        scaled + alpha'd per frame. Returns True if it painted."""
        gp = g["player"]
        r = getattr(gp, "rect", None)
        ship = bundle.get("ship_tex")
        if (ship is None or r is None
                or not g.get("player_visible", True)
                or not getattr(gp, "alive", False)):
            return False
        cx = int(r.centerx + off)
        cy = int(r.centery)
        w0 = bundle["ship_w"]
        h0 = bundle["ship_h"]
        s = frac
        a = 235 if s < 0.85 else int(235 * (1.0 - (s - 0.85) / 0.15))
        if a <= 0:
            return False
        vc = self._CRT_OFF_VFRAC
        LL = w0 * 2.0
        env_halo = min(clamp(s / 0.30, 0.0, 1.0),
                       clamp((0.90 - s) / 0.30, 0.0, 1.0))
        line_env = min(clamp(s / 0.30, 0.0, 1.0),
                       clamp((0.96 - s) / 0.18, 0.0, 1.0))
        # 1. Squashing ship (+ additive white-hot wash).
        vp = clamp(s / vc, 0.0, 1.0)
        if vp < 1.0:
            sh_h = max(1, int(round(h0 * (1.0 - vp))))
            sh_w = max(1, int(round(w0 + (LL * 0.9 - w0) * vp)))
            dst = pygame.Rect(cx - sh_w // 2, cy - sh_h // 2, sh_w, sh_h)
            gpu.blit(ship, dst, alpha=a)
            wv = int(220 * s)
            if wv > 0:
                wt = bundle["white_ship_tex"]
                wt.blend_mode = 2
                gpu.blit(wt, dst, alpha=min(255, int(wv * a / 255)))
                wt.blend_mode = 1
        # 2. Halo glow.
        hr = int(w0 * 1.065 * env_halo)
        if hr > 2:
            halo = gpu.baked("ghd_halo", self._crt_halo_surf)
            gpu.blit(halo, pygame.Rect(cx - hr, cy - hr, hr * 2, hr * 2),
                     alpha=int(a * 0.92))
        # 3. Feathered hot line.
        lw = int(LL * line_env)
        if lw > 2:
            line = gpu.baked("ghd_line", _build_ghd_line)
            gpu.blit(line, pygame.Rect(cx - lw // 2, cy - 2, lw, 4), alpha=a)
        # 4. Final X-sparkle + glow.
        if s > 0.86:
            fa = math.sin(clamp((s - 0.86) / 0.14, 0.0, 1.0) * math.pi)
            if fa > 0.03:
                L = max(2, int(w0 * 0.33 * (0.6 + 0.4 * fa)))
                sa_ = int(255 * fa)
                gr = int(L * 0.7)
                if gr > 1:
                    glow = gpu.baked("ghd_starglow", _build_ghd_starglow)
                    gpu.blit(glow, pygame.Rect(cx - gr, cy - gr, gr * 2, gr * 2),
                             alpha=sa_)
                star = gpu.baked("ghd_star", _build_ghd_star)
                D = max(2, int(L * (_GHD_STAR_REF * 2 + _GHD_STAR_REF) / _GHD_STAR_REF))
                gpu.blit(star, pygame.Rect(cx - D // 2, cy - D // 2, D, D), alpha=sa_)
        return True

    def _render_ghost_field(self, gs, sh):
        """Draw every active ghost's entity field (and any death shatter / CRT
        power-off) onto the two PLAY_W software surfaces `gs` (the steady field)
        and `sh` (the brighter death shatter). Shared by the software
        (_draw_ghosts) and GPU (_draw_ghosts_gpu) compositors — it produces the
        un-glitched, un-faded ghost pixels; the caller owns tears/scanline/fade/
        composite. Returns (drew, shatter_drew, max_frac). Caller clears gs/sh.

        Ghost entities whose position exactly matches a kept-timeline entity of
        the same category are skipped — only the divergence (your ship, your
        shots, enemies that lived/died differently) shows. A ghost in the last
        _GHOST_DEATH_DUR s of its branch is "dying" (frac>0): its player sprite
        is replaced by the CRT power-off and the whole layer's glitch ramps with
        the most-advanced dissolve (max_frac)."""
        _perf = self.app.perf
        _perf.start("gh.keys")
        # Per-category position sets from the kept (just-restored) timeline.
        main_lists = {"bullets": self.bullets, "balls": self.balls,
                      "enemies": self.enemies, "pickups": self.pickups,
                      "sparks": self.sparks, "lasers": self.lasers,
                      "rays": self.rays, "explosions": self.explosions,
                      "float_texts": self.float_texts}
        key = self._ghost_pos_key
        main_keys = {n: {key(e) for e in lst} for n, lst in main_lists.items()}
        player_key = key(self.player) if self.player.alive else None
        _perf.end("gh.keys")
        # PERF DIAGNOSTIC: log active/dying ghost counts at a low rate.
        self._gh_dbg = getattr(self, "_gh_dbg", 0) + 1
        if self._gh_dbg % 20 == 0:
            _nd = sum(1 for _g in self._active_ghosts
                      if self._ghost_death_frac(_g) > 0.0)
            _ne = sum(len(_g["lists"][n]) for _g in self._active_ghosts
                      for n in _GHOST_LIST_NAMES)
            print("[gh] active=%d dying=%d ghost_entities=%d"
                  % (len(self._active_ghosts), _nd, _ne), file=sys.stderr)

        _perf.start("gh.blit")
        # ALL ghost entities (normal + dying) go onto ONE PLAY_W surface, drawn
        # at offset 0 and composited onto the wider target at the margin. Dying
        # ghosts no longer get their own per-ghost full-surface glitch/fade
        # (that was the gh.dying spike — one surface clear+glitch+fade+blit per
        # dissolving branch). Instead the WHOLE layer's glitch intensity ramps
        # toward 2x while any ghost is dissolving (max_frac below) — a global
        # shudder in place of the per-ghost ramp. The cost: dying entities pop
        # out at branch end instead of fading, masked by that shudder; the ship
        # send-off (shatter / CRT power-off) still plays per ghost.
        drew = False
        shatter_drew = False
        max_frac = 0.0
        for g in self._active_ghosts:
            # Death shatter is anchored to the RECORDED death frame/position;
            # rides its own brighter layer (sh), composited separately.
            info = self._ghost_death_info(g["branch"])
            t = g["branch"]["frames"][g["cursor"]]["scalars"][2]
            if info[0] and t >= info[1]:
                if self._draw_ghost_shatter(sh, g, info, t, 0):
                    shatter_drew = True
            frac = self._ghost_death_frac(g)
            dying = frac > 0.0
            if self._blit_one_ghost(gs, g, main_keys, player_key, 0,
                                    draw_player=not dying):
                drew = True
            if dying:
                if frac > max_frac:
                    max_frac = frac
                # Rewound-while-alive ship: the CRT power-off (incl. the final
                # star) rides ON the glitched layer too — drawn onto gs so it
                # picks up the same tear/scanline shudder + ghost fade.
                if not info[0]:
                    self._draw_ghost_crt_off(gs, g, frac, 0)
                    drew = True
        _perf.end("gh.blit")
        return drew, shatter_drew, max_frac

    def _draw_ghosts(self, surf):
        """Software compositor: draw the ghost field, then apply the glitch
        (tears + scanline), the _GHOST_ALPHA fade, and composite onto `surf` —
        all in software (three full-surface ops). The GPU renderer uses
        _draw_ghosts_gpu instead, which keeps the entity render in software but
        does the glitch/fade/composite as GPU passes."""
        m = PLAY_MARGIN
        gs = self._ghost_surf
        gs.fill((0, 0, 0, 0))
        sh = self._ghost_shatter_surf
        sh.fill((0, 0, 0, 0))
        drew, shatter_drew, max_frac = self._render_ghost_field(gs, sh)
        _perf = self.app.perf
        _perf.start("gh.glitch")
        if drew:
            # One glitch for the whole layer; intensity ramps with the most-
            # advanced dissolve (1x idle -> 2x as a ghost ends).
            mul = 1.0 + max_frac
            _apply_ghost_glitch(gs, glitch_mul=mul, scanline_mul=mul)
            gs.fill((255, 255, 255, _GHOST_ALPHA),
                    special_flags=pygame.BLEND_RGBA_MULT)
            surf.blit(gs, (m, 0))
        if shatter_drew:
            sh.fill((255, 255, 255, _GHOST_SHATTER_ALPHA),
                    special_flags=pygame.BLEND_RGBA_MULT)
            surf.blit(sh, (m, 0))
        _perf.end("gh.glitch")

    def _gpu_ghost_target(self, gpu):
        """Cached PLAY_W render-target texture for the GPU ghost compositor —
        the isolated layer the scanline MOD pass operates on (so it dims only
        ghost pixels, not the scene behind)."""
        t = getattr(self, "_gpu_ghost_tex", None)
        if t is None:
            t = self._gpu_ghost_tex = gpu.make_target((PLAY_W, PLAY_H))
        return t

    def _draw_one_ghost_gpu(self, gpu, g, main_keys, player_key, draw_player=True):
        """GPU sibling of _blit_one_ghost: draw a ghost's divergent entities (+
        player when `draw_player`) NATIVELY via each entity's draw_gpu onto the
        renderer's current target (the isolated ghost target), at offset 0.
        No software rasterisation — every sprite reuses the SHARED uploaded
        texture (gpu.tex_for caches by surface id), so the ghost player ship
        draws from the very same texture as the live ship. Position-deduped
        against the kept timeline exactly like the software path. Returns True
        if anything drew."""
        key = self._ghost_pos_key
        drew = False
        lists = g["lists"]
        for name in _GHOST_LIST_NAMES:
            seen = main_keys.get(name, ())
            for e in lists[name]:
                if key(e) in seen:
                    continue
                e.draw_gpu(gpu, offset_x=0)
                drew = True
        if draw_player:
            gp = g["player"]
            if (g.get("player_visible", True)
                    and getattr(gp, "alive", False) and key(gp) != player_key):
                gp.draw_gpu(gpu, offset_x=0, sidebar_alpha=0.0,
                            sidebar_fill_override=None)
                drew = True
        return drew

    def _render_ghost_layers(self, gpu):
        """RENDER the ghost layer onto its own isolated targets (ght = the steady
        ghost field + scanline MOD; ghd = the brighter death send-offs). Ghost
        ENTITIES draw NATIVELY (draw_gpu) reusing the shared sprite textures.

        CALLED BEFORE the scene is drawn onto `frame` (see _draw_gpu), so the
        render-target is never switched AWAY from `frame` after it holds the
        scene — on tiled mobile GPUs (Mali/Adreno) re-binding a target doesn't
        reload its prior contents, which blanked the ribbon/scene behind the
        ghosts to black. The matching _composite_ghost_layers then blits these
        targets ONTO `frame` without any further target switch. Returns
        (drew, max_frac, death_drew); the targets are self._gpu_ghost_tex /
        self._gpu_ghost_death_tex."""
        _perf = self.app.perf
        _perf.start("gh.keys")
        main_lists = {"bullets": self.bullets, "balls": self.balls,
                      "enemies": self.enemies, "pickups": self.pickups,
                      "sparks": self.sparks, "lasers": self.lasers,
                      "rays": self.rays, "explosions": self.explosions,
                      "float_texts": self.float_texts}
        key = self._ghost_pos_key
        main_keys = {n: {key(e) for e in lst} for n, lst in main_lists.items()}
        player_key = key(self.player) if self.player.alive else None
        _perf.end("gh.keys")
        # PERF DIAGNOSTIC: log active/dying ghost counts + GPU tex-cache size +
        # process RSS at a low rate — so an OOM/thrash during replay shows its
        # growth curve in last_run.log (memory leak hunt 2026-06-09).
        self._gh_dbg = getattr(self, "_gh_dbg", 0) + 1
        if self._gh_dbg % 20 == 0:
            _nd = sum(1 for _g in self._active_ghosts
                      if self._ghost_death_frac(_g) > 0.0)
            _ne = sum(len(_g["lists"][n]) for _g in self._active_ghosts
                      for n in _GHOST_LIST_NAMES)
            print("[gh] active=%d dying=%d ghost_entities=%d dyn=%d rss=%dMB"
                  % (len(self._active_ghosts), _nd, _ne,
                     len(getattr(gpu, "_dyn", ())), _proc_rss_mb()), file=sys.stderr)
        # Pass 1 — ghost entities: native draw onto the isolated GPU target.
        ght = self._gpu_ghost_target(gpu)
        gpu.set_target(ght)
        gpu.begin((0, 0, 0, 0))
        _perf.start("gh.blit")
        drew = False
        max_frac = 0.0
        death_fx = []   # (g, info, t, frac, shatter, crtoff) to render on ghd
        for g in self._active_ghosts:
            info = self._ghost_death_info(g["branch"])
            t = g["branch"]["frames"][g["cursor"]]["scalars"][2]
            shatter = info[0] and t >= info[1]
            frac = self._ghost_death_frac(g)
            dying = frac > 0.0
            crtoff = dying and not info[0]
            if self._draw_one_ghost_gpu(gpu, g, main_keys, player_key,
                                        draw_player=not dying):
                drew = True
            if dying and frac > max_frac:
                max_frac = frac
            if shatter or crtoff:
                death_fx.append((g, info, t, frac, shatter, crtoff))
        _perf.end("gh.blit")
        _perf.start("gh.glitch")
        if drew:
            # Scanline MOD on the ghost target — quantise the dim ramp so we hit
            # the launch-baked ladder (a handful of textures), not one per frame.
            dim = min(255, int(round(_GHOST_GLITCH.scanline_dim
                                     * (1.0 + round(max_frac * 4) / 4))))
            scan = gpu.baked(("ghostscan", PLAY_W, PLAY_H, dim),
                             lambda d=dim: _ghost_scanline_mod(
                                 PLAY_W, PLAY_H, d / _GHOST_GLITCH.scanline_dim))
            scan.blend_mode = 4   # SDL_BLENDMODE_MOD — dstRGB *= srcRGB, keep dstA
            gpu.blit(scan, pygame.Rect(0, 0, PLAY_W, PLAY_H))
        # Pass 2 — death send-offs onto the brighter death target.
        death_drew = False
        if death_fx:
            ghd = self._gpu_ghost_death_target(gpu)
            gpu.set_target(ghd)
            gpu.begin((0, 0, 0, 0))
            for g, info, t, frac, shatter, crtoff in death_fx:
                bundle = self._ghost_death_gpu_bundle(g["branch"])
                if shatter and self._draw_ghost_shatter_gpu(gpu, bundle, g, info, t, 0):
                    death_drew = True
                if crtoff and self._draw_ghost_crt_off_gpu(gpu, bundle, g, frac, 0):
                    death_drew = True
        _perf.end("gh.glitch")
        self._ghost_max_frac = max_frac
        return drew, max_frac, death_drew

    def _composite_ghost_layers(self, gpu, m, drew, max_frac, death_drew):
        """Blit the already-rendered ghost (+ death) targets ONTO the scene —
        `frame` must already be the CURRENT render target (the caller drew the
        scene then calls this). No target switch happens here, so a tiled GPU
        never has to reload `frame`. Pairs with _render_ghost_layers."""
        _perf = self.app.perf
        _perf.start("gh.glitch")
        if drew:
            _composite_ghost_gpu(gpu, self._gpu_ghost_tex, (m, 0, PLAY_W, PLAY_H),
                                 1.0 + max_frac, _GHOST_ALPHA)
        if death_drew:
            gpu.blit(self._gpu_ghost_death_tex, pygame.Rect(m, 0, PLAY_W, PLAY_H),
                     alpha=_GHOST_SHATTER_ALPHA)
        _perf.end("gh.glitch")

    def _sidebar_alpha(self):
        """Sidebar fade gate. Fades the cooldown arcs in
        during the 2.4 s takeoff cinematic and out across the full
        outro (cinematic + fade-to-black). Plain function of intro_t
        and outro_t, both of which are part of the rewind snapshot
        scalars — so rewinding into / past the intro restores the
        same alpha automatically without extra plumbing."""
        if self.intro_t > 0:
            return clamp(1.0 - self.intro_t / 2.4, 0.0, 1.0)
        if self.outro_t > 0:
            return clamp(self.outro_t / max(0.001, OUTRO_TOTAL_DUR),
                         0.0, 1.0)
        return 1.0

    # Forced sidebar fill duration during the takeoff intro. Sidebars
    # animate 0 → 1 over this many seconds, then pin at 1 for the rest
    # of the intro. Outside the intro the gauges go back to live
    # cooldown values (which start at 0 = ready = full).
    _SIDEBAR_INTRO_FILL_DUR = 2.0

    def _sidebar_intro_fill(self):
        """Forced 0→1 sweep during the intro, then None — outside the
        intro the gauges revert to actual cooldown ratios. Driven off
        intro_t so it's automatically rewind-safe (intro_t lives in
        the snapshot scalars)."""
        if self.intro_t <= 0:
            return None
        elapsed = 2.4 - self.intro_t
        return clamp(elapsed / max(0.001, self._SIDEBAR_INTRO_FILL_DUR),
                     0.0, 1.0)

    def _resync_stuck_balls(self):
        """Re-bind any Ball.stuck_to ref to its current live host after
        a rewind+restore. The snap's stuck_to holds a Python ref that
        may be pointing at an ORPHAN copy of the enemy (when
        _restore_list created a fresh object because the live list was
        shorter at restore time, or because the class at that index
        differed). Match by Enemy._spawn_idx — a per-construction
        monotonic counter that's snapshotted alongside the rest of
        the enemy's state — so the re-attach lands on the same logical
        enemy regardless of Python object identity. If the host is
        truly gone (or dead), detach so the ball floats at its parked
        position and the player can still manually detonate."""
        if not self.balls:
            return
        by_idx = {}
        for e in self.enemies:
            sid = getattr(e, "_spawn_idx", None)
            if sid is not None:
                by_idx[sid] = e
        for ball in self.balls:
            if ball.stuck_to is None:
                continue
            host = ball.stuck_to
            # Snapshots store stuck_to as the host's `_spawn_idx` int (ref-free,
            # so the live buffer compresses losslessly); live play may still hold
            # a real Enemy ref. Accept either.
            target_idx = host if isinstance(host, int) else getattr(host, "_spawn_idx", None)
            live_host = by_idx.get(target_idx)
            if live_host is None or not live_host.alive:
                ball.stuck_to = None
                continue
            # Re-point at the live host AND snap world position so
            # multi-step rewinds don't accumulate drift from the
            # snap-stored x/y vs the live host's actual centre.
            ball.stuck_to = live_host
            ball.x = live_host.rect.centerx + ball.stuck_dx
            ball.y = live_host.rect.centery + ball.stuck_dy

    # Off-screen-enemy arrow geometry. Fixed size now — the urgency
    # channel is the blink rate only. The arrow's TIP sits on the
    # screen edge and its BASE sits on the circle's outer edge, so
    # the circle is pulled inward from the edge by exactly BODY_LEN.
    # 50% smaller than the original triangle since the dominant
    # marker now is the red-circle icon.
    _MARKER_BODY_LEN = 8.0
    _MARKER_HALF_W = 5.0
    # Every arrow pulses together at a fixed 2 Hz (brightness 0.4→1.0), in
    # the same red as the marker ring — no per-enemy tint, no distance-based
    # blink rate. Wall-clock driven so it keeps pulsing while paused.
    _MARKER_PULSE_HZ = 2.0
    _MARKER_ARROW_COLOR = _MARKER_CIRCLE_COLOR   # (220, 30, 30), match the ring

    def _draw_offscreen_enemy_markers(self, surf):
        pf_w, pf_h = PLAY_W, PLAY_H
        # All arrows share one 2 Hz brightness pulse (0.4→1.0), computed once
        # per frame off the wall clock. Drawn in screen space onto `surf` —
        # the framebuffer (software) or the SRCALPHA overlay the GPU path
        # uploads via blit_dynamic — so this renders identically on GPU.
        now_s = pygame.time.get_ticks() * 0.001
        pulse = 0.5 + 0.5 * math.sin(
            now_s * (2.0 * math.pi * self._MARKER_PULSE_HZ))
        bright = 0.4 + 0.6 * pulse
        ar, ag, ab = self._MARKER_ARROW_COLOR
        arrow_col = (int(ar * bright), int(ag * bright), int(ab * bright))
        for e in self.enemies:
            if not e.alive:
                continue
            if isinstance(e, Wall):
                continue  # indestructible scenery — no urgency to surface
            er = e.rect
            if (er.right > 0 and er.left < pf_w
                    and er.bottom > 0 and er.top < pf_h):
                continue  # any part visible — no marker
            ex, ey = er.centerx, er.centery
            # Suppress markers for enemies above the top of the screen.
            # The original spec was "sides and bottom only" — top-edge
            # escapes typically come from wave-spawn arrivals that just
            # haven't entered yet, and a marker there reads as noise
            # rather than an urgent escape signal.
            if ey <= 0:
                continue
            cx = 0 if ex < 0 else (pf_w - 1 if ex >= pf_w else ex)
            cy = 0 if ey < 0 else (pf_h - 1 if ey >= pf_h else ey)
            dx = ex - cx
            dy = ey - cy
            d = math.hypot(dx, dy)
            if d < 1.0:
                continue
            nx = dx / d
            ny = dy / d

            # Geometry: arrow TIP at the screen edge (= clamped cx, cy);
            # arrow BASE one body-length inward; circle outer edge sits
            # on the arrow base. Circle is therefore pulled inward by
            # exactly BODY_LEN, leaving room for the arrow to live
            # entirely on-screen instead of poking outside the visible
            # area.
            body_len = self._MARKER_BODY_LEN
            half_w = self._MARKER_HALF_W
            tip_x = cx
            tip_y = cy
            base_mx = cx - nx * body_len
            base_my = cy - ny * body_len

            # Icon: centre = arrow base − direction × radius (so the
            # circle's outer edge meets the arrow base from inward).
            icon, icon_r = _get_marker_icon(e)
            if icon is not None and icon_r > 0:
                ic_x = int(base_mx - nx * icon_r)
                ic_y = int(base_my - ny * icon_r)
                surf.blit(icon, icon.get_rect(center=(ic_x, ic_y)))

            # Perpendicular for the base corners.
            b1x = base_mx + -ny * half_w
            b1y = base_my + nx * half_w
            b2x = base_mx - -ny * half_w
            b2y = base_my - nx * half_w
            pygame.draw.polygon(
                surf, arrow_col,
                [(int(tip_x), int(tip_y)),
                 (int(b1x), int(b1y)),
                 (int(b2x), int(b2y))])

    def _apply_glitch_overlay(self, screen):
        """Old-TV CRT glitch over the playfield rect (0..PLAY_W, 0..PLAY_H).
        Intensity is self._glitch_t ∈ [0, 1]. Driven by the PLAY profile
        — tune _CRT_PROFILE_PLAY at module level to dial this overlay
        independently of the title-screen logo distortion."""
        if self._glitch_overlay is None:
            self._glitch_overlay = _build_crt_scanline_overlay(
                PLAY_W, PLAY_H, _CRT_PROFILE_PLAY)
        _apply_crt_glitch(screen, (0, 0, PLAY_W, PLAY_H), self._glitch_t,
                          profile=_CRT_PROFILE_PLAY,
                          scanline_cache=self._glitch_overlay)
        # The "HOLD X TO REWIND" prompt is NOT drawn here — it lives in
        # _draw_dead_pause_prompt, called from the shared _draw_screen_overlays
        # so BOTH the software path and the GPU overlay pass render it (the
        # GPU path never calls _apply_glitch_overlay, so an inline prompt here
        # was invisible on-device).

    def _draw_dead_pause_prompt(self, surf):
        """Pulsing "HOLD X TO REWIND" hint shown while paused-after-death.
        Drawn in screen space (PLAY_W/PLAY_H centred) onto `surf` — the real
        framebuffer in the software path, the SRCALPHA overlay surface in the
        GPU path. Called from _draw_screen_overlays (gated on _dead_paused) so
        it's shared by both render paths."""
        font = self.app.fonts.get("big") or self.app.fonts.get("small")
        if font is None:
            return
        t = pygame.time.get_ticks() * 0.006
        pulse = 0.6 + 0.4 * math.sin(t)
        jx = random.randint(-1, 1)
        jy = random.randint(-1, 1)
        label = "HOLD {btn_bomb} TO REWIND"
        sub_lbl = "({btn_cancel} to give up)"
        draw_rich_text(surf, PLAY_W // 2 + jx, PLAY_H // 2 - 10 + jy,
                       label, self.app.fonts, font, (220, 240, 255),
                       anchor="c", alpha=int(255 * pulse))
        sm = self.app.fonts.get("small")
        if sm is not None:
            draw_rich_text(surf, PLAY_W // 2, PLAY_H // 2 + 24,
                           sub_lbl, self.app.fonts, sm, (180, 200, 220),
                           anchor="c", alpha=int(200 * pulse))

    def _update(self, dt, controls):
        # life_t advances regardless of intro / outro / boss phases so
        # the HUD entry animation tracks "time since I left the map".
        # The chirp loop fires once per panel as life_t crosses each
        # arrival threshold — at panel_stagger=0.30 the chirps land
        # 300 ms apart, well clear of the ~50 ms tone length.
        self.life_t += dt
        chirps = self.app.sounds.get("hud_activate")
        while (chirps is not None
               and self._hud_chirp_idx < len(self._hud_chirp_times)
               and self.life_t >= self._hud_chirp_times[self._hud_chirp_idx]):
            idx = self._hud_chirp_idx
            if idx < len(chirps):
                try:
                    chirps[idx].play()
                except Exception:
                    pass
            self._hud_chirp_idx += 1

        self.stars.update(dt)
        if ENABLE_NEBULA:
            self.nebula.update(dt)
        self.bg_ribbon.update(dt)
        self.boss_intro_t = max(0, self.boss_intro_t - dt)

        # SELECT + L2 + R2 cheat trigger (edge-detected so a held combo
        # fires once). SELECT is required so the player can use L2 / R2
        # as fire-and-swap shoulder shortcuts without nuking the level
        # by accident. Skips during the intro/outro and after the level
        # has already been decided so the player can't double-trigger
        # or break the cinematic.
        combo_held = (controls.select and controls.l2_held
                      and controls.r2_held)
        if (combo_held and not self._cheat_l2r2_was_held
                and self.outcome is None
                and self.outro_t <= 0
                and self.intro_t <= 0
                and self._cheat_summary_t <= 0):
            self._fire_instant_clear_cheat()
        self._cheat_l2r2_was_held = combo_held
        if self._cheat_summary_t > 0:
            self._cheat_summary_t = max(0.0, self._cheat_summary_t - dt)

        # Cinematic intro: ship lifts off from the launch platform as it scrolls away.
        if self.intro_t > 0:
            self.intro_t -= dt
            p = clamp(1.0 - max(0.0, self.intro_t) / 2.4, 0.0, 1.0)
            eased = 1.0 - (1.0 - p) ** 3
            # Most of the takeoff illusion comes from the platform scrolling
            # away underneath; the ship only nudges up a little but grows into
            # combat scale.
            self.player.y = lerp(PLAY_H - 30, PLAY_H - 60, eased)
            # Re-centre x in case a previous run nudged it.
            self.player.x = lerp(self.player.x, PLAY_W // 2, eased * 0.5)
            self.player.rect.center = (int(self.player.x), int(self.player.y))
            self.player.cinematic_scale = lerp(0.35, 1.0, eased)
            self.player.thrust += dt * 80
            self.player.tilt = 0.0
            self.stars.update(dt * 1.6)
            self.sparks = [s for s in self.sparks if s.alive]
            self.explosions = [ex for ex in self.explosions if ex.alive]
            if self.intro_t <= 0:
                self.player.cinematic = False
                self.player.cinematic_scale = 1.0
            self._flush_kill_particles()
            return

        # Cinematic outro: ship climbs up to meet (and dock at) the arrival
        # station, then the screen fades to black while the dock music
        # finishes. Cinematic phase drives every visual via `p`; fade
        # phase just lets time pass — the _draw fade overlay handles the
        # blackout. Music selection still gates "dock" on outro_t > 0 so
        # the track keeps playing across both phases.
        if self.outro_t > 0:
            self.outro_t -= dt
            elapsed = OUTRO_TOTAL_DUR - self.outro_t
            if elapsed <= OUTRO_CINEMATIC_DUR:
                p = clamp(elapsed / OUTRO_CINEMATIC_DUR, 0.0, 1.0)
                eased = p * p
                # The end station settles with its body around y=0..120; aim for
                # the lower portion of it so the ship reads as docking from below.
                dock_y = 90
                self.player.y = lerp(self._outro_start_y, dock_y, eased)
                # Slide the player toward the playfield centre so it lines up with
                # the station's docking bay, in case combat ended off-centre.
                self.player.x = lerp(self.player.x, PLAY_W // 2, eased * 0.6)
                self.player.rect.center = (int(self.player.x), int(self.player.y))
                self.player.cinematic_scale = lerp(1.0, 0.25, eased)
            # else: fade phase — ship sits at the dock, no motion updates.
            self.player.thrust += dt * 80
            self.player.tilt = 0.0
            self.stars.update(dt * 1.6)
            for b in self.bullets: b.update(dt)
            for ball in self.balls: ball.update(dt)
            _op = self.particles
            for i in range(self._part_cursor, len(_op)): _op[i].update(dt)
            self._advance_particle_cursor()
            for s in self.sparks: s.update(dt)
            for ex in self.explosions: ex.update(dt)
            self.bullets = [b for b in self.bullets if b.alive]
            self.balls = [b for b in self.balls if b.alive]
            # Particles are APPEND-ONLY so the rewind buffer can
            # length-truncate-restore the list to a prior frame's
            # state. Dead entries stay in the list; Particle.draw
            # short-circuits on .alive=False, so the cost is one int
            # check per dead entry per frame.
            self.sparks = [s for s in self.sparks if s.alive]
            self.explosions = [ex for ex in self.explosions if ex.alive]
            if self.outro_t <= 0 and not self._win_held:
                # Outro just finished. Capture the clear-% now so the
                # banner shows a stable number, and enter the win-hold
                # state — _update will be skipped from the next frame
                # so the world freezes under the MISSION COMPLETE
                # banner until the player presses fire (continue) or
                # ability (retry — only if < 100% cleared).
                spawned = max(1, self.enemies_spawned)
                self._held_progress = max(0.0, min(
                    1.0, self.enemies_killed / spawned))
                self._win_held = True
                # A 100%-clear banner BANKS the win to disk right now,
                # matching what _begin_game_won does for L100 / game-
                # finishing wins. Without this, a player who rewinds
                # back through the outro (or even back into active sim)
                # and then quits via any exit path loses the completion
                # — save.completed/unlocked were only mutated by the
                # post_play handler downstream of outcome="win", and
                # that doesn't fire until the player taps fire on the
                # banner. _commit_win is idempotent + flips
                # _win_committed so the banner-press routes via
                # "win_committed" → shop_win (no double record).
                # Partial-clear (MISSION FAILED) banners stay
                # uncommitted — the player still has the choice to
                # retry-or-give-up, and a "give up" is a loss.
                if self._held_progress >= 1.0:
                    self._commit_win()
            self._flush_kill_particles()
            return

        # Test mode: god mode + a parade that plays the takeoff-then-land
        # cinematic for every station before the regular timeline kicks in.
        if self.is_test:
            self.player.invuln = max(self.player.invuln, 9999.0)
            self.player.shield_hp = self.player.shield_max
            if not self._test_parade_done:
                self._update_test_parade(dt)
                # During the "play" sub the player has manual control —
                # fall through to the normal update path so input drives
                # the ship. Takeoff and landing own the ship deterministi-
                # cally and early-return.
                if self._test_parade_sub != "play":
                    self._flush_kill_particles()
                    return

        perf = self.app.perf
        # Skip elapsed + timeline ticks during the inserted test-parade
        # "play" window — those 4 s shouldn't fire any waves. Bumping
        # elapsed would also push the post-parade timeline kick (in
        # _update_test_parade) off-target.
        in_test_play = (self.is_test
                        and not self._test_parade_done
                        and self._test_parade_sub == "play")
        if not in_test_play:
            self.elapsed += dt
            # Slave the particle clock to the sim clock so spawns this
            # frame capture the right spawn_t (closed-form recompute on
            # rewind restore reads off this same value).
            Particle._sim_t = self.elapsed
            # Spawn from timeline. Bracket fn() with a `len(self.enemies)`
            # delta so `self.enemies_spawned` tallies what each spawner
            # actually added — covers DMZ-driven wave reductions, kind
            # downgrades, and any future spawners that vary count at
            # runtime without us having to introspect each closure.
            perf.start("upd.spawn")
            while self.timeline_idx < len(self.level.timeline):
                t, fn = self.level.timeline[self.timeline_idx]
                if self.elapsed >= t:
                    before = len(self.enemies)
                    # Swap the module rng to a per-wave seeded state for
                    # the duration of fn(self). The wave's enemy attrs
                    # (Asteroid drift, shield rolls, etc.) read from this
                    # stream instead of the main rng, so rewind+resume
                    # reproduces the SAME wave even though eased-replay
                    # dt + interleaved player/enemy rng calls have shifted
                    # the main rng state by spawn time.
                    main_state = random.getstate()
                    random.seed(_wave_seed(self._wave_seed_base,
                                           self.timeline_idx))
                    try:
                        fn(self)
                    finally:
                        random.setstate(main_state)
                    # Walls are indestructible scenery — exclude them
                    # from the clear-% denominator so a level can still
                    # reach 100% with walls present (the player can't
                    # kill them, so counting them would guarantee <100%).
                    self.enemies_spawned += sum(
                        1 for e in self.enemies[before:]
                        if not isinstance(e, Wall))
                    self.timeline_idx += 1
                else:
                    break
            perf.end("upd.spawn")

        # Player
        perf.start("upd.player")
        prev_player_x = self.player.x
        self.player.update(dt, controls, self.bullets, lambda: self.enemies, self.particles,
                           self.app.sounds, self.lasers, on_bomb=self._bomb,
                           rays=self.rays, state=self)
        # Side-to-side parallax: stars shift opposite to player movement,
        # scaled by depth so the far layer barely budges.
        dx = self.player.x - prev_player_x
        self.stars.lateral_shift(dx)
        # Impulse-decay parallax for the playfield blit: each frame the
        # player moves, parallax_x kicks opposite to dx; with no input it
        # decays back to zero. The DECAY is what fixes the edge-clipping
        # bug — at rest, parallax_x is 0, so the player and enemies sit at
        # their natural screen positions and can reach left/right edges.
        # While moving, the whole playfield (bg + entities) lags behind
        # the player's motion, giving the camera-pan feel they wanted.
        self.parallax_x = clamp(
            self.parallax_x - dx * 0.55, -40.0, 40.0)
        self.parallax_x *= max(0.0, 1.0 - dt * 5.0)
        perf.end("upd.player")

        # Bullets
        perf.start("upd.bullets")
        for b in self.bullets:
            b.update(dt)
        # In-flight Ball projectiles travel + check for world-edge exit.
        # A ball that drifts off any edge is silently lost — no boom,
        # no visual. Cooldown still kicks in via the "no live balls"
        # branch in Player._update_ball so the player can't immediately
        # spawn another, but the explosion the player was holding for is
        # forfeited (price of missing).
        for ball in self.balls:
            if not ball.alive:
                continue
            ball.update(dt)
        perf.end("upd.bullets")

        # Enemies
        perf.start("upd.enemies")
        for e in self.enemies:
            e.update(dt, self.bullets, lambda: self.player if self.player.alive else None, self.app.sounds)
        self._separate_overlapping_shields()
        perf.end("upd.enemies")

        # Lasers (damage continuously)
        perf.start("upd.lasers")
        for laser in self.lasers:
            laser.update(dt)
            hit = laser.hit_rect()
            for e in self.enemies:
                if e.alive and hit.colliderect(e.hit_rect):
                    if e.hit(int(laser.damage_per_sec * dt)):
                        self._on_kill(e)
        # Rays — damage was applied at fire time; just tick the fade.
        for r in self.rays:
            r.update(dt)
        perf.end("upd.lasers")

        # Pickups
        perf.start("upd.pickups")
        for p in self.pickups:
            p.update(dt)
        for ft in self.float_texts:
            ft.update(dt)
        perf.end("upd.pickups")

        perf.start("upd.particles")
        # Start from the live-particle cursor: [0, _part_cursor) are dead and
        # stay dead going forward, so updating them is wasted work (this is the
        # bulk of upd.particles in a kill-heavy level). The cursor is from last
        # frame here — conservative (those entries were already dead) — then
        # re-advanced below to catch anything that died this frame.
        parts = self.particles
        for i in range(self._part_cursor, len(parts)):
            parts[i].update(dt)
        self._advance_particle_cursor()
        for s in self.sparks:
            s.update(dt)
        for ex in self.explosions:
            ex.update(dt)
        perf.end("upd.particles")

        # Friendly bullet vs enemy/obstacle. Walls absorb the shot without
        # dying. Uses pygame.Rect.collidelist (single C-level scan) per
        # bullet instead of a Python double-loop calling colliderect —
        # under stress (70 bullets × 19 enemies = 1330 pairs/frame) the
        # Python overhead was dominating. When an enemy dies mid-pass we
        # patch its slot in the rect list with an off-screen sentinel so
        # later bullets skip it instead of re-matching a corpse.
        perf.start("col.bullet_enemy")
        enemies = self.enemies
        # shoot_rect expands to the shield's outer bounding box while
        # the enemy is shielded — so a graze on the visible halo
        # registers and the shield-gate path absorbs / ricochets the
        # shot. Reverts to the regular sprite hitbox once shield is
        # down. (Ram collisions still use hit_rect a few blocks below.)
        hit_rects = [e.shoot_rect for e in enemies]
        dead = _DEAD_RECT_SENTINEL
        sparks = self.sparks
        for b in self.bullets:
            # Ricocheted bullets (player shot bounced off a wrong-colour
            # shield) keep `friendly=False` so they can also hurt the
            # player — but they SHOULD still damage enemies they hit on
            # the rebound. Include them here; the player-collision loop
            # below still picks them up if they end up on the ship.
            if not (b.alive and (b.friendly or b.ricocheted)):
                continue
            # Mask the most recent ricochet target so the bullet can't
            # immediately re-bounce off the same shield when the enemy
            # moves back into its path. Swap the rect to the dead
            # sentinel for the duration of this bullet's pass, restore
            # afterwards so other bullets still see the real rect.
            swap_idx = -1
            swap_rect = None
            le = b.last_ricochet_enemy
            if le is not None:
                if not le.alive:
                    b.last_ricochet_enemy = None
                else:
                    found = False
                    for i, en in enumerate(enemies):
                        if en is le:
                            swap_idx = i
                            swap_rect = hit_rects[i]
                            hit_rects[i] = dead
                            found = True
                            break
                    if not found:
                        b.last_ricochet_enemy = None
            br = b.rect
            while True:
                idx = br.collidelist(hit_rects)
                if idx == -1:
                    break
                e = enemies[idx]
                if not e.alive:
                    hit_rects[idx] = dead
                    continue
                if isinstance(e, Wall):
                    sparks.append(Spark(br.centerx, br.centery, (200, 200, 220)))
                    sparks.append(Spark(br.centerx, br.centery, WHITE))
                    e.hit_flash_t = 0.05
                    # Wall hits pay 1 credit each — mining-asteroid feel.
                    self._earn(1)
                    self.float_texts.append(FloatText(
                        br.centerx, br.centery - 6, "$1"))
                    b.alive = False
                    break
                # Coloured shield gate. Shield is a binary modifier:
                #   - right weapon  → pass through; check enemy hitbox
                #                     (rect) and damage normally if hit
                #   - wrong main    → check circle distance to shield;
                #                     if inside, ricochet (turns hostile)
                #   - missile/drone → absorbed by circle (no damage)
                #
                # The broad phase already matched on shoot_rect (shield
                # bounding box); now we refine.
                shield_dropped_by_hit = False
                if e.shield_color:
                    shield_rgb = SHIELD_COLOR_RGB[e.shield_color]
                    right_kind = SHIELD_COLOR_TO_KIND[e.shield_color]
                    bk = b.weapon_kind
                    if bk == right_kind:
                        # Bullet passes through the shield. Damage only
                        # registers if it actually overlaps the hitbox.
                        if not br.colliderect(e.hit_rect):
                            # Inside the broad-phase rect but missed the
                            # enemy's real hitbox — flies on, no hit.
                            break
                        # Right-kind hit on a shielded non-Boss permanently
                        # drops the shield AFTER the hit damage applies.
                        # Bosses keep their cyclic shield (the cycle is
                        # the boss-fight gameplay loop — see Boss.update).
                        if not isinstance(e, Boss):
                            shield_dropped_by_hit = True
                        # else: fall through to the normal hit() path.
                    else:
                        # Wrong weapon: circle test.
                        dx = b.x - e.rect.centerx
                        dy = b.y - e.rect.centery
                        if dx * dx + dy * dy > (e.shield_radius
                                                + SHIELD_THICKNESS) ** 2:
                            break
                        # Ricochet on EVERY wrong-colour shield, even if
                        # this bullet has already bounced before — the
                        # `_ricochet_bullet` nudge places the bullet
                        # outside the shield so it can't re-collide with
                        # the same shield this frame, and it'll cull
                        # naturally on a wall, an unshielded enemy, the
                        # player, or off-screen.
                        if bk in ("rail", "ball", "vulcan"):
                            _ricochet_bullet(b, e)
                        else:
                            b.alive = False
                        sparks.append(Spark(br.centerx, br.centery, shield_rgb))
                        break
                killed = e.hit(b.damage)
                if shield_dropped_by_hit and e.alive:
                    e.shield_color = None
                    e.shield_radius = 0
                    try:
                        self.app.sounds["shield_off"].play()
                    except Exception:
                        pass
                # Impact-spark burst only fires on Boss hits. Small fries
                # rely on the sprite hit_flash + (on kill) the explosion
                # particles for feedback — under stress that's the
                # difference between 100s of sparks/frame and dozens.
                if isinstance(e, Boss):
                    ix = br.centerx
                    iy = br.centery
                    # 1/4 the count, 3x bigger (size=12): a wide boss under
                    # sustained fire connected many bullets/frame, and a full
                    # 9-12 burst each piled up 100s of sparks/frame (per-frame
                    # draw + rewind-snapshot cost). Fewer, bigger reads as punchy.
                    burst = 3 if killed else 2
                    for _ in range(burst):
                        color = random.choice(IMPACT_SPARK_COLORS)
                        sparks.append(ImpactSpark(ix, iy, color, b.vx, b.vy,
                                                  size=12))
                    # White centre flash for a bit of contrast in the burst.
                    sparks.append(Spark(ix, iy, WHITE))
                e.hit_flash_t = 0.08
                if killed:
                    self._on_kill(e)
                    hit_rects[idx] = dead
                if b.pierce > 0:
                    b.pierce -= 1
                else:
                    b.alive = False
                break
            if swap_idx >= 0:
                hit_rects[swap_idx] = swap_rect
        perf.end("col.bullet_enemy")

        # In-flight Balls vs enemies / walls. A ball detonates on first
        # SOLID contact (right-colour shield, no shield, or wall). A
        # WRONG-colour shield STICKS the ball to the shield surface as
        # a sticky bomb — no detonation until the player manually pops
        # it via fire / R1. Walls always detonate. The blast itself
        # filters by shield colour inside _ball_explode, so a red-
        # shielded enemy in the centre of the blast still takes full
        # damage while a yellow-shielded one absorbs harmlessly.
        for ball in self.balls:
            if not ball.alive:
                continue
            # Stuck balls ride their host enemy until manually detonated.
            # No collision tests — they're already attached.
            if ball.stuck_to is not None:
                host = ball.stuck_to
                if host.alive:
                    ball.x = host.rect.centerx + ball.stuck_dx
                    ball.y = host.rect.centery + ball.stuck_dy
                else:
                    # Host died (splash, screen clear, etc.); detach but
                    # leave the ball parked in place so manual detonate
                    # still works at the last position.
                    ball.stuck_to = None
                continue
            br = ball.rect
            hit_e = None
            for e in self.enemies:
                if not e.alive:
                    continue
                # Broad-phase against shoot_rect (= shield circle's
                # bounding box when the enemy is shielded; otherwise =
                # hit_rect). Matches bullets — without this, a ball
                # threading through a shielded enemy's halo would skip
                # the inner hitbox entirely and fly off without
                # detonating, so e.g. a red-shielded Asteroid was
                # passable even though red matches the ball weapon.
                if not br.colliderect(e.shoot_rect):
                    continue
                # Refine. Wrong-colour shields use a circle test against
                # the actual shield radius so the latch only fires inside
                # the round halo, not its square bounding box. Right-
                # colour shields and unshielded enemies detonate as soon
                # as the shoot_rect overlap is real — the ball blast
                # radius takes care of damage falloff to the inner hitbox.
                sc = getattr(e, "shield_color", None)
                if (sc
                        and SHIELD_COLOR_TO_KIND.get(sc) != "ball"
                        and not isinstance(e, Wall)):
                    dx_s = ball.x - e.rect.centerx
                    dy_s = ball.y - e.rect.centery
                    rs = e.shield_radius + SHIELD_THICKNESS
                    if dx_s * dx_s + dy_s * dy_s > rs * rs:
                        continue  # inside square halo but outside circle
                hit_e = e
                break
            if hit_e is None:
                continue
            sc = getattr(hit_e, "shield_color", None)
            wrong_shield = (sc
                            and SHIELD_COLOR_TO_KIND.get(sc) != "ball"
                            and not isinstance(hit_e, Wall))
            if wrong_shield:
                # Sticky-bomb latch: freeze motion, remember the offset
                # from the host centre so we ride along with the shield,
                # and emit a small shield-coloured spark + white centre
                # flash so the latch is visually confirmed. The player
                # holds the trigger of the explosion.
                ball.vx = 0.0
                ball.vy = 0.0
                ball.stuck_to = hit_e
                ball.stuck_dx = ball.x - hit_e.rect.centerx
                ball.stuck_dy = ball.y - hit_e.rect.centery
                shield_rgb = SHIELD_COLOR_RGB.get(hit_e.shield_color,
                                                  (200, 200, 220))
                self.sparks.append(Spark(int(ball.x), int(ball.y),
                                         shield_rgb))
                self.sparks.append(Spark(int(ball.x), int(ball.y), WHITE))
            else:
                _ball_explode(self, ball.x, ball.y,
                              ball.effective_explode_r(),
                              ball.damage, self.app.sounds,
                              hostile=ball.ricocheted)
                ball.alive = False

        # Hostile (ricocheted) balls vs the player. A reflected ball
        # that drifts into the ship detonates ON the ship and damages
        # the player via _ball_explode's hostile pass. Friendly balls
        # pass over the player harmlessly (they only ever fly up at
        # release; only post-ricochet can they head back down).
        if self.player.alive:
            player_hit = self.player.hit_rect
            for ball in self.balls:
                if not ball.alive or not ball.ricocheted:
                    continue
                if ball.rect.colliderect(player_hit):
                    _ball_explode(self, ball.x, ball.y,
                                  ball.effective_explode_r(),
                                  ball.damage, self.app.sounds,
                                  hostile=True)
                    ball.alive = False

        # Enemy bullet vs walls (absorb) then vs player. Walls list is
        # usually tiny but the per-bullet inner loop still ran in Python;
        # collidelist drops it to a single C scan.
        perf.start("col.bullet_player")
        if self.player.alive:
            walls = [e for e in self.enemies
                     if e.alive and isinstance(e, Wall)]
            wall_rects = [w.hit_rect for w in walls]
            player_hit = self.player.hit_rect
            sparks = self.sparks
            for b in self.bullets:
                if not (b.alive and not b.friendly):
                    continue
                # Ball-absorbed bullets are en route to the ball core —
                # they shouldn't pop on walls or damage the player while
                # being sucked in.
                if b.being_absorbed:
                    continue
                br = b.rect
                if wall_rects and br.collidelist(wall_rects) != -1:
                    b.alive = False
                    sparks.append(Spark(br.centerx, br.centery, ORANGE))
                    continue
                if br.colliderect(player_hit):
                    b.alive = False
                    self._damage_player(400)
        perf.end("col.bullet_player")

        # Enemy vs player. Single C-level player.collidelistall over the
        # enemy rect list — yields every overlapping enemy in one call.
        # Walls push the player out, everything else damages (and dies if
        # not a boss).
        perf.start("col.enemy_player")
        if self.player.alive:
            enemies = self.enemies
            enemy_rects = [e.hit_rect for e in enemies]
            player_hit = self.player.hit_rect
            for idx in player_hit.collidelistall(enemy_rects):
                e = enemies[idx]
                if not e.alive:
                    continue
                if isinstance(e, Wall):
                    self._push_player_out(e.rect)
                    continue
                if not isinstance(e, Boss):
                    e.hit(9999)
                    self._on_kill(e, drop=False)
                self._damage_player(1600)
        perf.end("col.enemy_player")

        # Pickup pickup — single collidelistall, same shape as enemy>player.
        perf.start("col.pickup")
        if self.player.alive and self.pickups:
            pickups = self.pickups
            pickup_rects = [p.rect for p in pickups]
            player_hit = self.player.hit_rect
            for idx in player_hit.collidelistall(pickup_rects):
                p = pickups[idx]
                if not p.alive:
                    continue
                p.alive = False
                result = self.player.collect(p, save=self.app.save)
                if result and result[0] == "credits":
                    self._earn(result[1])
                    # Drift "+$N" above where the pickup was so the player
                    # sees how much they actually banked — useful when
                    # weapon-upgrade pickups convert to credits (200) and
                    # also for the basic money drop (25). Pickup is dead
                    # now, so use its last rect for the spawn point.
                    self.float_texts.append(FloatText(
                        p.rect.centerx, p.rect.top - 4,
                        f"${result[1]}"))
                self.app.sounds["pickup"].play()
        perf.end("col.pickup")

        # Cleanup
        perf.start("upd.cleanup")
        self.bullets = [b for b in self.bullets if b.alive]
        self.balls = [b for b in self.balls if b.alive]
        self.enemies = [e for e in self.enemies if e.alive]
        self.pickups = [p for p in self.pickups if p.alive]
        # Particles are APPEND-ONLY so the rewind buffer can
        # length-truncate-restore the list to a prior frame's state.
        # Dead entries stay in the list; Particle.draw short-circuits
        # on .alive=False.
        self.sparks = [s for s in self.sparks if s.alive]
        self.explosions = [ex for ex in self.explosions if ex.alive]
        self.lasers = [l for l in self.lasers if l.alive]
        self.rays = [r for r in self.rays if r.alive]
        self.float_texts = [t for t in self.float_texts if t.alive]
        perf.end("upd.cleanup")

        self.flash = max(0, self.flash - dt * 4)
        self.shake = max(0, self.shake - dt * 4)

        if self.message_timer > 0:
            self.message_timer -= dt

        # Test-only boss state machine: spawn the next boss whenever
        # the previous one is gone (killed or skipped via L2/R2). Runs
        # after the cleanup pass so a dead boss has been filtered out
        # of self.enemies by the time we check.
        if self.is_test:
            self._test_maybe_spawn_next_boss()

        # Win/loss. Both win paths wait for any floating powerups to
        # either be collected or drift off-screen before kicking off
        # the outro sequence. Death is handled by run()'s _nohit_step
        # — the dead-pause / rewind / give-up flow keeps outcome=None
        # until the player presses START to accept defeat (or rewinds
        # out of the death entirely).
        elif self.is_test:
            # Test mode finishes when all 10 bosses have been dispatched
            # and the field is clean. No timer — the player can dwell on
            # any boss for as long as they want.
            # Escaped enemies are frozen off-screen with a permanent
            # marker (see Enemy.escaped); they don't count toward
            # "nothing meaningfully in play" so the test mission can
            # still finish if one drifts past the cull threshold.
            # Walls scroll off the bottom on their own.
            if (self._test_boss_idx >= 10
                    and not any(not e.escaped for e in self.enemies)
                    and not self.pickups):
                self._maybe_begin_outro(dt)
        elif self.level.has_boss:
            if any(isinstance(e, Boss) for e in self.enemies):
                self.boss_spawned = True
            if (self.boss_spawned
                    and not any(isinstance(e, Boss) for e in self.enemies)
                    and not self.pickups):
                self._maybe_begin_outro(dt)
        else:
            # Same exclusion for non-boss levels: escaped enemies don't
            # block the outro — they only hurt clear% (kills/spawned
            # stays under 100).
            if (self.elapsed >= self.level.duration
                    and not any(not e.escaped for e in self.enemies)
                    and not self.pickups):
                self._maybe_begin_outro(dt)
        # Flush any kills queued during this frame's collision /
        # detonation passes. Done LAST so the shared-budget divisor
        # sees the full kill count, and BEFORE _run returns (and
        # therefore before _rewind.push) so the post-flush
        # `len(self.particles)` lands in the snapshot.
        self._flush_kill_particles()

    def _flush_kill_particles(self):
        """End-of-frame: drain the `_kill_fx_queue` populated by
        `_on_kill` and spawn the per-kill particle/debris bursts with a
        SHARED budget — a solo kill gets the full counts (16 ORANGE +
        5 YELLOW + n_debris for non-boss; 24 RED + 6 YELLOW + 22
        debris for boss), three kills in the same frame divide those
        counts three ways, etc. Floors at 2 particles per type so
        small bursts don't vanish in a mass-detonation.

        Rewind-safe: particles only ever APPEND to `self.particles`,
        each carries its own closed-form trajectory (`Particle._sim_t`
        was stamped at the start of this frame), and the snapshot
        captured after `_update` returns records the post-flush
        `len(self.particles)`. Replay through the same frame
        reconstructs each particle from its initial state."""
        if not self._kill_fx_queue:
            return
        n = len(self._kill_fx_queue)
        for kill in self._kill_fx_queue:
            cx = kill["cx"]
            cy = kill["cy"]
            visual_r = kill["visual_r"]
            sprite_colors = kill["sprite_colors"]
            if kill["is_boss"]:
                primary = max(2, 24 // n)
                accent = max(1, 6 // n)
                debris_n = max(2, 22 // n)
                for _ in range(primary):
                    self.particles.append(Particle(cx, cy, RED, size=10,
                                                   speed_range=(60, 320)))
                for _ in range(accent):
                    self.particles.append(Particle(cx, cy, YELLOW, size=10,
                                                   speed_range=(80, 260)))
                for _ in range(debris_n):
                    c = random.choice(sprite_colors)
                    sz = random.randint(6, 14)
                    self.particles.append(Debris(cx, cy, c, sz,
                                                 speed_range=(110, 360)))
            else:
                primary = max(2, 16 // n)
                accent = max(1, 5 // n)
                n_debris_base = max(4, min(14, visual_r // 3 + 4))
                debris_n = max(2, n_debris_base // n)
                for _ in range(primary):
                    self.particles.append(Particle(cx, cy, ORANGE, size=10,
                                                   speed_range=(72, 360)))
                for _ in range(accent):
                    self.particles.append(Particle(cx, cy, YELLOW, size=8,
                                                   speed_range=(96, 312)))
                max_chunk = max(6, visual_r // 3)
                for _ in range(debris_n):
                    c = random.choice(sprite_colors)
                    sz = random.randint(4, max_chunk)
                    self.particles.append(Debris(cx, cy, c, sz,
                                                 speed_range=(108, 384)))
        self._kill_fx_queue.clear()

    def _resolve_drop_kind(self, kind):
        """Spawn drops at their original kind. Weapon power-ups that
        can't apply to the player's current loadout (max level, locked
        tier, or — for "main" — the wrong main being held that frame)
        convert to credits inside Player.collect() at pickup time. This
        keeps the visible drop telegraph honest: a main-weapon icon
        ALWAYS spawns from main-drop rolls, even if the player can't
        currently consume it — they still get +$N from it.

        Pass-through now that the only drop kinds are 'money' and
        'main' — kept as a hook in case future drop kinds need
        on-the-fly rerolling."""
        return kind

    def _maybe_begin_outro(self, dt):
        """Wait for the field to settle before kicking off the outro
        cinematic. Called once a win condition fires; locks the weapons
        + cancels any in-flight ball charge on entry, then waits each
        frame for friendly bullets / balls / rays / lasers / float-texts
        to clear. A 3 s safety timeout caps the wait — float-texts have
        a ~1.5 s lifetime so the worst real case stays under that. Hard
        no-ops once outro_t > 0, game_won is already running, or
        outcome is decided."""
        if self.outro_t > 0 or self._game_won or self.outcome is not None:
            return
        if not self.player.weapons_locked:
            # Wind-down entry. Lock weapons + cancel any active ball
            # charge so the held shoulder can't release into a fresh
            # shot. Enemy bullets stay live — the player can still die
            # to leftover shrapnel during the wait (and on the rewind path
            # rewind out of it), which is the intended tension.
            self.player.weapons_locked = True
            if self.player.ball_state == "charging":
                self.player.ball_state = "cooldown"
                self.player.ball_charge_t = 0.0
                self.player.ball_cooldown_t = BALL_COOLDOWN_TIME
        self._win_pending_t += dt
        field_clear = (
            not any(b.alive and b.friendly for b in self.bullets)
            and not self.balls
            and not self.rays
            and not self.lasers
            and not self.float_texts
        )
        if field_clear or self._win_pending_t > 3.0:
            # Final level always routes to YOU WIN — first-time
            # completion AND replays — so the celebration is the
            # natural cap to every L100 run. `_is_game_finishing_win`
            # still catches the rare case of finishing 100/100 via a
            # non-L100 path (shouldn't be possible today but keeps the
            # gate symmetric with the cheat).
            if self.level.key == "L100" or self._is_game_finishing_win():
                self._begin_game_won()
            else:
                self._begin_outro()

    def _is_game_finishing_win(self):
        """True iff winning THIS level on THIS attempt fills out the
        100-level set for the first time. Already-completed saves
        replaying L100 keep the normal docking flow — no redundant
        celebration."""
        if self.is_test:
            return False
        save = self.app.save
        completed = set(getattr(save, "completed", None) or ())
        all_keys = {f"L{n:03d}" for n in range(1, 101)}
        if all_keys.issubset(completed):
            return False  # already 100% before this win — normal flow
        completed.add(self.level.key)
        return all_keys.issubset(completed)

    def _begin_game_won(self):
        """Game-fully-complete branch — no docking cinematic, no
        MISSION COMPLETE banner. Ship keeps flying with full controls;
        fireworks bloom behind a "YOU WIN" text until the player hits
        START. Save is committed immediately so the celebration is
        survivable across a force-quit."""
        if self._game_won or self.outcome is not None:
            return
        self._game_won = True
        self._game_won_t = 0.0
        self._firework_t = 0.0
        # Let the player go crazy — re-enable fire + swap that
        # _maybe_begin_outro turned off during the win wind-down.
        self.player.weapons_locked = False
        # Clear hazards same as _begin_outro (boss kill already cleared
        # most of these; defensive sweep mirrors the docking path).
        for b in self.bullets:
            if not b.friendly:
                b.alive = False
        for ball in self.balls:
            ball.alive = False
        self.balls = [ball for ball in self.balls if ball.alive]
        for e in self.enemies:
            e.alive = False
        self.enemies = []
        # Snapshot the run's clear% so post_play stat update lands the
        # right value, then commit the win to save — the player should
        # be able to quit mid-celebration with 100% recorded.
        spawned = max(1, self.enemies_spawned)
        self._held_progress = max(0.0, min(
            1.0, self.enemies_killed / spawned))
        self._committed_stolen_time = float(self.stolen_time)
        try:
            self.app._record_play_outcome(
                self.score, self.level.key, True, self._held_progress,
                stolen_time=self._committed_stolen_time)
        except Exception as e:
            print(f"game-won save commit failed: {e}")
        # Swap to the fully-layered menu theme — variant 5 cumulative
        # plays all six layers, matching the "everything unlocked"
        # title-screen treatment.
        try:
            self.app.set_menu_music(5, isolated=False)
        except Exception:
            pass

    _FIREWORK_PALETTE = (
        (255, 80, 80),    # red
        (255, 200, 80),   # gold
        (90, 200, 255),   # blue
        (120, 255, 120),  # green
        (220, 120, 255),  # purple
        (255, 255, 255),  # white
    )

    def _spawn_firework(self, x, y):
        """Pop one celebration burst at (x, y). Pure-spark — no
        ExplosionRing. Sparks are 2x the size + spread of the old
        combat-Particle bursts so the celebration reads bigger than a
        boss-kill puff. Lives in self._win_particles only — outside the
        rewind snapshot buffer."""
        color = random.choice(self._FIREWORK_PALETTE)
        n = random.randint(40, 70)
        for _ in range(n):
            angle = random.uniform(0.0, math.tau)
            speed = random.uniform(160.0, 440.0)
            vx = math.cos(angle) * speed
            vy = math.sin(angle) * speed
            life = random.uniform(0.9, 1.6)
            self._win_particles.append(FireworkSpark(
                x, y, color, size=6, vx=vx, vy=vy, life=life))

    def _tick_fireworks(self, dt):
        """Decrement the spawn timer and pop a new burst when it hits
        zero. Spawn positions stay inside a 60-px inset of the play
        area so most sparks bloom on-screen even with the larger
        radial spread."""
        self._firework_t -= dt
        if self._firework_t <= 0:
            inset = 60
            x = random.randint(inset, PLAY_W - inset)
            y = random.randint(inset, PLAY_H - inset)
            self._spawn_firework(x, y)
            self._firework_t = random.uniform(0.25, 0.65)
        for p in self._win_particles:
            p.update(dt)
        self._win_particles = [p for p in self._win_particles if p.alive]

    def _begin_outro(self):
        if self.outro_t > 0 or self.outcome is not None:
            return
        self.outro_t = OUTRO_TOTAL_DUR
        self._outro_start_y = float(self.player.y)
        self.player.cinematic = True
        # Clear remaining hazards for a clean docking sequence
        for b in self.bullets:
            if not b.friendly:
                b.alive = False
        for ball in self.balls:
            ball.alive = False
        self.balls = []
        for e in self.enemies:
            e.alive = False
        self.enemies = []
        # The outro update path early-returns before the regular per-frame
        # decay of shake / flash / parallax_x, so any residual value would
        # freeze for the whole 2.4 s cinematic and tremble the landing
        # station. Zero them here so docking reads calm.
        self.shake = 0
        self.flash = 0
        self.parallax_x = 0.0

    def _fire_instant_clear_cheat(self):
        """Simulate playing the level to completion in a single frame: fire
        every remaining timeline spawn, kill every enemy (with their normal
        drops + credits), then collect every pickup. The collected loot
        plus credit delta is stashed in self._cheat_summary so _draw can
        show a 3-second overlay before the outro starts."""
        earned_before = self.credits_earned
        counts = {"money": 0}

        # 1. Fast-forward the rest of the timeline so the rest-of-level
        #    enemies actually exist in self.enemies before we kill them.
        #    Same `len(self.enemies)` delta as the regular spawn loop so
        #    enemies_spawned keeps tracking truth — the cheat then kills
        #    each one through _on_kill, so the ratio stays at 1.0.
        while self.timeline_idx < len(self.level.timeline):
            _, fn = self.level.timeline[self.timeline_idx]
            try:
                before = len(self.enemies)
                fn(self)
                self.enemies_spawned += sum(
                    1 for e in self.enemies[before:]
                    if not isinstance(e, Wall))
            except Exception:
                pass
            self.timeline_idx += 1
        self.elapsed = max(self.elapsed, self.level.duration)

        # 2. Kill every enemy WITH drops. _on_kill awards SCORE + CREDITS
        #    and rolls the DROP_TABLE into self.pickups via the engine's
        #    existing logic.
        for e in list(self.enemies):
            if e.alive:
                # show_text=False — cheat clears the whole level in one
                # frame; the summary overlay already shows totals.
                self._on_kill(e, drop=True, show_text=False)
                e.alive = False
        self.enemies = []

        # 3. Collect every pickup the kills dropped. Maxed weapon pickups
        #    fall back to credits via player.collect() automatically.
        for p in list(self.pickups):
            if not p.alive:
                continue
            counts[p.kind] = counts.get(p.kind, 0) + 1
            result = self.player.collect(p, save=self.app.save)
            if result and result[0] == "credits":
                self._earn(result[1])
            p.alive = False
        self.pickups = []

        # 4. Stash the summary and pick the win-flow branch. L100 cheats
        #    always go to the YOU WIN celebration (preview escape
        #    hatch — lets devs / players reach the screen without
        #    99 prior wins on the save); other levels go through the
        #    docking outro + cheat-summary overlay as before.
        self._cheat_summary = {
            "credits": self.credits_earned - earned_before,
            "counts": counts,
        }
        self._cheat_summary_t = 3.0
        if self.level.key == "L100" or self._is_game_finishing_win():
            # Skip the credit-totals overlay — the YOU WIN fireworks
            # and the title-screen handoff are enough fanfare.
            self._cheat_summary = None
            self._cheat_summary_t = 0.0
            self._begin_game_won()
        else:
            self._begin_outro()
            # Default outro is 2.4 s; bump it so the 3 s summary completes
            # before we hand back to the App and roll the shop screen.
            self.outro_t = max(self.outro_t, self._cheat_summary_t + 0.4)

    def _bomb(self):
        # Clear all enemy bullets, damage every live enemy in the list
        # (the cull threshold in Enemy.update bounds how far off-screen
        # an enemy can be before it's removed, so this naturally caps
        # at "everything still meaningfully in play").
        for b in self.bullets:
            if not b.friendly:
                b.alive = False
        for e in self.enemies:
            if isinstance(e, Boss):
                e.hit(15)
            else:
                if e.hit(5):
                    self._on_kill(e)
        self.flash = 1.0
        self.shake = 1.0
        for _ in range(80):
            self.particles.append(Particle(
                random.uniform(0, PLAY_W), random.uniform(0, PLAY_H),
                random.choice([CYAN, WHITE, YELLOW]),
                size=4, speed_range=(40, 220), life_range=(0.3, 0.8),
            ))

    def _damage_player(self, dmg):
        killed = self.player.take_damage(dmg)
        if killed:
            self.shake = 1.2
            # Shatter the CURRENT (bank-aware) ship sprite. The FX is rendered
            # closed-form from `_death_t` on top of the glitch overlay (see
            # _draw / _render_death_fx), so the moment of death is always
            # visible and frame-accurate when scrubbing. Seed off the death
            # time so the shatter is identical on every redraw / on the ghost.
            sprite = self.player.current_sprite()
            self._death_t = self.elapsed
            self._death_pos = (float(self.player.rect.centerx),
                               float(self.player.rect.centery))
            self._death_sil = make_silhouette(sprite)
            self._death_shards = build_ship_shards(
                sprite, int(self.elapsed * 1000.0))
            self.app.sounds["big_boom"].play()
        else:
            self.app.sounds["hit"].play()
            self.flash = 0.4
            self.shake = 0.4

    def _death_fx_active(self):
        """True when the player-death shatter is currently within its FX
        window — used to gate both _render_death_fx and the GPU overlay pass."""
        if self._death_t is None or self._death_sil is None:
            return False
        age = self.elapsed - self._death_t
        return 0.0 <= age <= _DEATH_FX_DUR

    def _render_death_fx(self, screen, shake_x, shake_y, parallax_off):
        """Draw the player-death shatter on top of the glitch overlay (screen
        coords). Closed-form in age = elapsed - _death_t, so it plays forward,
        freezes with the dead-pause, and runs backward when scrubbing — the
        white flash peaking exactly on the death frame. No-op unless a death
        is currently in effect and within the FX window."""
        if not self._death_fx_active():
            return
        age = self.elapsed - self._death_t
        wx, wy = self._death_pos
        cx = wx + shake_x + parallax_off
        cy = wy + shake_y
        blit_death_fx(screen, self._death_shards, self._death_sil,
                      cx, cy, age, offset_x=0)

    def _on_kill(self, enemy, drop=True, show_text=True):
        # Track kills for the post-play clear % stat. Bosses, regular
        # enemies, and obstacles all funnel through here so the ratio
        # tracks "everything the player removed" against everything
        # that spawned. Flyaway / off-screen cleanup doesn't go through
        # _on_kill so those correctly count as misses.
        self.enemies_killed += 1
        self.score += enemy.SCORE
        self._earn(enemy.CREDITS)
        cx, cy = enemy.rect.centerx, enemy.rect.centery
        # Drift "+$N" above the kill so the player sees the bounty per
        # enemy. Suppressed by show_text=False from the level-clear cheat
        # which kills everything in one frame and would spam the screen.
        if show_text and enemy.CREDITS > 0:
            self.float_texts.append(FloatText(
                cx, cy - enemy.rect.height // 2 - 2,
                f"${enemy.CREDITS}"))
        is_boss = isinstance(enemy, Boss)
        # Visual radius from the entity's hitbox so the explosion matches
        # the sprite the player sees (falls back to sprite rect when no
        # hitbox is defined yet).
        hr = enemy.hit_rect
        visual_r = max(8, max(hr.width, hr.height) // 2)
        sprite_colors = _sample_sprite_colors(enemy.image, n=12)
        if is_boss:
            outer_r = int(visual_r * 2.5 + 12)
            mid_r = int(visual_r * 1.6 + 6)
            inner_r = max(8, int(visual_r * 1.0))
            self.explosions.append(ExplosionRing(cx, cy, max_r=outer_r, color=RED, life=0.85))
            self.explosions.append(ExplosionRing(cx, cy, max_r=mid_r, color=YELLOW, life=0.55))
            self.explosions.append(ExplosionRing(cx, cy, max_r=inner_r, color=WHITE, life=0.25))
            off_r = int(visual_r * 0.7)
            self.explosions.append(ExplosionRing(
                cx - off_r // 2, cy + off_r // 3,
                max_r=int(visual_r * 1.2 + 8), color=ORANGE, life=0.55))
            self.explosions.append(ExplosionRing(
                cx + off_r // 2, cy - off_r // 4,
                max_r=int(visual_r * 1.3 + 8), color=ORANGE, life=0.65))
            # Particle / debris burst is queued for end-of-frame flush
            # so kills that happen in the same frame share the budget
            # (see `_flush_kill_particles` + `_kill_fx_queue`). Numbers
            # here are the "solo kill" counts; a 3-way Ball-blast frame
            # would divide each by 3.
            self._kill_fx_queue.append({
                "cx": cx, "cy": cy, "visual_r": visual_r,
                "sprite_colors": sprite_colors, "is_boss": True,
            })
            # Boss drops — money only now that the weapon / shield /
            # bomb / side categories are gone. Four pieces so the boss
            # death still feels rewarding ($25 * 4 = $100 in addition
            # to the boss CREDITS).
            for _ in range(4):
                self.pickups.append(Pickup(
                    cx + random.uniform(-20, 20),
                    cy + random.uniform(-20, 20),
                    "money", self.assets["pickup_money"]))
            self.shake = 2.0
        else:
            outer_r = int(visual_r * 2.1 + 8)
            mid_r = int(visual_r * 1.4 + 4)
            inner_r = max(6, int(visual_r * 0.8))
            self.explosions.append(ExplosionRing(cx, cy, max_r=outer_r, color=ORANGE, life=0.55))
            self.explosions.append(ExplosionRing(cx, cy, max_r=mid_r, color=YELLOW, life=0.40))
            self.explosions.append(ExplosionRing(cx, cy, max_r=inner_r, color=WHITE, life=0.20))
            # Particle / debris burst is queued for end-of-frame flush
            # so kills that happen in the same frame share the budget
            # (see `_flush_kill_particles` + `_kill_fx_queue`).
            self._kill_fx_queue.append({
                "cx": cx, "cy": cy, "visual_r": visual_r,
                "sprite_colors": sprite_colors, "is_boss": False,
            })
            self.shake = max(self.shake, 0.4)
            if isinstance(enemy, Mine):
                # Mines get an even bigger shockwave + radius damage to the player.
                self.explosions.append(ExplosionRing(cx, cy, max_r=Mine.EXPLOSION_RADIUS,
                                                     color=(255, 160, 60), life=0.6))
                if self.player.alive:
                    d = math.hypot(self.player.rect.centerx - cx,
                                   self.player.rect.centery - cy)
                    if d < Mine.EXPLOSION_RADIUS:
                        self._damage_player(Mine.EXPLOSION_DAMAGE)
                self.shake = max(self.shake, 0.8)
            if drop and enemy.DROP_TABLE and random.random() < enemy.DROP_CHANCE * self.scrap_drop_factor:
                kind = self._resolve_drop_kind(_biased_drop_kind(self, enemy.DROP_TABLE))
                self.pickups.append(Pickup(cx, cy, kind, self.assets["pickup_" + kind]))
        self.app.sounds["big_boom" if is_boss else "boom"].play()

    def _separate_overlapping_shields(self):
        """Push apart pairs of shielded NON-BOSS enemies whose shield
        circles overlap AND whose colours differ. Same-colour overlaps
        stay (no forced weapon swap to clear them). Bosses are excluded
        — their sprites are huge + they manage their own shield cycle,
        the geometry gets messy."""
        shielded = [e for e in self.enemies
                    if e.alive and e.shield_color
                    and not isinstance(e, Boss)]
        n = len(shielded)
        if n < 2:
            return
        for i in range(n):
            a = shielded[i]
            ax = float(a.x)
            ay = float(a.y)
            ar = a.shield_radius
            for j in range(i + 1, n):
                b = shielded[j]
                if b.shield_color == a.shield_color:
                    continue
                bx = float(b.x)
                by = float(b.y)
                dx = bx - ax
                dy = by - ay
                d_sq = dx * dx + dy * dy
                min_d = ar + b.shield_radius
                if d_sq >= min_d * min_d:
                    continue
                # Overlapping. Split the displacement so both move half
                # the overlap apart along the connecting axis (+ 0.5 px
                # of slop so we don't keep re-triggering next frame).
                d = math.sqrt(d_sq) if d_sq > 1e-6 else 0.01
                overlap = min_d - d
                push = overlap * 0.5 + 0.5
                ndx = dx / d
                ndy = dy / d
                a.x = ax - ndx * push
                a.y = ay - ndy * push
                b.x = bx + ndx * push
                b.y = by + ndy * push
                a.rect.center = (int(a.x), int(a.y))
                b.rect.center = (int(b.x), int(b.y))
                ax = float(a.x)
                ay = float(a.y)

    def _push_player_out(self, wall_rect):
        """Resolve overlap between the player and a wall by pushing along the
        shallowest axis."""
        pr = self.player.rect
        overlap_left = pr.right - wall_rect.left
        overlap_right = wall_rect.right - pr.left
        overlap_top = pr.bottom - wall_rect.top
        overlap_bottom = wall_rect.bottom - pr.top
        if min(overlap_left, overlap_right, overlap_top, overlap_bottom) <= 0:
            return
        m = min(overlap_left, overlap_right, overlap_top, overlap_bottom)
        if m == overlap_left:
            self.player.x -= overlap_left + 0.5
        elif m == overlap_right:
            self.player.x += overlap_right + 0.5
        elif m == overlap_top:
            self.player.y -= overlap_top + 0.5
        else:
            self.player.y += overlap_bottom + 0.5
        self.player.rect.center = (int(self.player.x), int(self.player.y))

    def _earn(self, amount):
        """Bank in-level credits on the per-PlayState counter only —
        `app.save.credits` is updated once at level exit (in run()
        below, before returning the outcome). Keeping save.credits
        out of the per-frame mutation path is what makes money
        rewindable: credits_earned IS in the rewind snapshot, so
        scrubbing back to before a kill rolls the earnings back too.
        The displayed HUD credits read `save.credits +
        credits_earned` so the player still sees the live total."""
        self.credits_earned += amount

    def _draw_boss_intro(self, surf):
        t = self.boss_intro_t
        pulse = 0.5 + 0.5 * math.sin((2.6 - t) * 18)
        # pulsing red border
        border_alpha = int(140 + 80 * pulse)
        border = pygame.Surface((PLAY_W, PLAY_H), pygame.SRCALPHA)
        pygame.draw.rect(border, (220, 50, 50, border_alpha), (0, 0, PLAY_W, PLAY_H), 6)
        surf.blit(border, (0, 0))
        # WARNING text
        big = self.app.fonts["big"].render("! WARNING !", False, (255, 90, 90))
        surf.blit(big, big.get_rect(center=(PLAY_W // 2, PLAY_H // 2 - 24)))
        # Subtitle (only show if pulse > 0.3 to give a flicker)
        if pulse > 0.3:
            sub = self.app.fonts["small"].render("BOSS APPROACHING", False, (220, 180, 180))
            surf.blit(sub, sub.get_rect(center=(PLAY_W // 2, PLAY_H // 2 + 18)))

    def _blit_pinned_station(self, surf, img, ref_cx, ref_bottom, zoom):
        """Blit a station so it rides the ribbon's center-zoom exactly —
        no relative drift against the backdrop.

        The ribbon composite is scaled about screen-centre by `zoom`
        (2x at the docked/launch key-frame, 1x at the far end — see
        _cinematic_zoom_state + the bg blit in _draw). `ref_cx` /
        `ref_bottom` give the station's screen-space horizontal centre +
        bottom edge AT that key-frame, drawn at native (1.0x) scale. We
        then apply the identical center-zoom (factor r = zoom/2 relative
        to the 2x key-frame) to the station's scale AND position, so its
        scale-ratio and translation track the ribbon in lockstep. The
        station ends up at half the ribbon's apparent zoom-depth (which
        matches the long-standing docked-frame sizing) but moves in exact
        proportion to it.

        Because the pin keeps the station on-screen at the far-zoom end
        (instead of the old scroll that slid it fully off), it would pop
        in/out at zoom~1. A short alpha ramp keyed to the same `zoom` fades
        it in as the camera closes (landing) and out as it pulls away
        (takeoff): invisible at zoom=1, fully opaque by zoom>=1.35."""
        alpha = clamp((zoom - 1.0) / 0.35, 0.0, 1.0)
        if alpha <= 0.0:
            return
        r = zoom * 0.5
        orig_w = img.get_width()
        orig_h = img.get_height()
        if abs(r - 1.0) < 0.005:
            drawn = img
            sw, sh = orig_w, orig_h
        else:
            sw = max(1, int(orig_w * r))
            sh = max(1, int(orig_h * r))
            drawn = pygame.transform.scale(img, (sw, sh))
        drawn.set_alpha(int(alpha * 255))
        cx = PLAY_W * 0.5
        cy = PLAY_H * 0.5
        center_x = cx + (ref_cx - cx) * r
        bottom_y = cy + (ref_bottom - cy) * r
        surf.blit(drawn, (int(center_x - sw * 0.5), int(bottom_y - sh)))

    def _draw(self, controls):
        # GPU render mode: PlayState draws natively to the renderer. One dispatch
        # here covers every _draw() call site (live play + replay view). Timed as
        # "draw.gpu" (CPU command-submit cost; the GPU exec + vsync land in
        # "app.flip") so the live perf feed shows the GPU draw alongside upd.*.
        if getattr(self.app, "gpu", None) is not None:
            self.app.gpu_native = True
            self.app.perf.start("draw.gpu")
            self._draw_gpu(controls)
            self.app.perf.end("draw.gpu")
            return
        perf = self.app.perf
        screen = self.app.screen
        shake_x = random.randint(-int(self.shake * 3), int(self.shake * 3)) if self.shake > 0 else 0
        shake_y = random.randint(-int(self.shake * 3), int(self.shake * 3)) if self.shake > 0 else 0
        playfield = self._playfield
        playfield_full = self._playfield_full
        playfield_full.fill(BLACK)
        # Background composite. During intro / outro we render bg_ribbon
        # + nebula + stars onto a reusable PLAY_W x PLAY_H surface, then
        # nearest-neighbour scale + centre-blit onto playfield so every
        # backdrop layer zooms together: 2x -> 1x on intro (camera pulls
        # back from launch pad) and 1x -> 2x on outro (camera pulls
        # toward arrival station). PLAY_MARGIN side strips stay black
        # during the cinematic — parallax_x is zeroed there and the
        # player is mid-screen, so the lost margins don't matter. Normal
        # play takes the existing direct-blit path with its wider
        # playfield_full buffer for parallax-revealed margins.
        in_cinematic, zoom = self._cinematic_zoom_state()
        if in_cinematic:
            perf.start("draw.bg_zoom")
            bg = self._cinematic_bg_surf
            self.bg_ribbon.draw(bg)
            if ENABLE_NEBULA:
                self.nebula.draw(bg)
            self.stars.draw(bg)
            if abs(zoom - 1.0) < 0.005:
                playfield.blit(bg, (0, 0))
            else:
                sw = max(1, int(PLAY_W * zoom))
                sh = max(1, int(PLAY_H * zoom))
                scaled = pygame.transform.scale(bg, (sw, sh))
                playfield.blit(scaled,
                               ((PLAY_W - sw) // 2, (PLAY_H - sh) // 2))
            perf.end("draw.bg_zoom")
        else:
            perf.start("draw.bg_ribbon")
            # Bg fills the full (PLAY_W + 2*PLAY_MARGIN)-wide surface so the
            # bands exposed by parallax/shake on either side stay covered.
            self.bg_ribbon.draw(playfield_full)
            perf.end("draw.bg_ribbon")
            # Game-fully-complete: fade the ribbon (and nebula, which is
            # painted next) to black over _WIN_RIBBON_FADE_DUR seconds
            # so the fireworks read clean against a dark backdrop. Stars
            # + entities (incl. the player ship) draw AFTER this overlay
            # so they stay visible on top of the fade.
            if self._game_won:
                ratio = min(1.0, self._game_won_t / self._WIN_RIBBON_FADE_DUR)
                if ratio > 0:
                    overlay = self._outro_fade_overlay
                    overlay.set_alpha(int(255 * ratio))
                    playfield_full.blit(overlay, (0, 0))
            perf.start("draw.nebula")
            if ENABLE_NEBULA and not self._game_won:
                self.nebula.draw(playfield)
            perf.end("draw.nebula")
            perf.start("draw.stars")
            self.stars.draw(playfield)
            perf.end("draw.stars")
        # Entities draw onto the WIDER playfield_full surface with offset_x
        # = PLAY_MARGIN so sprites whose centre sits near a world edge can
        # still paint their full pixels into the cosmetic margin. When
        # parallax_x leans the camera, those margin pixels become visible
        # — without this offset, an enemy centred at world x=0 would draw
        # only its right half (the left half clipped at the subsurface
        # boundary) and the lean would reveal background where the rest
        # of the sprite should be. Same pattern as the player draw below.
        perf.start("draw.pickups")
        for p in self.pickups:
            p.draw(playfield_full, offset_x=PLAY_MARGIN)
        perf.end("draw.pickups")
        perf.start("draw.bullets")
        # Batch consecutive sprite-bearing bullets into a single
        # Surface.blits() call (one C scan instead of N Python blit calls).
        # Anything that needs special draw work (procedural enemy bullets,
        # rare flipped enemy glyphs) breaks the batch with .draw().
        batch = []
        batch_append = batch.append
        playfield_blits = playfield_full.blits
        for b in self.bullets:
            info = b.batch_blit_info(offset_x=PLAY_MARGIN)
            if info is not None:
                batch_append(info)
            else:
                if batch:
                    playfield_blits(batch, doreturn=False)
                    batch = []
                    batch_append = batch.append
                b.draw(playfield_full, offset_x=PLAY_MARGIN)
        if batch:
            playfield_blits(batch, doreturn=False)
        perf.end("draw.bullets")
        perf.start("draw.lasers")
        for laser in self.lasers:
            laser.draw(playfield_full, offset_x=PLAY_MARGIN)
        for r in self.rays:
            r.draw(playfield_full, offset_x=PLAY_MARGIN)
        perf.end("draw.lasers")
        # In-flight Ball projectiles draw on top of bullets so the red
        # ball reads clearly even when crossing a stream.
        for ball in self.balls:
            ball.draw(playfield_full, offset_x=PLAY_MARGIN)
        perf.start("draw.enemies")
        for e in self.enemies:
            e.draw(playfield_full, offset_x=PLAY_MARGIN)
        perf.end("draw.enemies")
        perf.start("draw.particles")
        parts = self.particles
        for i in range(self._part_cursor, len(parts)):
            parts[i].draw(playfield_full, offset_x=PLAY_MARGIN)
        for s in self.sparks:
            s.draw(playfield_full, offset_x=PLAY_MARGIN)
        for ex in self.explosions:
            ex.draw(playfield_full, offset_x=PLAY_MARGIN)
        for ft in self.float_texts:
            ft.draw(playfield_full, offset_x=PLAY_MARGIN)
        perf.end("draw.particles")
        # Stations are drawn BEFORE the player so the ship reads as taking
        # off from / docking at them. Both ride the ribbon's center-zoom via
        # _blit_pinned_station (zoom from _cinematic_zoom_state) so the
        # station stays glued to the backdrop instead of drifting on its own
        # curve. `zoom` was computed once at the top of _draw via
        # _cinematic_zoom_state (intro/outro/parade all covered).
        # Departing platform: at the launch key-frame (zoom=2) it rests with
        # its bottom on the screen bottom, native scale + ship parked on it;
        # as the camera pulls back (zoom 2->1) the pin recedes it toward
        # centre and shrinks it 1.0x -> 0.5x in lockstep with the ribbon.
        if self.intro_t > 0:
            ref_bottom = PLAY_H
            self._blit_pinned_station(playfield, self.station_start,
                                      PLAY_W * 0.5, ref_bottom, zoom)
        # Arrival station: at the dock key-frame (zoom=2) its top sits at
        # y=20, native scale, with the ship's dock point just below; earlier
        # in the outro (zoom->1) the pin places it smaller + nearer centre,
        # so it grows up into frame as the camera closes on it.
        if self.outro_t > 0:
            ref_bottom = 20 + self.station_end.get_height()
            self._blit_pinned_station(playfield, self.station_end,
                                      PLAY_W * 0.5, ref_bottom, zoom)
        perf.start("draw.player")
        if self.player.alive:
            # Draw onto the wider playfield_full + offset by PLAY_MARGIN
            # so banking sprites — which are visibly wider than the
            # straight ship — can extend past the logical playfield
            # edge into the cosmetic margin instead of being clipped
            # at the subsurface boundary.
            self.player.draw(playfield_full, offset_x=PLAY_MARGIN,
                             sidebar_alpha=self._sidebar_alpha(),
                             sidebar_fill_override=self._sidebar_intro_fill())
        perf.end("draw.player")
        # Replay ghost overlay — abandoned rewind branches, drawn AFTER the
        # whole kept timeline so the translucent copies sit on top of it.
        if self._replay_active and self._active_ghosts:
            self._draw_ghosts(playfield_full)
        if self.boss_intro_t > 0:
            self._draw_boss_intro(playfield)
        if self.player.bomb_flash > 0:
            o = self._bomb_overlay
            o.set_alpha(int(180 * self.player.bomb_flash))
            playfield_full.blit(o, (0, 0))
        if self.flash > 0:
            o = self._flash_overlay_red if self.outcome != "win" else self._flash_overlay_cyan
            o.set_alpha(int(80 * self.flash))
            playfield_full.blit(o, (0, 0))
        # Hidden test-mission cinematic — only runs in the test mission.
        if self.is_test and not getattr(self, "_test_parade_done", True):
            self._draw_test_parade_stations(playfield)
        # The R3 debug / perf overlay is drawn in the SHARED _draw_screen_overlays
        # tail (below) so it renders on the GPU path too — it used to be drawn
        # here onto `playfield`, which the GPU path never composites.

        # Parallax shifts the WHOLE playfield blit so bg + entities all
        # drift opposite to the player's lateral motion. With the
        # impulse-decay parallax_x update (below) this is non-zero only
        # while the player is actively moving — when they stop, it lerps
        # back to 0, so the player and enemies can still reach the
        # screen's left/right edges at rest.
        perf.start("draw.blit_screen")
        parallax_off = int(self.parallax_x)
        screen.blit(playfield_full,
                    (shake_x + parallax_off - PLAY_MARGIN, shake_y))
        if self._glitch_t > 0.01:
            self._apply_glitch_overlay(screen)
        perf.end("draw.blit_screen")
        self._draw_screen_overlays(screen, shake_x, shake_y, parallax_off)

    def _draw_screen_overlays(self, screen, shake_x, shake_y, parallax_off,
                              draw_black_backdrop=True):
        """Screen-space overlay tail shared by the software _draw() and the
        GPU overlay pass (_gpu_draw_overlays uploads these onto a transparent
        surface via blit_dynamic). Death shatter, off-screen markers, the
        centre banner, layout overlay, cheat summary, the outro/win black
        backdrop, win-complete banner, replay HUD, game-won screen and the
        test menu — everything drawn after the playfield is composited.

        draw_black_backdrop: software passes True (the opaque outro/win fade
        is drawn here onto the real framebuffer). The GPU path passes False —
        it fills those backdrops natively on the renderer BEFORE uploading
        this (transparent) overlay, because set_alpha on an RGB surface is
        ignored when blitting onto an SRCALPHA target (the ramp would snap to
        full black)."""
        # Player death shatter — drawn AFTER the glitch overlay so the moment
        # of death (and the white-flash frame marker) punches through the CRT
        # noise instead of being swallowed by it. World→screen maps by
        # (+shake +parallax); the playfield's PLAY_MARGIN cancels out.
        self._render_death_fx(screen, shake_x, shake_y, parallax_off)
        # Dead-pause "HOLD X TO REWIND" prompt — shared by the software + GPU
        # paths (see _draw_dead_pause_prompt). Drawn over the death shatter.
        if self._dead_paused:
            self._draw_dead_pause_prompt(screen)
        # Off-screen enemy markers — drawn IN SCREEN SPACE (after the
        # parallax + shake blit) so the player's lateral motion doesn't
        # drag them away from the edge. Skipped during cinematics + the
        # win-hold banner so the freeze frame doesn't get cluttered.
        if (self.intro_t <= 0 and self.outro_t <= 0
                and not self._win_held and self.enemies):
            self._draw_offscreen_enemy_markers(screen)
        # In-game HUD removed (v0.9.274) — the play area fills the whole
        # screen. The cooldown sidebars still draw around the ship (in
        # player.draw), and the replay HUD floats on top during replay.

        # Centre-screen banner: paused / mission complete / ship destroyed.
        # All three share the same template (dim overlay + big title + small
        # subtitle); only the strings differ, so one element with template
        # vars covers everything. visible_when=banner_visible gates the
        # whole container so no banner renders when none of the three
        # states are active.
        banner_title = banner_subtitle = ""
        # In test mode the pause state shows the loadout menu instead of
        # the generic "PAUSED" banner — skip that path here. During a replay
        # the HUD speed readout shows the paused (0.0×) state, so skip the
        # banner there too (you can still jog from the frozen frame).
        if self.pause and not self.is_test and not self._replay_active:
            # Resume = pause/Start; abort = North (same button as "give up"
            # on the FAILED banner); holding East rewinds straight out of the
            # break (unhinted — it's the natural rewind reflex).
            banner_title = "PAUSED"
            banner_subtitle = (btn_label('start') + " continue   "
                               "{btn_cancel} abort")
        # MISSION COMPLETE deliberately doesn't set banner_title here —
        # the win-hold path renders its own multi-line banner below
        # (after the OUTRO fade overlay) with the percentage on its
        # own coloured line and the button hints split off.
        # (Loss has no banner — the dead-pause prompt covers death, and
        # giving up sets outcome="loss" which routes straight to the shop
        # like any level end. The old one-frame "SHIP DESTROYED" banner was
        # invisible in practice and its "fire continue" hint was a lie.)
        play_vars = {
            "banner_visible": bool(banner_title),
            "banner_title": banner_title,
            "banner_subtitle": banner_subtitle,
        }
        banner = get_element("play", "play_banner", **play_vars)
        if banner is not None:
            _layout_draw_item(screen, banner, self.app.fonts,
                              self.app.assets, play_vars)

        draw_layout_overlay(screen, "play", self.app.fonts, self.app.assets,
                            template_vars=play_vars)

        # Cheat summary overlay — drawn last so it sits on top of every
        # other layer (banner, vignette, etc.).
        if self._cheat_summary_t > 0 and self._cheat_summary is not None:
            self._draw_cheat_summary(screen)

        # Post-dock fade to black. Drawn dead last so it covers HUD,
        # banner, cheat summary, everything. Alpha ramps 0->255 across
        # the OUTRO_FADE_DUR window so by the time the level actually
        # transitions, the screen is fully black and the dock music has
        # finished resolving its IV-V-I cadence.
        if draw_black_backdrop:
            if self.outro_t > 0:
                elapsed = OUTRO_TOTAL_DUR - self.outro_t
                if elapsed > OUTRO_CINEMATIC_DUR:
                    fade_t = (elapsed - OUTRO_CINEMATIC_DUR) / OUTRO_FADE_DUR
                    fade_t = clamp(fade_t, 0.0, 1.0)
                    if fade_t > 0:
                        overlay = self._outro_fade_overlay
                        overlay.set_alpha(int(255 * fade_t))
                        screen.blit(overlay, (0, 0))
            elif self._win_held or self.outcome == "win":
                # Outro has finished; keep the fully-black backdrop drawn
                # under the MISSION COMPLETE banner so the playfield doesn't
                # bleed back through while the player reads the result.
                overlay = self._outro_fade_overlay
                overlay.set_alpha(255)
                screen.blit(overlay, (0, 0))

        # Win-hold banner — drawn AFTER the OUTRO fade so it sits on top
        # of the black backdrop. Multi-line, cyan title, percentage on
        # its own colour-coded line.
        if self._win_held or self.outcome == "win":
            self._draw_win_complete(screen)

        # MISSION COMPLETE replay: the HUD column becomes a vertical
        # timeline bar + control hints (the playfield itself draws normally
        # because the restored snapshots carry _win_held = False).
        if self._replay_active:
            self._draw_replay_hud(screen)
            # Modal SAVING overlay on top of the frozen replay frame.
            if self._mreplay_saving:
                self._draw_mreplay_saving(screen)

        # Game-fully-complete YOU WIN screen. Fireworks bloom in the
        # playfield region (drawn on top of the player so the ship
        # appears to be flying through them); the YOU WIN title sits
        # mid-screen in cyan. Drawn after HUD / banner / outro so it's
        # the topmost layer except for the test-menu overlay.
        if self._game_won:
            self._draw_game_won(screen)

        # Test-mission upgrade menu sits on top of everything when paused.
        if self.is_test and self.pause:
            self._draw_test_menu(screen)

        # Debug / perf overlay (R3) — drawn in the SHARED tail so the GPU path
        # renders it too (was software-only, onto `playfield`). The GPU overlay
        # `active` gate already includes `_test_overlay_mode != 3`. Top-left
        # panel in screen-space; tracked under its own perf stage so the cost
        # of *viewing* perf-detail stays visible in the perf-detail panel.
        if self._test_overlay_mode != 3:
            perf = self.app.perf
            perf.start("draw.overlay")
            self._draw_test_banner(screen)
            perf.end("draw.overlay")

    def _draw_gpu(self, controls):
        """GPU sibling of _draw() — draws the scene STRAIGHT to the output at
        PLAY_W (640), no bleed margin / FULL_W frame. The parallax lean is a
        per-layer offset_x (depth: far layers move less, see _gpu_compose_scene);
        screen shake is a global gpu translation origin (the wider-than-screen
        ribbon + wrapping stars cover the shifted edges, so no margin is needed).

        The ONLY render-to-texture left is (a) the CRT glitch capture — a PLAY_W
        frame the tear pass re-samples; tear bands that read past the edge show
        black, which is fine; and (b) the cinematic bg-zoom — a PLAY_W layer
        scaled by `zoom`. Both are pre-rendered BEFORE the output target is bound
        so we never switch the target away from the scene after drawing it (tiled
        Mali GPUs don't reload a re-bound target). Ghosts/boss composite directly.
        Renders to gpu's CURRENT target (App sets the backbuffer; a test sets a
        readback target). Does NOT present — the App flips."""
        gpu = self.app.gpu
        sx = random.randint(-int(self.shake*3), int(self.shake*3)) if self.shake > 0 else 0
        sy = random.randint(-int(self.shake*3), int(self.shake*3)) if self.shake > 0 else 0
        px = int(self.parallax_x)
        in_cinematic, zoom = self._cinematic_zoom_state()
        ghosts_on = self._replay_active and self._active_ghosts
        boss_on = self.boss_intro_t > 0
        glitch_on = self._glitch_t > 0.01
        out = gpu.get_target()
        # Pre-render offscreen layers (ghost field, cinematic bg-zoom) FIRST so
        # the render target is never switched AWAY from the output/scene after we
        # begin drawing it (Mali tiled-GPU target-reload hazard).
        ghost_state = self._render_ghost_layers(gpu) if ghosts_on else None
        cine_tex = self._render_cine_layer(gpu, zoom) if in_cinematic else None
        if glitch_on:
            # Capture the scene to a PLAY_W frame, then present it shifted by
            # shake with the CRT tear/chroma/scanline pass. Tears that sample
            # past the frame edge show black — acceptable for the glitch.
            frame = getattr(self, "_gpu_scene_tex", None)
            if frame is None:
                frame = self._gpu_scene_tex = gpu.make_target((PLAY_W, PLAY_H))
            gpu.set_target(frame)
            gpu.begin(BLACK)
            self._gpu_compose_scene(gpu, px, zoom, cine_tex,
                                    ghosts_on, boss_on, ghost_state)
            gpu.set_target(out)
            gpu.begin(BLACK)
            if self._glitch_overlay is None:
                self._glitch_overlay = _build_crt_scanline_overlay(
                    PLAY_W, PLAY_H, _CRT_PROFILE_PLAY)
            _apply_crt_glitch_gpu(gpu, frame, (sx, sy, PLAY_W, PLAY_H),
                                  self._glitch_t, scanline_cache=self._glitch_overlay)
        else:
            # Direct draw to the output; shake the whole scene via the origin.
            # set_target(out): the ghost/cinematic pre-renders above left the
            # target on an offscreen texture — rebind the output before drawing.
            gpu.set_target(out)
            gpu.begin(BLACK)
            gpu.set_origin(sx, sy)
            self._gpu_compose_scene(gpu, px, zoom, cine_tex,
                                    ghosts_on, boss_on, ghost_state)
            gpu.set_origin(0, 0)
        # Screen-space overlays (banners, markers, win-complete, replay HUD,
        # game-won, death shatter, test menu) — drawn at origin 0 (screen-fixed),
        # software onto a transparent surface and uploaded as one streaming
        # texture. The opaque outro/win black backdrop is filled natively first.
        self._gpu_draw_overlays(gpu, sx, sy, px)

    def _render_cine_layer(self, gpu, zoom):
        """Render the cinematic backdrop+stars to a cached PLAY_W target (drawn
        at offset 0, no lean); _gpu_compose_scene blits it SCALED by `zoom`. Done
        BEFORE the output target is bound (see _draw_gpu) so the target isn't
        switched away from the scene afterwards."""
        cine = getattr(self, "_gpu_cine_tex", None)
        if cine is None:
            cine = self._gpu_cine_tex = gpu.make_target((PLAY_W, PLAY_H))
        gpu.set_target(cine)
        gpu.begin(BLACK)
        self.bg_ribbon.draw_gpu(gpu, PLAY_W, PLAY_H, offset_x=0)
        if ENABLE_NEBULA:
            self.nebula.draw_gpu(gpu, offset_x=0)
        self.stars.draw_gpu(gpu, lean=0)
        return cine

    def _gpu_compose_scene(self, gpu, px, zoom, cine_tex,
                           ghosts_on, boss_on, ghost_state):
        """Draw the playfield onto the CURRENT target at PLAY_W: backdrop (or the
        pre-rendered cinematic zoom layer), stars, entities, pinned stations,
        player, replay ghosts, boss-intro, flash. The parallax lean is applied
        per layer (depth-scaled) via offset_x; shake is whatever global origin
        gpu currently carries. Shared by the direct path and the glitch capture."""
        if cine_tex is not None:
            sw = max(1, int(PLAY_W * zoom))
            sh = max(1, int(PLAY_H * zoom))
            gpu.blit(cine_tex, pygame.Rect((PLAY_W - sw) // 2,
                                           (PLAY_H - sh) // 2, sw, sh))
        else:
            self.bg_ribbon.draw_gpu(gpu, PLAY_W, PLAY_H,
                                    offset_x=int(px * _LEAN_RIBBON))
            if self._game_won:
                ratio = min(1.0, self._game_won_t / self._WIN_RIBBON_FADE_DUR)
                if ratio > 0:
                    gpu.fill_rect(pygame.Rect(0, 0, PLAY_W, PLAY_H),
                                  (0, 0, 0, int(255 * ratio)))
            if ENABLE_NEBULA and not self._game_won:
                self.nebula.draw_gpu(gpu, offset_x=int(px * _LEAN_RIBBON))
            self.stars.draw_gpu(gpu, lean=px)
        self._gpu_draw_entities(gpu, px)
        # Pinned takeoff/landing stations — software onto a PLAY_W scratch,
        # uploaded (before the player, as in _draw).
        if self.intro_t > 0 or self.outro_t > 0:
            cs = self._gpu_center_scratch(PLAY_W, PLAY_H)
            cs.fill((0, 0, 0, 0))
            if self.intro_t > 0:
                self._blit_pinned_station(cs, self.station_start,
                                          PLAY_W * 0.5, PLAY_H, zoom)
            if self.outro_t > 0:
                self._blit_pinned_station(cs, self.station_end, PLAY_W * 0.5,
                                          20 + self.station_end.get_height(), zoom)
            gpu.blit_dynamic("pf_stations", cs, pygame.Rect(0, 0, PLAY_W, PLAY_H))
        if self.player.alive:
            self.player.draw_gpu(gpu, offset_x=px, sidebar_alpha=self._sidebar_alpha(),
                                 sidebar_fill_override=self._sidebar_intro_fill())
        # Replay ghosts (pre-rendered to their targets) + boss-intro, both AFTER
        # the player — composited at offset 0, no target switch.
        if ghosts_on:
            self._composite_ghost_layers(gpu, 0, *ghost_state)
        if boss_on:
            fs = self._gpu_full_scratch(PLAY_W, PLAY_H, 0)
            fs.fill((0, 0, 0, 0))
            self._draw_boss_intro(self._gpu_full_center)
            gpu.blit_dynamic("pf_post", fs, pygame.Rect(0, 0, PLAY_W, PLAY_H))
        self._gpu_play_flash(gpu, PLAY_W)

    def _advance_particle_cursor(self):
        """Advance the live-particle window past dead leading entries. O(newly-
        dead) amortised (the cursor persists), so the dead prefix is walked
        once total, not re-scanned every frame. Never passes a live particle —
        it stops at the first life>0 — so the skipped prefix is provably dead."""
        c = self._part_cursor
        ps = self.particles
        n = len(ps)
        if c > n:
            c = n
        while c < n and ps[c].life <= 0:
            c += 1
        self._part_cursor = c

    def _gpu_draw_entities(self, gpu, off):
        """Per-entity draw_gpu sweep shared by the fast + multi-pass paths
        (z-order mirrors _draw). `off` is the playfield offset_x. Bullets +
        particles/sparks (the highest-count lists) go through batched helpers
        that draw on the raw renderer and minimise per-item Python + state
        churn so SDL's internal same-texture / same-colour batching kicks in."""
        for p in self.pickups: p.draw_gpu(gpu, offset_x=off)
        self._gpu_draw_bullets(gpu, self.bullets, off)
        for laser in self.lasers: laser.draw_gpu(gpu, offset_x=off)
        for r in self.rays: r.draw_gpu(gpu, offset_x=off)
        for ball in self.balls: ball.draw_gpu(gpu, offset_x=off)
        for e in self.enemies: e.draw_gpu(gpu, offset_x=off)
        # particles: skip the dead leading window; sparks are culled (start 0)
        self._gpu_draw_particles(gpu, self.particles, off, self._part_cursor)
        self._gpu_draw_particles(gpu, self.sparks, off)
        for ex in self.explosions: ex.draw_gpu(gpu, offset_x=off)
        for ft in self.float_texts: ft.draw_gpu(gpu, offset_x=off)

    @staticmethod
    def _gpu_draw_bullets(gpu, bullets, off):
        """Batched sprite-bullet blits. Most bullets share one glyph texture,
        so a tight loop on the raw Texture.draw (skipping gpu.blit's per-call
        colour/alpha guard) lets SDL collapse them into one GL draw. Spriteless
        bullets (procedural enemy fire) fall back to their own draw_gpu."""
        Rect = pygame.Rect
        ox, oy = gpu._ox, gpu._oy   # raw draw bypasses gpu.blit's shake origin
        cache = {}
        for b in bullets:
            spr = b.sprite
            if spr is None:
                b.draw_gpu(gpu, offset_x=off)
                continue
            t = cache.get(id(spr))
            if t is None:
                t = cache[id(spr)] = gpu.tex_for(spr)
            sw, sh = spr.get_width(), spr.get_height()
            t.draw(dstrect=Rect(b.rect.centerx + off - sw // 2 + ox,
                                b.rect.centery - sh // 2 + oy, sw, sh),
                   flip_y=(not b.friendly and b.vy > 0))

    @staticmethod
    def _gpu_draw_particles(gpu, parts, off, start=0):
        """Batched shrinking-rect particles (base Particle + Spark). draw_color
        is set only when the colour changes, so SDL coalesces same-colour runs
        (a kill burst shares one palette) into one GL draw. Subclasses with a
        custom draw_gpu (ImpactSpark, Debris, ...) dispatch to their own.
        `start` skips the dead leading window (the append-only particle list)."""
        ren = gpu.renderer
        Rect = pygame.Rect
        ox, oy = gpu._ox, gpu._oy   # raw draw bypasses gpu.fill_rect's shake origin
        last = None
        n = len(parts)
        for i in range(start, n):
            p = parts[i]
            cls = p.__class__
            if cls is not Particle and cls is not Spark:
                p.draw_gpu(gpu, offset_x=off)
                last = None   # the custom draw may have changed draw_color
                continue
            if p.life <= 0:
                continue
            a = p.life / p.max_life
            c = p.color
            if c != last:
                ren.draw_color = (c[0], c[1], c[2], c[3] if len(c) > 3 else 255)
                last = c
            w = int(p.size * a)
            h = int(p.size_h * a)
            ren.fill_rect(Rect(int(p.x) + off + ox, int(p.y) + oy,
                               1 if w < 1 else w, 1 if h < 1 else h))

    def _gpu_play_flash(self, gpu, w):
        """Bomb-flash + hit-flash full-width overlays, shared by both paths.
        The overlay textures are solid colour so a w=PLAY_W vs FULL_W dst is
        visually identical."""
        if self.player.bomb_flash > 0:
            gpu.blit(gpu.tex_for(self._bomb_overlay), pygame.Rect(0, 0, w, PLAY_H),
                     alpha=int(180 * self.player.bomb_flash))
        if self.flash > 0:
            o = self._flash_overlay_red if self.outcome != "win" else self._flash_overlay_cyan
            gpu.blit(gpu.tex_for(o), pygame.Rect(0, 0, w, PLAY_H),
                     alpha=int(80 * self.flash))

    def _gpu_center_scratch(self, w, h):
        """Cached PLAY_W transparent scratch for GPU uploads of PLAY_W-local
        software layers (pinned stations)."""
        s = getattr(self, "_gpu_center_surf", None)
        if s is None or s.get_size() != (w, h):
            s = self._gpu_center_surf = pygame.Surface((w, h), pygame.SRCALPHA)
        return s

    def _gpu_full_scratch(self, w, h, m):
        """Cached full-width transparent scratch (+ a PLAY_W centre subsurface)
        for GPU uploads of playfield_full-local layers (ghosts, boss-intro)."""
        s = getattr(self, "_gpu_full_surf", None)
        if s is None or s.get_size() != (w, h):
            s = self._gpu_full_surf = pygame.Surface((w, h), pygame.SRCALPHA)
            self._gpu_full_center = s.subsurface((m, 0, w - 2 * m, h))
        return s

    def _gpu_draw_overlays(self, gpu, sx, sy, px):
        """GPU companion to the screen-space overlay tail. Fills the
        outro/win black backdrop natively on the renderer, then renders the
        rest of _draw_screen_overlays onto a cached transparent surface and
        composites it via blit_dynamic. The surface upload only runs when an
        overlay is actually present (the usual case is nothing → no upload)."""
        # Native opaque black backdrop (outro fade ramp / win-hold / game-won)
        # — drawn straight on the renderer output so the alpha ramp is exact.
        if self.outro_t > 0:
            elapsed = OUTRO_TOTAL_DUR - self.outro_t
            if elapsed > OUTRO_CINEMATIC_DUR:
                fade_t = clamp((elapsed - OUTRO_CINEMATIC_DUR) / OUTRO_FADE_DUR,
                               0.0, 1.0)
                if fade_t > 0:
                    gpu.fill_rect(pygame.Rect(0, 0, SCREEN_W, SCREEN_H),
                                  (0, 0, 0, int(255 * fade_t)))
        elif self._win_held or self.outcome == "win":
            gpu.fill_rect(pygame.Rect(0, 0, SCREEN_W, SCREEN_H), (0, 0, 0, 255))
        # The remaining overlays composite cleanly via SRCALPHA. Skip the whole
        # software pass + upload when nothing is active (the common case).
        markers_on = (self.intro_t <= 0 and self.outro_t <= 0
                      and not self._win_held and self.enemies)
        active = (self._death_fx_active() or markers_on or self.pause
                  or self._dead_paused
                  or self._win_held or self.outcome == "win"
                  or self._replay_active or self._game_won
                  or (self._cheat_summary_t > 0 and self._cheat_summary is not None)
                  or (self.is_test and not getattr(self, "_test_parade_done", True))
                  or self._test_overlay_mode != 3)
        if not active:
            return
        surf = getattr(self, "_gpu_overlay_surf", None)
        if surf is None:
            surf = self._gpu_overlay_surf = pygame.Surface(
                (SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        surf.fill((0, 0, 0, 0))
        self._draw_screen_overlays(surf, sx, sy, px, draw_black_backdrop=False)
        gpu.blit_dynamic("play_overlay", surf,
                         pygame.Rect(0, 0, SCREEN_W, SCREEN_H))

    # Percentage tiers for the MISSION COMPLETE banner. Lower bound on
    # each band; the next band's lower bound is the upper bound here.
    # 100% sits in its own bucket so a perfect clear glows distinctly
    # yellow regardless of where the cutoffs land.
    _WIN_PCT_COLORS = (
        (70,  (255, 100, 50)),    # below 70 → red-orange (misses dragging it down)
        (100, (255, 165, 40)),    # 70..99 → orange
        (101, (255, 230, 80)),    # exactly 100 → yellow
    )

    def _win_pct_color(self, pct):
        for upper, color in self._WIN_PCT_COLORS:
            if pct < upper:
                return color
        return self._WIN_PCT_COLORS[-1][1]

    # Gold for the YOU WIN headline — saturated yellow with a touch
    # of orange, distinct from the YELLOW constant (which reads more
    # lemon).
    _WIN_GOLD = (255, 195, 30)
    # Seconds for the bg ribbon → black fade on entry. Stars + ship +
    # fireworks + headline keep drawing over the resulting black
    # backdrop (they all draw AFTER the fade overlay in _draw).
    _WIN_RIBBON_FADE_DUR = 1.0

    def _draw_game_won(self, screen):
        """Game-fully-complete YOU WIN overlay. The bg-ribbon black
        fade is applied at the playfield-composite stage in _draw;
        here we just paint the sparks + headline on top of the
        already-composited screen. Centred on the play area (PLAY_W
        wide), not the full screen — the HUD column sits to the right
        and would pull the visual centre off."""
        for p in self._win_particles:
            p.draw(screen)
        # YOU WIN — gold, doubled-scale via nearest-neighbour. font
        # "mega" (scale 6) is already 2x the size of "big" (scale 3)
        # we were using before. Centre on the play area.
        fonts = self.app.fonts
        title_font = (fonts.get("mega") or fonts.get(6)
                      or fonts.get("big") or fonts.get(3))
        text = title_font.render("YOU WIN", False, self._WIN_GOLD)
        cx = PLAY_W // 2
        cy = PLAY_H // 2
        rect = text.get_rect(center=(cx, cy))
        screen.blit(text, rect)
        # Subtle dismiss hint below — only visible after the input
        # grace window so it doesn't pre-empt the celebration.
        if self._game_won_t > 1.0:
            small = fonts.get("small") or fonts.get(2)
            draw_rich_text(screen, cx, rect.bottom + 18,
                           "{btn_cancel} to exit", fonts, small,
                           (180, 200, 220), anchor="c")

    def _draw_win_complete(self, screen):
        """MISSION COMPLETE / MISSION FAILED overlay shown while
        `_win_held`. Full clear: the headline is STOLEN TIME — the
        committed rewind score — with NEW BEST! or (best: X.XX s)
        beneath it. Partial clear: headline is N enemies escaped; the
        stolen time is hidden because there's no completion to score.

        Yellow (YELLOW) is the score-emphasis color and ties
        the banner to the same yellow used in the map-details bar chart
        for the current-best dot + textual readout."""
        fonts = self.app.fonts
        title_font = fonts.get("big") or fonts.get(3) or fonts.get("small")
        big_font = fonts.get("big") or fonts.get(3) or fonts.get("small")
        small = fonts.get("small") or fonts.get(2)
        # Action-hint lines carry {btn_*} tokens -> inline face glyphs.
        # <100% treated as a fail: title flips to MISSION FAILED and the
        # fire action becomes "give up" instead of "continue".
        ghost_fail = self._held_progress < 1.0
        banner_title = "MISSION FAILED" if ghost_fail else "MISSION COMPLETE"
        banner_color = (255, 90, 90) if ghost_fail else CYAN
        title_surf = title_font.render(banner_title, False, banner_color)
        # Headline below the title — escaped count on fail, stolen time
        # on a 100% clear. Stolen time is the committed (banked) value;
        # the live counter may keep growing if the player rewinds again
        # after the banner, but the score is locked the moment we hit
        # _commit_win.
        if ghost_fail:
            escaped = max(0, self.enemies_spawned - self.enemies_killed)
            noun = "enemy" if escaped == 1 else "enemies"
            head_surf = big_font.render(
                f"{escaped} {noun} escaped", False, banner_color)
            sub_surf = None
        else:
            t = float(self._committed_stolen_time
                      if self._committed_stolen_time is not None
                      else self.stolen_time)
            head_surf = big_font.render(
                f"STOLEN TIME: {t:.2f} s", False, YELLOW)
            # NEW BEST! when this attempt beat every prior committed
            # score (or there are no priors — first completion is by
            # definition a record). Otherwise show the prior best for
            # comparison so the player can see the bar to clear.
            stats = (self.app.save.level_stats or {}).get(self.level.key, {})
            times = stats.get("stolen_times") or []
            priors = [float(x) for x in times[:-1]] if times else []
            if not priors or t <= min(priors):
                sub_surf = small.render("NEW BEST!", False, YELLOW)
            else:
                sub_surf = small.render(
                    f"best: {min(priors):.2f} s", False, (200, 210, 230))
        credits_surf = small.render(
            f"+{self.credits_earned} credits", False, WHITE)
        # Action-hint lines. COMPLETE and FAIL use DIFFERENT buttons (see the
        # win-hold dispatch in run()):
        #   COMPLETE : GO continue  ·  hold East rewind  ·  North replay level
        #   FAIL     : West retry  ·  North give up  ·  hold East rewind
        #              (South is intentionally UNMAPPED on FAIL — the player
        #               must pick retry / give up / rewind, not reflex GO.)
        hint_lines = []
        # In replay the continue / rewind / retry / replay actions don't apply
        # (you're watching, not playing) — so drop the control hints entirely;
        # the title + stolen-time + credits still show.
        if not self._replay_active:
            if ghost_fail:
                hint_lines.append("{btn_ability} retry")
                hint_lines.append("{btn_cancel} give up")
            else:
                hint_lines.append("{btn_fire} continue")
            if _REWIND_UNLOCKED or ghost_fail:
                hint_lines.append("hold {btn_bomb} to rewind")
            if (not ghost_fail) and len(self._rewind) > 1:
                hint_lines.append("{btn_ability} replay")

        # Vertical stack: title / head / (sub) / credits separated by
        # pad_block, then the hint lines (first after a block, the rest by
        # line padding). Hint lines are kept as token STRINGS and drawn via
        # draw_rich_text (inline glyphs); the rest are pre-rendered surfaces.
        # When sub_surf is None (partial clear) the slot is simply skipped.
        pad_block, pad_line = 14, 4
        hint_h = small.get_height()
        seq = [title_surf, head_surf]
        if sub_surf is not None:
            seq.append(sub_surf)
        seq.append(credits_surf)
        first_hint_idx = len(seq)
        seq.extend(hint_lines)
        cx = SCREEN_W // 2

        def _item_h(it):
            return hint_h if isinstance(it, str) else it.get_height()

        total = _item_h(seq[0])
        for i in range(1, len(seq)):
            total += (pad_line if i >= first_hint_idx + 1 else pad_block) + _item_h(seq[i])
        y = (SCREEN_H - total) // 2
        screen.blit(title_surf, title_surf.get_rect(midtop=(cx, y)))
        y += title_surf.get_height()
        for i in range(1, len(seq)):
            y += (pad_line if i >= first_hint_idx + 1 else pad_block)
            it = seq[i]
            if isinstance(it, str):
                draw_rich_text(screen, cx, y, it, fonts, small,
                               (200, 210, 230), anchor="t")
            else:
                screen.blit(it, it.get_rect(midtop=(cx, y)))
            y += _item_h(it)

    def _build_replay_bar(self):
        """Pre-render the static parts of the replay timeline bar: per-row
        thickness (swelling where ghost branches overlap the timeline) baked
        into a dim surface, a bright surface (for the played portion), and a
        translucent glow. Bottom row = level start, top = end. Branch sim-
        time spans are mapped onto buffer-index fractions via the elapsed
        array (the buffer's elapsed is non-linear in index thanks to the
        post-rewind ramps, so a direct bisect is needed)."""
        snaps = self._rewind.snaps
        h = max(1, _REPLAY_BAR_BOT - _REPLAY_BAR_TOP)
        maxc = max(1, len(snaps) - 1)
        # Use precomputed snap times when present (a loaded _LazyFrames) so we
        # don't decode every snapshot on the main thread; live buffers decode
        # cheaply. Same for each branch's end time.
        elapsed = getattr(snaps, "times", None)
        if elapsed is None:
            elapsed = [s["scalars"][2] for s in snaps]
        counts = [0] * h
        for br in self._ghost_branches:
            a = bisect.bisect_left(elapsed, br["anchor_t"])
            end_t = br["end_t"] if "end_t" in br else br["frames"][-1]["scalars"][2]
            b = bisect.bisect_right(elapsed, end_t)
            f0 = a / maxc
            f1 = min(1.0, b / maxc)
            r_top = int(round((1.0 - f1) * (h - 1)))   # frac 1 → top row 0
            r_bot = int(round((1.0 - f0) * (h - 1)))   # frac 0 → bottom row
            for r in range(max(0, r_top), min(h, r_bot + 1)):
                counts[r] += 1
        widths = [min(_REPLAY_BAR_MAX_W,
                      _REPLAY_BAR_BASE_W + _REPLAY_BAR_PER_BRANCH * c)
                  for c in counts]
        cxl = _REPLAY_BAR_AREA_W // 2

        def _bar(color, alpha, pad):
            s = pygame.Surface((_REPLAY_BAR_AREA_W, h), pygame.SRCALPHA)
            for i, w in enumerate(widths):
                ww = w + pad
                pygame.draw.rect(s, (color[0], color[1], color[2], alpha),
                                 (cxl - ww // 2, i, ww, 1))
            return s

        self._bar_h = h
        self._bar_dim = _bar((46, 96, 140), 255, 0)
        self._bar_bright = _bar((125, 230, 255), 255, 0)
        # Two-pass glow for a soft halo.
        glow = _bar((70, 170, 240), 46, 8)
        glow.blit(_bar((110, 200, 255), 30, 16), (0, 0))
        self._bar_glow = glow

    @staticmethod
    def _float_text(screen, font, text, color, topleft=None, midtop=None):
        """Blit text with a 1px black drop-shadow so it stays legible floating
        over the busy playfield. Returns the foreground rect."""
        fg = font.render(text, False, color)
        r = fg.get_rect(midtop=midtop) if midtop else fg.get_rect(topleft=topleft)
        screen.blit(font.render(text, False, (0, 0, 0)), (r.x + 1, r.y + 1))
        screen.blit(fg, r)
        return r

    def _draw_replay_hud(self, screen):
        """Floating replay overlay (no HUD container): a vertical timeline bar
        on the right edge of the play area, plus the REPLAY label / progress /
        speed / save status (top-left) and control hints (bottom-left), each
        with a drop shadow for legibility over the playfield."""
        fonts = self.app.fonts
        small = fonts.get("small") or fonts.get(2)
        tiny = fonts.get("tiny") or fonts.get(1)
        maxc = max(1, len(self._rewind.snaps) - 1)
        frac = min(1.0, max(0.0, self._replay_cursor / maxc))
        h = self._bar_h
        topy = _REPLAY_BAR_TOP
        barx = _REPLAY_BAR_X
        bx = barx + _REPLAY_BAR_AREA_W // 2
        # Vertical timeline bar, floating over the playfield's right edge.
        screen.blit(self._bar_glow, (barx, topy))
        screen.blit(self._bar_dim, (barx, topy))
        play_row = int(round((1.0 - frac) * (h - 1)))
        if play_row < h:   # played portion = rows at/below the playhead
            screen.blit(self._bar_bright, (barx, topy + play_row),
                        area=pygame.Rect(0, play_row,
                                         _REPLAY_BAR_AREA_W, h - play_row))
        py = topy + play_row
        pygame.draw.rect(screen, WHITE, (bx - 16, py - 1, 32, 3))
        pygame.draw.circle(screen, WHITE, (bx, py), 4)
        pygame.draw.circle(screen, (140, 230, 255), (bx, py), 7, 1)
        # Top-left label stack.
        x = 8
        r = self._float_text(screen, small, "REPLAY", (140, 230, 255),
                             topleft=(x, 8))
        n = len(self._active_ghosts)
        sub_txt = f"{int(round(frac * 100))}%"
        if n:
            sub_txt += f"  {n} ghost{'s' if n != 1 else ''}"
        r = self._float_text(screen, tiny, sub_txt, (200, 220, 240),
                             topleft=(x, r.bottom + 2))
        spd = self._play_speed
        spd_txt = ("PAUSED" if (self.pause and abs(spd) < 0.05)
                   else f"{spd:.1f}x")
        spd_col = ((255, 225, 120) if (spd > 1.05 or spd < -0.05)
                   else (150, 235, 255))
        r = self._float_text(screen, small, spd_txt, spd_col,
                             topleft=(x, r.bottom + 3))
        # (The SAVING % itself is the modal _draw_mreplay_saving overlay; here
        # we only flash the SAVED / FAILED result after the modal clears.)
        if self._mreplay_msg_t > 0.0 and not self._mreplay_saving:
            ok = self._mreplay_save_result
            self._float_text(screen, small,
                             "SAVED" if ok else "SAVE FAILED",
                             (130, 240, 150) if ok else (255, 110, 110),
                             topleft=(x, r.bottom + 3))
        self._draw_replay_hints(screen, tiny)

    def _draw_mreplay_saving(self, screen):
        """Modal SAVING overlay — same centred title / % / bar as the loading
        screen, but over a DIMMED freeze-frame of the replay (not a black
        fill) since the playfield is still meaningful context. Amber palette
        distinguishes it from the cyan LOADING screen. Input is locked while
        this is up (see the modal guard in _replay_step)."""
        dim = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        dim.fill((0, 0, 0, 150))
        screen.blit(dim, (0, 0))
        # SINGLE amber bar (like the cyan LOAD screen). Save reports progress as
        # frames-written / total-frames across snapshots + ghost branches, so the
        # one bar fills at a steady rate rather than the old MAIN/GHOSTS halves.
        self._draw_replay_progress(
            screen, self._mreplay_save_disp, "SAVE REPLAY",
            "SAVING", "",
            title_col=(255, 215, 110), fill1=(255, 205, 90),
            fill2=(235, 150, 50), border=(90, 75, 35), single=True)

    def _draw_replay_hints(self, screen, font):
        """Control hints floating at the bottom-left of the play area."""
        lines = [
            "{dpad:UD} speed",
            "{btn_bomb} reverse",
            "{btn_fire} " + ("play" if self.pause else "pause"),
            "{btn_cancel} quit",
        ]
        if self._replay_can_save():
            lines.insert(3, "{btn_ability} save")
        lh = font.get_height() + 3
        y = SCREEN_H - len(lines) * lh - 4
        for ln in lines:
            draw_float_rich(screen, self.app.fonts, font, ln,
                            (190, 210, 235), topleft=(8, y))
            y += lh

    def _replay_can_save(self):
        return (not self._replay_view_only
                and not getattr(self.level, "is_test", False)
                and len(self._rewind.snaps) > 1)

    def _save_replay(self):
        """Persist this run's buffer + ghost branches to one file for the
        level (overwriting any prior one). The encode+pickle+zlib runs on a
        daemon thread so it doesn't freeze the replay — the buffer isn't
        mutated during replay (scrub only reads it), so it's safe to read."""
        if self._mreplay_saving or not self._replay_can_save():
            return
        self._mreplay_saving = True
        self._mreplay_save_result = None
        self._mreplay_save_pct = 0.0
        self._mreplay_save_disp = 0.0
        # Pass the compressed buffer THROUGH (don't list()-materialise it): the
        # whole point of _CompressedFrames is that its blobs are already the exact
        # on-disk per-frame format, so save streams them straight out — no decode,
        # no re-encode, no ~+57 MB spike, faster than the old path. Only fall back
        # to a list() for a non-compressed buffer (e.g. a loaded replay being
        # re-saved). Either is safe to read from the worker: the SAVING screen is
        # modal, so the buffer isn't mutated during the save.
        src = self._rewind.snaps
        snaps = src.snapshot_view() if isinstance(src, _CompressedFrames) else list(src)
        branches = list(self._ghost_branches)
        key = self.level.key
        assets = self.assets
        profile = self.app.profile_name

        def _on_progress(p):
            self._mreplay_save_pct = p

        def _worker():
            ok = False
            try:
                ok = save_mreplay(key, profile, snaps, branches, assets,
                                  progress=_on_progress)
            finally:
                self._mreplay_save_result = ok
                self._mreplay_saving = False

        try:
            threading.Thread(target=_worker, daemon=True).start()
        except Exception:
            self._mreplay_saving = False
            self._mreplay_save_result = False

    def _draw_cheat_summary(self, screen):
        """Centre-of-screen panel listing the cash + pickups the L2+R2
        cheat awarded. Visible for 3 s; alpha fades over the last 0.6 s."""
        fonts = self.app.fonts
        summary = self._cheat_summary
        credits = summary.get("credits", 0)
        counts = summary.get("counts", {})
        lines = [("INSTANT CLEAR", "big")]
        lines.append((f"+${credits}", "big"))
        labels = (
            ("main",   "Weapon"),
            ("side",   "Sidekick"),
            ("shield", "Shield"),
            ("bomb",   "Bomb"),
            ("money",  "Coin"),
        )
        for key, label in labels:
            n = counts.get(key, 0)
            if n > 0:
                lines.append((f"{label} x{n}", "small"))
        # Panel size sized to the rendered content.
        rendered = []
        for txt, sz in lines:
            font = fonts.get(sz) or fonts["small"]
            rendered.append((font.render(txt, False, WHITE), sz))
        line_h = max(s.get_height() for s, _ in rendered) + 4
        panel_w = max(s.get_width() for s, _ in rendered) + 48
        panel_h = line_h * len(rendered) + 28
        # Fade alpha over the last 0.6 s.
        fade = clamp(self._cheat_summary_t / 0.6, 0.0, 1.0)
        bg_alpha = int(210 * fade)
        text_alpha = int(255 * fade)
        panel = pygame.Surface((panel_w, panel_h), pygame.SRCALPHA)
        panel.fill((10, 14, 30, bg_alpha))
        pygame.draw.rect(panel, (120, 200, 255, text_alpha),
                         (0, 0, panel_w, panel_h), 2)
        y = 14
        for surf, _ in rendered:
            surf.set_alpha(text_alpha)
            panel.blit(surf, ((panel_w - surf.get_width()) // 2, y))
            y += line_h
        screen.blit(panel,
                    ((SCREEN_W - panel_w) // 2,
                     (SCREEN_H - panel_h) // 2))

    # ---- Test-mission gamepad handlers ------------------------------------
    _TEST_RSTICK_THRESH = 0.5
    # Right-stick / trigger axis indices are read from the module-level
    # JOY_* globals at call time (not snapshotted into class constants)
    # so they pick up the platform-specific values that set_button_scheme
    # installs at App init.

    def _test_set_action(self, msg):
        self._test_action_msg = msg
        self._test_action_t = 1.8

    def _handle_overlay_toggle(self, events):
        """R3 cycles the debug/perf overlay. In test mode all 4 modes are
        reachable (debug -> perf -> perf-detail -> off); in normal play
        mode 0 (test-only debug info) is skipped so the cycle is
        off -> perf -> perf-detail -> off."""
        for ev in events:
            if ev.type != pygame.JOYBUTTONDOWN or ev.button != JOY_R3:
                continue
            if self.is_test:
                self._test_overlay_mode = (self._test_overlay_mode + 1) % 4
            else:
                cycle = (3, 1, 2)  # off, perf summary, perf detail
                cur = self._test_overlay_mode
                idx = cycle.index(cur) if cur in cycle else 0
                self._test_overlay_mode = cycle[(idx + 1) % len(cycle)]
            return  # one toggle per frame even if R3 buffered multiple events

    def _handle_test_inputs(self, events, controls):
        """Test-mission-only input. Most bindings come straight from
        normal gameplay (fire / bomb / ability / shoulder fire-swap /
        START pause / SEL+L2+R2 cheat). The test layer only adds:
          * R3 action-banner echo (overlay cycle itself lives in
            _handle_overlay_toggle so it works outside test too).
          * Right-stick LEFT / RIGHT = previous / next wave-or-boss.
        Right-stick is disabled while the pause menu is open so menu
        navigation doesn't spill into wave/boss navigation."""
        # Diagnostic snapshot + R3 action-banner echo.
        for ev in events:
            if ev.type != pygame.JOYBUTTONDOWN:
                continue
            self._test_last_btn = ev.button
            self._test_last_btn_t = pygame.time.get_ticks()
            if ev.button == JOY_R3:
                modes = ("debug", "perf", "perf-detail", "off")
                self._test_set_action(
                    f"overlay -> {modes[self._test_overlay_mode]}")
        if self.app.joys:
            j = self.app.joys[0]
            try:
                n_axes = j.get_numaxes()
                self._test_diag_axes = tuple(
                    round(j.get_axis(i), 2) for i in range(min(8, n_axes)))
                self._test_diag_n_btn = j.get_numbuttons()
            except pygame.error:
                pass
        # Right-stick navigation. Skip while paused so menu d-pad nav
        # doesn't echo through here.
        if self.pause:
            self._test_rstick_prev = (0, 0)
            return
        rx = self._test_max_axis(JOY_AXIS_RSX, signed=True)
        qx = (1 if rx > self._TEST_RSTICK_THRESH
              else (-1 if rx < -self._TEST_RSTICK_THRESH else 0))
        pqx, _pqy = self._test_rstick_prev
        if qx != pqx and qx != 0:
            self._test_navigate(+1 if qx > 0 else -1)
        self._test_rstick_prev = (qx, 0)

    def _test_max_axis(self, axis, signed=False):
        """Largest axis reading across all joysticks for the given axis idx.
        signed=False returns max(value, ...) clamped to >= 0; signed=True
        keeps the sign so the caller can detect left/right or up/down."""
        best = 0.0
        for j in self.app.joys:
            try:
                if axis < j.get_numaxes():
                    v = j.get_axis(axis)
                    if signed:
                        if abs(v) > abs(best):
                            best = v
                    else:
                        if v > best:
                            best = v
            except pygame.error:
                pass
        return best

    def _test_current_progress(self):
        """Index of the most-recently-spawned wave or boss as a single
        0..15 integer:
          * 0..5  → wave 1..6
          * 6..15 → boss 1..10
        Returns -1 if nothing has fired yet."""
        if self._test_boss_idx >= 1:
            return self._test_boss_idx - 1 + self._test_waves_end
        return self.timeline_idx - 1

    def _test_navigate(self, delta):
        """Right-stick LEFT/RIGHT: jump to previous (-1) or next (+1)
        item. Crosses the wave-boss boundary in either direction.
        Clamps at the first wave; reaching past the last boss triggers
        the outro."""
        cur = self._test_current_progress()
        target = cur + delta
        if target < 0:
            target = 0  # clamp at first wave
        if target >= self._test_waves_end + 10:
            # past the last boss → trigger outro via the regular gate
            self._test_clear_field()
            self._test_boss_idx = 10
            self.timeline_idx = self._test_waves_end
            self._test_set_action("next -> finish")
            return
        self._test_apply_progress(target)

    def _test_apply_progress(self, target):
        """Clear the field and seed state so the next tick spawns the
        target item. target is 0..15 (waves 0..5, bosses 6..15)."""
        self._test_clear_field()
        waves_end = self._test_waves_end
        if target < waves_end:
            # Wave phase: rewind/forward the timeline to wave `target`.
            self.timeline_idx = target
            self.elapsed = self.level.timeline[target][0]
            # Reset boss state so the spawn machine doesn't fire a boss
            # while we're back in waves (the wave's own enemies prevent
            # it via the "enemies present" gate, but the wave fires only
            # next tick — defensive reset is cheap and avoids a 1-frame
            # window where the gate would let a boss through).
            self._test_boss_idx = 0
            self._test_set_action(f"wave {target + 1}/6")
        else:
            # Boss phase: park timeline past the waves so they don't
            # re-fire, set boss_idx so the state machine spawns the
            # target boss next tick.
            boss_n = target - waves_end  # 0..9
            self.timeline_idx = waves_end
            self.elapsed = self.level.timeline[waves_end - 1][0] + 0.001
            self._test_boss_idx = boss_n
            self._test_set_action(f"boss {boss_n + 1}/10")

    def _save_test_loadout(self):
        """Persist the current loadout to save.test_loadout so the next
        test-mode entry resumes from where the player left off. Clones
        via asdict round-trip so later in-game mutations (e.g. bomb
        pickup) don't leak into the saved copy."""
        try:
            self.app.save.test_loadout = Loadout(**asdict(self.player.loadout))
            self.app.save.save()
        except Exception as e:
            print(f"test loadout save failed: {e}")

    # ---- Test-mission pause menu ------------------------------------------
    # Rows: (label, kind). `kind` drives _test_menu_change.
    # The three mains are listed explicitly — all are always owned and the
    # player swaps live via L1/R1 (rail/ball/no-hold=vulcan). Engine is
    # the only support upgrade with gameplay effect (ship speed); side
    # weapons, ability, shield, and bombs are all disabled by the
    # universal-mechanics rules, so they're not editable here.
    _TEST_MENU_ROWS = (
        ("Rail",    "main_rail"),
        ("Ball",    "main_ball"),
        ("Vulcan",  "main_vulcan"),
        ("Engine",  "engine"),
    )

    def _test_menu_value(self, kind):
        """Render the current value of a menu row as a string."""
        lo = self.player.loadout
        if kind in ("main_rail", "main_ball", "main_vulcan"):
            return str(getattr(lo, kind, 0))
        if kind == "engine":
            return str(lo.engine)
        return ""

    def _test_menu_change(self, delta):
        """Apply ±delta to the value of the cursor row. Free — no cost
        deduction. Change takes effect immediately."""
        cur = self._test_menu_cursor
        if cur >= len(self._TEST_MENU_ROWS):
            return
        kind = self._TEST_MENU_ROWS[cur][1]
        lo = self.player.loadout
        p = self.player
        if kind in ("main_rail", "main_ball", "main_vulcan"):
            new = int(clamp(getattr(lo, kind, 1) + delta, 1, MAIN_WEAPON_MAX))
            setattr(lo, kind, new)
            # Reset both main cooldowns so the next held shot fires
            # immediately whichever main the player is on.
            p.cooldown_main = 0
            p.cooldown_rail = 0
        elif kind == "engine":
            lo.engine = int(clamp(lo.engine + delta, 1, MAX_LEVELS["engine"]))

    def _handle_test_menu_input(self, events, controls):
        """Pause-menu nav. Uses unified controls.up/down/left/right
        held-state and tracks per-direction edges so a single press
        moves exactly once. Covers d-pad, left stick, and keyboard
        arrows in one path."""
        n = len(self._TEST_MENU_ROWS)
        prev_up, prev_down, prev_left, prev_right = self._test_menu_dirs_prev
        if controls.up and not prev_up:
            self._test_menu_cursor = (self._test_menu_cursor - 1) % n
        elif controls.down and not prev_down:
            self._test_menu_cursor = (self._test_menu_cursor + 1) % n
        if controls.left and not prev_left:
            self._test_menu_change(-1)
        elif controls.right and not prev_right:
            self._test_menu_change(+1)
        self._test_menu_dirs_prev = (
            controls.up, controls.down, controls.left, controls.right)

    def _draw_test_menu(self, screen):
        """Centered pause-menu overlay for the test mission. Dim
        backdrop + framed panel + 8 rows + footer hint."""
        fonts = self.app.fonts
        dim = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        dim.fill((0, 0, 0, 190))
        screen.blit(dim, (0, 0))
        pw, ph = 320, 290
        px = (SCREEN_W - pw) // 2
        py = (SCREEN_H - ph) // 2
        panel = pygame.Surface((pw, ph), pygame.SRCALPHA)
        panel.fill((15, 18, 32, 240))
        pygame.draw.rect(panel, (120, 200, 255), (0, 0, pw, ph), 2)
        title_font = fonts.get("big") or fonts.get(3) or fonts["small"]
        title = title_font.render("TEST LOADOUT", False, (255, 220, 80))
        panel.blit(title, ((pw - title.get_width()) // 2, 10))
        row_h = 22
        y0 = 46
        small = fonts["small"]
        for i, (label, kind) in enumerate(self._TEST_MENU_ROWS):
            active = (i == self._test_menu_cursor)
            text_color = (255, 220, 80) if active else (200, 200, 210)
            label_color = (255, 220, 80) if active else (130, 140, 160)
            row_y = y0 + i * row_h
            label_surf = small.render(label, False, label_color)
            panel.blit(label_surf, (22, row_y))
            value = self._test_menu_value(kind)
            val_str = f"< {value} >" if active else value
            val_surf = small.render(val_str, False, text_color)
            panel.blit(val_surf, (pw - 22 - val_surf.get_width(), row_y))
        draw_rich_text(panel, pw // 2, ph - 22,
                       "START/{btn_fire} close   {btn_ability} abort",
                       self.app.fonts, small, (130, 140, 160), anchor="t")
        screen.blit(panel, (px, py))

    def _test_maybe_spawn_next_boss(self):
        """Test-only state machine: spawn the next boss once the wave
        phase has completed and there's no boss alive. The previous
        boss either died naturally or was wiped by skip-step / skip-
        chapter (which calls _test_clear_field). Skips while wave
        enemies are still around so the boss intro doesn't overlap
        with the last wave."""
        if self.timeline_idx < self._test_waves_end:
            return  # waves still firing
        if self._test_boss_idx >= 10:
            return  # all bosses dispatched
        if self.enemies:
            return  # current boss (or surviving wave enemy) still alive
        _spawn_test_boss(self, self._test_boss_idx)
        self._test_boss_idx += 1

    def _set_test_ribbon_for_sector(self, sector_idx):
        """Test-only: swap bg_ribbon to the given sector's theme so the
        visual-checkup parade pairs each boss with its native backdrop.
        Preserves scroll position across the swap so the transition
        doesn't snap the drift back to zero."""
        sector_idx = max(0, min(len(SECTOR_RIBBONS) - 1, sector_idx))
        theme = SECTOR_RIBBONS[sector_idx]
        prev_scroll = self.bg_ribbon.scroll if self.bg_ribbon is not None else 0.0
        self.bg_ribbon = _cached_ribbon(theme, width=PLAY_W + 2 * PLAY_MARGIN)
        self.bg_ribbon.speed = -abs(self.bg_ribbon.speed)
        self.bg_ribbon.scroll = prev_scroll % self.bg_ribbon.tile_h

    def _test_clear_field(self):
        """Sweep the play area — used by skip-chapter so the next chapter
        starts on a clean slate."""
        for e in self.enemies:
            e.alive = False
        for b in self.bullets:
            if not b.friendly:
                b.alive = False
        for ball in self.balls:
            ball.alive = False
        self.enemies = [e for e in self.enemies if e.alive]
        self.bullets = [b for b in self.bullets if b.alive]
        self.balls = []
        self.pickups = []
        self.particles = []
        self._part_cursor = 0
        self.sparks = []
        self.explosions = []
        self.lasers = []
        self.boss_intro_t = 0

    def _cinematic_zoom_state(self):
        """Return (in_cinematic, zoom_factor) for the bg composite.

        Zoom is 2x -> 1x during any takeoff phase (camera pulls away
        from the launch pad) and 1x -> 2x during any landing phase
        (camera pulls toward the arrival station). Takeoff uses the
        full 2.4 s curve in lockstep with the station's shrink, so a
        constant 2:1 ratio holds across the whole intro. Landing
        deliberately stops at p=0.5 — the station's grow-in clamps
        there via `entry = min(p/0.5, 1.0)` so the bg zoom matches the
        clamp, even though it cuts the second-half motion. The
        camera-keeps-zooming-after-the-station-arrives mismatch read
        as "station stopped while the parallax kept going" pre-v0.9.87.

        Covers three sources:
          * Regular level intro (self.intro_t > 0).
          * Regular level outro (self.outro_t > 0).
          * Test-parade per-station takeoff / landing sub-phases.
            (The inserted "play" sub-phase between them is excluded —
            the player has manual control there and the bg sits at 1x.)
        """
        if self.intro_t > 0:
            p = clamp(1.0 - max(0.0, self.intro_t) / 2.4, 0.0, 1.0)
            eased = 1.0 - (1.0 - p) ** 3
            return True, lerp(2.0, 1.0, eased)
        if self.outro_t > 0:
            # Drive zoom off elapsed-in-cinematic so the post-dock fade
            # phase holds the camera at its docked 2x rather than re-zooming.
            elapsed = OUTRO_TOTAL_DUR - self.outro_t
            p = clamp(elapsed / OUTRO_CINEMATIC_DUR, 0.0, 1.0)
            entry = min(p / 0.5, 1.0)
            eased = entry * entry
            return True, lerp(1.0, 2.0, eased)
        if (self.is_test
                and not getattr(self, "_test_parade_done", True)
                and self._test_parade_sub in ("takeoff", "landing")):
            sub_dur = self._test_parade_sub_duration
            p = clamp(1.0 - max(0.0, self._test_parade_t) / sub_dur, 0, 1)
            if self._test_parade_sub == "takeoff":
                eased = 1.0 - (1.0 - p) ** 3
                return True, lerp(2.0, 1.0, eased)
            entry = min(p / 0.5, 1.0)
            eased = entry * entry
            return True, lerp(1.0, 2.0, eased)
        return False, 1.0

    def _update_test_parade(self, dt):
        """Advance the per-station takeoff/play/land cinematic. Each
        station is shown twice — once as the launch pad, once as the
        destination — with a 4 s free-flight window between so the
        player can actually fly the ship during the visual checkup.
        After all 10 stations the regular timeline starts."""
        self._test_parade_t -= dt
        sub_duration = (self._test_parade_play_duration
                        if self._test_parade_sub == "play"
                        else self._test_parade_sub_duration)
        p = clamp(1.0 - max(0.0, self._test_parade_t) / sub_duration, 0, 1)
        if self._test_parade_sub == "takeoff":
            eased = 1.0 - (1.0 - p) ** 3
            self.player.y = lerp(PLAY_H - 30, PLAY_H - 60, eased)
            self.player.x = lerp(self.player.x, PLAY_W // 2, eased * 0.5)
            self.player.cinematic_scale = lerp(0.35, 1.0, eased)
            self.player.cinematic = True
            self.player.rect.center = (int(self.player.x), int(self.player.y))
        elif self._test_parade_sub == "landing":
            eased = p * p
            self.player.y = lerp(self._test_parade_landing_start_y, 90, eased)
            self.player.x = lerp(self.player.x, PLAY_W // 2, eased * 0.6)
            self.player.cinematic_scale = lerp(1.0, 0.25, eased)
            self.player.cinematic = True
            self.player.rect.center = (int(self.player.x), int(self.player.y))
        else:
            # "play" sub: hand control back to the player so they can fly
            # the ship around for 4 s between takeoff and landing. The
            # main _update path's player.update() does the real work —
            # we just clear the cinematic flag here.
            self.player.cinematic = False
            self.player.cinematic_scale = 1.0
        self.player.thrust += dt * 80
        self.player.tilt = 0.0
        if self._test_parade_sub in ("takeoff", "landing"):
            self.stars.update(dt * 1.6)
        else:
            self.stars.update(dt)
        if ENABLE_NEBULA:
            self.nebula.update(dt)
        self.bg_ribbon.update(dt)

        if self._test_parade_t <= 0:
            if self._test_parade_sub == "takeoff":
                # Hand control to the player for 4 s before the landing
                # cinematic takes the ship back.
                self._test_parade_sub = "play"
                self._test_parade_t = self._test_parade_play_duration
            elif self._test_parade_sub == "play":
                # Capture wherever the player flew the ship so landing
                # lerps from there into the dock instead of snapping.
                self._test_parade_sub = "landing"
                self._test_parade_t = self._test_parade_sub_duration
                self._test_parade_landing_start_y = float(self.player.y)
            else:
                # Done with this station; on to the next one's takeoff.
                self._test_parade_idx += 1
                if self._test_parade_idx >= 10:
                    self._test_parade_done = True
                    self.player.cinematic = False
                    self.player.cinematic_scale = 1.0
                    self.player.y = PLAY_H - 60
                    self.player.rect.center = (int(self.player.x),
                                               int(self.player.y))
                    # Kick the timeline forward so the first enemy wave
                    # fires immediately after the parade ends.
                    if self.level.timeline:
                        self.elapsed = self.level.timeline[0][0]
                else:
                    self._test_parade_sub = "takeoff"
                    self._test_parade_t = self._test_parade_sub_duration
                    self.player.y = float(PLAY_H - 30)
                    self.player.rect.center = (int(self.player.x),
                                               int(self.player.y))

    def _draw_test_parade_stations(self, surf):
        """Blit the current station for the active sub-phase, pinned to the
        ribbon's center-zoom (same _blit_pinned_station the regular
        intro/outro use): takeoff rests on the screen bottom at the launch
        key-frame and recedes as the camera pulls back, landing tops out at
        y=20 at the dock key-frame and grows up into frame. The "play"
        sub-phase has no station — it's the inserted free-flight gap."""
        idx = self._test_parade_idx
        _, zoom = self._cinematic_zoom_state()
        if self._test_parade_sub == "takeoff":
            img = self._test_stations_start.get(idx)
            if img is not None:
                self._blit_pinned_station(surf, img, PLAY_W * 0.5,
                                          PLAY_H, zoom)
        elif self._test_parade_sub == "landing":
            img = self._test_stations_end.get(idx)
            if img is not None:
                self._blit_pinned_station(surf, img, PLAY_W * 0.5,
                                          20 + img.get_height(), zoom)
        # "play" sub draws no station; player is mid-flight.
        line1 = self.app.fonts["small"].render(
            f"STATION {idx + 1}/10 - {SECTOR_NAMES[idx].upper()}",
            False, WHITE)
        line2 = self.app.fonts["tiny"].render(
            f"({self._test_parade_sub})", False, (160, 200, 240))
        surf.blit(line1, line1.get_rect(center=(PLAY_W // 2, PLAY_H - 56)))
        surf.blit(line2, line2.get_rect(center=(PLAY_W // 2, PLAY_H - 36)))

    # Panel margins — top-left corner placement, with enough padding to
    # keep the rendered glyphs from kissing the playfield edges.
    _PANEL_X = 4
    _PANEL_Y = 4
    _PANEL_PAD = 5

    def _draw_test_banner(self, surf):
        """Top-left overlay. R3 cycles between four modes:
          0 = debug banner (loadout + controls + raw input diagnostics) —
              only available in the test mission
          1 = performance summary (fps + frame ms + live object counts)
          2 = performance detail (per-stage ms breakdown of every update +
              draw phase, with peak spikes — two-column panel)
          3 = off (nothing rendered)"""
        mode = self._test_overlay_mode
        if mode == 3:
            return
        if mode == 2:
            self._draw_perf_detail_panel(surf)
            return
        if mode == 0 and not self.is_test:
            return  # debug banner needs test-mode state to render
        font = self.app.fonts["small"]   # 2x of the old tiny font
        if mode == 1:
            lines = self._test_perf_lines()
        else:
            lines = self._test_debug_lines()
        if not lines:
            return
        # Render then clamp height: never draw past the bottom of the
        # playfield. If we'd overflow we silently drop tail lines.
        line_h = font.get_height() + 2
        pad = self._PANEL_PAD
        max_lines = max(1, (PLAY_H - self._PANEL_Y * 2) // line_h - 1)
        if len(lines) > max_lines:
            lines = lines[:max_lines]
        rendered = [font.render(t, False, c) for t, c in lines]
        max_w = max(r.get_width() for r in rendered)
        bg_w = min(PLAY_W - self._PANEL_X * 2, max_w + pad * 2)
        bg_h = line_h * len(rendered) + pad * 2
        bg = pygame.Surface((bg_w, bg_h), pygame.SRCALPHA)
        bg.fill((0, 0, 0, 180))
        surf.blit(bg, (self._PANEL_X, self._PANEL_Y))
        y = self._PANEL_Y + pad
        for r in rendered:
            surf.blit(r, (self._PANEL_X + pad, y))
            y += line_h

    # Sections we instrument inside _update and _draw, grouped for the
    # detail panel. Keep the order stable so the panel doesn't reshuffle
    # frame to frame.
    _PERF_GROUPS = (
        ("UPDATE", (
            ("upd.spawn",        "spawn"),
            ("upd.player",       "player"),
            ("upd.bullets",      "bullets"),
            ("upd.enemies",      "enemies"),
            ("upd.lasers",       "lasers"),
            ("upd.pickups",      "pickups"),
            ("upd.particles",    "particles"),
            ("col.bullet_enemy", "col b>e"),
            ("col.bullet_player","col b>p"),
            ("col.enemy_player", "col e>p"),
            ("col.pickup",       "col pick"),
            ("upd.cleanup",      "cleanup"),
        )),
        ("DRAW", (
            ("draw.bg_ribbon",   "bg ribbon"),
            ("draw.nebula",      "nebula"),
            ("draw.stars",       "stars"),
            ("draw.pickups",     "pickups"),
            ("draw.bullets",     "bullets"),
            ("draw.lasers",      "lasers"),
            ("draw.enemies",     "enemies"),
            ("draw.particles",   "particles"),
            ("draw.player",      "player"),
            ("draw.overlay",     "perf hud"),
            ("draw.blit_screen", "screen blit"),
            ("draw.hud",         "game hud"),
        )),
        ("FRAME", (
            ("app.tick",         "tick (idle)"),
            ("app.events",       "events"),
            ("app.state",        "state.run"),
            ("app.flip",         "display flip"),
            ("frame",            "TOTAL"),
        )),
    )

    def _draw_perf_detail_panel(self, surf):
        """Per-stage ms breakdown of every instrumented section. Laid out
        in TWO columns so the full update + draw + frame trees fit inside
        the 480x480 playfield at the 2x font size (single column would
        overflow vertically). Highlights anything eating >10% of the frame
        budget so the bottleneck pops visually."""
        perf = self.app.perf
        font = self.app.fonts["small"]   # 2x of the old tiny font
        line_h = font.get_height() + 2
        fps = self.app.clock.get_fps()
        budget_ms = 1000.0 / FPS
        total_ms = perf.ms("frame")

        if fps < 30: fps_col = RED
        elif fps < 50: fps_col = ORANGE
        else: fps_col = (120, 220, 140)

        def fmt(key, label):
            ms_v = perf.ms(key)
            if ms_v > budget_ms * 0.20:
                col = RED
            elif ms_v > budget_ms * 0.10:
                col = ORANGE
            elif ms_v > 0.05:
                col = WHITE
            else:
                col = DIM
            # Compact format — label + smoothed ms. The BitmapFont is
            # monospace so columns line up naturally. Per-row peak was
            # dropped so two columns fit inside the 480-px playfield at
            # the 2x font; the frame-wide peak is shown in the header.
            return (f"{label:<12}{ms_v:5.2f}", col)

        def section(group_name, entries):
            lines = []
            total = sum(perf.ms(k) for k, _ in entries if k != "frame")
            if group_name == "FRAME":
                lines.append(("-- FRAME --", YELLOW))
            else:
                lines.append((f"-- {group_name} {total:5.2f} --", YELLOW))
            for key, label in entries:
                lines.append(fmt(key, label))
            return lines

        # Header lines apply to the left column.
        header = [
            (f"PERF fps {fps:5.1f}", fps_col),
            (f"bud {budget_ms:4.1f}  tot {total_ms:5.2f}", WHITE),
            (f"frame peak {perf.peak_ms('frame'):5.2f}", DIM),
            (f"b{len(self.bullets):>3d} e{len(self.enemies):>3d} "
             f"p{len(self.particles):>3d}", DIM),
        ]

        upd_group  = self._PERF_GROUPS[0]
        drw_group  = self._PERF_GROUPS[1]
        frm_group  = self._PERF_GROUPS[2]

        col1 = header + section(*upd_group)
        col2 = section(*drw_group) + section(*frm_group)
        col2.append(("R3 cycle", DIM))

        pad = self._PANEL_PAD
        # Clamp each column's line count so we never run past the playfield
        # bottom, no matter how many sections accumulate later.
        max_lines = max(1, (PLAY_H - self._PANEL_Y * 2 - pad * 2) // line_h)
        col1 = col1[:max_lines]
        col2 = col2[:max_lines]

        rendered1 = [font.render(t, False, c) for t, c in col1]
        rendered2 = [font.render(t, False, c) for t, c in col2]
        col1_w = max(r.get_width() for r in rendered1)
        col2_w = max(r.get_width() for r in rendered2)
        gap = 12
        bg_w = min(PLAY_W - self._PANEL_X * 2,
                   col1_w + gap + col2_w + pad * 2)
        bg_h = line_h * max(len(rendered1), len(rendered2)) + pad * 2
        bg = pygame.Surface((bg_w, bg_h), pygame.SRCALPHA)
        bg.fill((0, 0, 0, 180))
        surf.blit(bg, (self._PANEL_X, self._PANEL_Y))

        x1 = self._PANEL_X + pad
        x2 = x1 + col1_w + gap
        # Drop the second column entirely if it would land off-screen — the
        # left column still gives the most-watched numbers.
        draw_col2 = x2 + col2_w <= self._PANEL_X + bg_w
        y = self._PANEL_Y + pad
        for r in rendered1:
            surf.blit(r, (x1, y))
            y += line_h
        if draw_col2:
            y = self._PANEL_Y + pad
            for r in rendered2:
                surf.blit(r, (x2, y))
                y += line_h

    def _test_debug_lines(self):
        """Loadout, control legend, raw input diagnostics. Lines are kept
        short enough to fit in the panel at the scale-2 font (~25 chars per
        line for the 480-px playfield)."""
        mt = self.player.loadout.main_type
        mlvl = getattr(self.player.loadout, f"main_{mt}", 0)
        st = self.player.loadout.side_type
        slvl = (getattr(self.player.loadout, f"side_{st}", 0)
                if st != "none" else 0)
        ab = self.player.loadout.ability
        lines = [
            ("TEST MODE", YELLOW),
            (f"main: {mt} L{mlvl}", WHITE),
            (f"side: {st}" + (f" L{slvl}" if st != "none" else ""), WHITE),
            (f"ability: {ab}", WHITE),
            ("START loadout menu", DIM),
            ("RStick L/R prev/next", DIM),
            ("R3 overlay cycle", DIM),
        ]
        if self._test_action_t > 0:
            lines.append(("> " + self._test_action_msg, CYAN))
        if self._test_diag_axes:
            # Split axes into rows of 4 so each line stays narrow.
            ax = self._test_diag_axes
            for i in range(0, len(ax), 4):
                chunk = ax[i:i + 4]
                lines.append(
                    (f"ax{i}: " + " ".join(f"{v:+.2f}" for v in chunk), DIM))
        if self._test_diag_n_btn:
            lines.append((f"#btns: {self._test_diag_n_btn}", DIM))
        if (self._test_last_btn is not None
                and pygame.time.get_ticks() - self._test_last_btn_t < 3000):
            lines.append((f"last btn idx: {self._test_last_btn}", ORANGE))
        return lines

    def _test_perf_lines(self):
        """Live frame stats + object counts so you can see whether a wave
        or a boss tanks performance. Also summarizes the top-level update/
        draw/flip split from the PerfMonitor — for the per-stage breakdown
        cycle R3 once more to the perf-detail mode."""
        clock = self.app.clock
        perf = self.app.perf
        fps = clock.get_fps()
        ms = (1000.0 / fps) if fps > 0.5 else 0.0
        # Colour FPS red if it falls under 30, yellow under 50, green
        # otherwise — quick visual cue while playing.
        if fps < 30: fps_col = RED
        elif fps < 50: fps_col = ORANGE
        else: fps_col = (120, 220, 140)
        # Sum each phase's instrumented children for the headline numbers.
        upd_keys = ("upd.spawn", "upd.player", "upd.bullets", "upd.enemies",
                    "upd.lasers", "upd.pickups", "upd.particles",
                    "col.bullet_enemy", "col.bullet_player",
                    "col.enemy_player", "col.pickup", "upd.cleanup")
        drw_keys = ("draw.bg_ribbon", "draw.nebula", "draw.stars",
                    "draw.pickups", "draw.bullets", "draw.lasers",
                    "draw.enemies", "draw.particles", "draw.player",
                    "draw.overlay", "draw.blit_screen", "draw.hud")
        upd_ms = sum(perf.ms(k) for k in upd_keys)
        drw_ms = sum(perf.ms(k) for k in drw_keys)
        flip_ms = perf.ms("app.flip")
        tick_ms = perf.ms("app.tick")
        frame_ms = perf.ms("frame")
        return [
            ("PERF", YELLOW),
            (f"fps: {fps:5.1f}   {ms:4.1f} ms", fps_col),
            (f"frame  {frame_ms:5.2f} ms", WHITE),
            (f"update {upd_ms:5.2f}", WHITE),
            (f"draw   {drw_ms:5.2f}", WHITE),
            (f"flip   {flip_ms:5.2f}", WHITE),
            (f"idle   {tick_ms:5.2f}", DIM),
            (f"bullets  {len(self.bullets):>4d}", WHITE),
            (f"enemies  {len(self.enemies):>4d}", WHITE),
            (f"particles{len(self.particles):>4d}", WHITE),
            (f"sparks   {len(self.sparks):>4d}", WHITE),
            (f"explosns {len(self.explosions):>4d}", WHITE),
            (f"pickups  {len(self.pickups):>4d}", WHITE),
            (f"lasers   {len(self.lasers):>4d}", WHITE),
            ("R3: cycle overlay", DIM),
        ]


# =============================================================================
# MISSION MAP SCREEN
# =============================================================================

class MapScreen:
    """100 levels across 10 sectors. L1/L2/R1/R2 (or Q/E) page between sectors; D-pad picks within."""

    def __init__(self, app):
        self.app = app
        self.stars = ParallaxStars(SCREEN_W, SCREEN_H, counts=(70, 50, 30))
        self.t = 0
        self.outcome = None
        n = self._next_to_play_n()
        self.sector_idx = (n - 1) // 10
        self.cursor = f"L{n:03d}"
        # Edge state for L2/R2 trigger-axis sector pagination — Steam
        # Deck and other PC pads expose the triggers as axes, not
        # buttons, so JOYBUTTONDOWN never fires for them. We sample
        # controls.l2_held / r2_held each frame and act on the rising
        # edge (held this frame, not last frame).
        self._prev_l2_held = False
        self._prev_r2_held = False
        self.bg_ribbon = self._build_map_ribbon(self.sector_idx)
        self._last_sector = self.sector_idx
        self._flash_msg = None
        self._flash_t = 0.0
        # Cached static graph layer (sector tabs + edges-without-chevron +
        # nodes-without-cursor) for the current sector. Keyed off
        # sector_idx because that's the only thing that changes between
        # frames on this screen — completed/unlocked don't mutate until
        # we leave the map and come back (a fresh MapScreen instance
        # gets a fresh cache). Cursor moves redraw cheaply over the top.
        # Saves ~3 ms/frame on RG by skipping ~9 edges + 10 multi-circle
        # nodes + 10 sector tab circles per frame.
        self._graph_cache_surf = None
        self._graph_cache_sector = None

    # Sentinel "transparent" colour for the graph cache. Picked off the
    # palette of every map element (tabs, edges, nodes, captions) so a
    # colorkeyed opaque blit can pretend it's a per-pixel alpha mask —
    # ~5× faster than SRCALPHA on RG's mali blit path.
    _GRAPH_CACHE_KEY = (255, 0, 255)

    # Built graph-cache surfaces SHARED across MapScreen instances, keyed by a
    # signature of everything that affects the render (sector + per-node
    # progress/best/replay state). Building it costs ~15 ms (string membership
    # in save.completed, draws, filesystem replay-checks) and the surface upload
    # adds more — and it ran fresh on EVERY new MapScreen, landing on the screen-
    # transition capture frame (>16 ms). Sharing it means cycling map<->play<->
    # shop within a sector at unchanged progress is a cache HIT (skip build +
    # reuse the warm GPU texture, since gpu.tex_for keys by surface identity).
    # Bounded LRU. The surface is immutable after build (drawn FROM, never onto).
    _GRAPH_SURF_CACHE = {}
    _GRAPH_SURF_CACHE_CAP = 12

    def _graph_cache_sig(self):
        """Cheap-ish signature of the save/sector state the graph cache renders.
        Two MapScreens with the same signature produce a pixel-identical graph,
        so they can share one surface."""
        save = self.app.save
        keys = self._sector_keys()
        return (self.sector_idx, self.app.profile_name, self._max_sector(),
                frozenset(save.completed), frozenset(save.unlocked),
                tuple((self._level_best_stolen(k),
                       has_saved_replay(k, self.app.profile_name))
                      for k in keys))

    def _level_best_stolen(self, key):
        """Best (minimum) recorded stolen-time for a level, or None if it
        has never been cleared. Same source the LEVEL-panel chart reads."""
        stats = (getattr(self.app.save, "level_stats", None) or {}).get(key, {})
        times = [float(t) for t in (stats.get("stolen_times") or [])
                 if t is not None]
        return min(times) if times else None

    def _node_is_perfect(self, key):
        """A completed level with a zero best stolen-time (cleared without ever
        rewinding) — gets the gold disc + glitter treatment."""
        if key not in self.app.save.completed:
            return False
        bt = self._level_best_stolen(key)
        return bt is not None and bt < 0.005

    def _build_graph_cache(self):
        """Render the static parts of the map screen onto a SCREEN-sized
        Surface: 10 sector tabs, all edges (without travelling
        chevrons), all nodes (without cursor ring). Per-frame `_draw`
        blits this once + overlays the moving bits.

        Cached by sector_idx — when the player pages L1/R1 we rebuild.
        completed / unlocked sets can't change within a single MapScreen
        instance (returning from a win constructs a fresh MapScreen).

        Uses convert() + colorkey instead of SRCALPHA so the per-frame
        blit is the fast opaque-with-skip path. SRCALPHA was 3 ms slower
        on RG than the original direct-draw it replaced — defeated the
        whole point of caching.

        Shared across instances via _GRAPH_SURF_CACHE (keyed by
        _graph_cache_sig) so a re-entered map with unchanged progress skips the
        whole build + reuses the warm texture."""
        sig = self._graph_cache_sig()
        cached = MapScreen._GRAPH_SURF_CACHE.get(sig)
        if cached is not None:
            del MapScreen._GRAPH_SURF_CACHE[sig]          # re-insert as MRU
            MapScreen._GRAPH_SURF_CACHE[sig] = cached
            self._graph_cache_surf = cached
            self._graph_cache_sector = self.sector_idx
            return
        save = self.app.save
        fonts = self.app.fonts
        sector_palette = STATION_PALETTES[self.sector_idx]
        base, accent, dark = sector_palette
        max_sector = self._max_sector()

        cache = pygame.Surface((SCREEN_W, SCREEN_H)).convert()
        cache.fill(self._GRAPH_CACHE_KEY)
        cache.set_colorkey(self._GRAPH_CACHE_KEY)

        # Sector tabs.
        tabs_y = 14
        spacing = 28
        tabs_total = (10 - 1) * spacing
        tabs_x0 = (HUD_X - tabs_total) // 2
        for i in range(10):
            x = tabs_x0 + i * spacing
            sector_done = all(
                f"L{(i * 10) + slot + 1:03d}" in save.completed
                for slot in range(10))
            if i == self.sector_idx:
                pygame.draw.circle(cache, CYAN, (x, tabs_y), 6)
                pygame.draw.circle(cache, WHITE, (x, tabs_y), 7, 1)
            elif sector_done:
                pygame.draw.circle(cache, GREEN, (x, tabs_y), 5)
            elif i <= max_sector:
                pygame.draw.circle(cache, accent, (x, tabs_y), 4, 1)
            else:
                pygame.draw.circle(cache, (60, 60, 80), (x, tabs_y), 3)

        keys = self._sector_keys()
        # Edges — static lines only, chevrons drawn per-frame.
        for i in range(len(keys) - 1):
            a_pos = MAP_GRAPH[keys[i]].pos
            b_pos = MAP_GRAPH[keys[i + 1]].pos
            a_done = keys[i] in save.completed
            b_avail = keys[i + 1] in save.unlocked
            _draw_map_edge(cache, a_pos, b_pos, a_done, b_avail,
                           0.0, accent, with_chevron=False)
        # Nodes — cursor flourish drawn per-frame.
        for k in keys:
            node = MAP_GRAPH[k]
            is_boss = self.app.levels[k].has_boss
            done = k in save.completed
            avail = k in save.unlocked
            _draw_map_node(cache, node.pos[0], node.pos[1], sector_palette,
                           is_boss=is_boss, done=done, avail=avail,
                           cursor=False, t=0.0,
                           label_n=int(k[1:]), fonts=fonts,
                           best_time=self._level_best_stolen(k),
                           has_replay=has_saved_replay(k, self.app.profile_name))
        self._graph_cache_surf = cache
        self._graph_cache_sector = self.sector_idx
        MapScreen._GRAPH_SURF_CACHE[sig] = cache
        if len(MapScreen._GRAPH_SURF_CACHE) > MapScreen._GRAPH_SURF_CACHE_CAP:
            del MapScreen._GRAPH_SURF_CACHE[next(iter(MapScreen._GRAPH_SURF_CACHE))]

    def _build_map_ribbon(self, sector_idx):
        """Build the map-screen backdrop: native-aspect tiled at SCREEN_W,
        mirror-flipped so the wrap is seamless, and given a steady downward
        drift of 1 px every 2 frames (30 px/s at 60 fps) — calm enough not
        to compete with menu focus, fast enough to read as motion."""
        ribbon = _cached_ribbon(SECTOR_RIBBONS[sector_idx], width=SCREEN_W)
        ribbon.speed = -30.0
        return ribbon

    def _next_to_play_n(self):
        """Lowest unlocked level number that hasn't been completed yet.
        Falls back to the lowest unlocked overall if everything's cleared.
        Delegates to the module-level `next_play_level` so the menu
        music's variant selection (which also calls it) stays in lock-
        step with where the cursor lands on map entry."""
        return next_play_level(self.app.save)

    def _max_unlocked_n(self):
        nums = []
        for k in self.app.save.unlocked:
            if k.startswith("L") and k[1:].isdigit():
                nums.append(int(k[1:]))
        return max(nums) if nums else 1

    def _max_sector(self):
        return (self._max_unlocked_n() - 1) // 10

    def _sector_keys(self):
        start_n = self.sector_idx * 10 + 1
        return [f"L{n:03d}" for n in range(start_n, start_n + 10)]

    def _default_cursor(self):
        """Lowest unlocked-and-not-completed level in the current sector.
        Falls back to the lowest unlocked level here, or the sector's
        first slot if nothing's unlocked yet."""
        save = self.app.save
        keys = self._sector_keys()
        for k in keys:
            if k in save.unlocked and k not in save.completed:
                return k
        for k in keys:
            if k in save.unlocked:
                return k
        return keys[0]

    def run(self, events, controls):
        dt = 1.0 / FPS
        self.t += dt
        self.stars.update(dt)
        self.bg_ribbon.update(dt)
        menu = MenuInput(controls)

        # Holding either L2 or R2 unlocks free sector navigation — this is
        # the hidden "browse bot runs in areas you haven't unlocked yet"
        # affordance. Without the modifier the normal max-sector cap applies.
        max_sec = 9 if (controls.l2_held or controls.r2_held) else self._max_sector()

        # Sector pagination
        sector_changed = False
        for ev in events:
            if ev.type == pygame.JOYBUTTONDOWN:
                # Both shoulder pairs page sectors — L1/L2 = prev, R1/R2
                # = next. On the device the triggers are exposed as
                # digital buttons (idx 10/11), so JOYBUTTONDOWN fires
                # for them. PC pads (Steam Deck etc.) report the
                # triggers as axes — the rising-edge branch below
                # handles those.
                if ev.button in (JOY_L1, JOY_L2) and self.sector_idx > 0:
                    self.sector_idx -= 1; sector_changed = True
                if ev.button in (JOY_R1, JOY_R2) and self.sector_idx < max_sec:
                    self.sector_idx += 1; sector_changed = True
            if ev.type == pygame.KEYDOWN:
                # Keyboard sector paging on [ and ] — Q/E are now the menu
                # North/West actions, so they can't page sectors any more.
                if ev.key == pygame.K_LEFTBRACKET and self.sector_idx > 0:
                    self.sector_idx -= 1; sector_changed = True
                if ev.key == pygame.K_RIGHTBRACKET and self.sector_idx < max_sec:
                    self.sector_idx += 1; sector_changed = True
        # Axis-trigger rising edge — picks up Steam Deck / Xbox L2/R2
        # which never fire JOYBUTTONDOWN. controls.l2_held is set when
        # the analog trigger crosses 0.3, so we just diff against last
        # frame's value to find the moment of press.
        if controls.l2_held and not self._prev_l2_held and self.sector_idx > 0:
            self.sector_idx -= 1; sector_changed = True
        if controls.r2_held and not self._prev_r2_held and self.sector_idx < max_sec:
            self.sector_idx += 1; sector_changed = True
        self._prev_l2_held = controls.l2_held
        self._prev_r2_held = controls.r2_held
        if sector_changed:
            self.cursor = self._default_cursor()
            self.app.sounds["menu"].play()
            self.bg_ribbon = self._build_map_ribbon(self.sector_idx)

        # Dev shortcut: unlock every level. Keyboard Ctrl+U, joystick SELECT+X.
        for ev in events:
            if (ev.type == pygame.KEYDOWN and ev.key == pygame.K_u
                    and (pygame.key.get_mods() & pygame.KMOD_CTRL)):
                self._unlock_all()
            if (ev.type == pygame.JOYBUTTONDOWN and ev.button == JOY_X
                    and controls.select):
                self._unlock_all()

        # D-pad within sector — but while L2 or R2 is held, the d-pad belongs
        # to the replay gesture (so the cursor stays put while you trigger
        # the shortcut for the currently-cursored level).
        if not (controls.l2_held or controls.r2_held):
            self._handle_nav(menu)

        if self._flash_t > 0:
            self._flash_t -= dt

        # GO = play the cursored level (forward in the go/back loop:
        # title -> map -> play -> shop -> map -> play ...). Level details
        # for the cursored node are shown live in the side panel, so there
        # is no details overlay / West binding any more.
        if menu.go:
            if self.cursor in self.app.save.unlocked:
                self.app.save.current_node = self.cursor
                self.app.save.save()
                level = self.app.levels[self.cursor]
                self.outcome = ("play", level)
            else:
                self.app.sounds["deny"].play()

        # WEST = watch the cursored level's saved mission replay (shown in
        # the LEVEL panel's REPLAY row). Deny if there's no recording.
        if menu.west:
            if has_saved_replay(self.cursor, self.app.profile_name):
                self.app.sounds["menu"].play()
                self.outcome = ("play_replay", self.cursor)
            else:
                self.app.sounds["deny"].play()

        # BACK (East) = shop. The back chain is map -> shop -> title, so
        # backing out of the map lands in the shop (back again -> title).
        # Mouse RMB is the "safe back" everywhere, so it backs here too.
        # Esc (START) also backs here as a convenience (it's otherwise idle
        # on the map).
        if menu.back or menu.start or controls.rmb_pressed:
            self.app.sounds["menu"].play()
            self.outcome = ("shop", None)

        # Hidden bot-replay shortcut: same gesture as on the title screen,
        # but plays back just the currently-cursored level. If the replay
        # file doesn't have a block for this level (because the bot didn't
        # reach it), say so on screen rather than silently no-op'ing.
        prof = _gesture_to_profile(controls)
        if prof is not None:
            path = _find_replay_path(prof)
            if path is None:
                self._flash_msg = f"NO REPLAY: {prof}"
                self._flash_t = 1.6
                self.app.sounds["deny"].play()
            elif not _replay_has_level(path, self.cursor):
                self._flash_msg = f"{prof}: didn't reach {self.cursor}"
                self._flash_t = 1.8
                self.app.sounds["deny"].play()
            else:
                self.outcome = ("replay_level", (prof, self.cursor))

        self._draw(controls)
        return self.outcome

    def _unlock_all(self):
        """Dev affordance: unlock + complete all 100 levels for testing.
        Marking everything completed (not just unlocked) puts
        `areas_completed(save) == 10`, which means the menu music
        treats the game as fully cleared — the 6th layer (harmonica
        counter on v1/v4) plays on the title screen and on sector 10
        in the map screen, so the cheat lets the dev hear the full
        progression instantly."""
        all_keys = [f"L{n:03d}" for n in range(1, 101)]
        before_unlocked = len(self.app.save.unlocked)
        before_completed = len(self.app.save.completed)
        self.app.save.unlocked = list(all_keys)
        self.app.save.completed = list(all_keys)
        self.app.save.save()
        self._flash_msg = (
            f"DEV: UNLOCKED + COMPLETED ALL  "
            f"(+{100 - before_unlocked} unlock, +{100 - before_completed} done)"
        )
        self._flash_t = 2.5
        self.app.sounds["confirm"].play()

    def _handle_nav(self, menu):
        # `menu` (MenuInput) folds keyboard WASD/arrows, d-pad and
        # stick-as-hat into one set of edges.
        keys = self._sector_keys()
        if self.cursor not in keys:
            self.cursor = keys[0]
        idx = keys.index(self.cursor)

        # LEFT/RIGHT traverse the sector linearly (1 -> 2 -> ... -> boss).
        # Because the rows are laid out left-to-right, RIGHT on the last
        # level of a row lands on the first level of the next row, and LEFT
        # on the first level of a row wraps back to the last of the previous
        # row — exactly the "flow off the end of a row" feel asked for.
        if menu.left or menu.right:
            nidx = idx + (1 if menu.right else -1)
            if 0 <= nidx < len(keys):
                self.cursor = keys[nidx]
                self.app.sounds["menu"].play()
            return

        # UP/DOWN hop between rows: nearest node in the vertical direction,
        # breaking ties toward the same column.
        if menu.up or menu.down:
            cur_pos = MAP_GRAPH[self.cursor].pos
            dy = -1 if menu.up else 1
            best, best_score = None, 1e9
            for k in keys:
                if k == self.cursor:
                    continue
                p = MAP_GRAPH[k].pos
                vy = p[1] - cur_pos[1]
                if vy * dy <= 0:
                    continue
                score = abs(vy) * 3 + abs(p[0] - cur_pos[0])
                if score < best_score:
                    best_score = score
                    best = k
            if best:
                self.cursor = best
                self.app.sounds["menu"].play()

    def _draw(self, controls):
        if getattr(self.app, "gpu", None) is not None:
            self.app.gpu_native = True
            self._draw_gpu(controls)
            return
        screen = self.app.screen
        save = self.app.save
        fonts = self.app.fonts

        # Full-screen sector-themed ribbon under the persistent parallax
        # stars. Ribbon is constructed at SCREEN_W and slowly drifts so
        # the map reads as a quiet menu rather than a static placard.
        screen.fill(BLACK)
        self.bg_ribbon.draw(screen)
        self.stars.draw(screen)

        sector_palette = STATION_PALETTES[self.sector_idx]
        base, accent, dark = sector_palette
        max_sector = self._max_sector()
        progress_n = sum(1 for k in save.completed if k.startswith("L"))

        # ---- Top bar: sector tabs + static graph layer ----
        # Sector tabs, edges (lines only) and nodes (cursor-less) are
        # all baked into _graph_cache_surf. Rebuild on first frame +
        # whenever the sector pages. The per-frame overlay below draws
        # the cursor ring + edge chevrons on top.
        if (self._graph_cache_surf is None
                or self._graph_cache_sector != self.sector_idx):
            self._build_graph_cache()
        screen.blit(self._graph_cache_surf, (0, 0))

        # Editable text bits go through the layout system so the user can
        # tweak position/font/color/text via the layout editor. The dynamic
        # state (sector name, progress %) is interpolated into the spec's
        # text templates via map_vars.
        map_vars = {
            "sector_name": SECTOR_NAMES[self.sector_idx],
            "sector_n": f"{self.sector_idx + 1:02d}",
            "progress": f"{progress_n:02d}",
            "has_prev": self.sector_idx > 0,
            "has_next": self.sector_idx < max_sector,
            "all_clear": progress_n >= 100,
            **button_label_vars(),
        }
        for eid in ("nav_hint_l", "nav_hint_r"):
            el = get_element("map", eid, **map_vars)
            if el is not None:
                _layout_draw_item(screen, el, fonts, self.app.assets, map_vars)

        # ---- Sector header banner ----
        # Panel chrome stays in code; the text inside is element-driven.
        _panel(screen, 60, 32, HUD_X - 120, 50)
        for eid in ("sector_title",):
            el = get_element("map", eid, **map_vars)
            if el is not None:
                _layout_draw_item(screen, el, fonts, self.app.assets, map_vars)

        # ---- Per-frame graph overlay ----
        # Static layer (tabs + edges + nodes minus cursor flourishes) is
        # already on `screen` from the cache blit above. Now draw only
        # the moving pieces: travelling chevrons on reachable edges +
        # pulsing cursor ring on the selected node.
        keys = self._sector_keys()
        for i in range(len(keys) - 1):
            a_done = keys[i] in save.completed
            b_avail = keys[i + 1] in save.unlocked
            if a_done or b_avail:
                _draw_map_edge_chevron(screen,
                                       MAP_GRAPH[keys[i]].pos,
                                       MAP_GRAPH[keys[i + 1]].pos,
                                       self.t)
        if self.cursor in MAP_GRAPH:
            cur_node = MAP_GRAPH[self.cursor]
            cur_is_boss = self.app.levels[self.cursor].has_boss
            _draw_map_cursor_ring(screen, cur_node.pos[0], cur_node.pos[1],
                                  cur_is_boss, self.t)

        # Glitter on 'perfect clear' (zero-rewind) gold discs — animated, so it
        # rides the per-frame overlay rather than the cached graph surface.
        for k in keys:
            if self._node_is_perfect(k):
                p = MAP_GRAPH[k].pos
                rad = 20 if self.app.levels[k].has_boss else 13
                _draw_node_sparkles(screen, p[0], p[1], rad, self.t, int(k[1:]))

        # (The bottom "MISSION DOSSIER" card was removed v0.9.285 — the
        # cursored level's details now live in the right-side LEVEL panel,
        # so the bottom card was redundant.)

        # Right-side strip: header / STATUS / LOADOUT (per-weapon bars
        # + side / shield / engine / ability / bombs) / CONTROL — all
        # built in _build_map_panel_spec(). _side_strip_vars supplies
        # the per-weapon level / colour vars and the full loadout
        # snapshot the new LOADOUT panel needs. The strip plays a brief
        # entry animation (panels slide in from off-screen right,
        # staggered top-to-bottom, bg fades in) keyed off self.t — past
        # the end of the animation _draw_animated_side_strip short-
        # circuits to the plain render path.
        map_panel_vars = _side_strip_vars(self.app, map_screen=self)
        map_root = get_element("map", "map_root", **map_panel_vars)
        if map_root is not None:
            # "bouncy": short slide + alpha-lead + ease-out-back overshoot.
            # A/B-paired with the shop's "slow" mode so the player can
            # pick which feel to keep.
            _draw_animated_side_strip(screen, map_root, fonts,
                                      self.app.assets, map_panel_vars,
                                      self.t, mode="bouncy")
        # Stolen-time history chart: rendered AFTER the side strip's
        # bouncy entry settles so the bars don't fight the strip's slide.
        # No-op when the cursored level has no completions yet.
        self._draw_stolen_time_chart(screen)

        # End-of-game banner — element rendering handles visibility via
        # `visible_when: all_clear`, so the in-line check moved to map_vars.
        el = get_element("map", "all_clear", **map_vars)
        if el is not None:
            _layout_draw_item(screen, el, fonts, self.app.assets, map_vars)

        if self._flash_t > 0 and self._flash_msg:
            a = clamp(self._flash_t / 2.5, 0.0, 1.0)
            box_w = 360
            box_h = 36
            bx = (HUD_X - box_w) // 2
            by = 96
            overlay = pygame.Surface((box_w, box_h), pygame.SRCALPHA)
            overlay.fill((20, 28, 50, int(220 * a)))
            screen.blit(overlay, (bx, by))
            pygame.draw.rect(screen, (160, 200, 240, int(255 * a)),
                             (bx, by, box_w, box_h), 1)
            txt = fonts["small"].render(self._flash_msg, False, ORANGE)
            screen.blit(txt, txt.get_rect(center=(HUD_X // 2, by + box_h // 2)))

        draw_layout_overlay(screen, "map", fonts, self.app.assets)

    def _draw_gpu(self, controls):
        """Native GPU sibling of _draw(). bg/stars, the cached graph surface
        (uploaded as one texture), all layout text + the header panel, and the
        animated side strip (the perf-critical part) render natively. The
        bespoke vector decorations (travelling chevrons, cursor ring, perfect-
        clear sparkles, the stolen-time chart, the flash message) are intricate
        per-pixel art — rendered once onto a transparent escape-hatch overlay
        and uploaded. Mirrors _draw()'s z-order; decorations sit in the map
        column, disjoint from the right-side strip."""
        gpu = self.app.gpu
        save = self.app.save
        fonts = self.app.fonts
        # Draw to the current output target (the App leaves it at the
        # backbuffer; a readback test sets its own target).
        gpu.begin(BLACK)
        self.bg_ribbon.draw_gpu(gpu, SCREEN_W, SCREEN_H)
        self.stars.draw_gpu(gpu)
        max_sector = self._max_sector()
        progress_n = sum(1 for k in save.completed if k.startswith("L"))
        if (self._graph_cache_surf is None
                or self._graph_cache_sector != self.sector_idx):
            self._build_graph_cache()
        gpu.blit(gpu.tex_for(self._graph_cache_surf),
                 pygame.Rect(0, 0, SCREEN_W, SCREEN_H))
        map_vars = {
            "sector_name": SECTOR_NAMES[self.sector_idx],
            "sector_n": f"{self.sector_idx + 1:02d}",
            "progress": f"{progress_n:02d}",
            "has_prev": self.sector_idx > 0,
            "has_next": self.sector_idx < max_sector,
            "all_clear": progress_n >= 100,
            **button_label_vars(),
        }
        for eid in ("nav_hint_l", "nav_hint_r"):
            el = get_element("map", eid, **map_vars)
            if el is not None:
                _layout_draw_item_gpu(gpu, el, fonts, self.app.assets, map_vars)
        _panel_gpu(gpu, 60, 32, HUD_X - 120, 50)
        el = get_element("map", "sector_title", **map_vars)
        if el is not None:
            _layout_draw_item_gpu(gpu, el, fonts, self.app.assets, map_vars)
        # Side strip — native (the original perf complaint).
        map_panel_vars = _side_strip_vars(self.app, map_screen=self)
        map_root = get_element("map", "map_root", **map_panel_vars)
        if map_root is not None:
            _draw_animated_side_strip_gpu(gpu, map_root, fonts,
                                          self.app.assets, map_panel_vars,
                                          self.t, mode="bouncy")
        # Bespoke vector decorations → transparent escape-hatch overlay.
        dec = getattr(self, "_gpu_dec_surf", None)
        if dec is None:
            dec = self._gpu_dec_surf = pygame.Surface(
                (SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        dec.fill((0, 0, 0, 0))
        keys = self._sector_keys()
        for i in range(len(keys) - 1):
            a_done = keys[i] in save.completed
            b_avail = keys[i + 1] in save.unlocked
            if a_done or b_avail:
                _draw_map_edge_chevron(dec, MAP_GRAPH[keys[i]].pos,
                                       MAP_GRAPH[keys[i + 1]].pos, self.t)
        if self.cursor in MAP_GRAPH:
            cur_node = MAP_GRAPH[self.cursor]
            cur_is_boss = self.app.levels[self.cursor].has_boss
            _draw_map_cursor_ring(dec, cur_node.pos[0], cur_node.pos[1],
                                  cur_is_boss, self.t)
        for k in keys:
            if self._node_is_perfect(k):
                p = MAP_GRAPH[k].pos
                rad = 20 if self.app.levels[k].has_boss else 13
                _draw_node_sparkles(dec, p[0], p[1], rad, self.t, int(k[1:]))
        self._draw_stolen_time_chart(dec)
        if self._flash_t > 0 and self._flash_msg:
            a = clamp(self._flash_t / 2.5, 0.0, 1.0)
            box_w, box_h = 360, 36
            bx = (HUD_X - box_w) // 2
            by = 96
            overlay = pygame.Surface((box_w, box_h), pygame.SRCALPHA)
            overlay.fill((20, 28, 50, int(220 * a)))
            dec.blit(overlay, (bx, by))
            pygame.draw.rect(dec, (160, 200, 240, int(255 * a)),
                             (bx, by, box_w, box_h), 1)
            txt = fonts["small"].render(self._flash_msg, False, ORANGE)
            dec.blit(txt, txt.get_rect(center=(HUD_X // 2, by + box_h // 2)))
        gpu.blit_dynamic("map_dec", dec, pygame.Rect(0, 0, SCREEN_W, SCREEN_H))
        # End-of-game banner + user overlay items — native.
        el = get_element("map", "all_clear", **map_vars)
        if el is not None:
            _layout_draw_item_gpu(gpu, el, fonts, self.app.assets, map_vars)
        draw_layout_overlay_gpu(gpu, "map", fonts, self.app.assets)

    def _draw_stolen_time_chart(self, screen):
        """Bar chart of running-min stolen-time per completed attempt for
        the cursored level — with the textual 'BEST: X.XX s' readout
        living INSIDE this container's top edge so the LEVEL panel above
        only carries the level's metadata rows.

        Bars represent the running minimum: bar height i = min(times[:i+1]).
        The series therefore steps down or stays flat — never up. Dots on
        top mark the attempts where the running min actually improved;
        the LATEST (current-best) improvement dot is yellow to tie back
        to the BEST header text inside this same container, earlier
        improvements are a muted slate so only the live record draws
        the eye.

        Y-axis is clipped so the current best bar is at least 25 % of
        the bar area's height — without this, a player who made one
        terrible attempt followed by big improvements would see all the
        improvement bars compressed to ~nothing."""
        save = self.app.save
        cursor = self.cursor
        stats = (getattr(save, "level_stats", None) or {}).get(cursor, {})
        raw = stats.get("stolen_times") or []
        if not raw:
            return
        times = [float(t) for t in raw if t is not None]
        if not times:
            return

        # Running min — the series we actually plot.
        running = []
        cur = float("inf")
        improvement = []   # True at each index where running min dropped
        for t in times:
            if t < cur:
                cur = t
                improvement.append(True)
            else:
                improvement.append(False)
            running.append(cur)
        current_best = running[-1]

        # NOTE: the BEST header always renders once a time exists; the bar
        # chart below is gated on >= 2 improvements (see after the header).

        # Container rect — sits inside the LEVEL panel, below its 8
        # metadata rows. Numbers match _build_map_panel_spec(): DET_Y=40,
        # row 0 at y=14, 8 rows × 17 px → first slot past the last row
        # sits at y=14 + 8*17 = 150 (panel-local), plus 8 px breathing.
        chart_x = HUD_X + 12
        chart_top = 40 + 150 + 8
        chart_w = HUD_W - 24
        chart_h = SCREEN_H - 98 - 4 - chart_top
        if chart_w <= 4 or chart_h <= 16:
            return

        # Background plate so the bars + header read off the panel chrome.
        plate = pygame.Surface((chart_w, chart_h), pygame.SRCALPHA)
        plate.fill((22, 26, 44, 200))
        screen.blit(plate, (chart_x, chart_top))
        FRAME_COL = (60, 70, 100)
        pygame.draw.rect(screen, FRAME_COL,
                         (chart_x, chart_top, chart_w, chart_h), 1)

        # Header: "BEST: X.XX s" — yellow, top-left padded inside the
        # container. One size down from the original scale-2 "small"
        # 5x7 by reaching for the BOLDER 7x9 family at scale 1: smaller
        # than the original but keeps enough visual weight to register
        # as the score (the plain 5x7 scale 1 used by the LEVEL panel
        # rows blended into them and lost the headline feel).
        BEST_COL = (255, 220, 80)
        head_font = (self.app.fonts.get(("7x9", 1))
                     or self.app.fonts.get(1)
                     or self.app.fonts.get("tiny")
                     or self.app.fonts.get(2)
                     or self.app.fonts.get("small"))
        head_surf = head_font.render(
            f"BEST: {current_best:.2f} s", False, BEST_COL)
        head_h = head_surf.get_height()
        screen.blit(head_surf, (chart_x + 6, chart_top + 4))

        # The header (BEST: X.XX s) ALWAYS shows once there's a recorded time.
        # The bar chart below only draws once the player has actually IMPROVED
        # at least once — improvement[0] is the baseline, so require >= 2 marks
        # (baseline + a real drop). Otherwise the container just holds the
        # header with empty space below it.
        if sum(improvement) < 2:
            return

        # Y-axis clip: current best ≥ 25 % of bar area height.
        observed_max = max(running)
        y_max = max(current_best * 1.05,
                    min(observed_max, current_best * 4.0))
        # When the best stolen-time is 0 (a clean clear — the ideal), the clip
        # formula collapses to 0 and the bar-height division blows up. Span the
        # full observed range instead so the improvement-to-zero still plots.
        if y_max <= 0.0:
            y_max = max(observed_max, 1e-6)

        BAR_FILL = (110, 140, 190)         # solid bar color
        DOT_DIM = (170, 190, 220)         # older improvement dots
        DOT_BEST = BEST_COL                # current best dot — matches header

        # Bar area lives below the header with a small separating gap.
        bar_top = chart_top + 4 + head_h + 4
        bar_bottom = chart_top + chart_h - 3
        bar_area_h = bar_bottom - bar_top
        if bar_area_h <= 4:
            return

        # Bar layout — fixed gap between bars; bar width derived from
        # how many fit. With many attempts the bars shrink to ~2 px.
        n = len(running)
        GAP = 1
        avail = chart_w - 4   # 2 px inner padding each side
        bw = max(1, (avail - (n - 1) * GAP) // n)
        actual = n * bw + (n - 1) * GAP
        start_x = chart_x + (chart_w - actual) // 2
        baseline_y = bar_bottom
        usable_h = bar_area_h - 2   # leave 2 px above the tallest dot

        # Track the index of the LAST improvement so we can dot it
        # in yellow even if it's not the very last bar (current best
        # held while later bars failed to improve — common case).
        last_imp_idx = -1
        for i, imp in enumerate(improvement):
            if imp:
                last_imp_idx = i

        for i, v in enumerate(running):
            v_clip = min(v, y_max)
            h = max(1, int(round((v_clip / y_max) * usable_h)))
            x = start_x + i * (bw + GAP)
            y = baseline_y - h
            pygame.draw.rect(screen, BAR_FILL, (x, y, bw, h))
            if improvement[i]:
                col = DOT_BEST if i == last_imp_idx else DOT_DIM
                cx = x + bw // 2
                cy = max(bar_top + 1, y - 2)
                r = 2 if i == last_imp_idx else 1
                pygame.draw.circle(screen, col, (cx, cy), r)

def _draw_repeat_glyph(surf, cx, cy, radius, color, width=2):
    """Anticlockwise circled-arrow ('repeat') glyph: a near-full ring with a
    gap at the top, the open end capped by an arrowhead pointing in the
    counter-clockwise direction of travel. Drawn inside a level disc when the
    level has a saved mission replay."""
    # Screen y points DOWN, so DEcreasing the parametric angle sweeps the
    # point counter-clockwise on screen. Leave a gap at the top for the head.
    gap = 1.45
    a0 = -math.pi / 2 - gap / 2              # left lip of the top gap
    a1 = a0 - (2 * math.pi - gap)            # sweep CCW (decreasing a)
    steps = 24
    pts = []
    for i in range(steps + 1):
        a = a0 + (a1 - a0) * (i / steps)
        pts.append((int(cx + math.cos(a) * radius),
                    int(cy + math.sin(a) * radius)))
    pygame.draw.lines(surf, color, False, pts, width)
    # Arrowhead at the end (a1). Travel direction for decreasing a is
    # (sin a, -cos a); the head points that way, base spread perpendicular.
    ex, ey = pts[-1]
    tx, ty = math.sin(a1), -math.cos(a1)
    head = max(3.0, radius * 0.9)
    nx, ny = -ty, tx
    tip = (ex + tx * head, ey + ty * head)
    b1 = (ex + nx * head * 0.55, ey + ny * head * 0.55)
    b2 = (ex - nx * head * 0.55, ey - ny * head * 0.55)
    pygame.draw.polygon(surf, color, [
        (int(tip[0]), int(tip[1])),
        (int(b1[0]), int(b1[1])),
        (int(b2[0]), int(b2[1])),
    ])


def _draw_node_sparkles(surf, cx, cy, radius, t, seed=0):
    """Gold glitter rising off a 'perfect clear' disc. Stateless: a few sparkle
    slots each cycle on a staggered period; during a slot's active window a small
    4-point glint spawns on the disc, floats UPWARD past the rim (escaping the
    circle a bit) and fades as it climbs. Driven by the map's animation time `t`
    — no particle pool."""
    SLOTS = 5
    for i in range(SLOTS):
        period = 1.5 + 0.45 * i                      # staggered cycle lengths
        phase_off = 0.137 * (i + 1) + 0.31 * seed
        raw = t / period + phase_off
        ph = raw % 1.0
        ACTIVE = 0.5                                 # visible fraction of cycle
        if ph >= ACTIVE:
            continue                                 # dormant the rest
        p = ph / ACTIVE                              # 0..1 lifetime
        # Quick ramp-in, then fade out as it rises ("float up fading").
        a_factor = min(1.0, p / 0.18) * (1.0 - p)
        if a_factor <= 0.04:
            continue
        # Spawn spot per appearance (pseudo-random, anywhere on the disc).
        h = (int(raw) * 2654435761 + i * 40503 + seed * 97 + 1) & 0xffffffff
        ang = (h % 1024) / 1024.0 * math.tau
        spawn_r = radius * (0.25 + 0.7 * (((h >> 11) % 1024) / 1024.0))
        sx0 = cx + math.cos(ang) * spawn_r
        sy0 = cy + math.sin(ang) * spawn_r
        # Float upward past the rim (rise > radius) with a faint horizontal sway.
        rise = radius * (1.0 + 0.5 * (((h >> 22) % 256) / 256.0))
        drift = (((h >> 5) % 7) - 3) * 0.6           # -1.8..1.8 px
        sx = int(sx0 + drift * p)
        sy = int(sy0 - rise * p)                     # screen y is down → up
        arm = max(1, int(round(1.0 + 1.8 * a_factor)))   # 1..3 px arms
        a = int(40 + 210 * a_factor)
        col = (255, 228, 140)
        ext = arm + 1
        spr = pygame.Surface((ext * 2 + 1, ext * 2 + 1), pygame.SRCALPHA)
        c = (col[0], col[1], col[2], a)
        cc = ext
        pygame.draw.line(spr, c, (cc - arm, cc), (cc + arm, cc))
        pygame.draw.line(spr, c, (cc, cc - arm), (cc, cc + arm))
        spr.fill((255, 245, 200, min(255, a + 40)), (cc, cc, 1, 1))
        surf.blit(spr, (sx - cc, sy - cc))


def _draw_map_node(surf, x, y, palette, is_boss, done, avail, cursor, t, label_n, fonts, best_time=None, has_replay=False):
    base, accent, dark = palette
    # A "perfect clear" = completed with zero stolen time (never rewound). Those
    # discs go GOLD instead of green and earn per-frame glitter (drawn in
    # MapScreen._draw); the redundant "0.00s" best-time label is suppressed.
    perfect = bool(done and best_time is not None and best_time < 0.005)
    glow = _PERFECT_RING if perfect else accent      # gold accent on perfects
    if is_boss:
        r_outer = 20
        r_mid = 14
        r_inner = 6
        if done:
            fill, ring_col = ((_PERFECT_FILL, _PERFECT_RING) if perfect
                              else ((60, 130, 80), GREEN))
        elif avail:
            fill = base; ring_col = accent
        else:
            fill = (40, 40, 56); ring_col = (90, 90, 110)
        pygame.draw.circle(surf, dark if avail or done else (30, 30, 44), (x, y), r_outer)
        pygame.draw.circle(surf, ring_col, (x, y), r_outer, 2)
        # antenna marks (4 directions). Static — was time-animated when
        # the node was the cursor, but moved into the cached graph
        # surface in v0.9.88 so the cursor flourish lives in the
        # per-frame overlay (`_draw_map_cursor_overlay`) instead.
        if avail or done:
            for ang_deg in (0, 90, 180, 270):
                ang = math.radians(ang_deg)
                px = int(x + math.cos(ang) * (r_outer + 4))
                py = int(y + math.sin(ang) * (r_outer + 4))
                pygame.draw.rect(surf, glow, (px - 1, py - 1, 3, 3))
        pygame.draw.circle(surf, fill, (x, y), r_mid)
        pygame.draw.circle(surf, ring_col, (x, y), r_mid, 1)
        pygame.draw.circle(surf, glow if avail or done else (80, 80, 100), (x, y), r_inner)
        label = "B"
        lc = BLACK if avail or done else (140, 140, 160)
    else:
        r = 13
        if done:
            fill, ring_col = ((_PERFECT_FILL, _PERFECT_RING) if perfect
                              else ((60, 130, 80), GREEN))
        elif avail:
            fill = base; ring_col = accent
        else:
            fill = (44, 44, 60); ring_col = (90, 90, 110)
        pygame.draw.circle(surf, fill, (x, y), r)
        pygame.draw.circle(surf, ring_col, (x, y), r, 2)
        if avail or done:
            pygame.draw.circle(surf, glow, (x, y), 3)
        lc = BLACK if avail or done else (140, 140, 160)

    if cursor:
        _draw_map_cursor_ring(surf, x, y, is_boss, t)

    if has_replay:
        # A saved mission replay → circled "repeat" arrow inside the disc,
        # signalling the level can be re-watched. Takes the inner-glyph slot
        # ahead of the boss "B". (Completed levels no longer get a checkmark —
        # the green fill + ring already reads as cleared.)
        gr = 9 if is_boss else 7
        gcol = WHITE if (avail or done) else (150, 150, 170)
        _draw_repeat_glyph(surf, x, y, gr, gcol)
    elif is_boss:
        # Boss keeps its "B" marker inside the disc.
        ntxt = fonts["tiny"].render(label, False, lc)
        surf.blit(ntxt, ntxt.get_rect(center=(x, y - 2)))

    # Caption UNDER the circle = the "sector.level" name (e.g. "1.1"), in the
    # 5x7 scale-2 family. The boss reads "X.BOSS" instead of "X.10". The best
    # stolen-time sits ABOVE the circle once the level's been cleared; an
    # uncleared level leaves that space empty so the row still lines up.
    rad = r_outer if is_boss else r
    name_col = (200, 210, 230) if (avail or done) else (110, 110, 130)
    sector = (label_n - 1) // 10 + 1
    lvl = (label_n - 1) % 10 + 1
    cap_txt = f"{sector}.BOSS" if is_boss else f"{sector}.{lvl}"
    name_font = fonts.get("small") or fonts["tiny"]
    cap = name_font.render(cap_txt, False, name_col)
    surf.blit(cap, cap.get_rect(center=(x, y + rad + 11)))

    if best_time is not None and not perfect:
        # Rewind glyph (U+23F1) + 2-decimal stolen time + lowercase "s", one
        # size up from tiny (the bolder 7x9 family at scale 1). Drawn via draw()
        # rather than render() so the lowercase "s" survives — render()
        # uppercases everything, draw() preserves case. A perfect (0.00s) clear
        # shows no label — the gold disc + glitter is the marker.
        tf = fonts.get(("7x9", 1)) or fonts["tiny"]
        label_txt = f"⏱{best_time:.2f}s"
        w = tf.size(label_txt)[0]
        tf.draw(surf, x - w // 2, y - rad - 9 - tf.full_height // 2,
                label_txt, (255, 220, 80))


def _draw_map_edge(surf, a, b, a_done, b_avail, t, accent, with_chevron=True):
    """`with_chevron=False` skips the per-frame travelling chevron so the
    rest (which is purely static) can be baked into MapScreen's cached
    graph surface. The chevron is then drawn per-frame on top via
    `_draw_map_edge_chevron`."""
    dx = b[0] - a[0]
    dy = b[1] - a[1]
    length = math.hypot(dx, dy)
    if length == 0:
        return
    nx, ny = dx / length, dy / length

    if a_done:
        pygame.draw.line(surf, GREEN, a, b, 2)
    elif b_avail:
        # solid colored toward next available, with a subtle pulse
        pygame.draw.line(surf, accent, a, b, 2)
    else:
        # locked: dashed faint
        seg, gap = 6, 6
        pos = 0
        while pos < length:
            x1 = a[0] + nx * pos
            y1 = a[1] + ny * pos
            ne = min(pos + seg, length)
            x2 = a[0] + nx * ne
            y2 = a[1] + ny * ne
            pygame.draw.line(surf, (70, 80, 110), (int(x1), int(y1)), (int(x2), int(y2)), 1)
            pos += seg + gap
        return

    if with_chevron:
        _draw_map_edge_chevron(surf, a, b, t)


def _draw_map_cursor_ring(surf, x, y, is_boss, t):
    """Pulsing yellow cursor ring on a map node. Pulled out so MapScreen
    can draw it on top of the cached static-graph surface every frame
    instead of inside `_draw_map_node`'s cache pass."""
    radius = (22 if is_boss else 16) + int(math.sin(t * 6) * 2)
    pygame.draw.circle(surf, YELLOW, (x, y), radius, 2)


def _draw_map_edge_chevron(surf, a, b, t):
    """Travelling chevron for a reachable edge. Pulled out of
    `_draw_map_edge` so MapScreen can blit the cached static graph
    once and only redraw the cheap moving chevrons per frame."""
    dx = b[0] - a[0]
    dy = b[1] - a[1]
    length = math.hypot(dx, dy)
    if length == 0:
        return
    travel_t = (t * 0.6) % 1.0
    cx = a[0] + dx * travel_t
    cy = a[1] + dy * travel_t
    angle = math.atan2(dy, dx)
    size = 5
    tip = (cx + math.cos(angle) * size, cy + math.sin(angle) * size)
    left = (cx + math.cos(angle + 2.5) * size, cy + math.sin(angle + 2.5) * size)
    right = (cx + math.cos(angle - 2.5) * size, cy + math.sin(angle - 2.5) * size)
    pygame.draw.polygon(surf, WHITE, [
        (int(tip[0]), int(tip[1])),
        (int(left[0]), int(left[1])),
        (int(right[0]), int(right[1])),
    ])


# =============================================================================
# SHOP SCREEN
# =============================================================================

# Shop rows grouped by category. The flat SHOP_ITEMS list (cursor index
# space + lookup tables) is derived from this so the order + grouping
# live in one place. Reordered MAIN to rail → vulcan → ball (was
# rail → ball → vulcan); dropped the "Ability: " prefix from each
# slot 4 entry — the category header above the rows already names them.
SHOP_CATEGORIES = [
    ("MAIN WEAPONS", [
        ("main_rail",   "Rail"),
        ("main_vulcan", "Vulcan"),
        ("main_ball",   "Ball"),
    ]),
    ("OTHERS", [
        ("engine", "Engine"),
    ]),
]
SHOP_ITEMS = [item for _label, group in SHOP_CATEGORIES for item in group]


def _active_shop_categories():
    return SHOP_CATEGORIES


def _active_shop_items():
    return SHOP_ITEMS

# Tint each main-weapon row's NAME with its bullet identity so the player
# can spot a row at a glance without reading the label. Bars stay neutral
# (white-on-cursor, lavender otherwise) and GREEN-when-maxed. Ball's
# red picks the same family as the red-shielded-enemy halo so the
# weapon-shield colour pairing reads at a glance.
SHOP_MAIN_NAME_COLOR = {
    "rail":   CYAN,
    "vulcan": YELLOW,
    "ball":   (255, 100, 100),
}


def _parse_weapon_key(key):
    """Split a SHOP_ITEMS key like 'main_rail' / 'side_drone' into
    (slot, weapon_type). Returns (None, None) if not a weapon row."""
    if key.startswith("main_"):
        return ("main", key[len("main_"):])
    if key.startswith("side_"):
        return ("side", key[len("side_"):])
    return (None, None)


class ShopScreen:
    # Visual constants — uniform across every upgrade row's bar so a tier
    # cell looks the same width whether it belongs to rail, shield, or
    # engine. Main weapons subdivide each tier into 4 sub-cells.
    TIER_PX = 32          # width of one tier segment
    TIER_GAP = 1          # 1px gap between tier segments
    BAR_H = 14

    REVEAL_PER_UNLOCK_SEC = 0.65   # duration per cascade item
    REVEAL_FLASH_COLOR = (255, 240, 140)
    FADE_FROM_BLACK_DUR = 0.25     # post-level entry fade window
    SHOP_DOWNGRADE_HOLD = 0.45     # hold West this long → downgrade (refund)

    def __init__(self, app, pending_unlocks=None, from_level=False):
        self.app = app
        self.cursor = 0
        self.outcome = None
        self.flash_text = None
        # Shop content. Cached on entry so a toggle
        # mid-session doesn't reshape an already-visible shop.
        self.categories = _active_shop_categories()
        self.items = _active_shop_items()
        self.flash_t = 0
        # Lifetime clock — drives the side-strip entry animation in
        # _draw_animated_side_strip. Starts at 0 each time the shop is
        # entered so the panels slide in fresh.
        self.t = 0.0
        # True when entered straight from a finished level (post_play
        # path in App._transition). Switches the side-strip animation
        # to the slower "hud" profile and arms the fade-from-black
        # overlay so the transition out of the outro reads as one
        # continuous reveal.
        self.from_level = bool(from_level)
        self.fade_from_black_t = self.FADE_FROM_BLACK_DUR if self.from_level else 0.0
        # Pre-allocated full-screen black surface re-used by the fade-
        # from-black overlay below. .convert() matches the display
        # pixel format so set_alpha + blit go through the mali driver's
        # fast path — without it the RG flickered between black and
        # garbage frames during the 0.25 s fade. Same pattern as
        # PlayState._outro_fade_overlay.
        self._fade_overlay = None
        if self.from_level:
            try:
                self._fade_overlay = pygame.Surface(
                    (SCREEN_W, SCREEN_H)).convert()
            except pygame.error:
                self._fade_overlay = pygame.Surface((SCREEN_W, SCREEN_H))
            self._fade_overlay.fill(BLACK)
        # Reveal animation state. `pending_unlocks` is the list of
        # (category, new_tier) tuples produced by _apply_boss_unlocks().
        # We pop them one-by-one and animate each. Side-weapon + shield
        # rows aren't in `self.items` (filtered out by
        # `_active_shop_categories` — side weapons + shield are
        # disabled by the core mechanics), so their reveals would
        # animate against rows that don't exist. Drop them here so the
        # cascade only flashes rows the player can see.
        self.pending_unlocks = [u for u in (pending_unlocks or [])
                                if u[0] not in ("missile", "drone", "shield")]
        self.current_unlock = None     # (category, new_tier)
        self.current_unlock_t = 0.0
        # Cursor model: rows 0..len(items)-1 are upgrades, and one extra slot
        # at index len(items) is the CONTINUE entry. Focus CONTINUE on entry so
        # a fire-mash through end-of-level → shop → map still leaves cleanly
        # without spending credits.
        self.cursor = len(self.items)
        # North = HOLD to downgrade (full refund of a tier). Held past
        # SHOP_DOWNGRADE_HOLD refunds one tier; the red meter sweeps the row
        # right→left as it charges. (Buy moved to South-tap on an upgrade row.)
        self._down_held_prev = False
        self._buy_hold_t = 0.0
        self._buy_consumed = False
        self._buy_hold_frac = 0.0
        self._start_next_unlock()

    def _start_next_unlock(self):
        if self.pending_unlocks:
            self.current_unlock = self.pending_unlocks.pop(0)
            self.current_unlock_t = 0.0
            try:
                self.app.sounds["confirm"].play()
            except Exception:
                pass
        else:
            self.current_unlock = None

    def _is_revealing(self):
        return self.current_unlock is not None

    def _skip_reveal(self):
        self.pending_unlocks = []
        self.current_unlock = None

    def _tick_reveal(self, dt):
        if self.current_unlock is None:
            return
        self.current_unlock_t += dt
        if self.current_unlock_t >= self.REVEAL_PER_UNLOCK_SEC:
            self._start_next_unlock()

    def run(self, events, controls):
        dt = 1.0 / FPS
        self.t += dt
        if self.fade_from_black_t > 0:
            self.fade_from_black_t = max(0.0, self.fade_from_black_t - dt)
        menu = MenuInput(controls)
        # Reveal animation blocks shop interaction. Any action press skips.
        if self._is_revealing():
            self._tick_reveal(dt)
            if menu.go or menu.north or menu.back or menu.west:
                self._skip_reveal()
            self._draw()
            return None
        n_items = len(self.items)
        n_sel = n_items + 1            # + the CONTINUE entry at index n_items
        moved = False
        if menu.up:
            self.cursor = (self.cursor - 1) % n_sel; moved = True
        if menu.down:
            self.cursor = (self.cursor + 1) % n_sel; moved = True
        if moved:
            self.app.sounds["menu"].play()
        on_continue = (self.cursor >= n_items)

        # North (or mouse MIDDLE — the "destructive back") = HOLD to downgrade
        # (full refund) on an upgrade row. The red meter sweeps the row
        # right→left while held, refunding one tier at the threshold. No-op on
        # the CONTINUE entry.
        held = (controls.cancel_held or controls.mmb_held) and not on_continue
        if held:
            if not self._down_held_prev:
                self._buy_hold_t = 0.0
                self._buy_consumed = False
            self._buy_hold_t += dt
            if (not self._buy_consumed
                    and self._buy_hold_t >= self.SHOP_DOWNGRADE_HOLD):
                self._downgrade()
                self._buy_consumed = True
        else:
            self._buy_hold_t = 0.0
            self._buy_consumed = False
        self._buy_hold_frac = (
            min(1.0, self._buy_hold_t / self.SHOP_DOWNGRADE_HOLD)
            if held and not self._buy_consumed else 0.0)
        self._down_held_prev = held

        # GO (South): on the CONTINUE entry → forward to the map (shop → map →
        # play); on an upgrade row → buy/upgrade (instant — downgrade is North
        # now, so buy no longer needs the tap-vs-hold release dance). BACK
        # (East) = title — the back chain is map → shop → title.
        if menu.go:
            if on_continue:
                self.app.save.save()
                self.app.sounds["menu"].play()
                self.outcome = ("map", None)
            else:
                self._buy()
        # Esc (START) also backs here — idle on the shop otherwise.
        if menu.back or menu.start or controls.rmb_pressed:   # RMB = "safe back"
            self.app.save.save()
            self.app.sounds["menu"].play()
            self.outcome = ("title", None)

        if self.flash_t > 0:
            self.flash_t -= dt
        self._draw()
        if self.outcome:
            return self.outcome
        return None

    def _item_cost(self, key):
        """Returns the credit cost for the action this row offers, or
        None if the row is at MAX or the next purchase would cross
        into a locked tier."""
        save = self.app.save
        slot, wtype = _parse_weapon_key(key)
        if slot == "main":
            # All 3 main weapons are always owned + always equipped
            # (L1/R1 hold swaps between them in-flight). The only
            # action a main row offers now is "upgrade".
            lvl = getattr(save.loadout, f"main_{wtype}")
            if lvl >= MAIN_WEAPON_MAX:
                return None
            if _main_tier(lvl + 1) > _unlocked_tier_for(save, key):
                return None
            return MAIN_UPGRADE_COSTS[wtype][lvl]
        # Engine: each level == one tier.
        lvl = getattr(save.loadout, key)
        costs = WEAPON_COSTS[key]
        if lvl >= MAX_LEVELS[key]:
            return None
        if (lvl + 1) > _unlocked_tier_for(save, key):
            return None
        return costs[lvl]

    def _row_action(self, key):
        """Human-readable verb for what B does on this row right now."""
        save = self.app.save
        slot, wtype = _parse_weapon_key(key)
        if slot == "main":
            lvl = getattr(save.loadout, f"main_{wtype}")
            if lvl >= MAIN_WEAPON_MAX:
                return "max"
            if _main_tier(lvl + 1) > _unlocked_tier_for(save, key):
                return "locked"
            return "upgrade"
        lvl = getattr(save.loadout, key)
        if lvl >= MAX_LEVELS[key]:
            return "max"
        if (lvl + 1) > _unlocked_tier_for(save, key):
            return "locked"
        return "upgrade"

    def _can_buy(self, key):
        save = self.app.save
        action = self._row_action(key)
        if action == "max":
            return False
        cost = self._item_cost(key)
        if cost is None:
            return False
        return save.credits >= cost

    def _buy(self):
        key = self.items[self.cursor][0]
        save = self.app.save
        if not self._can_buy(key):
            self.app.sounds["deny"].play()
            action = self._row_action(key)
            self.flash_text = "ALREADY MAX" if action == "max" else "NOT ENOUGH"
            self.flash_t = 1.0
            return
        slot, wtype = _parse_weapon_key(key)
        if slot == "main":
            lvl = getattr(save.loadout, f"main_{wtype}")
            save.credits -= MAIN_UPGRADE_COSTS[wtype][lvl]
            setattr(save.loadout, f"main_{wtype}", lvl + 1)
        else:
            cost = self._item_cost(key)
            save.credits -= cost
            setattr(save.loadout, key, getattr(save.loadout, key) + 1)
        self.flash_text = "UPGRADED"
        self.flash_t = 1.2
        self.app.sounds["confirm"].play()
        save.save()

    def _downgrade(self):
        """Refund one tier on the cursored row (full credit-back of that
        tier's cost) and step the level down. Floor is level 1 (the free
        starting tier). Refund = the cost paid to reach the current level =
        costs[lvl - 1], mirroring _buy's costs[lvl] purchase index."""
        key = self.items[self.cursor][0]
        save = self.app.save
        slot, wtype = _parse_weapon_key(key)
        if slot == "main":
            attr = f"main_{wtype}"
            lvl = getattr(save.loadout, attr)
            costs = MAIN_UPGRADE_COSTS[wtype]
        else:
            attr = key
            lvl = getattr(save.loadout, key)
            costs = WEAPON_COSTS[key]
        if lvl <= 1:
            self.app.sounds["deny"].play()
            self.flash_text = "MIN TIER"
            self.flash_t = 1.0
            return
        refund = costs[lvl - 1]
        setattr(save.loadout, attr, lvl - 1)
        save.credits += refund
        self.flash_text = f"REFUND +{refund}"
        self.flash_t = 1.2
        try: self.app.sounds["confirm"].play()
        except Exception: pass
        save.save()

    def _draw(self):
        if getattr(self.app, "gpu", None) is not None:
            self.app.gpu_native = True
            self._draw_gpu()
            return
        screen = self.app.screen
        fonts = self.app.fonts
        save = self.app.save
        screen.fill(BLACK)

        # ===== Left panel: header + item list ====================================
        pygame.draw.rect(screen, HUD_BG, (0, 0, HUD_X, SCREEN_H))
        el = get_element("shop", "hangar_title")
        if el is not None:
            _layout_draw_item(screen, el, fonts, self.app.assets, {})

        # Column layout: name on left, bar at fixed column, cost right-aligned.
        # Bar must end before the longest cost label ("EQUIPPED" ~ 96 px at
        # scale-2 advance 12); cost text starts at COST_RIGHT - 96 = 360,
        # so the bar's right edge sits at BAR_X + BAR_W <= 354 with a small
        # gap. BAR_W deliberately narrower than the old 180 to leave room.
        NAME_X = 20
        BAR_X = HUD_X - 260      # 220
        BAR_W = 130
        COST_RIGHT = HUD_X - 24
        ROW_H = 22
        # Category chrome — every group gets a tiny header in muted slate
        # plus a 1-px hairline trailing across the row, then the items
        # render below. Gap between groups visually separates them
        # without committing real container chrome (rounded panels).
        CAT_HEADER_H = 16
        CAT_GAP = 5
        CAT_HEADER_COLOR = (110, 130, 170)
        CAT_HAIRLINE_COLOR = (50, 60, 90)
        list_top = 60
        y = list_top
        i = 0
        for cat_idx, (cat_label, group) in enumerate(self.categories):
            # Category header — small label, then a hairline filling the
            # rest of the row at the label's vertical midpoint.
            hdr = fonts["small"].render(cat_label, False, CAT_HEADER_COLOR)
            screen.blit(hdr, (NAME_X - 4, y))
            line_y = y + hdr.get_height() // 2
            pygame.draw.line(screen, CAT_HAIRLINE_COLOR,
                             (NAME_X - 4 + hdr.get_width() + 6, line_y),
                             (HUD_X - 16, line_y), 1)
            y += CAT_HEADER_H
            for key, label in group:
                row_color = WHITE if i == self.cursor else DIM
                cost = self._item_cost(key)
                action = self._row_action(key)
                slot, wtype = _parse_weapon_key(key)
                if i == self.cursor:
                    pygame.draw.rect(screen, (30, 36, 60), (12, y - 4, HUD_X - 24, 22))
                    # Downgrade hold meter: a red fill sweeps the row while
                    # North is held, completing into a refund at the threshold.
                    # Mirrored — it grows from the row's RIGHT edge leftward.
                    if self._buy_hold_frac > 0.0:
                        full_w = HUD_X - 26
                        fw = int(full_w * self._buy_hold_frac)
                        fx = 13 + (full_w - fw)
                        pygame.draw.rect(screen, (135, 55, 45),
                                         (fx, y - 3, fw, 20))
                # Main-weapon names take their bullet identity colour so
                # a row reads as "the yellow one" at a glance. Bar fill
                # stays neutral / GREEN-when-maxed below; only the label
                # changes hue.
                name_color = row_color
                if slot == "main":
                    wc = SHOP_MAIN_NAME_COLOR.get(wtype)
                    if wc is not None:
                        name_color = wc if i == self.cursor else tuple(
                            c * 5 // 6 for c in wc)
                name_surf = fonts["small"].render(label, False, name_color)
                screen.blit(name_surf, (NAME_X, y))
                # Main weapons are always-on (L1/R1 hold swap); no EQ
                # tag. Only main + engine rows exist now (the side /
                # ability / shield / bomb categories are dead — see
                # SHOP_CATEGORIES).
                if True:
                    # Slot setup. Each weapon / equipment carries its
                    # own current level + total tiers; "subs_per_tier"
                    # is the internal subdivision (4 for main, 1 for
                    # engine).
                    if slot == "main":
                        lvl = getattr(save.loadout, f"main_{wtype}")
                        subs_per_tier = 4
                        full_tiers = 5
                    else:
                        lvl = getattr(save.loadout, key)
                        subs_per_tier = 1
                        full_tiers = MAX_LEVELS[key]
                    visible_tiers = max(0, min(full_tiers,
                                                _unlocked_tier_for(save, key)))
                    if visible_tiers <= 0:
                        # Should never happen at runtime (default unlock = 2)
                        y += ROW_H
                        i += 1
                        continue
                    # Bar width = visible tiers * TIER_PX + (visible - 1) gaps.
                    # Uniform: every row's tier-cell looks the same width.
                    bar_w = visible_tiers * self.TIER_PX + max(0, (visible_tiers - 1) * self.TIER_GAP)
                    bar_max = visible_tiers * subs_per_tier
                    bar_val = min(lvl, bar_max)
                    fill_col = (GREEN if lvl >= full_tiers * subs_per_tier
                                else (WHITE if i == self.cursor else (160, 160, 200)))
                    _layout_draw_tiered_bar(screen, {
                        "x": BAR_X, "y": y + 2,
                        "w": bar_w, "h": self.BAR_H,
                        "value": bar_val, "max": bar_max,
                        "tiers": visible_tiers,
                        "color": fill_col,
                        "bg_color": DARKER,
                        "sep_color": (60, 70, 110),
                    }, None)
                    # Reveal-animation flash overlay on the newly-unlocked tier
                    # cell for the row that matches the currently-animating unlock.
                    if self.current_unlock is not None:
                        unlock_cat, unlock_tier = self.current_unlock
                        cat_key = _shop_key_for_cat(unlock_cat)
                        if cat_key == key and unlock_tier == visible_tiers:
                            # Flash intensity peaks at start, fades over duration.
                            t_norm = min(1.0, self.current_unlock_t / self.REVEAL_PER_UNLOCK_SEC)
                            alpha = int(255 * (1.0 - t_norm))
                            cell_x = BAR_X + (visible_tiers - 1) * (self.TIER_PX + self.TIER_GAP)
                            flash = pygame.Surface((self.TIER_PX, self.BAR_H),
                                                    pygame.SRCALPHA)
                            flash.fill((*self.REVEAL_FLASH_COLOR, alpha))
                            screen.blit(flash, (cell_x, y + 2))
                            # Small label above the flashing cell.
                            label_txt = f"T{unlock_tier} UNLOCKED"
                            lbl = fonts["tiny"].render(label_txt, False,
                                                        self.REVEAL_FLASH_COLOR)
                            lbl.set_alpha(min(255, int(255 * (1.0 - t_norm * 0.7))))
                            screen.blit(lbl, (cell_x + self.TIER_PX // 2 - lbl.get_width() // 2,
                                              y - 8))
                    # Cost label
                    if action == "max":
                        cost_str, cost_col = "MAX", GREEN
                    elif action == "locked":
                        cost_str, cost_col = "LOCKED", (110, 110, 130)
                    elif action == "equip":
                        cost_str, cost_col = "EQUIP", CYAN
                    elif action == "buy":
                        cost_str, cost_col = f"${cost}", ORANGE
                    else:
                        cost_str, cost_col = f"${cost}", row_color
                    c = fonts["small"].render(cost_str, False, cost_col)
                    screen.blit(c, (COST_RIGHT - c.get_width(), y))
                y += ROW_H
                i += 1
            if cat_idx < len(self.categories) - 1:
                y += CAT_GAP

        # CONTINUE entry below the upgrades — a selectable, CENTERED row
        # (cursor index == len(items)), focused on shop entry. Selecting it +
        # South leaves to the map. An extra half-row of space sets it apart
        # from the upgrade list; no column hint (the CONTROL panel covers it).
        y += CAT_GAP + 2 + ROW_H // 2
        cont_sel = (self.cursor >= len(self.items))
        if cont_sel:
            pygame.draw.rect(screen, (30, 36, 60), (12, y - 4, HUD_X - 24, 22))
        cont_color = WHITE if cont_sel else DIM
        cont_surf = fonts["small"].render("CONTINUE", False, cont_color)
        screen.blit(cont_surf, (HUD_X // 2 - cont_surf.get_width() // 2, y))

        # Flash toast — UPGRADED / NOT ENOUGH / ALREADY MAX — anchored
        # over the playfield's freed bottom space (the old wide
        # UPGRADE DETAIL strip moved into the right-side DETAIL panel).
        if self.flash_t > 0 and self.flash_text:
            txt = fonts["small"].render(self.flash_text, False, YELLOW)
            screen.blit(txt, txt.get_rect(center=(HUD_X // 2, SCREEN_H - 30)))

        # Right-side strip — header / BALANCE / DETAIL (cursored row
        # breakdown, replaces the old bottom strip) / CONTROL. All
        # vars (credits + per-cursor detail pieces) come from one
        # helper shared with the map sidebar. Plays the same entry
        # animation as MapScreen (panels stream in from the right,
        # staggered top-to-bottom, bg fades in).
        shop_panel_vars = _side_strip_vars(self.app, self)
        shop_root = get_element("shop", "shop_root", **shop_panel_vars)
        if shop_root is not None:
            # When the shop opens straight after a level (post_play path
            # in App._transition), the side panels animate in with the
            # slower HUD profile to match the just-finished playfield's
            # HUD timings. Direct map↔shop hops keep the snappier
            # "bouncy" profile.
            strip_mode = "hud" if self.from_level else "bouncy"
            _draw_animated_side_strip(screen, shop_root, fonts,
                                      self.app.assets, shop_panel_vars,
                                      self.t, mode=strip_mode)

        draw_layout_overlay(screen, "shop", fonts, self.app.assets)

        # Fade-from-black overlay — only set when entering from a level
        # (post_play). 0.25 s of alpha 255 → 0 so the shop appears out
        # of the blackness of the just-finished outro fade. Surface is
        # pre-allocated + .convert()ed in __init__ so set_alpha + blit
        # go through the mali driver's fast path on RG (per-frame alloc
        # caused flicker pre-v0.9.136).
        if self.fade_from_black_t > 0 and self._fade_overlay is not None:
            ratio = max(0.0, min(1.0, self.fade_from_black_t / self.FADE_FROM_BLACK_DUR))
            self._fade_overlay.set_alpha(int(255 * ratio))
            screen.blit(self._fade_overlay, (0, 0))

    def _draw_gpu(self):
        """Native GPU sibling of _draw(). The shop has no weird blends — the
        whole left item list (highlight/hold-meter/reveal-flash rects, category
        hairlines, name/cost text, tiered bars) ports straight to GPU
        primitives, the right strip uses the native animated side strip, and
        the fade-from-black is a translucent fill_rect. Mirrors _draw exactly."""
        gpu = self.app.gpu
        fonts = self.app.fonts
        save = self.app.save
        gpu.begin(BLACK)
        gpu.fill_rect((0, 0, HUD_X, SCREEN_H), HUD_BG)
        el = get_element("shop", "hangar_title")
        if el is not None:
            _layout_draw_item_gpu(gpu, el, fonts, self.app.assets, {})

        def _txt(surf, x, y):
            gpu.blit(gpu.tex_for(surf),
                     pygame.Rect(x, y, surf.get_width(), surf.get_height()))

        NAME_X = 20
        BAR_X = HUD_X - 260
        BAR_W = 130
        COST_RIGHT = HUD_X - 24
        ROW_H = 22
        CAT_HEADER_H = 16
        CAT_GAP = 5
        CAT_HEADER_COLOR = (110, 130, 170)
        CAT_HAIRLINE_COLOR = (50, 60, 90)
        list_top = 60
        y = list_top
        i = 0
        for cat_idx, (cat_label, group) in enumerate(self.categories):
            hdr = fonts["small"].render(cat_label, False, CAT_HEADER_COLOR)
            _txt(hdr, NAME_X - 4, y)
            line_y = y + hdr.get_height() // 2
            gpu.line((NAME_X - 4 + hdr.get_width() + 6, line_y),
                     (HUD_X - 16, line_y), CAT_HAIRLINE_COLOR)
            y += CAT_HEADER_H
            for key, label in group:
                row_color = WHITE if i == self.cursor else DIM
                cost = self._item_cost(key)
                action = self._row_action(key)
                slot, wtype = _parse_weapon_key(key)
                if i == self.cursor:
                    gpu.fill_rect((12, y - 4, HUD_X - 24, 22), (30, 36, 60))
                    if self._buy_hold_frac > 0.0:
                        full_w = HUD_X - 26
                        fw = int(full_w * self._buy_hold_frac)
                        fx = 13 + (full_w - fw)
                        gpu.fill_rect((fx, y - 3, fw, 20), (135, 55, 45))
                name_color = row_color
                if slot == "main":
                    wc = SHOP_MAIN_NAME_COLOR.get(wtype)
                    if wc is not None:
                        name_color = wc if i == self.cursor else tuple(
                            c * 5 // 6 for c in wc)
                name_surf = fonts["small"].render(label, False, name_color)
                _txt(name_surf, NAME_X, y)
                if True:
                    if slot == "main":
                        lvl = getattr(save.loadout, f"main_{wtype}")
                        subs_per_tier = 4
                        full_tiers = 5
                    else:
                        lvl = getattr(save.loadout, key)
                        subs_per_tier = 1
                        full_tiers = MAX_LEVELS[key]
                    visible_tiers = max(0, min(full_tiers,
                                               _unlocked_tier_for(save, key)))
                    if visible_tiers <= 0:
                        y += ROW_H
                        i += 1
                        continue
                    bar_w = visible_tiers * self.TIER_PX + max(0, (visible_tiers - 1) * self.TIER_GAP)
                    bar_max = visible_tiers * subs_per_tier
                    bar_val = min(lvl, bar_max)
                    fill_col = (GREEN if lvl >= full_tiers * subs_per_tier
                                else (WHITE if i == self.cursor else (160, 160, 200)))
                    _layout_draw_tiered_bar_gpu(gpu, {
                        "x": BAR_X, "y": y + 2,
                        "w": bar_w, "h": self.BAR_H,
                        "value": bar_val, "max": bar_max,
                        "tiers": visible_tiers,
                        "color": fill_col,
                        "bg_color": DARKER,
                        "sep_color": (60, 70, 110),
                    }, None)
                    if self.current_unlock is not None:
                        unlock_cat, unlock_tier = self.current_unlock
                        cat_key = _shop_key_for_cat(unlock_cat)
                        if cat_key == key and unlock_tier == visible_tiers:
                            t_norm = min(1.0, self.current_unlock_t / self.REVEAL_PER_UNLOCK_SEC)
                            alpha = int(255 * (1.0 - t_norm))
                            cell_x = BAR_X + (visible_tiers - 1) * (self.TIER_PX + self.TIER_GAP)
                            gpu.fill_rect((cell_x, y + 2, self.TIER_PX, self.BAR_H),
                                          (*self.REVEAL_FLASH_COLOR, alpha))
                            label_txt = f"T{unlock_tier} UNLOCKED"
                            lbl = fonts["tiny"].render(label_txt, False,
                                                       self.REVEAL_FLASH_COLOR)
                            gpu.blit(gpu.tex_for(lbl),
                                     pygame.Rect(cell_x + self.TIER_PX // 2 - lbl.get_width() // 2,
                                                 y - 8, lbl.get_width(), lbl.get_height()),
                                     alpha=min(255, int(255 * (1.0 - t_norm * 0.7))))
                    if action == "max":
                        cost_str, cost_col = "MAX", GREEN
                    elif action == "locked":
                        cost_str, cost_col = "LOCKED", (110, 110, 130)
                    elif action == "equip":
                        cost_str, cost_col = "EQUIP", CYAN
                    elif action == "buy":
                        cost_str, cost_col = f"${cost}", ORANGE
                    else:
                        cost_str, cost_col = f"${cost}", row_color
                    c = fonts["small"].render(cost_str, False, cost_col)
                    _txt(c, COST_RIGHT - c.get_width(), y)
                y += ROW_H
                i += 1
            if cat_idx < len(self.categories) - 1:
                y += CAT_GAP

        y += CAT_GAP + 2 + ROW_H // 2
        cont_sel = (self.cursor >= len(self.items))
        if cont_sel:
            gpu.fill_rect((12, y - 4, HUD_X - 24, 22), (30, 36, 60))
        cont_color = WHITE if cont_sel else DIM
        cont_surf = fonts["small"].render("CONTINUE", False, cont_color)
        _txt(cont_surf, HUD_X // 2 - cont_surf.get_width() // 2, y)

        if self.flash_t > 0 and self.flash_text:
            txt = fonts["small"].render(self.flash_text, False, YELLOW)
            r = txt.get_rect(center=(HUD_X // 2, SCREEN_H - 30))
            _txt(txt, r.x, r.y)

        shop_panel_vars = _side_strip_vars(self.app, self)
        shop_root = get_element("shop", "shop_root", **shop_panel_vars)
        if shop_root is not None:
            strip_mode = "hud" if self.from_level else "bouncy"
            _draw_animated_side_strip_gpu(gpu, shop_root, fonts,
                                          self.app.assets, shop_panel_vars,
                                          self.t, mode=strip_mode)

        draw_layout_overlay_gpu(gpu, "shop", fonts, self.app.assets)

        if self.fade_from_black_t > 0 and self._fade_overlay is not None:
            ratio = max(0.0, min(1.0, self.fade_from_black_t / self.FADE_FROM_BLACK_DUR))
            gpu.fill_rect((0, 0, SCREEN_W, SCREEN_H), (0, 0, 0, int(255 * ratio)))

    def _detail_pieces(self, key, cost):
        """Returns 5-tuple: current level string, current effect, next effect,
        cost string, cost colour. Used by the bottom DETAIL strip."""
        save = self.app.save
        slot, wtype = _parse_weapon_key(key)
        # Tier descriptions are 5-long for main weapons, 3-long for side.
        # Within a tier, sub-levels share the tier description plus a +dmg
        # bump. Damage per bullet is 100 + 10*(level-1) for everything.
        MAIN_TIER_DESCS = {
            "rail":   ["1.0s cooldown", "0.9s cooldown", "0.8s cooldown",
                       "0.7s cooldown", "0.5s cooldown"],
            "ball":   ["charge only, no absorb",
                       "65px suction, heavy drag",
                       "80px suction, modest drag",
                       "100px suction, light drag",
                       "120px suction, nimble"],
            "vulcan": ["rapid 1", "rapid dual", "rapid triple",
                       "rapid quad", "rapid quint"],
        }
        SIDE_TIER_DESCS = {
            "missile": ["1 heatseeker", "2 heatseekers", "3 heatseekers"],
            "drone":   ["1 drone shot", "2 drone shots", "3 drone shots"],
        }

        def _level_eff(level, max_tiers, tier_descs):
            """Format a level as 'tier-name · T<n> sub/4 · <dmg>dmg'."""
            tier = max(1, min(max_tiers, (level - 1) // 4 + 1))
            sub = (level - 1) % 4 + 1
            dmg = 100 + 10 * (level - 1)
            return f"{tier_descs[tier - 1]} · T{tier} {sub}/4 · {dmg}dmg"

        if slot == "main":
            # All mains are always owned + always equipped (L1/R1 hold).
            # The row only ever offers upgrade or shows MAX.
            tier_descs = MAIN_TIER_DESCS[wtype]
            lvl = getattr(save.loadout, f"main_{wtype}")
            mx = MAIN_WEAPON_MAX
            hold_label = {"rail": "hold L1", "ball": "hold R1",
                          "vulcan": "no hold"}[wtype]
            cur_eff = _level_eff(lvl, 5, tier_descs)
            if lvl < mx:
                return (f"Lv {lvl}/{mx}  ({hold_label})", cur_eff,
                        _level_eff(lvl + 1, 5, tier_descs),
                        f"${cost}", YELLOW)
            return (f"Lv {lvl}/{mx}  ({hold_label})", cur_eff,
                    "fully upgraded", "MAX", GREEN)
        if key == "engine":
            cur = save.loadout.engine
            mx = MAX_LEVELS["engine"]
            cur_eff = f"{ENGINE_SPEEDS[cur]} px/s"
            if cur < mx:
                nx = cur + 1
                return (f"Lv {cur}/{mx}", cur_eff, f"{ENGINE_SPEEDS[nx]} px/s",
                        f"${cost}", YELLOW)
            return (f"Lv {cur}/{mx}", cur_eff, "fully upgraded", "MAX", GREEN)
        return ("", "", "", "", DIM)

    def _detail_stats(self, key):
        """NOW / NEXT damage + cooldown for the cursored row, as the four
        table-cell strings (now_dmg, next_dmg, now_cd, next_cd). Only main
        weapons carry damage/cooldown — everything else blanks to '—'."""
        slot, wtype = _parse_weapon_key(key)
        if slot != "main":
            return ("—", "—", "—", "—")

        def _dmg(lvl):
            return RAILGUN_DAMAGE[lvl] if wtype == "rail" else 100 + 10 * (lvl - 1)

        def _cd(lvl):
            return MAIN_FIRE_RATE_BY_TYPE[wtype][lvl]

        lvl = getattr(self.app.save.loadout, f"main_{wtype}")
        mx = MAIN_WEAPON_MAX
        now_dmg = f"DMG {_dmg(lvl)}"
        now_cd = f"CD {_cd(lvl):.2f}S"
        if lvl < mx:
            next_dmg = str(_dmg(lvl + 1))
            next_cd = f"{_cd(lvl + 1):.2f}S"
        else:
            next_dmg = next_cd = "—"
        return (now_dmg, next_dmg, now_cd, next_cd)




# =============================================================================
# BOOT SPLASH — old-TV warm-up into dead-channel static
# =============================================================================

class BootSplashScreen:
    """Old-TV-turning-on boot sequence. A tube warm-up (ignition flash + a
    horizontal slit that blooms open) settles into dim, blurry grey static
    (a dead channel) with a soft vignette, shown while the heavy world build
    (assets / sounds / music) runs on a background thread. When the build is
    ready the splash yields the real first screen ('title') so the EXISTING
    screen crossfade blends the static into the title.

    Pure-software screen (draws into app.screen, gpu_native stays False — same
    present path as TitleScreen). Cheap per frame: one palette-noise window,
    panned + periodically regenerated, smoothscaled to 640x480 (the 2x2 blur),
    plus pre-baked vignette + scanline overlays. Nothing here reads the assets
    the build thread is producing, so there's no cross-thread hazard."""

    WARMUP_DUR = 0.25       # tube warm-up (2x faster), eased in and out
    MIN_HOLD   = 0.45       # min static AFTER warm-up before we may cut to title
    GREY_LO, GREY_HI = 10, 98     # static grey band — low floor = darker dark pixels
    PAN = 96                      # pan margin around the 640x480 window
    BUF_W, BUF_H = SCREEN_W + PAN, SCREEN_H + PAN
    NBUF = 3                      # pre-baked panning buffers (variety w/o per-frame scale)

    def __init__(self, app):
        self.app = app
        self.t = 0.0
        self.age = 0
        self.outcome = None
        self._prewarmed = False
        self._rng = random.Random(0x5EED5)
        # Pre-baked, pre-blurred static buffers (larger than the screen so a
        # window can pan), all built up front (a few smoothscales, ~100ms on
        # the A53) so EVERY static frame is just a plain window blit — no
        # per-frame smoothscale, so the static stays smooth even while the
        # build thread saturates all four cores.
        self._buffers = [self._build_buffer() for _ in range(self.NBUF)]
        # Vignette + scanlines pre-combined into ONE overlay (one blit/frame).
        self._overlay = self._build_vignette()
        self._overlay.blit(self._build_scanlines(), (0, 0))
        # Boot-frame profiling — wall-clock between run() calls, so the
        # one-line summary at hand-off reports the real on-device static FPS
        # (and the one-time prewarm hitch) straight into last_run.log.
        self._prof_last = None
        self._prof_max = 0.0
        self._prof_sum = 0.0
        self._prof_n = 0
        self._prof_over45 = 0
        self._prof_prewarm_ms = 0.0

    def _build_buffer(self):
        # os.urandom -> 8-bit palette noise (dim grey ramp) -> ONE blurred
        # upscale to BUF_W x BUF_H. Done only a handful of times total (never
        # per frame); the smoothscale is what gives the soft 2x2 blur. Source
        # is half-size so each blurred block ends up ~2 logical px.
        sw, sh = self.BUF_W // 2, self.BUF_H // 2
        raw = os.urandom(sw * sh)
        s = pygame.image.frombuffer(raw, (sw, sh), "P")
        span = self.GREY_HI - self.GREY_LO
        s.set_palette([(self.GREY_LO + i * span // 255,) * 3 for i in range(256)])
        return pygame.transform.smoothscale(s.convert(), (self.BUF_W, self.BUF_H))

    def _build_vignette(self):
        # Edge-following darkening whose alpha is the EUCLIDEAN distance to the
        # inner clear rectangle (inset BAND from every edge). Along a straight
        # edge only one axis contributes, so the dark band is uniform; near a
        # corner BOTH edges contribute (sqrt(dx^2+dy^2)), so the clear->black
        # boundary curves into a quarter-circle — the corners round naturally,
        # no pillow bulge and no hard square. Built cheaply as the rectangle's
        # outward dilations: a rounded rect grown by `o` with border_radius `o`
        # is exactly the iso-distance-`o` contour. Drawn large->small so each
        # pixel keeps the alpha of the smallest contour covering it; the corners
        # past the band are never covered, so they stay solid black.
        v = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        v.fill((0, 0, 0, 255))
        BAND = 112                       # dark-band thickness from each edge (75% of 150)
        iw, ih = SCREEN_W - 2 * BAND, SCREEN_H - 2 * BAND
        for o in range(BAND, -1, -1):
            rw, rh = iw + 2 * o, ih + 2 * o
            t = o / BAND                 # 0 at the inner lip -> 1 at the edge
            a = int(255 * (t * t * (3 - 2 * t)))         # 0 inner -> 255 edge
            pygame.draw.rect(v, (0, 0, 0, a),
                             pygame.Rect((SCREEN_W - rw) // 2,
                                         (SCREEN_H - rh) // 2, rw, rh),
                             border_radius=o)
        return v

    def _build_scanlines(self):
        s = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        for y in range(0, SCREEN_H, 2):
            pygame.draw.line(s, (0, 0, 0, 26), (0, y), (SCREEN_W, y))
        return s

    def _window(self):
        # Random 640x480 sub-window of a random pre-baked buffer — a plain view
        # (free); the blit that uses it is the only per-frame pixel cost.
        buf = self._buffers[self._rng.randrange(len(self._buffers))]
        ox = self._rng.randint(0, self.BUF_W - SCREEN_W)
        oy = self._rng.randint(0, self.BUF_H - SCREEN_H)
        return buf.subsurface((ox, oy, SCREEN_W, SCREEN_H))

    @staticmethod
    def _skip(events, controls):
        if getattr(controls, "confirm_pressed", False) or \
           getattr(controls, "start_pressed", False):
            return True
        for ev in events:
            if ev.type == pygame.KEYDOWN and ev.key in (
                    pygame.K_RETURN, pygame.K_SPACE, pygame.K_ESCAPE):
                return True
            if ev.type == pygame.JOYBUTTONDOWN:
                return True
        return False

    def run(self, events, controls):
        app = self.app
        if self.outcome is not None:
            return self.outcome          # transition already armed — stop drawing
        app.gpu_native = False
        # Boot-frame profiling: wall-clock since the previous run() call.
        now = time.perf_counter()
        if self._prof_last is not None:
            ms = (now - self._prof_last) * 1000.0
            self._prof_max = max(self._prof_max, ms)
            self._prof_sum += ms
            self._prof_n += 1
            if ms > 45.0:
                self._prof_over45 += 1
        self._prof_last = now
        dt = 1.0 / FPS
        self.t += dt
        screen = app.screen
        W, H = SCREEN_W, SCREEN_H

        # GPU cache prewarm FIRST — one screen per frame, started once the world
        # (assets+sounds) is ready so it overlaps the music gen still on the
        # build thread. It must run BEFORE the static draw below: the TitleScreen
        # prewarm is a SOFTWARE screen that draws to self.screen, so doing it
        # after would leave the title on self.screen and _present would upload
        # it = a one-frame title flash near the transition. Drawing the static
        # afterwards overwrites self.screen, so the present is always the static.
        if getattr(app, "_boot_world_ready", False) and not self._prewarmed:
            _pw0 = time.perf_counter()
            try:
                done = app._prewarm_step()
            except Exception:
                done = True
            self._prof_prewarm_ms += (time.perf_counter() - _pw0) * 1000.0
            if done:
                self._prewarmed = True
            self._prof_last = time.perf_counter()    # don't count a prewarm frame

        win = self._window()                            # 640x480, pre-blurred
        warm = self.t / self.WARMUP_DUR
        if warm < 1.0:
            e = warm * warm * (3 - 2 * warm)            # smoothstep: eases in AND out
            h = max(2, int(H * e))
            y = (H - h) // 2
            field = pygame.transform.scale(win, (W, h))
            bloom = int(150 * math.sin(math.pi * e))     # eased swell-and-fade ignition
            if bloom > 1:
                field.fill((bloom, bloom, bloom),
                           special_flags=pygame.BLEND_RGB_ADD)
            screen.fill(BLACK)
            screen.blit(field, (0, y))
            # vignette scales WITH the static band so its top/bottom darken too
            screen.blit(pygame.transform.scale(self._overlay, (W, h)), (0, y))
        else:
            screen.blit(win, (0, 0))
            screen.blit(self._overlay, (0, 0))

        # Cut to the title once EVERYTHING is built and the caches are warm.
        ready = getattr(app, "_boot_assets_ready", False)
        if (ready and self._prewarmed
                and (self.t >= self.WARMUP_DUR + self.MIN_HOLD
                     or self._skip(events, controls))):
            self.outcome = app._boot_target
            avg = self._prof_sum / max(1, self._prof_n)
            print("[boot] splash %d frames: avg %.1fms max %.1fms (>45ms: %d); "
                  "prewarm %.0fms" % (self._prof_n, avg, self._prof_max,
                                      self._prof_over45, self._prof_prewarm_ms),
                  file=sys.stderr)
        return self.outcome


# =============================================================================
# TITLE / GAMEOVER
# =============================================================================

class TitleScreen:
    def __init__(self, app):
        self.app = app
        self.stars = ParallaxStars(SCREEN_W, SCREEN_H, counts=(80, 60, 40))
        # Mirror-tiled backdrop scrolling downward behind the stars. The
        # theme follows the player's current progress (current save node →
        # sector → SECTOR_RIBBONS) so the title hints at where you are.
        self._rebuild_for_profile()
        self.t = 0
        self.outcome = None
        self.cursor = 0
        # When True, an "OVERWRITE PROGRESS?" dialog is showing and the
        # menu is suspended until the user presses Y (confirm wipe) or
        # B/Start (cancel back to the menu).
        self._confirm_new_game = False
        # SOUND / MUSIC slider state (see _handle_slider_input). _dirty
        # tracks whether the in-memory bus level has drifted from the
        # last save.save() so we can flush on release / cursor-move
        # rather than once per auto-repeat tick.
        self._slider_dir = 0
        self._slider_hold_t = 0.0
        self._slider_fires_done = 0
        self._slider_dirty = False
        # Release-notes overlay state. Mounted from `app.pending_release_notes`
        # at construction; when non-None, normal title input is suspended
        # until the player presses ability (install) or confirm (dismiss).
        # Dismiss only suppresses the overlay for THIS TitleScreen
        # instance — we leave App.pending_release_notes set so any
        # subsequent return-to-title (Map → START → Title, game over →
        # Title, etc.) re-mounts the modal. The reminder keeps coming
        # back until the player actually installs the update, and the
        # notes accumulate naturally because the fetch is keyed off
        # the installed VERSION (which doesn't change without an install).
        self._notes = None
        self._notes_scroll = 0
        # Seconds the up/down d-pad has been held while the notes modal
        # is up. After REPEAT_DELAY the modal starts auto-scrolling at
        # REPEAT_DT intervals so a long changelog doesn't require
        # tapping. Reset to 0 when neither direction is held.
        self._notes_held_t = 0.0
        self._notes_dismissed = False
        # Tracks the exact text that was dismissed so a *different*
        # changelog (e.g. a new release shipping mid-session) can
        # re-pop the overlay even though the player already closed the
        # previous one.
        self._notes_dismissed_text = ""
        self._mount_release_notes()
        # One-shot update check on title entry. Each fresh TitleScreen
        # (boot, return from Map / GameOver / Continue cancel) kicks
        # off a single background fetch — no 5-second polling: the
        # v0.8.7 loop blew through GitHub's 60-req/hr anonymous quota
        # before ETag support landed, and even with conditional
        # fetches the cost-benefit of polling for changes the player
        # has 5 seconds to notice isn't compelling.
        # The Event still exists because _install_worker uses it to
        # decide whether the player is still on the title when an
        # install finishes (i.e. should we execv now or defer to
        # the next launch).
        self._update_check_stop = threading.Event()
        if not EMSCRIPTEN:
            # Web build skips the background GitHub poll — no sockets/threads
            # in Pyodide, and the page is always the latest deploy anyway.
            threading.Thread(target=self._update_check_once,
                             daemon=True).start()
        # Install state machine: idle / running / noop / fail_net /
        # fail_write / needs_restart / gated. Drives the bottom-of-
        # screen toast and gates re-triggers while a fetch is in
        # flight. The actual fetch lives on a daemon thread so the
        # main loop stays responsive (4 × 5 s timeout = up to 20 s
        # blocking otherwise).
        self._install_state = "idle"
        self._install_t = 0.0
        self._install_target_at_start = ""

    def _rebuild_for_profile(self):
        """Re-pick the backdrop ribbon + Continue/New Game/Quit menu to
        match the currently-active profile. Called on init and again
        whenever L1/R1 cycles to a new profile."""
        node = self.app.save.current_node or "L001"
        try:
            n = int(node[1:])
        except (ValueError, IndexError):
            n = 1
        sector_idx = max(0, min(len(SECTOR_RIBBONS) - 1, (n - 1) // 10))
        theme = SECTOR_RIBBONS[sector_idx]
        # Preserve the previous ribbon's scroll position so cycling between
        # profiles whose progress lands on the same sector doesn't visibly
        # snap the drift back to zero. Even when the sector differs, the
        # consistent scroll feels less jarring than a hard reset.
        prev_scroll = getattr(getattr(self, "bg_ribbon", None), "scroll", 0.0)
        # Native aspect, mirror-tiled 3x so the source art reads at its true
        # proportions on the title screen too (shared cache — see _cached_ribbon).
        self.bg_ribbon = _cached_ribbon(theme, width=SCREEN_W,
                                        tile_h=SCREEN_H * 2)
        self.bg_ribbon.speed = -24.0
        self.bg_ribbon.scroll = prev_scroll % self.bg_ribbon.tile_h
        self.has_save = SaveData.profile_exists(self.app.profile_name)
        # SOUND / MUSIC are slider rows — D-pad/stick L/R adjusts each
        # by 2% while the cursor is on them. Confirm on them is a no-op
        # (handled in run()). They live between the play actions and
        # Quit so the existing accelerator (top entries) keeps working.
        play_opts = (["Continue", "New Game"] if self.has_save
                     else ["New Game"])
        self.options = play_opts + ["SOUND", "MUSIC", "Quit"]
        # CRT-glitch overlay for the title logo. Cached at the
        # logo's native dimensions; invalidates if the layout editor
        # resizes the logo between sessions.
        self._title_logo_glitch_overlay = None

    def _save_has_progress(self):
        """Heuristic for "is there anything worth losing in this profile?".
        Used to gate the New Game confirm prompt — a brand-new profile
        (or one wiped a moment ago) skips the dialog and starts directly."""
        s = self.app.save
        if s.credits > 0 or s.high_score > 0:
            return True
        if s.completed:
            return True
        if s.current_node not in (None, "", "L001"):
            return True
        if s.unlocked and set(s.unlocked) - {"L001"}:
            return True
        return False

    def _start_new_game(self):
        """Reset the active profile to a fresh save and head to the
        map. Fresh SaveData() = rewind locked again; mirror to the
        module flag so the HUD's "rewind" control hint doesn't
        survive past the wipe."""
        self.app.save = SaveData()
        self.app.save.save(self.app.profile_name)
        global _REWIND_UNLOCKED
        _REWIND_UNLOCKED = False
        self.has_save = True
        self.options = ["Continue", "New Game", "SOUND", "MUSIC", "Quit"]
        self._confirm_new_game = False
        self.outcome = ("map", None)

    # ── SOUND / MUSIC slider rows ─────────────────────────────────────
    _SLIDER_STEP = 0.02      # 2% per fire — matches the user spec.
    _SLIDER_INIT_DELAY = 0.4  # seconds before auto-repeat kicks in.
    _SLIDER_FAST_AT = 1.0     # after this long of holding, accelerate.
    _SLIDER_REPEAT_SLOW = 0.10
    _SLIDER_REPEAT_FAST = 0.04

    def _menu_display_options(self):
        """Build the list of display strings passed to the menu draw.
        SOUND / MUSIC rows get their current percentage appended live so
        the slider read-out tracks bus changes per frame."""
        out = []
        for opt in self.options:
            if opt == "SOUND":
                pct = int(round(self.app.sfx_bus.level * 100))
                out.append(f"SOUND {pct}%")
            elif opt == "MUSIC":
                pct = int(round(self.app.music_bus.level * 100))
                out.append(f"MUSIC {pct}%")
            else:
                out.append(opt)
        return out

    def _slider_apply(self, direction, play_sound):
        """Apply the ±_SLIDER_STEP nudge to the bus matching whichever
        slider row the cursor is on. play_sound True only on the initial
        edge press — auto-repeat ticks stay silent so a long hold
        doesn't become an annoying menu-tick stream."""
        choice = self.options[self.cursor]
        delta = direction * self._SLIDER_STEP
        if choice == "SOUND":
            if self.app.sfx_bus.adjust_by(delta):
                self.app._apply_sfx_volume()
                self.app.save.volume = self.app.sfx_bus.level
                self._slider_dirty = True
                if play_sound:
                    try: self.app.sounds["menu"].play()
                    except Exception: pass
        elif choice == "MUSIC":
            if self.app.music_bus.adjust_by(delta):
                self.app._apply_music_volume()
                self.app.save.music_volume = self.app.music_bus.level
                self._slider_dirty = True
                if play_sound:
                    try: self.app.sounds["menu"].play()
                    except Exception: pass

    def _handle_slider_input(self, dt, controls):
        """Slider input model: D-pad / left-stick horizontal nudges the
        bus while the cursor is on a SOUND or MUSIC row. First press
        fires immediately; holding triggers auto-repeat after an initial
        delay, accelerating once the hold passes _SLIDER_FAST_AT. Saves
        to disk on release so a continuous hold doesn't hammer the SD
        card with one write per tick."""
        on_slider = (self.cursor < len(self.options)
                     and self.options[self.cursor] in ("SOUND", "MUSIC"))
        if not on_slider:
            # Cursor moved off a slider — flush any pending save and
            # reset the hold state so a future press starts clean.
            if self._slider_dir != 0:
                self._slider_dir = 0
                self._slider_hold_t = 0.0
                if self._slider_dirty:
                    try: self.app.save.save()
                    except Exception: pass
                    self._slider_dirty = False
            return
        cur = (-1 if controls.left else (1 if controls.right else 0))
        if cur != self._slider_dir:
            # Direction change. Flush save if we were just holding,
            # then fire the new direction's edge.
            if self._slider_dir != 0 and self._slider_dirty:
                try: self.app.save.save()
                except Exception: pass
                self._slider_dirty = False
            self._slider_dir = cur
            self._slider_hold_t = 0.0
            self._slider_fires_done = 0
            if cur != 0:
                self._slider_apply(cur, play_sound=True)
                self._slider_fires_done = 1
            return
        if cur == 0:
            return
        # Same direction still held — advance the timer and fire any
        # auto-repeat ticks owed since last frame.
        self._slider_hold_t += dt
        t = self._slider_hold_t
        owed = 0  # number of auto-fires (post-edge) the timer should owe.
        if t > self._SLIDER_INIT_DELAY:
            past = t - self._SLIDER_INIT_DELAY
            if past <= self._SLIDER_FAST_AT - self._SLIDER_INIT_DELAY:
                owed = int(past / self._SLIDER_REPEAT_SLOW) + 1
            else:
                slow_span = self._SLIDER_FAST_AT - self._SLIDER_INIT_DELAY
                slow_fires = int(slow_span / self._SLIDER_REPEAT_SLOW) + 1
                fast_past = past - slow_span
                owed = slow_fires + int(fast_past / self._SLIDER_REPEAT_FAST)
        total_should = 1 + owed  # +1 for the edge fire counted in done.
        while self._slider_fires_done < total_should:
            self._slider_apply(cur, play_sound=False)
            self._slider_fires_done += 1

    def _toggle_channel(self):
        """SELECT+ability: stable ↔ uat. Persists the .uat_channel marker,
        refreshes the in-memory channel so the version stamp colour flips
        immediately, then re-runs the updater against the new channel.
        If anything diffs, restart via autoupdate_apply_restart so the
        new code loads on the new channel."""
        cur = autoupdate_channel()
        new = "uat" if cur == "stable" else "stable"
        self.app.channel = autoupdate_set_channel(new)
        try: self.app.sounds["menu"].play()
        except Exception: pass
        # `force=True` bypasses the Windows-default gate so the user can
        # drive the switch end-to-end from the dev box.
        result = _check_release_update(force=True)
        if result == INSTALL_PENDING_RESTART:
            autoupdate_apply_restart()

    def _manual_update(self):
        """Ability (no SELECT) on the title: kick off the install on a
        background thread so the main loop keeps pumping while the
        4 × ~5 s GitHub fetches run. A toast at the bottom of the title
        reports running → noop / fail / needs_restart so a silent
        failure can't masquerade as 'nothing happened'."""
        if self._install_state == "running":
            return  # Already installing — second press is a no-op.
        try: self.app.sounds["menu"].play()
        except Exception: pass
        self._install_state = "running"
        self._install_t = 0.0
        self._install_target_at_start = getattr(
            self.app, "latest_release_tag", "") or ""
        threading.Thread(target=self._install_worker,
                         daemon=True).start()

    def _install_worker(self):
        """Background fetch + write. On success we ask the main thread
        to execv from a safe point (still on the title) — running execv
        from this daemon while the player is mid-game would be a nasty
        surprise. Files are already on disk either way, so the next
        launch picks them up regardless."""
        try:
            result = _check_release_update(force=True)
        except Exception:
            result = INSTALL_FAIL_NET
        # NOOP with a pending restart means a previous install wrote the
        # new files but the running process is still on the old VERSION.
        # Promote it to PENDING_RESTART so the toast + execv branch fire
        # — without this the toast would say "Already up to date" while
        # the disk has new code waiting for the next boot.
        if result == INSTALL_NOOP and _install_pending_restart():
            result = INSTALL_PENDING_RESTART
        if result == INSTALL_PENDING_RESTART:
            if not self._update_check_stop.is_set():
                # Still on the title — restart now. autoupdate_apply_restart
                # execv's; if it succeeds we won't return here.
                autoupdate_apply_restart()
                # execv failed (rare on Linux). Tell the player to
                # restart manually so they pick up the new files.
                self._install_state = "needs_restart"
            else:
                # Player left the title mid-fetch — defer the restart
                # to the next launch. Files are written; next boot is
                # already the new version.
                self._install_state = "needs_restart"
            self._install_t = 0.0
            return
        mapping = {
            INSTALL_NOOP: "noop",
            INSTALL_FAIL_NET: "fail_net",
            INSTALL_FAIL_WRITE: "fail_write",
            INSTALL_GATED: "gated",
        }
        self._install_state = mapping.get(result, "fail_net")
        self._install_t = 0.0

    def _draw_install_toast(self, screen):
        """Bottom-of-screen status line for the manual install path.
        Visible whenever the state machine isn't idle; auto-clears 3 s
        after settling so the player isn't staring at a stale message."""
        state = self._install_state
        if state == "idle":
            return
        target = self._install_target_at_start or "update"
        if state == "running":
            msg, col = f"Installing {target}…", (140, 200, 255)
        elif state == "noop":
            msg, col = "Already up to date.", (140, 220, 160)
        elif state == "needs_restart":
            msg, col = (f"{target} installed — restart to apply.",
                        (255, 200, 90))
        elif state == "fail_net":
            msg, col = ("Update failed: couldn't reach GitHub.",
                        (240, 110, 110))
        elif state == "fail_write":
            msg, col = ("Update failed: file write blocked.",
                        (240, 110, 110))
        elif state == "gated":
            msg, col = ("Update gated (PEWPEW_AUTOUPDATE=0 or marker).",
                        (180, 180, 180))
        else:
            return
        font = self.app.fonts.get("small") or self.app.fonts["tiny"]
        # Centred above the version stamp / right-edge scale hint so it
        # doesn't fight either for space.
        surf = font.render(msg, False, col)
        bx = (SCREEN_W - surf.get_width()) // 2
        by = SCREEN_H - surf.get_height() - 22
        bg = pygame.Surface((surf.get_width() + 12, surf.get_height() + 6),
                            pygame.SRCALPHA)
        bg.fill((18, 22, 38, 220))
        screen.blit(bg, (bx - 6, by - 3))
        pygame.draw.rect(screen, col,
                         (bx - 6, by - 3,
                          surf.get_width() + 12, surf.get_height() + 6), 1)
        screen.blit(surf, (bx, by))

    # ── Release-notes overlay ──────────────────────────────────────────
    def _mount_release_notes(self):
        """Grab any pending notes off App and prepare a wrapped + scrolled
        view. Empty pending = nothing to mount. Suppressed when the
        player has dismissed THIS exact text already (so a frame-loop
        call doesn't immediately re-pop after close), but a periodic
        refresh that swaps in *different* content (e.g. a new release
        shipped while the player was sitting on the title) will re-pop
        the modal because the dismissed-text no longer matches."""
        if self._notes is not None:
            return
        text = (getattr(self.app, "pending_release_notes", "") or "").strip()
        if not text:
            return
        if self._notes_dismissed and text == self._notes_dismissed_text:
            return
        self._notes = text
        self._notes_scroll = 0
        # Cache the wrap so we don't re-word-wrap every frame; the panel
        # geometry is fixed.
        self._notes_lines_cache = None
        # Fresh content cancels any prior dismiss so the player doesn't
        # see the new modal flicker open and instantly close.
        self._notes_dismissed = False

    def _show_last_release_notes(self):
        """Mount the most recent fetched release-notes from disk so the
        player can re-read what shipped after they've already installed
        it. Called from the title's ability handler when there's no
        pending update.

        Sync refresh path: if the cache is missing OR holds a release
        block older than the running VERSION, do a 3-second synchronous
        fetch of just the latest release body and overwrite the cache
        before mounting. Covers two real races:
          - BG check on title entry hasn't completed before the player
            pressed X (cache might still be the previous session's
            content).
          - BG check's seed fetch failed silently (transient network
            blip) and the staleness path never ran.

        Crucially: we do *not* touch `app.pending_release_notes`.
        That field is reserved for the auto-mount-on-update path; if
        we set it for re-read, every subsequent title entry would
        re-pop the overlay until the user dismissed it again."""
        try:
            text = LAST_NOTES_PATH.read_text(encoding="utf-8")
        except Exception:
            text = ""
        text = text.strip()
        if not text or _cache_is_outdated(VERSION):
            try:
                seed, _t, _e, seed_status = fetch_release_notes_since(
                    "", etag=None, timeout=3)
            except Exception:
                seed_status, seed = CHECK_FAIL, ""
            if seed_status == CHECK_OK and seed:
                _write_release_cache(seed)
                try:
                    text = LAST_NOTES_PATH.read_text(encoding="utf-8").strip()
                except Exception:
                    text = _latest_release_block(seed)
            if not text:
                return
        self._notes = text
        self._notes_scroll = 0
        self._notes_lines_cache = None
        self._notes_dismissed = False
        try: self.app.sounds["menu"].play()
        except Exception: pass

    def _dismiss_release_notes(self):
        """Player closed the overlay without updating. Only suppress for
        this TitleScreen instance — app.pending_release_notes stays set
        so the next return-to-title (Map → START → Title, game over →
        Title, etc.) re-mounts the modal. Reminder keeps coming back
        until the player installs the update; skipped versions
        accumulate naturally because fetch_release_notes_since is keyed
        off the installed VERSION."""
        self._notes_dismissed_text = self._notes or ""
        self._notes = None
        self._notes_scroll = 0
        self._notes_lines_cache = None
        self._notes_dismissed = True
        try: self.app.sounds["menu"].play()
        except Exception: pass

    def _update_check_once(self):
        """Background-thread worker: a single update-check round per
        TitleScreen instance. Holds app.update_check_in_flight True for
        the duration so the title version stamp can blink for the
        ACTUAL fetch duration (replaces the old 0.5 s fixed-window
        blink). ETag conditional makes the check effectively free if
        upstream hasn't changed since the previous title entry."""
        self.app.last_check_ts = time.monotonic()
        self.app.update_check_in_flight = True
        try:
            channel = autoupdate_channel()
            if channel == "stable":
                notes, latest, etag, status = (
                    fetch_release_notes_since(
                        VERSION, etag=self.app.release_etag,
                        timeout=3))
                self.app.last_check_status = status
                self.app.release_etag = etag
                if status == CHECK_OK:
                    self.app.pending_release_notes = notes
                    self.app.latest_release_tag = latest
                    self.app.update_available = bool(notes)
                    # Persist for the re-read overlay. Two paths:
                    #   - notes non-empty: write JUST the most recent
                    #     release block (the player notices "yellow
                    #     title twice" when several releases stack).
                    #   - notes empty + no cache yet: do a one-shot
                    #     fetch with last_seen="" so the cache gets
                    #     seeded with the latest release body on first
                    #     run after upgrading into a build that has
                    #     persistence (v0.9.5 was that build — earlier
                    #     versions never wrote the file).
                    if notes:
                        _write_release_cache(notes)
                    elif _cache_is_outdated(VERSION):
                        # Empty main fetch (we're on the latest) but the
                        # cache file is missing OR holds a release block
                        # older than VERSION. Happens when the user
                        # installed several versions in a row and an
                        # intermediate one was the last to write the
                        # cache. Do a one-shot fetch with last_seen=""
                        # so the seed grabs the actually-latest body.
                        seed, _seed_latest, _seed_etag, seed_status = (
                            fetch_release_notes_since(
                                "", etag=None, timeout=3))
                        if seed_status == CHECK_OK and seed:
                            _write_release_cache(seed)
                # CHECK_NOT_MODIFIED keeps the cached values, which is
                # the whole point of the conditional request.
            else:
                # Bumped the timeout from 3 s to 8 s — the 3 s budget
                # was killing the pewpew.py fetch on slow links and
                # autoupdate_check_available was silently treating that
                # as "no update", which was the title-screen bug the
                # user reported on 2026-05-30.
                result, rv = autoupdate_check_available(timeout=8)
                if result is None:
                    # Network blip — leave whatever the previous probe
                    # reported in place so a flake doesn't toggle the
                    # hint off. Mark the status so the title can decide
                    # whether to render a different message.
                    self.app.last_check_status = CHECK_FAIL
                else:
                    self.app.update_available = result
                    self.app.last_check_status = CHECK_OK
                    if rv:
                        self.app.latest_release_tag = rv
        except Exception:
            pass
        finally:
            self.app.update_check_in_flight = False

    # Overlay panel geometry — fixed so wrap can cache.
    _NOTES_PANEL = (40, 40, SCREEN_W - 80, SCREEN_H - 80)
    _NOTES_PAD = 10
    _NOTES_TITLE_H = 22
    _NOTES_FOOTER_H = 18

    # Tag-driven styling for release-notes lines. Tuple shape:
    #   (font_key, color, indent_px, prefix_text, line_gap_px)
    # font_key is whatever App.fonts accepts (int, "small", or ("7x9", n)).
    # Lines tagged via prefix in the raw notes (=== ===, ##, ### , - , > ,
    # # , [short]...[/short]); the parser maps each to a style key here.
    #
    # Sizes step down through the combined-family height ladder:
    #   5x7×1 7 · 7x9×1 10 · 5x7×2 14 · 7x9×2 20 · 5x7×3 21 · 5x7×4 28 ·
    #   7x9×3 30 · 5x7×5 35 · 7x9×4 40 · 5x7×6 42 · 5x7×7 49
    # so "one size down" can hop between families (e.g. 7x9×2 → 5x7×2).
    _NOTES_STYLES = {
        # Per-release banner — fetcher emits these around every release body.
        "release_header": (3,          (255, 200, 90), 0,  "",   6),
        # [short]...[/short] block — TL;DR for the device. Warm tan colour
        # distinguishes it from body text at the same size.
        "short":          (2,          (255, 235, 190), 0, "",   3),
        # Markdown-ish headings, decreasing emphasis.
        "h1":             (3,          (200, 230, 255), 0, "",   4),
        "h2":             (3,          (220, 240, 255), 0, "",   2),
        "h3":             (2,          (200, 230, 255), 2, "",   1),
        # Quote / callout block.
        "quote":          (2,          (170, 180, 210), 14, "",  0),
        # Bullet at two indent levels (2-space leading = sub-bullet).
        "bullet":         (2,          (220, 220, 230), 6,  "• ", 0),
        "bullet2":        (2,          (200, 210, 220), 22, "› ", 0),
        # Default body.
        "body":           (2,          (200, 200, 210), 0,  "",   0),
        # Sentinel for blank input lines — renders as half-line vertical
        # spacing with no glyph.
        "blank":          (2,          (0, 0, 0),       0,  "",   0),
    }

    def _notes_font_for(self, key):
        """Look up a font key against App.fonts with a chain of fallbacks
        so a missing entry never crashes the overlay."""
        f = self.app.fonts.get(key)
        if f is not None:
            return f
        return (self.app.fonts.get("small")
                or self.app.fonts.get(2)
                or self.app.fonts.get("tiny"))

    def _notes_classify_line(self, raw, state):
        """Map one raw input line to (style_key, text). state carries
        block-level mode (e.g. inside a [short] section). style_key may
        be None for marker lines that emit no output."""
        leading = len(raw) - len(raw.lstrip(" "))
        s = raw.strip()
        if s == "[short]":
            state["mode"] = "short"
            return None, ""
        if s == "[/short]":
            state["mode"] = "body"
            return None, ""
        if not s:
            return "blank", ""
        if state.get("mode") == "short":
            return "short", s
        if s.startswith("=== ") and s.endswith(" ==="):
            return "release_header", s[4:-4]
        if s.startswith("### "):
            return "h3", s[4:]
        if s.startswith("## "):
            return "h2", s[3:]
        if s.startswith("# "):
            return "h1", s[2:]
        if s.startswith("> "):
            return "quote", s[2:]
        if s.startswith("- ") or s.startswith("* "):
            if leading >= 2:
                return "bullet2", s[2:]
            return "bullet", s[2:]
        return "body", s

    def _notes_wrapped_lines(self):
        """Word-wrap the notes — per-style font + indent — into a list of
        (style_key, text) tuples ready for rendering. Cached after first
        call (panel geometry is fixed). Each tuple is one displayed line."""
        if self._notes_lines_cache is not None:
            return self._notes_lines_cache
        px, py, pw, ph = self._NOTES_PANEL
        body_w_full = pw - self._NOTES_PAD * 2
        out = []
        state = {"mode": "body"}
        for raw_line in self._notes.splitlines():
            sk, txt = self._notes_classify_line(raw_line, state)
            if sk is None:
                continue
            if sk == "blank":
                out.append((sk, ""))
                continue
            font_key, color, indent, prefix, _gap = self._NOTES_STYLES[sk]
            font = self._notes_font_for(font_key)
            avail = max(20, body_w_full - indent)
            text = prefix + txt
            words = text.split(" ") if text else [""]
            cur = ""
            for w in words:
                trial = w if not cur else cur + " " + w
                if font.render(trial, False, color).get_width() <= avail:
                    cur = trial
                    continue
                if cur:
                    out.append((sk, cur))
                # Word longer than the line — hard-break by character.
                while len(w) > 1 and font.render(w, False, color).get_width() > avail:
                    lo, hi, fit = 1, len(w), 1
                    while lo <= hi:
                        mid = (lo + hi) // 2
                        if font.render(w[:mid], False, color).get_width() <= avail:
                            fit = mid
                            lo = mid + 1
                        else:
                            hi = mid - 1
                    out.append((sk, w[:fit]))
                    w = w[fit:]
                cur = w
            if cur:
                out.append((sk, cur))
        self._notes_lines_cache = out
        return out

    def _notes_line_height(self, style_key):
        """Pixel height a styled line occupies (font height + 1-px-of-
        scale leading + the style's own extra `gap`). Without the leading
        the BitmapFont's `full_height` butts consecutive lines exactly
        edge-to-edge — at scale 2 the 5x7 body text comes out as a
        block-of-text with no separator. One scale-pixel of leading is
        the minimum that visually separates rows; per-style `gap`
        stacks on top for headers / banners that want a fatter break.
        Blank lines render as half a body-line worth of vertical space."""
        font_key, _color, _indent, _prefix, gap = self._NOTES_STYLES[style_key]
        font = self._notes_font_for(font_key)
        h = (font.full_height if hasattr(font, "full_height")
             else font.render("Ag", False, WHITE).get_height())
        leading = getattr(font, "scale", 1) or 1
        if style_key == "blank":
            return max(4, h // 2)
        return h + leading + gap

    def _notes_total_height(self):
        """Sum of styled line heights — what the body box has to scroll
        through. Caller compares against body_h to compute max scroll."""
        total = 0
        for sk, _text in self._notes_wrapped_lines():
            total += self._notes_line_height(sk)
        return total

    def _scroll_notes(self, delta_lines):
        """Pixel-based scroll: one delta = one body-font line (~14 px) so
        styled headers don't make a single press feel inconsistent. Clamped
        so the bottom anchors when the user holds down at the end."""
        px, py, pw, ph = self._NOTES_PANEL
        body_h = ph - self._NOTES_PAD * 2 - self._NOTES_TITLE_H - self._NOTES_FOOTER_H
        step_px = self._notes_line_height("body")
        total_px = self._notes_total_height()
        max_scroll = max(0, total_px - body_h)
        self._notes_scroll = max(0, min(max_scroll,
                                        self._notes_scroll + delta_lines * step_px))

    def _draw_release_notes(self, screen):
        """Render the modal: dim backdrop, framed panel, title bar,
        scrollable body, footer hint. Lines outside the body box are
        clipped via Surface.set_clip."""
        # Dim everything behind us.
        dim = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        dim.fill((0, 0, 0, 180))
        screen.blit(dim, (0, 0))

        px, py, pw, ph = self._NOTES_PANEL
        # Panel bg + border. Deep near-black-blue so the orange banner
        # and the brighter cyan headers stand out more cleanly than they
        # did against the previous mid-navy.
        bg = pygame.Surface((pw, ph), pygame.SRCALPHA)
        bg.fill((8, 12, 22, 245))
        screen.blit(bg, (px, py))
        pygame.draw.rect(screen, (110, 160, 220), (px, py, pw, ph), 1)

        # Title bar — explains the action. Doesn't show the target tag
        # because the release banner in the body already does (=== vX.Y.Z
        # ... ===) and seeing the version twice reads as a glitch. When
        # the overlay is being shown as a re-read (no pending update),
        # the action label flips from "install" to "close". Chrome font
        # is 5x7 ×2 — one step below the body banner in the height
        # ladder, matches the body text but in cyan.
        title_font = self.app.fonts.get(2) or self.app.fonts.get("small")
        if getattr(self.app, "update_available", False):
            title_txt = "UPDATE AVAILABLE  ·  {btn_ability} to install"
        else:
            title_txt = "LATEST RELEASE NOTES  ·  {btn_ability} to close"
        draw_rich_text(screen, px + self._NOTES_PAD, py + 4, title_txt,
                       self.app.fonts, title_font, (80, 220, 255), anchor="tl")
        pygame.draw.rect(screen, (60, 80, 130),
                         (px + self._NOTES_PAD, py + self._NOTES_TITLE_H + 2,
                          pw - self._NOTES_PAD * 2, 1))

        # Body (clipped). Variable-height styled lines — pixel-based
        # scroll keeps headers/body proportions consistent regardless of
        # which style sits at the scroll boundary.
        body_x = px + self._NOTES_PAD
        body_y = py + self._NOTES_PAD + self._NOTES_TITLE_H
        body_w = pw - self._NOTES_PAD * 2
        body_h = ph - self._NOTES_PAD * 2 - self._NOTES_TITLE_H - self._NOTES_FOOTER_H
        prev_clip = screen.get_clip()
        screen.set_clip(pygame.Rect(body_x, body_y, body_w, body_h))
        lines = self._notes_wrapped_lines()
        # cy walks from body_y - scroll_offset; lines above the box are
        # safely clipped by set_clip, but we early-stop once cy passes
        # body's bottom to skip wasted renders.
        cy = body_y - self._notes_scroll
        bottom = body_y + body_h
        for sk, text in lines:
            font_key, color, indent, _prefix, gap = self._NOTES_STYLES[sk]
            font = self._notes_font_for(font_key)
            glyph_h = (font.full_height if hasattr(font, "full_height")
                       else font.render("Ag", False, color).get_height())
            # Matches the leading bake-in inside _notes_line_height so the
            # scroll bookkeeping and the visible layout stay in lockstep.
            leading = getattr(font, "scale", 1) or 1
            if sk == "blank":
                cy += max(4, glyph_h // 2)
                if cy >= bottom:
                    break
                continue
            # Only render rows that overlap the visible body — keeps cost
            # bounded when the notes are long and the player has scrolled
            # near the bottom.
            if cy + glyph_h > body_y and cy < bottom:
                screen.blit(font.render(text, False, color),
                            (body_x + indent, cy))
            cy += glyph_h + leading + gap
            if cy >= bottom + glyph_h:
                break
        screen.set_clip(prev_clip)

        # Scroll indicator: a tiny up/down arrow when there's more above/below.
        total_h = self._notes_total_height()
        if self._notes_scroll > 0:
            pygame.draw.polygon(screen, (200, 200, 220),
                                [(px + pw - 14, body_y + 6),
                                 (px + pw - 8, body_y + 14),
                                 (px + pw - 20, body_y + 14)])
        if self._notes_scroll + body_h < total_h:
            arrow_y = body_y + body_h - 8
            pygame.draw.polygon(screen, (200, 200, 220),
                                [(px + pw - 14, arrow_y),
                                 (px + pw - 8, arrow_y - 8),
                                 (px + pw - 20, arrow_y - 8)])

        # Footer hint — device-correct. Keyboard pages on Q/E, installs on
        # Enter, closes on Esc; pad scrolls on the d-pad, installs on West
        # (silk), closes on South.
        footer_font = self.app.fonts.get("small") or self.app.fonts["tiny"]
        update_pending = getattr(self.app, "update_available", False)
        if _HINT_DEVICE == "kbd":
            footer_txt = ("Q/E page   Enter: install   Esc: close"
                          if update_pending else "Q/E page   Esc: close")
        elif update_pending:
            footer_txt = ("{dpad} scroll   {btn_ability}: install   "
                          "{btn_fire}: close")
        else:
            footer_txt = "{dpad} scroll   {btn_fire}/{btn_ability}: close"
        draw_rich_text(screen, px + self._NOTES_PAD,
                       py + ph - footer_font.get_height() - 3,
                       footer_txt, self.app.fonts, footer_font,
                       (140, 140, 160), anchor="tl")

    # Auto-repeat tuning for held-d-pad scroll on the notes modal. After
    # this delay the held direction starts auto-scrolling at REPEAT_DT
    # intervals. Tap-to-step (single press) keeps its existing event-
    # driven path so a quick press still moves exactly one step.
    _NOTES_REPEAT_DELAY = 0.30
    _NOTES_REPEAT_DT = 0.05

    def _handle_release_notes_input(self, events, controls):
        """Scroll on d-pad / left-stick / arrows; dismiss on confirm or
        start; ability triggers the install (re-runs the updater and
        re-execs on success). Page-step on shoulders so a long
        changelog isn't a carpal-tunnel exercise. Holding up/down past
        the delay starts continuous scrolling."""
        # Keyboard and pad are decoupled here (the overlay is the one place E
        # means "page down" on the keyboard, which would collide with the
        # West=install reading if we went through the unified action fields).
        for ev in events:
            if ev.type == pygame.KEYDOWN:
                # Keyboard: W/S or arrows scroll a line; Q / E page; Esc closes;
                # Enter installs (when an update is pending) else closes.
                if ev.key in (pygame.K_UP, pygame.K_w):
                    self._scroll_notes(-1)
                elif ev.key in (pygame.K_DOWN, pygame.K_s):
                    self._scroll_notes(+1)
                elif ev.key in (pygame.K_q, pygame.K_PAGEUP):
                    self._scroll_notes(-8)
                elif ev.key in (pygame.K_e, pygame.K_PAGEDOWN):
                    self._scroll_notes(+8)
                elif ev.key == pygame.K_ESCAPE:
                    self._dismiss_release_notes()
                elif ev.key == pygame.K_RETURN:
                    if _install_pending_restart():
                        autoupdate_apply_restart()
                    elif getattr(self.app, "update_available", False):
                        self._manual_update()
                    self._dismiss_release_notes()
            elif ev.type == pygame.JOYHATMOTION:
                _, hy = ev.value
                if hy > 0:
                    self._scroll_notes(-1)
                elif hy < 0:
                    self._scroll_notes(+1)
            elif ev.type == pygame.JOYBUTTONDOWN:
                # Pad: L1/L2 · R1/R2 page; West installs (or closes when there's
                # nothing to install); South / East close.
                if ev.button in (JOY_L1, JOY_L2):
                    self._scroll_notes(-8)
                elif ev.button in (JOY_R1, JOY_R2):
                    self._scroll_notes(+8)
                elif ev.button == BUTTON_SCHEME["ability"][0]:
                    if _install_pending_restart():
                        autoupdate_apply_restart()
                    elif getattr(self.app, "update_available", False):
                        self._manual_update()
                    self._dismiss_release_notes()
                elif ev.button in (BUTTON_SCHEME["fire"][0],
                                   BUTTON_SCHEME["bomb"][0]):
                    self._dismiss_release_notes()
        # Mouse: wheel scrolls the text (~3 lines per notch); RMB ("safe back")
        # closes.
        if controls.wheel_y:
            self._scroll_notes(int(round(-controls.wheel_y)) * 3)
        if controls.rmb_pressed:
            self._dismiss_release_notes()
        # Held-direction auto-repeat. controls.up / controls.down are the
        # unified held-state flags (keyboard arrows, joystick hat, and analog
        # stick all fold into them). Initial press handled above; we only start
        # firing here after _NOTES_REPEAT_DELAY of holding.
        if controls.up or controls.down:
            self._notes_held_t += 1.0 / FPS
            while self._notes_held_t >= self._NOTES_REPEAT_DELAY + self._NOTES_REPEAT_DT:
                self._scroll_notes(-1 if controls.up else +1)
                self._notes_held_t -= self._NOTES_REPEAT_DT
        else:
            self._notes_held_t = 0.0

    def _cycle_profile(self, delta):
        """L1/R1 step the active profile by `delta` (±1) and reload the
        title state for the new slot. Wraps around the 5-name list."""
        try:
            idx = PROFILE_NAMES.index(self.app.profile_name)
        except ValueError:
            idx = 0
        new = PROFILE_NAMES[(idx + delta) % len(PROFILE_NAMES)]
        if new == self.app.profile_name:
            return
        self.app.switch_profile(new)
        self.cursor = 0
        self._rebuild_for_profile()
        try:
            self.app.sounds["menu"].play()
        except Exception:
            pass

    def run(self, events, controls):
        dt = 1.0 / FPS
        self.t += dt
        self.bg_ribbon.update(dt)
        self.stars.update(dt)
        # Tick the install state machine so settled non-running states
        # auto-clear after 3 s and the player isn't staring at a stale
        # toast forever.
        if self._install_state not in ("idle", "running"):
            self._install_t += dt
            if self._install_t > 3.0:
                self._install_state = "idle"
        # Release-notes modal: scroll on d-pad / stick / arrows; dismiss
        # on confirm; nothing else reacts while it's up.
        self._mount_release_notes()
        if self._notes is not None:
            self._handle_release_notes_input(events, controls)
            self._draw()
            if self.outcome is not None:
                self._update_check_stop.set()
            return self.outcome
        menu = MenuInput(controls)
        moved = False
        if menu.up:
            self.cursor = (self.cursor - 1) % len(self.options); moved = True
        if menu.down:
            self.cursor = (self.cursor + 1) % len(self.options); moved = True
        # Special raw keys/buttons NOT in the standard menu action set.
        # Keyboard: Q / E cycle the profile (prev / next); Backspace cycles the
        # dev present mode (was Tab); pad: L1 / R1 cycle profile. Q/E are gated
        # off SELECT (Shift+Q/E are the hidden SEL combos) and off the OVERWRITE
        # modal. `profile_keyed` suppresses the plain-West notes action the same
        # frame E cycles, so pressing E doesn't ALSO open the notes overlay.
        profile_keyed = False
        for ev in events:
            if ev.type == pygame.KEYDOWN:
                if not self._confirm_new_game and not controls.select:
                    if ev.key == pygame.K_q:
                        self._cycle_profile(-1); profile_keyed = True
                    elif ev.key == pygame.K_e:
                        self._cycle_profile(+1); profile_keyed = True
                if ev.key == pygame.K_BACKSPACE and not controls.select:
                    self.app.cycle_scale_mode()
                    try:
                        self.app.sounds["menu"].play()
                    except Exception:
                        pass
            if ev.type == pygame.JOYBUTTONDOWN:
                if ev.button == JOY_L1:
                    self._cycle_profile(-1)
                elif ev.button == JOY_R1:
                    self._cycle_profile(+1)
        if moved:
            # Any d-pad / stick deflection while the OVERWRITE prompt is
            # up dismisses it — the player clearly meant to keep poking
            # the menu, not erase their save.
            if self._confirm_new_game:
                self._confirm_new_game = False
            self.app.sounds["menu"].play()
        # East jumps the cursor to "Quit" (doesn't confirm — the player still
        # presses GO to actually leave). Gated on no SELECT held so it doesn't
        # compete with SEL+East (FPS cycle), and gated off the New-Game
        # OVERWRITE modal so it can't reach in through that.
        if (controls.bomb_pressed
                and not menu.select
                and not self._confirm_new_game
                and "Quit" in self.options):
            quit_idx = self.options.index("Quit")
            if quit_idx != self.cursor:
                self.cursor = quit_idx
                try:
                    self.app.sounds["menu"].play()
                except Exception:
                    pass
        # SOUND / MUSIC slider input — only fires while the cursor is on
        # a slider row and the OVERWRITE modal isn't up.
        if not self._confirm_new_game:
            self._handle_slider_input(1.0 / FPS, controls)
        if self._confirm_new_game:
            # Modal: North commits the wipe; South (GO) cancels. START is not
            # a menu button — it only pauses in-game (see SEL+START combo
            # below, which still reads start_pressed as a modified shortcut).
            if menu.north or controls.mmb_pressed:   # MMB = "destructive back"
                self._start_new_game()
            elif menu.go:
                self._confirm_new_game = False
                try:
                    self.app.sounds["menu"].play()
                except Exception:
                    pass
        elif menu.go:
            choice = self.options[self.cursor]
            if choice == "Continue":
                self.outcome = ("map", None)
            elif choice == "New Game":
                # If the active profile already has progress, ask first —
                # the actual reset happens via Y in the modal branch
                # above.
                if self.has_save and self._save_has_progress():
                    self._confirm_new_game = True
                else:
                    self._start_new_game()
            elif choice == "Quit":
                self.outcome = ("quit", None)
        # Hidden / utility face-button combos. Single if/elif chain so
        # SELECT-modified bindings take precedence over the unmodified
        # ones. Order: channel-toggle > visual-checkup > scale-cycle >
        # plain-cancel (ghost-toggle) > plain-ability (manual update).
        if controls.select and controls.start_pressed:
            # SELECT + START: flip the auto-update channel between
            # stable (latest GitHub release) and uat (master tip),
            # persist the .uat_channel marker, then reload. Moved off
            # SELECT+ability in v0.9.218 so the scale-mode cycle could
            # take the more discoverable SEL+west slot.
            self._toggle_channel()
        elif controls.select and controls.cancel_pressed:
            # Hidden visual-checkup mission (SELECT + north — silk Y
            # on RG, silk X on PC).
            self.outcome = ("play", make_test_level())
        elif controls.select and controls.ability_pressed:
            # SELECT + ability (west face — silk Y on RG, silk X on PC):
            # cycle the dev-machine present mode (the gamepad
            # equivalent of keyboard TAB). Took over from SEL+east in
            # v0.9.218 — west is the more natural mode-cycle slot.
            self.app.cycle_scale_mode()
            try:
                self.app.sounds["menu"].play()
            except Exception:
                pass
        elif controls.select and controls.bomb_pressed:
            # SELECT + bomb (east face — silk A on RG, silk B on PC):
            # cycle the FPS lock. Steam Game Mode on the Legion Go S
            # reports 60Hz to SDL even when the panel is set to 120,
            # so an in-game override that bypasses detection
            # entirely is the only reliable way to actually run at
            # native refresh on that platform.
            self.app.cycle_fps_override()
            try:
                self.app.sounds["menu"].play()
            except Exception:
                pass
        elif (controls.ability_pressed
                and not self._confirm_new_game
                and not profile_keyed):
            # Plain ability/west (no SELECT, no modal). Three roles:
            #   - restart pending → execv straight away (files on
            #     disk are already current; the install would NOOP)
            #   - update available → fire _manual_update (may re-exec)
            #   - no update        → re-open the most recent release
            #                        notes from disk so the player can
            #                        scroll back through what shipped
            if _install_pending_restart():
                try: self.app.sounds["menu"].play()
                except Exception: pass
                autoupdate_apply_restart()
            elif getattr(self.app, "update_available", False):
                self._manual_update()
            else:
                self._show_last_release_notes()
        # Hidden bot-replay shortcut: L2 (avg upgrade path) or R2 (optimal)
        # held + D-pad direction → play back the latest recorded bot run for
        # the matching profile. dpad left=good, up=med, right=bad.
        prof = _gesture_to_profile(controls)
        if prof is not None and _find_replay_path(prof) is not None:
            self.outcome = ("replay_full", prof)
        self._draw()
        # Tell the periodic update-check thread to exit when we're
        # transitioning away — otherwise the daemon would keep polling
        # GitHub every 5 s for the rest of the process.
        if self.outcome is not None:
            self._update_check_stop.set()
        return self.outcome

    def _draw(self):
        screen = self.app.screen
        screen.fill(BLACK)
        self.bg_ribbon.draw(screen)
        self.stars.draw(screen)

        # --- LOGO --------------------------------------------------------
        logo_el = get_element("title", "logo")
        if logo_el is not None:
            logo = self.app.logo
            scale = float(logo_el.get("scale", 1.0))
            if abs(scale - 1.0) > 0.001:
                sw, sh = logo.get_size()
                logo = pygame.transform.smoothscale(
                    logo, (max(1, int(sw * scale)), max(1, int(sh * scale))))
            anchor = logo_el.get("anchor", "c")
            ax = _LAYOUT_ANCHOR_AX.get(anchor, 0.5)
            ay = _LAYOUT_ANCHOR_AY.get(anchor, 0.5)
            lw, lh = logo.get_size()
            lx = int(logo_el.get("x", SCREEN_W // 2)) - int(lw * ax)
            ly = int(logo_el.get("y", 130)) - int(lh * ay)
            logo_rect = pygame.Rect(lx, ly, lw, lh)
            # Glossy light-wave sweep across the title's editor-defined hitbox,
            # masked so only the YELLOW areas of the logo brighten.
            entry = self.app.assets.get("_engine_data", {}).get("title", {})
            hitbox = entry.get("hitbox")
            stripe = self.app.title_gloss_stripe
            yellow_mask = self.app.title_yellow_mask
            # Sweep math + hitbox are baked at the original (unscaled) logo
            # size, so skip the gloss when the user has scaled the logo away
            # from 1.0× — a plain blit is the safer fallback.
            yellow_dim = self.app.title_yellow_dim
            # Clip the hitbox to actual logo bounds — a sprite-editor edit
            # can push the rect past the edge, which makes subsurface() raise.
            clipped_hitbox = None
            if hitbox:
                hx, hy, hw, hh = hitbox
                clipped = pygame.Rect(int(hx), int(hy), max(1, int(hw)),
                                       max(1, int(hh))).clip(logo.get_rect())
                if clipped.w > 0 and clipped.h > 0:
                    clipped_hitbox = clipped
            if (clipped_hitbox is not None and stripe is not None
                    and yellow_mask is not None and yellow_dim is not None
                    and abs(scale - 1.0) < 0.001):
                hx, hy, hw, hh = (clipped_hitbox.x, clipped_hitbox.y,
                                  clipped_hitbox.w, clipped_hitbox.h)
                stripe_w = stripe.get_width()
                # Cadence: two back-to-back sweeps, then a fixed 1s rest.
                # Total cycle = 2*sweep_dur + rest_dur (not a fixed period).
                sweep_dur = 0.9
                rest_dur = 1.0
                group_period = sweep_dur * 2 + rest_dur
                travel = hw + stripe_w * 2
                local_t = self.t % group_period
                if local_t < sweep_dur * 2:
                    cycle = (local_t % sweep_dur) / sweep_dur
                    stripe_x = int(cycle * travel) - stripe_w
                else:
                    stripe_x = None  # rest gap: dim stays, no boost
                mask_rect = pygame.Rect(hx, hy, hw, hh).clip(
                    yellow_mask.get_rect())
                # Build a per-pixel brightness multiplier (factor) sized to
                # the hitbox. Yellow pixels go to 64 (25%) by default and
                # rise back up toward 255 (100%) under the moving stripe;
                # non-yellow pixels stay at 255 (unchanged).
                factor = pygame.Surface((hw, hh)).convert()
                factor.fill((255, 255, 255))
                if mask_rect.w > 0 and mask_rect.h > 0:
                    # Dim yellow pixels to 64.
                    factor.blit(yellow_dim.subsurface(mask_rect),
                                (mask_rect.x - hx, mask_rect.y - hy),
                                special_flags=pygame.BLEND_SUB)
                    if stripe_x is not None:
                        # Boost (only on yellow) brings them back toward 255.
                        boost = pygame.Surface((hw, hh)).convert()
                        boost.fill((0, 0, 0))
                        boost.blit(stripe, (stripe_x, 0))
                        boost.blit(yellow_mask.subsurface(mask_rect),
                                   (mask_rect.x - hx, mask_rect.y - hy),
                                   special_flags=pygame.BLEND_MULT)
                        factor.blit(boost, (0, 0),
                                    special_flags=pygame.BLEND_ADD)
                glossed = logo.copy()
                glossed.subsurface((hx, hy, hw, hh)).blit(
                    factor, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
                screen.blit(glossed, logo_rect)
            else:
                screen.blit(logo, logo_rect)
            # CRT distortion on the title logo — same tear / chroma-
            # band / scanline effect as the dead-pause overlay in
            # PlayState, scoped to the logo rect so the menu
            # underneath stays readable. Intensity pulses 0.35→0.55
            # so the title doesn't feel static while the player
            # decides.
            if (self._title_logo_glitch_overlay is None
                    or self._title_logo_glitch_overlay.get_size()
                        != (logo_rect.w, logo_rect.h)):
                self._title_logo_glitch_overlay = _build_crt_scanline_overlay(
                    logo_rect.w, logo_rect.h, _CRT_PROFILE_TITLE)
            pulse = 0.35 + 0.20 * (0.5 + 0.5 * math.sin(self.t * 3.0))
            _apply_crt_glitch(
                screen,
                (logo_rect.x, logo_rect.y, logo_rect.w, logo_rect.h),
                pulse,
                profile=_CRT_PROFILE_TITLE,
                scanline_cache=self._title_logo_glitch_overlay)

        # --- MENU --------------------------------------------------------
        menu_el = get_element("title", "menu")
        if menu_el is not None:
            menu_el = dict(menu_el)
            menu_el["_preview_cursor"] = self.cursor
            _layout_draw_menu(screen, menu_el, self.app.fonts,
                              options=self._menu_display_options())

        # --- TIP (blinks) ------------------------------------------------
        tip_el = get_element("title", "tip", **button_label_vars())
        if tip_el is not None and (not tip_el.get("blink", True)
                                   or int(self.t * 2) % 2 == 0):
            _draw_text_with_dpad(screen, tip_el, self.app.fonts)

        # --- PROFILE NAME + L1/R1 hint -----------------------------------
        # Driven by the layout system so position/font/color are editable.
        # The text template carries the L1/R1 hints inline with the
        # interpolated {profile_name}, so the whole line is one element.
        prof_el = get_element("title", "profile",
                              profile_name=self.app.profile_name)
        if prof_el is not None:
            _layout_draw_text(screen, prof_el, self.app.fonts)

        draw_layout_overlay(screen, "title", self.app.fonts, self.app.assets)

        # "OVERWRITE PROGRESS?" confirmation modal — only when New Game
        # was picked on a profile that has saved progress.
        if self._confirm_new_game:
            self._draw_confirm_new_game(screen)

        # Version stamp in the bottom-left so the player can see at a
        # glance that the auto-update pulled a fresh build. Drawn last so
        # nothing else (vignette etc.) overlays it.
        # Use the scale-2 "small" font so the version reads at arm's length
        # on the handheld — scale-1 "tiny" was legible on a desktop monitor
        # but a 3-character build stamp at 3 px tall got lost on the device.
        ver_font = self.app.fonts.get("small") or self.app.fonts["tiny"]
        # Red on UAT so the player sees at a glance they're on the master-
        # tip channel; grey on stable. App.channel is refreshed by the
        # SELECT+ability toggle so the colour flips live.
        _ch = getattr(self.app, "channel", "stable")
        if _ch != "stable":
            # Red on any non-stable channel; label it so the player knows which
            # tip they track — "UAT" for master, the branch name otherwise.
            _lbl = "UAT" if _ch == "uat" else _ch.upper()
            ver_text, ver_color = f"v{VERSION} {_lbl}", (220, 60, 60)
        else:
            ver_text, ver_color = f"v{VERSION}", DIM
        # "Checking for updates" indicator: while the background fetch
        # is in flight, smoothly pulse the version stamp's alpha between
        # 1.0 (fully solid) and 0.5 (half-faded — never to 0 because a
        # disappearing stamp reads like a glitch). cos(2π·f·t) starts
        # at 1.0 so the first frame after the worker fires is at full
        # opacity. ~1 Hz feels like a slow heartbeat — easy to register
        # without being distracting.
        stamp_alpha = 255
        if getattr(self.app, "update_check_in_flight", False):
            since_check = time.monotonic() - getattr(
                self.app, "last_check_ts", time.monotonic())
            since_check = max(0.0, since_check)
            wave = math.cos(since_check * (2.0 * math.pi))   # 1 Hz, starts at 1
            alpha_f = 0.75 + 0.25 * wave                      # 0.5 .. 1.0
            stamp_alpha = max(128, min(255, int(255 * alpha_f)))
        ver_surf = ver_font.render(ver_text, False, ver_color)
        ver_x, ver_y = 6, SCREEN_H - ver_surf.get_height() - 4
        if stamp_alpha < 255:
            ver_surf.set_alpha(stamp_alpha)
        screen.blit(ver_surf, (ver_x, ver_y))
        # Update / restart hint next to the version stamp. Two cases:
        #   - install pending  → "  ({btn_ability}: INSTALL X.Y.Z)"
        #   - restart pending  → "  ({btn_ability}: RESTART)"
        # The pictogram in {btn_ability} stays a silk glyph (rich-text
        # renders the face button per platform); only the verb label
        # changes. RESTART beats INSTALL — once a previous install
        # wrote new files but didn't re-exec, hitting West should pick
        # up that pending state rather than re-running the install
        # (which would NOOP).
        hint_x = ver_x + ver_surf.get_width()
        if _install_pending_restart():
            rect = draw_rich_text(screen, hint_x, ver_y,
                                  "  ({btn_ability}: RESTART)",
                                  self.app.fonts, ver_font, (255, 200, 90),
                                  anchor="tl", alpha=stamp_alpha)
            hint_x = rect.right
        elif getattr(self.app, "update_available", False):
            tag = (getattr(self.app, "latest_release_tag", "") or "").strip()
            # Strip a leading "v" if the release tag carried one, so we
            # always render "INSTALL 0.9.420" not "INSTALL v0.9.420".
            if tag.startswith("v"):
                tag = tag[1:]
            label = (f"  ({{btn_ability}}: INSTALL {tag})" if tag
                     else "  ({btn_ability}: INSTALL)")
            rect = draw_rich_text(screen, hint_x, ver_y, label,
                                  self.app.fonts, ver_font, (255, 200, 90),
                                  anchor="tl", alpha=stamp_alpha)
            hint_x = rect.right
        # Check-status hint — surfaces a silent rate-limit or generic
        # network failure so the player isn't left wondering why no
        # overlay appears. Stays at full opacity so the warning is
        # never half-faded.
        status = getattr(self.app, "last_check_status", "init")
        if EMSCRIPTEN:
            # The web build has no update mechanism — the page is always the
            # latest deploy — so the gated-off probe's CHECK_FAIL is expected,
            # not a warning. Suppress the hint rather than show "check fail".
            msg = None
        elif status == CHECK_RATE_LIMITED:
            msg, col = "  rate limit", (240, 180, 80)
        elif status == CHECK_FAIL:
            msg, col = "  check fail", (220, 100, 100)
        else:
            msg = None
        if msg:
            hint = ver_font.render(msg, False, col)
            screen.blit(hint, (hint_x, ver_y))

        # Scale-mode hint, bottom-right. Shown on every non-RG path —
        # the RG mali fullscreen runs at logical 640x480 and never
        # goes through _present(), so the toggle is a no-op there.
        # Used to be gated on `display.get_size() != (640, 480)`, but
        # the vrr mode sets the display TO (640, 480) for its SCALED
        # renderer — the hint would vanish exactly in the mode where
        # the player needs to see what's active. `not on_device` is
        # the correct gate: shows on PC + Steam Deck (which need it),
        # hidden on RG (where it doesn't do anything).
        if not getattr(self.app, "on_device", False):
            mode = getattr(self.app, "scale_mode", "integer")
            # SEL+ability (west face) is the scale-mode cycle as of
            # v0.9.218 — moved from SEL+east. Read the silk letter
            # off BUTTON_SCHEME so the hint matches whichever
            # controller layout is active.
            override = SaveData.load_fps_override()
            fps_state = f"{override}Hz" if override else "auto"
            scale_txt = "SEL+{btn_ability}: scale (" + mode + f") @ {FPS}Hz"
            fps_txt = "SEL+{btn_bomb}: fps (" + fps_state + ")"
            lh = ver_font.get_height()
            # Stack the two hint lines bottom-up (right-anchored).
            draw_rich_text(screen, SCREEN_W - 6, SCREEN_H - lh - 4,
                           scale_txt, self.app.fonts, ver_font, DIM, anchor="tr")
            draw_rich_text(screen, SCREEN_W - 6, SCREEN_H - 2 * lh - 4,
                           fps_txt, self.app.fonts, ver_font, DIM, anchor="tr")

        # Release-notes overlay sits on top of everything (incl. the
        # version stamp + confirm modal — we suspend everything-else
        # input while it's up, so co-existing with another modal is a
        # non-issue here).
        if self._notes is not None:
            self._draw_release_notes(screen)

        # Install status toast — visible whenever the install state
        # machine isn't idle. Drawn after the release-notes overlay so
        # "Installing…" can show on top of the modal (the player just
        # pressed install from inside it).
        self._draw_install_toast(screen)

    def _draw_confirm_new_game(self, screen):
        """Dim-the-screen modal: 'OVERWRITE PROGRESS?' + a face-button hint
        whose silk letters track the active platform (RG silk X/B vs
        Steam Deck silk Y/A — north confirms, south cancels)."""
        fonts = self.app.fonts
        title_font = fonts.get("big") or fonts["small"]
        body_font = fonts.get("small") or fonts["tiny"]
        title_surf = title_font.render("OVERWRITE PROGRESS?", False, YELLOW)
        prof = self.app.profile_name
        sub_surf = body_font.render(f"Profile \"{prof}\" has saved progress.",
                                    False, WHITE)
        # {btn_cancel}=north face confirms (wipes), {btn_fire}=south cancels.
        hint_txt = "{btn_cancel} to confirm    {btn_fire} to cancel"
        hint_w = _measure_rich(hint_txt, fonts, body_font)
        hint_h = body_font.get_height()
        # Panel sized to the widest line + padding.
        w = max(title_surf.get_width(), sub_surf.get_width(), hint_w) + 48
        h = title_surf.get_height() + sub_surf.get_height() + hint_h + 56
        # Full-screen dim behind the panel so the menu underneath fades.
        dim = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        dim.fill((0, 0, 0, 160))
        screen.blit(dim, (0, 0))
        # Panel.
        panel = pygame.Surface((w, h), pygame.SRCALPHA)
        panel.fill((20, 24, 44, 235))
        pygame.draw.rect(panel, (220, 180, 80, 255), (0, 0, w, h), 2)
        y = 14
        for surf in (title_surf, sub_surf):
            panel.blit(surf, ((w - surf.get_width()) // 2, y))
            y += surf.get_height() + 12
        draw_rich_text(panel, w // 2, y, hint_txt, fonts, body_font, DIM,
                       anchor="t")
        screen.blit(panel, ((SCREEN_W - w) // 2, (SCREEN_H - h) // 2))


# GameOverScreen removed (v0.9.291): a loss now ends like any level end and
# drops the player straight into the shop (App._transition post_play, won=False
# → ShopScreen) instead of a separate SHIP LOST screen.


# =============================================================================
# BOT REPLAY VIEWER
# =============================================================================
#
# Reader for the binary replay format written by tuning/bot/replay.py.
# Inlined here so the device-side game (which doesn't ship the tuning/
# package) can play replays without depending on that import.

REPLAYS_DIR = Path(__file__).resolve().parent / "replays"


def _replay_bits_to_controls(c, b):
    c.reset_pulses()
    c.left              = bool(b & (1 << 0))
    c.right             = bool(b & (1 << 1))
    c.up                = bool(b & (1 << 2))
    c.down              = bool(b & (1 << 3))
    c.fire              = bool(b & (1 << 4))
    c.bomb_pressed      = bool(b & (1 << 5))
    c.ability_pressed   = bool(b & (1 << 6))
    c.confirm_pressed   = bool(b & (1 << 7))
    c.cancel_pressed    = bool(b & (1 << 8))
    c.start_pressed     = bool(b & (1 << 9))
    c.select            = bool(b & (1 << 10))
    c.start             = bool(b & (1 << 11))


def _read_replay_file(path):
    """Parse a .bin replay. Returns (seed, profile, [block, ...])."""
    data = Path(path).read_bytes()
    o = 0
    if data[o:o + 4] != b"PWRP":
        raise ValueError("not a pewpew replay")
    o += 4
    version, seed = struct.unpack_from("<IQ", data, o); o += 12
    if version != 1:
        raise ValueError(f"unsupported replay version {version}")
    (prof_len,) = struct.unpack_from("<H", data, o); o += 2
    profile = data[o:o + prof_len].decode("utf-8"); o += prof_len
    blocks = []
    while o < len(data):
        (marker,) = struct.unpack_from("<I", data, o); o += 4
        if marker != 0xC001:
            raise ValueError(f"unexpected marker 0x{marker:08X} at {o}")
        level_key = data[o:o + 4].decode("ascii").strip(); o += 4
        (attempt,) = struct.unpack_from("<I", data, o); o += 4
        (meta_len,) = struct.unpack_from("<I", data, o); o += 4
        meta = json.loads(data[o:o + meta_len].decode("utf-8")); o += meta_len
        (frame_count,) = struct.unpack_from("<I", data, o); o += 4
        frames = list(struct.unpack_from(f"<{frame_count}H", data, o))
        o += 2 * frame_count
        (trailer,) = struct.unpack_from("<I", data, o); o += 4
        if trailer != 0xC002:
            raise ValueError(f"bad trailer at {o}")
        won, score = struct.unpack_from("<BI", data, o); o += 5
        blocks.append({
            "level_key": level_key,
            "attempt": attempt,
            "meta": meta,
            "frames": frames,
            "won": bool(won),
            "score": score,
        })
    return seed, profile, blocks


def _per_level_seed_for_replay(base_seed, level_key, attempt):
    """Mirror tuning.bot.session._per_level_seed — used as a fallback when a
    replay file (recorded by an older session writer) doesn't carry its own
    per_level_seed entry."""
    try:
        n = int(level_key[1:])
    except (ValueError, IndexError):
        n = 0
    s = (int(base_seed) * 2654435761) & 0xFFFFFFFF
    s ^= (n * 7919) & 0xFFFFFFFF
    s ^= (int(attempt) * 1597) & 0xFFFFFFFF
    return s & 0xFFFFFFFF


# Boss-tier unlock schedule. Each boss level (L010..L090) unlocks one
# main-weapon tier; the cascade rule means once all three main weapons
# have a given tier, side / shield / engine catch up to that tier too.
# Boss 10 (L100) is the final boss — nothing left to unlock.
_BOSS_MAIN_UNLOCKS = {
    10: ("rail",   3), 20: ("ball",   3), 30: ("vulcan", 3),
    40: ("rail",   4), 50: ("ball",   4), 60: ("vulcan", 4),
    70: ("rail",   5), 80: ("ball",   5), 90: ("vulcan", 5),
}
_CASCADE_CATS = ("missile", "drone", "shield", "engine")


def _apply_boss_unlocks(save, level_key):
    """Mutate `save` to apply boss-tier unlocks + cascade. Returns the
    list of (category, new_tier) actually unlocked this call (skipping
    ones already at or beyond that tier). The returned list is the
    sequence ShopScreen should reveal one-by-one."""
    try:
        n = int(level_key[1:])
    except (ValueError, IndexError):
        return []
    info = _BOSS_MAIN_UNLOCKS.get(n)
    if info is None:
        return []
    wtype, new_tier = info
    pending = []
    attr = f"unlocked_tier_{wtype}"
    if getattr(save, attr, 2) < new_tier:
        setattr(save, attr, new_tier)
        pending.append((wtype, new_tier))
    # Cascade: side / shield / engine T(N) unlocks the instant all 3 main
    # weapons have T(N).
    main_tiers = (save.unlocked_tier_rail,
                  save.unlocked_tier_ball,
                  save.unlocked_tier_vulcan)
    if all(t >= new_tier for t in main_tiers):
        for cat in _CASCADE_CATS:
            cat_attr = f"unlocked_tier_{cat}"
            if getattr(save, cat_attr, 2) < new_tier:
                setattr(save, cat_attr, new_tier)
                pending.append((cat, new_tier))
    return pending


def _shop_key_for_cat(cat):
    """Map a tier-unlock category (e.g. 'rail', 'shield') to its
    SHOP_ITEMS key ('main_rail', 'shield')."""
    if cat in ("rail", "ball", "vulcan"):
        return f"main_{cat}"
    if cat in ("missile", "drone"):
        return f"side_{cat}"
    return cat   # shield / engine


def _unlocked_tier_for(save, shop_key):
    """Map a SHOP_ITEMS key to its unlocked-tier counter on the save.
    Returns 5 (max) for keys that don't have tier locking (bomb, ability)."""
    mapping = {
        "main_rail":    save.unlocked_tier_rail,
        "main_ball":    save.unlocked_tier_ball,
        "main_vulcan":  save.unlocked_tier_vulcan,
        "side_missile": save.unlocked_tier_missile,
        "side_drone":   save.unlocked_tier_drone,
        "shield":       save.unlocked_tier_shield,
        "engine":       save.unlocked_tier_engine,
    }
    return mapping.get(shop_key, 5)


def _gesture_to_profile(controls):
    """Decode L2/R2 + dpad-direction into a profile name. Returns None when
    no gesture is in flight this frame."""
    if not (controls.l2_held or controls.r2_held):
        return None
    if controls.dpad_left_pressed:    skill = "good"
    elif controls.dpad_up_pressed:    skill = "med"
    elif controls.dpad_right_pressed: skill = "bad"
    else:
        return None
    path = "avg" if controls.l2_held else "optimal"
    return f"{skill}_{path}"


def _find_replay_path(profile_name):
    """Path to replays/replay-<profile>.bin, with device fallback.

    On the dev machine all 6 profile replays sit in replays/, so each gesture
    finds its own. On the device we deploy only the longest-path "canonical"
    profile, so we fall back to whatever single replay-*.bin is present
    rather than silently no-op'ing — the user gets to see THE bot run
    regardless of which gesture they did.
    """
    p = REPLAYS_DIR / f"replay-{profile_name}.bin"
    if p.is_file():
        return p
    if not REPLAYS_DIR.is_dir():
        return None
    candidates = sorted(REPLAYS_DIR.glob("replay-*.bin"))
    return candidates[0] if candidates else None


def _replay_has_level(path, level_key):
    """True iff the replay contains a block for `level_key`. Replay files
    are ~50 KB so a full parse here costs nothing."""
    try:
        _seed, _prof, blocks = _read_replay_file(path)
    except Exception:
        return False
    target = level_key.strip()
    return any(b["level_key"].strip() == target for b in blocks)


class ReplayState:
    """Plays back a recorded bot run.

    Modes:
      single_level_key=None  → run all blocks back-to-back (title shortcut)
      single_level_key="L042" → just that one level (map shortcut)

    Per-level flow:
      shop_view (ShopScreen, user presses Y to dismiss)
        → playing (PlayState driven by recorded inputs)
        → (next block, if any) → shop_view  OR  done

    Determinism: each level seeds random with the per_level_seed recorded
    in the block's metadata (falling back to a derived seed for older
    replay files). The recorded inputs are fed straight into the same
    Controls structure the live game uses, so the playback retraces the
    bot's path frame-for-frame.
    """

    def __init__(self, app, replay_path, single_level_key=None,
                 return_to="title"):
        self._bits_to_controls = _replay_bits_to_controls

        self.app = app
        self.return_to = return_to
        self.outcome = None
        self.banner_t = 1.4         # seconds of "REPLAY: <profile>" overlay
        try:
            self.seed, self.profile, blocks = _read_replay_file(replay_path)
        except Exception as e:
            print(f"[replay] failed to read {replay_path}: {e!r}")
            self.outcome = (return_to, None)
            self.seed, self.profile, blocks = 0, "?", []

        if single_level_key:
            blocks = [b for b in blocks if b["level_key"] == single_level_key]
        self.blocks = blocks
        self.block_idx = 0
        self.frame_idx = 0
        self.play_state = None
        self.shop_state = None
        self.replay_controls = Controls()
        self.phase = "shop_view" if blocks else "done"

        if blocks:
            self._restore_save(blocks[0]["meta"].get("save", {}))
            self.shop_state = ShopScreen(app)

    # ---------- state helpers ----------

    def _restore_save(self, save_dict):
        save = self.app.save
        save.credits = int(save_dict.get("credits", save.credits))
        save.completed = list(save_dict.get("completed", save.completed))
        save.unlocked = list(save_dict.get("unlocked", save.unlocked))
        lo = save_dict.get("loadout") or {}
        for k, v in lo.items():
            if hasattr(save.loadout, k):
                try:
                    setattr(save.loadout, k, v)
                except Exception:
                    pass

    def _enter_playing(self):
        block = self.blocks[self.block_idx]
        meta = block.get("meta", {})
        seed = meta.get("per_level_seed")
        if seed is None:
            seed = _per_level_seed_for_replay(
                self.seed, block["level_key"], block.get("attempt", 1))
        random.seed(int(seed) & 0xFFFFFFFF)
        level_key = block["level_key"]
        level = self.app.levels.get(level_key)
        if level is None:
            self._advance_block()
            return
        self.play_state = PlayState(self.app, level)
        self.frame_idx = 0
        self.phase = "playing"

    def _advance_block(self):
        self.block_idx += 1
        if self.block_idx >= len(self.blocks):
            self.phase = "done"
            return
        block = self.blocks[self.block_idx]
        self._restore_save(block.get("meta", {}).get("save", {}))
        self.shop_state = ShopScreen(self.app)
        self.phase = "shop_view"

    # ---------- frame ----------

    def run(self, events, controls):
        if self.banner_t > 0:
            self.banner_t -= 1.0 / FPS

        if self.phase == "shop_view":
            # Render the real shop; ignore its outcome (we drive transitions).
            self.shop_state.run(events, controls)
            self.shop_state.outcome = None
            if controls.cancel_pressed:
                self._enter_playing()
        elif self.phase == "playing":
            block = self.blocks[self.block_idx]
            frames = block.get("frames", [])
            if self.frame_idx < len(frames):
                self._bits_to_controls(self.replay_controls,
                                       frames[self.frame_idx])
                self.frame_idx += 1
            else:
                # Out of recorded inputs: hold neutral so the PlayState
                # finishes whatever cinematic / death animation is in flight.
                self.replay_controls.reset_pulses()
                self.replay_controls.left = self.replay_controls.right = False
                self.replay_controls.up = self.replay_controls.down = False
                self.replay_controls.fire = False
            self.play_state.run(events, self.replay_controls)
            ps_done = self.play_state.outcome is not None
            frames_done = self.frame_idx >= len(frames)
            if ps_done or (frames_done and self.frame_idx > 0):
                # Force-end if we exhausted frames but the state hangs on
                # (e.g. determinism drift left enemies alive past the cap).
                self._advance_block()

        # Always-on overlay banner during playback so the user can tell.
        self._draw_overlay()

        if self.phase == "done":
            self.outcome = (self.return_to, None)
        return self.outcome

    def _draw_overlay(self):
        # Top-left "REPLAY: <profile>" pill; visible briefly then dims.
        if self.banner_t <= 0:
            return
        fonts = self.app.fonts
        font = fonts.get("small") or fonts.get(2)
        if font is None:
            return
        text = f"REPLAY · {self.profile}"
        surf = font.render(text, False, (240, 240, 240))
        pad = 4
        bg = pygame.Surface((surf.get_width() + pad * 2,
                             surf.get_height() + pad * 2), pygame.SRCALPHA)
        a = max(0, min(255, int(255 * (self.banner_t / 1.4))))
        bg.fill((20, 30, 60, min(220, a)))
        self.app.screen.blit(bg, (12, 12))
        if a < 255:
            surf.set_alpha(a)
        self.app.screen.blit(surf, (12 + pad, 12 + pad))


# =============================================================================
# GPU RENDER BACKEND  (pure-GPU path — branch gpu-mt-spike)
# =============================================================================
#
# Hardware-accelerated rendering via pygame._sdl2. The software-Surface path
# (App.screen + blits + pygame.draw, presented through SCALED's GPU upscale)
# stays the default + fallback; this backend issues GPU draws instead, so the
# A55 cores stop doing per-pixel compositing.
#
# Why a from-scratch backend rather than "upload the finished software frame to
# one texture" — that's exactly what SCALED already does, and it wins nothing
# because the CPU still composited the frame. The win only comes from drawing
# NATIVELY on the GPU. SDL_Renderer draws textured quads + lines + filled rects;
# it exposes NO filled-polygon/circle/geometry call in pygame 2.x, so procedural
# shapes (cooldown arcs, gradient bands, rays) are BAKED to a texture once
# (rendered in software) and then drawn as quads — animated fills become a
# bottom-aligned source-rect crop of the baked texture. Multi-pass effects (the
# CRT scroll glitch) use a render-to-target texture.
#
# Measured throughput (2026-06-08, on-device):
#   - RGB10 Max3 (libmali, SDL 2.32 — batched renderer): ~3.5x the software blit
#     path; 1000 quads/4.4ms. Big win.
#   - RG35XX Pro (mali, SDL 2.0.12 — NO batched renderer): draw-call bound, so
#     the per-quad win is small; value is offloading the weak CPU. 600 rotated
#     quads sustain 60fps. Minimize draw calls / atlas where possible.

class GpuRenderer:
    """Thin, game-shaped wrapper over a pygame._sdl2 Window + Renderer.

    Coordinates are the logical 640x480 (or PLAY) space; the renderer's
    logical_size makes the GPU scale to the panel (replacing SCALED). All
    drawing is textured quads + fill_rect + lines; procedural fills come in as
    pre-baked textures (see `baked`). Holds two texture caches: `upload`/`get`
    for static assets (uploaded once at load), `baked` for procedural shapes."""

    def __init__(self, logical_size, fullscreen=True, vsync=True, title="Pewpew",
                 hidden=False, from_display=False, window_size=None, resizable=False):
        from pygame._sdl2 import video as _sdl2_video
        self._v = _sdl2_video
        w, h = int(logical_size[0]), int(logical_size[1])
        # The on-screen window can be bigger than the logical render size; the
        # renderer's logical_size (set below) scales content to fill it. Used by
        # the desktop/SteamOS windowed path (logical 640x480, larger window).
        ww, wh = (int(window_size[0]), int(window_size[1])) if window_size else (w, h)
        if from_display:
            # Wrap the window pygame.display.set_mode() already created. REQUIRED
            # for the real App: set_mode establishes the video mode that
            # Surface.convert/convert_alpha (and therefore make_assets' sprite
            # loading) depend on — a bare _sdl2 Window does NOT, so sprites would
            # silently fall back to procedural. The caller must set_mode first.
            self.window = self._v.Window.from_display_module()
        elif hidden:
            # Offscreen context for headless validation / screenshot readback.
            # (Pair with a prior set_mode((w,h), HIDDEN) so convert works.)
            self.window = self._v.Window(title, size=(w, h), hidden=True)
        elif fullscreen:
            try:
                self.window = self._v.Window(title, size=(ww, wh),
                                             fullscreen_desktop=True)
            except Exception:
                self.window = self._v.Window(title, size=(ww, wh))
        else:
            self.window = self._v.Window(title, size=(ww, wh), resizable=resizable)
        # Try richest renderer first, degrade gracefully: vsync + target
        # textures are both optional capabilities on older SDLs.
        self.renderer = None
        for kw in ({"accelerated": True, "vsync": bool(vsync), "target_texture": True},
                   {"accelerated": True, "target_texture": True},
                   {"accelerated": True}):
            try:
                self.renderer = self._v.Renderer(self.window, **kw)
                break
            except Exception:
                continue
        if self.renderer is None:
            raise RuntimeError("no accelerated SDL renderer available")
        try:
            self.renderer.logical_size = (w, h)
        except Exception:
            pass
        # Alpha-blend fill_rect/draw_rect/line (so translucent primitives like
        # the laser glow / ray fade actually blend). Texture blits carry their
        # own per-texture blend_mode; clear() ignores this.
        try:
            self.renderer.draw_blend_mode = 1  # SDL_BLENDMODE_BLEND
        except Exception:
            pass
        self.size = (w, h)
        self._tex = {}      # key -> Texture (static asset uploads)
        self._baked = {}    # key -> Texture (procedural fills, built once)
        # id(surface) -> (Texture, surface) identity cache, LRU-CAPPED. It holds
        # a ref to each surface (so its id stays valid), which means a churn of
        # DISTINCT transient surfaces (per-frame scaled sprites / rendered text /
        # flash tints) would otherwise leak textures+surfaces forever — that
        # OOM'd a long replay (RSS 190MB -> 600MB+). The cap evicts the least-
        # recently-used so hot shared assets (touched every frame) stay while
        # one-shot surfaces are dropped and freed.
        self._dyn = {}
        self._dyn_cap = 2048
        self._disc_tex = None   # lazy unit filled-circle texture
        self._tri_tex = None    # lazy unit downward-triangle texture
        self._dynamic = {}      # key -> (Texture, (w,h)) streaming overlay cache
        # Global integer translation added to every primitive's destination by
        # the wrappers below (+ the raw stars/bullets/particles hot loops, which
        # add it by hand). Used to SHAKE the whole playfield by an offset with no
        # bleed margin or extra render target — a translate, NOT an SDL viewport,
        # so it never clips and the wider-than-screen ribbon / wrapping stars
        # still cover the shifted edges. Reset to (0,0) after the shaken draw.
        self._ox = 0
        self._oy = 0

    # ---- texture management --------------------------------------------
    def upload(self, key, surface):
        """Upload a Surface as a blend-enabled Texture under `key` (replacing
        any prior one). Call once per static asset after the GL context exists."""
        t = self._v.Texture.from_surface(self.renderer, surface)
        t.blend_mode = 1  # SDL_BLENDMODE_BLEND
        self._tex[key] = t
        return t

    def get(self, key):
        return self._tex.get(key)

    def tex_for(self, surface):
        """Upload-and-cache a Surface as a texture keyed by object identity —
        for semi-static layers that hold their own Surface (nebula/ribbon
        tiles, a sprite's source surface). Re-uploads if the slot's id was
        reused by a different Surface (e.g. a ribbon rebuilt its layer). Holds
        a ref to the Surface so its id stays valid while cached."""
        key = id(surface)
        ent = self._dyn.get(key)
        if ent is not None and ent[1] is surface:
            # Cache hit — mark most-recently-used (re-insert at the dict's end;
            # eviction below drops from the front = least-recently-used).
            del self._dyn[key]
            self._dyn[key] = ent
            return ent[0]
        src = surface
        if surface.get_colorkey() is not None:
            # Texture.from_surface won't honour a colorkey — the keyed
            # pixels upload opaque. Bake colorkey -> per-pixel alpha by
            # blitting onto a transparent SRCALPHA surface (keyed pixels
            # are skipped, staying transparent). Used by the cooldown-arc
            # cached surfaces.
            src = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
            src.blit(surface, (0, 0))
        t = self._v.Texture.from_surface(self.renderer, src)
        t.blend_mode = 1
        self._dyn[key] = (t, surface)
        if len(self._dyn) > self._dyn_cap:
            # Evict the least-recently-used entry — dropping its (Texture,
            # surface) refs frees both, bounding the cache.
            del self._dyn[next(iter(self._dyn))]
        return t

    def upload_tex(self, surface):
        """Upload a Surface to a NEW texture the CALLER owns — NOT entered into
        any cache. Use for transient per-session textures (e.g. a replay's
        per-branch death-FX shards) that must be freed when the caller drops
        them, rather than leaking forever in the id-keyed `tex_for` cache. The
        texture is destroyed when its last reference goes away."""
        src = surface
        if surface.get_colorkey() is not None:
            src = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
            src.blit(surface, (0, 0))
        t = self._v.Texture.from_surface(self.renderer, src)
        t.blend_mode = 1
        return t

    def baked(self, key, builder):
        """Texture for a procedural shape, built once via `builder()` (which
        returns a Surface) and cached. The crop/rotate/tint at draw time make
        one baked shape serve many on-screen variants (e.g. the cooldown arc)."""
        t = self._baked.get(key)
        if t is None:
            surf = builder()
            t = self._v.Texture.from_surface(self.renderer, surf)
            t.blend_mode = 1
            self._baked[key] = t
        return t

    def make_target(self, size):
        """A render-target texture for multi-pass effects (CRT glitch, etc.)."""
        t = self._v.Texture(self.renderer, (int(size[0]), int(size[1])), target=True)
        t.blend_mode = 1
        return t

    # ---- frame ----------------------------------------------------------
    def begin(self, color=(0, 0, 0)):
        # color may carry a 4th alpha component — a transparent clear
        # (0,0,0,0) is used to reset a render-target texture before
        # compositing a translucent layer (e.g. a side-strip panel).
        a = color[3] if len(color) > 3 else 255
        self.renderer.draw_color = (color[0], color[1], color[2], a)
        self.renderer.clear()

    def present(self):
        self.renderer.present()

    def get_target(self):
        return self.renderer.target

    def set_target(self, tex):
        self.renderer.target = tex

    def set_origin(self, ox=0, oy=0):
        """Set a global integer translation added to every primitive's dest
        (blit/fill_rect/draw_rect/line + the disc/tri/blit_dynamic built on them;
        the raw stars/bullets/particles loops add it themselves). Shakes the
        whole playfield by an offset with no bleed margin or extra target. Reset
        to (0,0) after the shaken draw."""
        self._ox = int(ox)
        self._oy = int(oy)

    def origin_pad(self):
        """Max |translation| currently set — backdrop layers expand their tile
        coverage by this so a shake origin can't expose a black edge."""
        return max(abs(self._ox), abs(self._oy))

    def to_surface(self):
        """Read the current render target back to a Surface (for offscreen
        validation / screenshots; expensive — not a per-frame call)."""
        return self.renderer.to_surface()

    # ---- primitives -----------------------------------------------------
    def blit(self, tex, dst, src=None, angle=0.0, alpha=255, color=None,
             flip_x=False, flip_y=False, origin=None, blend=None):
        """Draw a texture as a quad. `dst`/`src` are Rects (src=None → whole
        texture). Supports rotation (deg), per-draw alpha + color modulation,
        and flips — all free on the GPU. Modulation state is restored after so
        textures stay shareable.

        `blend` overrides the texture's blend_mode for this draw only (e.g. 0 =
        SDL_BLENDMODE_NONE for an OPAQUE texture, so it never depends on its
        source-alpha — Mali reads a no-alpha texture's srcA as 0 under BLEND and
        draws nothing). Restored to BLEND afterwards so the texture stays
        shareable."""
        if self._ox or self._oy:
            dst = dst.move(self._ox, self._oy)
        if color is not None:
            tex.color = (color[0], color[1], color[2])
        if alpha != 255:
            tex.alpha = alpha
        if blend is not None:
            tex.blend_mode = blend
        tex.draw(srcrect=src, dstrect=dst, angle=angle, origin=origin,
                 flip_x=flip_x, flip_y=flip_y)
        if blend is not None:
            tex.blend_mode = 1
        if color is not None:
            tex.color = (255, 255, 255)
        if alpha != 255:
            tex.alpha = 255

    def stream_tex(self, key, surface):
        """Update (or lazily create) a keyed persistent streaming texture from
        `surface` and return it WITHOUT blitting — for layers that need extra
        GPU passes (tears, scanline MOD, multi-blit composites) before they hit
        the output. The upload half of blit_dynamic; blit_dynamic == this + a
        blit. blend_mode stays BLEND so the texture composites with its alpha."""
        ent = self._dynamic.get(key)
        size = surface.get_size()
        if ent is None or ent[1] != size:
            t = self._v.Texture.from_surface(self.renderer, surface)
            t.blend_mode = 1
            self._dynamic[key] = (t, size)
        else:
            t = ent[0]
            t.update(surface)
        return t

    def blit_dynamic(self, key, surface, dst, alpha=255):
        """Blit a per-frame-changing software surface via a persistent streaming
        texture (keyed), updated from the surface each call. The HYBRID path for
        complex overlays (result banners, replay HUD, menus): render them with
        the existing software helpers onto a Surface, then upload+composite here
        — no need to port the whole layout/chrome subsystem. The full-surface
        upload only runs when the overlay is actually present, so it's cheap for
        the usually-absent banners."""
        self.blit(self.stream_tex(key, surface), dst, alpha=alpha)

    def fill_rect(self, rect, color):
        if self._ox or self._oy:
            rect = pygame.Rect(rect).move(self._ox, self._oy)
        a = color[3] if len(color) > 3 else 255
        self.renderer.draw_color = (color[0], color[1], color[2], a)
        self.renderer.fill_rect(rect)

    def draw_rect(self, rect, color):
        if self._ox or self._oy:
            rect = pygame.Rect(rect).move(self._ox, self._oy)
        a = color[3] if len(color) > 3 else 255
        self.renderer.draw_color = (color[0], color[1], color[2], a)
        self.renderer.draw_rect(rect)

    def line(self, p0, p1, color):
        if self._ox or self._oy:
            p0 = (p0[0] + self._ox, p0[1] + self._oy)
            p1 = (p1[0] + self._ox, p1[1] + self._oy)
        a = color[3] if len(color) > 3 else 255
        self.renderer.draw_color = (color[0], color[1], color[2], a)
        self.renderer.draw_line(p0, p1)

    # ---- baked filled shapes (SDL_Renderer has no filled circle/triangle) ---
    def _unit_disc(self):
        if self._disc_tex is None:
            D = 64
            s = pygame.Surface((D, D), pygame.SRCALPHA)
            pygame.draw.circle(s, (255, 255, 255, 255), (D // 2, D // 2), D // 2)
            self._disc_tex = self._v.Texture.from_surface(self.renderer, s)
            self._disc_tex.blend_mode = 1
        return self._disc_tex

    def disc(self, cx, cy, r, color, alpha=255):
        """Filled circle = a scaled + colour-modded unit-disc texture. Edges
        are smooth (the big disc downscales) vs pygame.draw.circle's aliased
        edge — visually equivalent. Used for the ball weapon, etc."""
        if r < 1:
            return
        d = int(round(r * 2))
        self.blit(self._unit_disc(),
                  pygame.Rect(int(round(cx - r)), int(round(cy - r)), d, d),
                  color=color, alpha=alpha)

    def _unit_tri_down(self):
        if self._tri_tex is None:
            S = 64
            s = pygame.Surface((S, S), pygame.SRCALPHA)
            pygame.draw.polygon(s, (255, 255, 255, 255),
                                [(0, 0), (S - 1, 0), (S // 2, S - 1)])
            self._tri_tex = self._v.Texture.from_surface(self.renderer, s)
            self._tri_tex.blend_mode = 1
        return self._tri_tex

    def tri_down(self, cx, top_y, half_w, length, color, alpha=255):
        """Downward filled triangle: top edge [cx-half_w, cx+half_w] at top_y,
        apex at (cx, top_y+length). Scaled + tinted unit triangle — engine
        flames."""
        if half_w < 1 or length < 1:
            return
        self.blit(self._unit_tri_down(),
                  pygame.Rect(int(round(cx - half_w)), int(round(top_y)),
                              int(round(half_w * 2)), int(round(length))),
                  color=color, alpha=alpha)


# =============================================================================
# APP
# =============================================================================

# Screen-transition fade/glitch tuning. OVERLAPPING crossfade (not a true cross:
# the NEW screen is always opaque underneath; the OLD glitching frame is drawn on
# top and fades its OPACITY out over it — no black gap). Timeline (total 0.3 s):
#   [0.0, 0.1)  only the OLD frame, glitch ramping up
#   t = 0.1     state swap + gc/build + capture NEW (hidden under the opaque OLD)
#   [0.1, 0.2]  NEW opaque underneath + OLD on top fading 1→0 (both glitch)
#   [0.2, 0.3]  only the NEW frame, glitch ramping down to clean
_FX_OUT_DUR = 0.2      # OLD frame lifetime [0, 0.2]
_FX_IN_START = 0.1     # NEW frame appears + heavy work happens here
_FX_IN_DUR = 0.2       # NEW frame glitch lifetime [0.1, 0.3]
_FX_TOTAL = 0.3
_FX_GLITCH_MAX = 6.4
# Glitch ramp floor = the in-play CRT value (the rewind/dead-pause overlay tops
# out at intensity 1.0), so the transition glitch starts where gameplay leaves
# off and ramps LINEARLY up to _FX_GLITCH_MAX instead of from zero.
_FX_GLITCH_MIN = 1.0
# The glitch + additive-contrast ramp occupies the first 1/3 of each frame's life
# (old: ramp up over [0, OUT_DUR/3]; new: ramp down over the last IN_DUR/3).
_FX_RAMP_FRAC = 1.0 / 3.0
# Max additive-contrast strength at full ramp (0.5 → +50 %, i.e. up to 1.5×, not 2×).
_FX_CONTRAST_MAX = 0.5
# OLD-frame opacity fade curve exponent. >1 = ease-in: the old frame stays nearly
# opaque early in the overlap then drops to transparent SUDDENLY at the end (so
# the crossfade keeps the old glitching frame readable, then snaps it away).
_FX_FADE_CURVE = 2.5
# Darken is a SEPARATE black overlay composited ON TOP of both crossfade layers
# (not baked into either layer), on its own symmetric triangular curve: 0 at
# t=0, peak _FX_DARKEN_MAX at the midpoint (_FX_TOTAL/2), back to 0 at _FX_TOTAL.
# So the whole transition dips toward black through the middle then lifts.
_FX_DARKEN_MAX = 0.75
# Transition glitch profile = the play CRT profile WITHOUT the rolling vsync bar
# (the "vertical scanline" sweep). Per-LAYER it draws tears + chroma only; the
# static scanline grille is a SEPARATE unified pass on its own 0%→100%→0% curve
# (see _fx_scanline_alpha / _fx_compose), not baked into each layer.
_FX_CRT_PROFILE = _dc_replace(_CRT_PROFILE_PLAY, vsync_enabled=False)
_BLEND_ADD = 2   # SDL_BLENDMODE_ADD — used for the 2× contrast pre-pass (GPU)


class App:
    def __init__(self, windowed=False):
        # Mixer buffer. 256 samples (~11 ms) is fine on desktop/device where
        # audio runs on its own thread. On the web pygame's audio is a
        # main-thread ScriptProcessorNode sharing the CPU with the game loop,
        # so a tiny buffer underruns on any frame stall -> constant crackle.
        # 2048 (~93 ms) absorbs frame hitches and GC pauses; the small extra
        # SFX latency is a fair trade for clean sound.
        #
        # On device: 256 samples is ~11.6 ms @ 22050 — SMALLER than a single
        # 60 fps frame (16.6 ms), so ANY frame hitch underruns the SDL/ALSA
        # callback. That caused chronic crackle AND a hard freeze: a long frame
        # underran the callback, and the next Channel.pause() (in
        # _sync_pause_music) blocked >10 s on the mixer lock during ALSA
        # underrun-recovery (music kept looping because the pause never took).
        # 1024 (~46 ms) gives real headroom against frame hitches.
        _mix_buf = 2048 if EMSCRIPTEN else 1024
        pygame.mixer.pre_init(22050, -16, 1, _mix_buf)
        pygame.init()
        try:
            pygame.mixer.init()
        except pygame.error:
            pass
        # Mirror what the mixer actually opened at — pre_init's
        # rate / channel hints aren't honoured on every backend, so
        # we read back via `get_init()` and synthesise PCM to match.
        # If we skipped this, music would play at half- or double-
        # speed on devices that negotiate a different sample rate.
        _refresh_mixer_params()
        self.windowed = windowed
        # Detect the handheld vs a desktop dev machine. The handheld's
        # mali SDL build advertises driver name "mali" — anywhere else
        # (Windows, regular desktop Linux, macOS) we treat as PC. The
        # PC path always renders into a fixed 640x480 logical Surface
        # and scale-blits to the actual display with integer factor +
        # black letterbox bands; the device path lets pygame.SCALED do
        # native scaling on the framebuffer.
        # PEWPEW_ON_DEVICE forces the handheld path on/off explicitly — set
        # by launch.sh so non-Anbernic CFWs (ROCKNIX/JELOS/Batocera on
        # kmsdrm, where the driver isn't "mali" and /mnt/mmc is absent)
        # still take the fullscreen + device-button-scheme + volume-key
        # path. "0" forces it off (handy on a dev box). Falls back to the
        # original Anbernic auto-detect when the var is unset.
        _force_dev = os.environ.get("PEWPEW_ON_DEVICE")
        if _force_dev is not None:
            on_device = (_force_dev == "1")
        else:
            on_device = (pygame.display.get_driver() == "mali"
                         or Path("/mnt/mmc").exists())
        # Stash on self so the volume-key path can gate on it (only the
        # RG has the hardware volume keys we want to feed master_bus).
        self.on_device = on_device
        # The RG35XX Pro (mali fbdev) is the only platform where the GAME owns
        # the master output volume — its hardware vol-keys drive the master bus
        # and there's no system volume OSD. On non-mali handhelds (ROCKNIX has
        # its own system volume + "VOLUME %" OSD) and on PC, the game does NOT
        # react to system volume: master stays pinned at 1.0 and players mix via
        # the title SOUND / MUSIC menu entries (the per-bus sliders).
        self._is_rg = bool(on_device and pygame.display.get_driver() == "mali")
        # Module-level mirror for entity-layer code (Player.draw) that
        # doesn't carry an App back-reference. Currently gates the
        # cached-blit fast path for the cooldown sidebars —
        # see `_draw_cooldown_arcs_cached`.
        global _IS_RG_DEVICE, FPS
        _IS_RG_DEVICE = on_device
        # Detect display refresh rate and run sim + render at that
        # rate. Priority chain:
        #   1. PEWPEW_FPS=N env override (testing / debugging /
        #      capped TVs). Clamped to [FPS_MIN..FPS_MAX].
        #   2. Persisted save-store override (SaveData.load_fps_override).
        #      Lets the user lock a rate from inside the game via the
        #      title-screen SEL+east cycle. Necessary because Steam
        #      Game Mode launch options don't reliably forward env
        #      vars to pewpew.py on every launcher path (gamescope,
        #      Legion Go S wrapper, etc).
        #   3. SDL_GetCurrentDisplayMode + SDL_GetDesktopDisplayMode
        #      via ctypes. Pygame 2.6.1 doesn't expose either through
        #      its own API even when the underlying SDL does, so we
        #      call SDL directly. Available since SDL 2.0.0.
        #   4. Fall back to 60 (the RG's panel rate; also a safe
        #      default everywhere).
        env_fps = os.environ.get("PEWPEW_FPS")
        detected_fps = None
        if env_fps:
            try:
                n = int(env_fps)
                if FPS_MIN <= n <= FPS_MAX:
                    detected_fps = n
            except ValueError:
                pass
        if detected_fps is None:
            override = SaveData.load_fps_override()
            if override:
                detected_fps = override
        if detected_fps is None:
            detected_fps = _sdl_query_refresh_rate()
        if detected_fps is not None:
            FPS = detected_fps
        print(f"[fps] sim + render rate: {FPS} Hz "
              f"(on_device={on_device})", file=sys.stderr)
        # Pick the per-platform face-button scheme NOW so Controls.poll +
        # the layout chrome both see the right indices / letters from the
        # first frame onwards.
        set_button_scheme(on_device)
        try:
            desk_w, desk_h = pygame.display.get_desktop_sizes()[0]
        except Exception:
            desk_w, desk_h = 1920, 1080

        driver = pygame.display.get_driver()
        force_soft = os.environ.get("PEWPEW_NO_SCALED") == "1"
        # GPU render mode — DEFAULT ON (opt-OUT via PEWPEW_GPU=0). Creates an
        # _sdl2 Renderer-backed window INSTEAD of a set_mode surface; PlayState
        # + Map + Shop render natively (_draw_gpu), the Title menu renders
        # software→self.screen then uploads via blit_dynamic in _present. Covers
        # the ROCKNIX/JELOS handhelds (panfrost/libmali, modern batched SDL),
        # desktop + SteamOS. Auto-falls back to the software path on ANY init
        # failure. EXCLUDED from the default: web (EMSCRIPTEN keeps its own path)
        # and the Anbernic stock mali-fbdev (SDL 2.0.12 has no batched renderer
        # and modern SDL segfaults there — the proven SCALED path below stays).
        # Force GPU on anywhere (incl. stock mali) with PEWPEW_GPU=1.
        _gpu_opt = os.environ.get("PEWPEW_GPU")
        _gpu_default_ok = not EMSCRIPTEN and not (on_device and driver == "mali")
        _gpu_enabled = ((_gpu_opt == "1" and not EMSCRIPTEN)
                        or (_gpu_opt != "0" and _gpu_default_ok))
        self.gpu = None
        self.gpu_native = False
        if _gpu_enabled:
            try:
                # A HIDDEN set_mode display establishes the pixel format that
                # Surface.convert/convert_alpha need (lots of surface-baking
                # helpers call .convert() unwrapped). It never shows — the
                # GpuRenderer owns the visible window + the present.
                pygame.display.set_mode((SCREEN_W, SCREEN_H), pygame.HIDDEN)
                if on_device:
                    self.gpu = GpuRenderer((SCREEN_W, SCREEN_H), fullscreen=True, vsync=True)
                else:
                    _wmul = int(os.environ.get("PEWPEW_GPU_WSCALE", "2"))
                    self.gpu = GpuRenderer((SCREEN_W, SCREEN_H), fullscreen=False,
                                           window_size=(SCREEN_W * _wmul, SCREEN_H * _wmul),
                                           resizable=True)
                print("[gpu] GPU render mode ON", file=sys.stderr)
            except Exception as e:
                print(f"[gpu] GPU mode unavailable, software fallback: {e!r}", file=sys.stderr)
                self.gpu = None
        if self.gpu is not None:
            self.display = None
            self.screen = pygame.Surface((SCREEN_W, SCREEN_H))
            self.scale_mode = "integer"
            # Present ONE black frame right away: the GPU window is created here
            # but the run loop's first real present is ~350 ms out (rest of
            # __init__), and the fresh window otherwise shows uninitialised
            # (white) content until then. Paint it black immediately — before
            # the glitch-texture bake below — so there's no white flash before
            # the boot splash starts.
            self.gpu_native = False
            self.screen.fill(BLACK)
            try:
                self._present()
            except Exception:
                pass
            # Bake the glitch/scanline textures now (launch), shared by in-play
            # rewind (CRT) and replay ghosts — avoids the first-frame build hitch.
            _prewarm_glitch_textures(self.gpu)
        elif on_device and driver == "mali" and not force_soft:
            # RG35XX Pro (mali fbdev): pygame.SCALED + FULLSCREEN lets the
            # mali driver handle native scaling on the framebuffer. screen IS
            # the display so _present() just flips.
            self.display = pygame.display.set_mode(
                (SCREEN_W, SCREEN_H), pygame.SCALED | pygame.FULLSCREEN)
            self.screen = self.display
        elif on_device and not force_soft:
            # Other handhelds (ROCKNIX/JELOS on wayland; launch.sh LD_PRELOADs
            # the system SDL2 = Mesa). SCALED drives an SDL GLES2 renderer that
            # streams one texture per frame and presents with vsync — GPU-
            # accelerated AND stable on panfrost/Mesa (verified ~60fps for 35s,
            # no GPU hang). It maintains 640x480 logical size, so on a 1280x720
            # panel it aspect-scales to 960x720 with pillarbars on the GPU.
            #
            # Two earlier approaches both lost: the plain *software-surface*
            # wayland present opened the render node and HARD-HUNG the device
            # (reboot, no trace) — a panfrost bug specific to that present path,
            # not to GPU use in general; and forcing software GL
            # (LIBGL_ALWAYS_SOFTWARE) was stable but far too slow (CPU compositing
            # a fullscreen surface every frame). vsync also paces cleanly; fall
            # back without it if the renderer refuses vsync.
            try:
                self.display = pygame.display.set_mode(
                    (SCREEN_W, SCREEN_H), pygame.SCALED | pygame.FULLSCREEN, vsync=1)
            except pygame.error:
                self.display = pygame.display.set_mode(
                    (SCREEN_W, SCREEN_H), pygame.SCALED | pygame.FULLSCREEN)
            self.screen = self.display
        elif on_device:
            # PEWPEW_NO_SCALED=1 escape hatch: plain software fullscreen at
            # native res; _present() scales the 640x480 screen onto it (no GLES
            # renderer, no GPU). Stable but CPU-bound — a debugging last resort.
            self.display = pygame.display.set_mode(
                (desk_w, desk_h), pygame.FULLSCREEN)
            self.screen = pygame.Surface((SCREEN_W, SCREEN_H))
            # Panels vary (e.g. 1280x720 16:9); default to aspect-fill (sharp
            # nearest-neighbour, 4:3 preserved, pillarboxed), honoring a saved
            # mode but never "vrr" (needs a renderer this path omits).
            _saved = SaveData._read_file().get("scale_mode")
            self.scale_mode = _saved if _saved in (
                "integer", "scaled-grid", "fill", "fill-grid") else "fill"
        elif windowed:
            # Dev-machine windowed: open a RESIZABLE window at the
            # largest integer multiple that fits, leaving slack for
            # window chrome + taskbar.
            init_scale = max(1, min(
                (desk_w - 80) // SCREEN_W,
                (desk_h - 120) // SCREEN_H,
            ))
            init_w = SCREEN_W * init_scale
            init_h = SCREEN_H * init_scale
            self.display = pygame.display.set_mode(
                (init_w, init_h), pygame.RESIZABLE)
            self.screen = pygame.Surface((SCREEN_W, SCREEN_H))
        elif EMSCRIPTEN:
            # Web build: the display spans the whole browser viewport and the
            # game renders into a 640x480 Surface that _present_touch()
            # centres, with on-screen touch controls drawn into the
            # margins. get_desktop_sizes() under pygbag can report a stale /
            # squarish canvas, so prefer the real JS viewport via
            # platform.window and keep it synced each frame
            # (_sync_web_viewport) — that also handles phone rotation.
            vw, vh = self._web_viewport(desk_w, desk_h)
            self.display = pygame.display.set_mode((vw, vh), pygame.RESIZABLE)
            self.screen = pygame.Surface((SCREEN_W, SCREEN_H))
            self.scale_mode = "integer"   # unused on the touch path; kept valid
        else:
            # Dev-machine fullscreen: set_mode flags depend on the
            # active scale_mode (the cycle picks between crisp-integer
            # and VRR-friendly). _apply_dev_display_mode() centralises
            # that branch so cycle_scale_mode can also call it when
            # the player crosses the "vrr" boundary at runtime.
            self._desk_w = desk_w
            self._desk_h = desk_h
            # Load scale_mode early so the first set_mode picks the
            # right flags. The later `self.scale_mode = ...` line just
            # re-reads it harmlessly — kept there so the surrounding
            # initialization order isn't shuffled.
            self.scale_mode = SaveData.load_scale_mode()
            self._apply_dev_display_mode()
        pygame.display.set_caption("Pewpew")
        # Web build: split touch (phone/tablet) from desktop (mouse+keyboard).
        #   touch  -> on-screen TouchControls, mouse routed through them.
        #   desktop-> static bindings legend; mouse falls through to the game.
        # WEB_IS_TOUCH (module global) also gates the desktop mouse in
        # Controls.poll. Native/device builds get neither.
        self.touch = None
        self.legend = None
        if EMSCRIPTEN:
            global WEB_IS_TOUCH
            WEB_IS_TOUCH = _web_is_touch()
            if WEB_IS_TOUCH:
                self.touch = TouchControls()
            else:
                self.legend = WebLegend(self)
        pygame.mouse.set_visible(False)
        self.clock = pygame.time.Clock()
        # Dev-machine present mode: True = nearest-neighbour at the largest
        # integer multiple that fits (crisp pixels, black bands on whichever
        # axes have slack). False = nearest-neighbour at the largest aspect-
        # preserving fractional fit (fills more of the window; pixels stay
        # hard squares but some span an extra display pixel). TitleScreen
        # TAB / Y toggles this. Ignored on device (the mali fullscreen path
        # bypasses _present). Persisted via SaveData so the user's choice
        # survives a relaunch.
        self.scale_mode = SaveData.load_scale_mode()
        # Auto-update channel cache (read at boot; refreshed on toggle).
        # Drives the title version-stamp colour: stable = grey, uat = red.
        self.channel = autoupdate_channel()
        # Release-notes queue + (X) update hint. On stable, fetch every
        # release body strictly newer than the running VERSION — that's
        # the "accumulated changelog" the title overlay shows. Non-empty
        # notes = update available; the (X) hint and overlay both light
        # up. On UAT we don't have a "release" notion, so fall back to
        # the hash probe and skip the overlay (no markdown to show).
        # Sync with a 5 s timeout so a flaky connection can't stall
        # boot indefinitely. TitleScreen also runs its own periodic
        # refresh every 5 s while it's up, so this initial fetch is
        # just to seed the first frame.
        self.pending_release_notes = ""
        self.update_available = False
        # Newest release tag the changelog fetch surfaced — empty when
        # no update is pending or we're on UAT (no release notion). The
        # overlay title bar names this version so the player sees what
        # they're being asked to install.
        self.latest_release_tag = ""
        # ETag of the last successful releases-list fetch. The periodic
        # loop sends it as If-None-Match so unchanged polls cost zero
        # rate-limit quota (GitHub's anonymous quota is 60 req/hr per IP
        # — 5 s polling would blow through that in 5 minutes without
        # conditional requests).
        self.release_etag = None
        # Status of the most recent check: CHECK_OK, CHECK_NOT_MODIFIED,
        # CHECK_RATE_LIMITED, CHECK_FAIL, or "init" before anything has
        # run. Drives a small hint near the version stamp so the
        # player knows when the check is broken (rate-limited / no
        # net) instead of just seeing a silently-empty overlay.
        self.last_check_status = "init"
        # Timestamp of the most recent update-check fetch (used by the
        # title-stamp blink in the "background probe just started" path
        # — see TitleScreen._update_check_once). Default to -inf so the
        # first render before any check has happened doesn't blink.
        self.last_check_ts = float("-inf")
        # True while a background update-check is in flight. The title
        # version stamp blinks WHILE this is True (replaces the old
        # fixed 0.5 s blink window so the blink genuinely tracks "are
        # we still talking to GitHub right now"). Workers must use a
        # try / finally to flip it back to False on every exit path.
        self.update_check_in_flight = False
        if EMSCRIPTEN:
            # Web build: no sockets, no real threads, and the page is always
            # the latest deploy — so there's nothing to update to.
            self.last_check_status = CHECK_FAIL
        # No boot-time update check: each TitleScreen runs its own one-shot
        # async check on entry (TitleScreen._update_check_once, both channels),
        # so the release-notes fields just keep their defaults until then —
        # nothing on the boot path ever waits on the network.

        self.joys = []
        for i in range(pygame.joystick.get_count()):
            j = pygame.joystick.Joystick(i)
            j.init()
            self.joys.append(j)
        # Edge-detector state for synthesising D-pad ("hat") events from
        # the left analog stick. Every screen handles JOYHATMOTION for
        # menu navigation already, so feeding it stick crossings means
        # the stick "just works" everywhere with no per-screen change.
        self._stick_dir_x = 0  # -1/0/+1
        self._stick_dir_y = 0  # -1/0/+1 (already in hat convention: +1 = UP)

        # The heavy world build (assets / sounds / music / title logo) runs on
        # a background thread (_boot_build) while the boot splash shows static —
        # see the end of __init__. Here we only set the placeholders it fills
        # and the cheap, main-thread-safe mixer channel CONFIG its generated
        # Sounds will play through (set_num_channels / Channel() are quick and
        # must stay on the main thread; only Sound/PCM generation moves off).
        self.assets = {}
        self.logo = None
        self.title_gloss_stripe = None
        self.title_yellow_mask = None
        self.title_yellow_dim = None
        self.sounds = {}
        self.music_tracks = {}
        if pygame.mixer.get_init():
            pygame.mixer.set_num_channels(16)
            self.music_channel = pygame.mixer.Channel(0)
            # Per-layer menu music channels — channels 1..MENU_VARIANT_COUNT.
            # Cumulative menu playback puts each layer's iso PCM on its own
            # channel so the dev tuning UI's per-layer multipliers can be
            # applied live via Channel.set_volume.
            self.menu_layer_channels = [
                pygame.mixer.Channel(i + 1)
                for i in range(MENU_VARIANT_COUNT)
            ]
        else:
            self.music_channel = None
            self.menu_layer_channels = []
        # Per-composition / per-layer volume multipliers loaded from the
        # tuning JSON if present. Untuned slots default to 1.0 in the
        # `menu_layer_mult()` helper.
        self.menu_layer_mults = _load_menu_tuning()
        # Per-layer crossfade state. `_targets` is what each menu-layer
        # channel SHOULD be at given the current state (audibility +
        # bus + mults). `_current_vols` is what's actually applied to
        # the channel right now — the fade tick moves the latter
        # toward the former at MENU_LAYER_FADE_RATE per second so
        # variant / iso / profile changes crossfade smoothly without
        # PCM regen or restarts.
        n = len(self.menu_layer_channels)
        self._menu_layer_current_vols = [0.0] * n
        self._menu_layer_targets = [0.0] * n
        # Per-composition slot-to-native order. `_menu_layer_orders[comp][slot]`
        # tells which native (original) variant's iso PCM + mult should
        # play in `slot`. Dev workflow: hold SELECT on the map + press
        # B to swap the current slot with the one below; the iso PCMs
        # and tuning values move together. Loaded from disk so an
        # in-progress reorder survives a relaunch.
        self._menu_layer_orders = {
            tag: list(range(MENU_VARIANT_COUNT)) for tag in _KNOWN_COMP_TAGS
        }
        for tag, order in _load_menu_orders().items():
            full = list(range(MENU_VARIANT_COUNT))
            for i, native in enumerate(order):
                if 0 <= native < MENU_VARIANT_COUNT and i < len(full):
                    full[i] = native
            self._menu_layer_orders[tag] = full
        self.current_music = None
        # Hand-pixeled bitmap font with vertical gradient. Every integer scale
        # 1..7 is available as fonts[scale] (e.g. fonts[4]) plus a few named
        # aliases for backward compatibility with the rest of the codebase.
        self.fonts = {}
        for scale in range(1, 8):
            self.fonts[scale] = BitmapFont(scale=scale)
        # 7x9 family — keyed by ("7x9", scale) so the layout engine can
        # look them up without colliding with the integer 5x7 scales.
        for scale in range(1, 5):
            self.fonts[("7x9", scale)] = BitmapFont7x9(scale=scale)
        self.fonts["tiny"]  = self.fonts[1]   #  7 px tall
        self.fonts["small"] = self.fonts[2]   # 14 px
        self.fonts["big"]   = self.fonts[3]   # 21 px
        self.fonts["large"] = self.fonts[4]   # 28 px
        self.fonts["huge"]  = self.fonts[5]   # 35 px
        self.fonts["mega"]  = self.fonts[6]   # 42 px
        self.fonts["giant"] = self.fonts[7]   # 49 px
        # Floating in-world numbers (e.g. "+$25" on pickup). One size up
        # from the tiny HUD font so the pop animation reads at distance.
        FloatText.set_font(self.fonts.get(2) or self.fonts.get("small"))
        self.levels = make_levels()
        self.profile_name = SaveData.current_profile_name()
        self.save = SaveData.load(self.profile_name)
        global _REWIND_UNLOCKED
        _REWIND_UNLOCKED = bool(getattr(self.save, "rewind_unlocked", False))
        self.volume_input = VolumeInput() if self._is_rg else None
        # Per-profile SFX + music buses (title-screen sliders drive these).
        self.sfx_bus = AudioBus(self.save.volume, label="SFX")
        self.music_bus = AudioBus(self.save.music_volume, label="MUSIC")
        # Device-global master bus — only the RG hardware volume keys
        # touch it. On non-RG it stays at 1.0 (no-op multiplier). Both
        # _apply_sfx_volume / _apply_music_volume fold master_bus.gain in
        # as the final stage so the user-facing slider percents stay
        # honest (100 % means full per-bus, the master is a separate
        # device-output scale).
        self.master_bus = AudioBus(
            SaveData.load_master_volume() if self._is_rg else 1.0,
            label="VOL")
        self.volume_show_t = 0.0
        self.volume_show_bus = self.master_bus
        # In-game volume pip-bar shows only on the RG (it's the bar for the
        # master bus the RG vol-keys drive); off everywhere else.
        self._show_volume_bar = self._is_rg
        # (_apply_sfx_volume / _apply_music_volume run at the end of
        #  _boot_build, once the sounds it generates on the thread exist.)
        self.perf = PerfMonitor()
        # Live perf HTTP endpoint on port 8080. Default: on for the
        # device (so a tool on the LAN can poll perf while the player
        # plays), off elsewhere — set PEWPEW_PERF_HTTP=1 to force-enable
        # on PC/dev for testing. Read-only JSON snapshot; can't be used
        # to mutate game state.
        env_pref = os.environ.get("PEWPEW_PERF_HTTP")
        perf_http_on = ((env_pref == "1") if env_pref is not None
                        else bool(self.on_device))
        if perf_http_on:
            self._perf_http = start_perf_http_server(self.perf)
        else:
            self._perf_http = None
        # Debug/profiling hook: PEWPEW_REPLAY_LOAD=<level key> boots straight
        # into that level's saved mission-replay viewer (skips title→map→West),
        # so an on-device perf run can land in the replay without driving the
        # controller. Sibling of the other PEWPEW_* test hooks; ignored if the
        # key is unknown.
        # The boot splash is the FIRST live screen; it transitions (via the
        # normal crossfade) to this target once _boot_build has produced the
        # world. PEWPEW_REPLAY_LOAD still lands straight in the replay viewer.
        _rl = os.environ.get("PEWPEW_REPLAY_LOAD", "").strip()
        if _rl and _rl in self.levels:
            self._boot_target = ("play_replay", _rl)
        else:
            self._boot_target = ("title", None)
        self.controls = Controls()
        # Screen-transition crossfade state. The OLD frozen frame glitches +
        # fades its opacity out over the NEW frozen frame (which is drawn opaque
        # underneath, also glitching). The state swap + gc/build happen at
        # _FX_IN_START, hidden under the still-opaque old frame. Input is blocked
        # throughout (no live state.run). See _fx_begin / _fx_tick. `None` = idle.
        self._fx_phase = None       # None | "active"
        self._fx_t = 0.0
        self._fx_frame = 0          # per-frame glitch seed → old+new tear alike
        self._fx_pending = None     # the (kind, payload) outcome to apply at the swap
        self._fx_constructed = False  # has the new state been built yet (frame N)?
        self._fx_swapped = False    # has the new-frame capture happened yet (frame N+1)?
        self._fx_old = None         # frozen OLD frame: GPU tex (mode) or Surface (sw)
        self._fx_new = None         # frozen NEW frame
        self._fx_tgt_old = None     # GPU: capture target for a native OLD frame
        self._fx_tgt_new = None     # GPU: capture target for a native NEW frame
        self._fx_comp = None        # GPU: scratch target for the fading OLD layer
        self._fx_scan = None        # cached SCREEN-sized CRT scanline overlay
        # ── Boot splash + threaded world build ──────────────────────────────
        # __init__ returns NOW (everything above is cheap), so the run loop's
        # first frame draws the static almost immediately. The heavy build
        # (assets / sounds / music / logo) runs on a daemon thread; the splash
        # polls the flags below and drives the GPU cache prewarm one screen per
        # frame (spread under the static, overlapped with music gen), then
        # yields _boot_target so the existing crossfade blends static → title.
        #   _boot_world_ready  — assets + sounds done (prewarm may start)
        #   _boot_assets_ready — everything done (may transition to title)
        self._boot_world_ready = False
        self._boot_assets_ready = False
        self.state = BootSplashScreen(self)
        if EMSCRIPTEN:
            # Pyodide is single-threaded — build inline (the splash still shows
            # for the warm-up frames the build's synchronous, then transitions).
            self._boot_build()
        else:
            threading.Thread(target=self._boot_build,
                             name="boot-build", daemon=True).start()

    def _boot_build(self):
        """Heavy world build, run on a background thread while the boot splash
        shows static: assets + the projectile/FX/backdrop wiring, the title
        logo + its gloss/mask layers, and (if the mixer is up) the cached SFX +
        per-layer menu music. Reattaches the volume buses once the sounds
        exist, then flips _boot_assets_ready so the splash can cut to the title.
        Wrapped so a failure can't hang the splash — ready is set either way."""
        try:
            self.assets = make_assets()
            BackgroundRibbon.set_backdrops(self.assets.get("_backdrops", {}))
            Bullet.set_glyphs(self.assets.get("_projectiles", {}))
            ExplosionRing.set_fx(self.assets.get("_fx", {}))
            _setup_ball_fx(self.assets.get("_fx", {}),
                           self.assets.get("_engine_data", {}))
            logo = self._load_title_logo()
            self.title_gloss_stripe = _make_gloss_stripe(
                height=logo.get_height(), stripe_w=70, peak=191)
            self.title_yellow_mask = _make_yellow_mask(logo)
            self.title_yellow_dim = _make_yellow_dim_layer(self.title_yellow_mask)
            self.logo = logo
            if pygame.mixer.get_init():
                self.sounds = make_sounds_cached()
            else:
                self.sounds = {k: _Silent() for k in (
                    "shoot", "shoot2", "rail", "hit", "boom", "big_boom",
                    "pickup", "money", "bomb", "menu", "confirm", "deny", "warn",
                    "ball_charge", "ball_level_up", "ball_overcharge",
                    "ball_absorb", "ball_release", "ball_detonate", "ball_ready")}
            self._apply_sfx_volume()
            # Visuals + sounds are ready — enough for the GPU screen prewarm to
            # run (it renders Title/Map/Shop/Play to warm texture caches). Signal
            # it NOW so the splash spreads the prewarm across frames OVERLAPPED
            # with the music gen below + hidden under the static, instead of one
            # ~650ms freeze at the static->title transition.
            self._boot_world_ready = True
            if pygame.mixer.get_init():
                tracks = {}
                for k in MUSIC_KINDS:
                    if k == "menu":
                        tracks["menu_iso"] = [
                            make_music_cached("menu", variant=v, isolated=True)
                            for v in range(MENU_VARIANT_COUNT)
                        ]
                    else:
                        tracks[k] = make_music_cached(k)
                self.music_tracks = tracks
            self._apply_music_volume()
        except Exception as e:
            import traceback
            traceback.print_exc()
            print(f"[boot] world build failed: {e}", file=sys.stderr)
        finally:
            self._boot_assets_ready = True

    def _prewarm_step(self):
        """Warm ONE screen's GPU caches per call — render it once into an
        offscreen target (no present; the real self.state is restored), so the
        shared glyph + sprite/disc textures it builds on first paint are warm
        before the player ever sees it. Chunked (one screen per call) and driven
        across boot-static frames so the prewarm never costs a single huge
        frame. Title is warmed FIRST so the static->title crossfade reveal is
        smooth too. Returns True once every screen has been warmed."""
        if self.gpu is None:
            return True
        if not hasattr(self, "_prewarm_makers"):
            _lv = self.levels.get("L001") or next(iter(self.levels.values()), None)
            self._prewarm_makers = [lambda: TitleScreen(self),
                                    lambda: MapScreen(self),
                                    lambda: ShopScreen(self)]
            if _lv is not None:
                self._prewarm_makers.append(lambda: PlayState(self, _lv))
            self._prewarm_i = 0
            self._prewarm_tgt = None
        if self._prewarm_i >= len(self._prewarm_makers):
            return True
        make = self._prewarm_makers[self._prewarm_i]
        self._prewarm_i += 1
        saved_state = getattr(self, "state", None)
        saved_native = self.gpu_native
        g = self.gpu
        try:
            if self._prewarm_tgt is None:
                self._prewarm_tgt = g.make_target((SCREEN_W, SCREEN_H))
            self.state = make()
            self.gpu_native = False
            g.set_target(self._prewarm_tgt)
            g.begin(BLACK)
            self.state.run([], Controls())
        except Exception:
            pass
        finally:
            try:
                g.set_target(None)
            except Exception:
                pass
            self.state = saved_state
            self.gpu_native = saved_native
        return self._prewarm_i >= len(self._prewarm_makers)

    def _load_title_logo(self):
        """Pixel-perfect: use the title sprite at exactly the size the
        editor saved (scale + crop already baked in). The fallback is the
        procedurally drawn PEWPEW text."""
        here = Path(__file__).resolve().parent
        sprite_dir = here / "art" / "sprites"
        for ext in (".bmp", ".png"):
            path = sprite_dir / f"title{ext}"
            if path.is_file():
                try:
                    return pygame.image.load(str(path)).convert_alpha()
                except Exception:
                    continue
        return make_logo("PEWPEW", scale=7, color=(120, 220, 255))

    def _apply_sfx_volume(self):
        g = self.sfx_bus.gain * self.master_bus.gain
        for s in self.sounds.values():
            try: s.set_volume(g)
            except Exception: pass

    def _apply_music_volume(self):
        """Re-apply the music bus gain to whichever menu / gameplay
        track is playing. Menu modes refresh the per-layer channel
        volumes (which fold in the bus gain + per-layer mults); non-
        menu tracks (game / boss / takeoff / dock) just use the bus
        gain on the main channel. Master bus is folded in as the final
        device-output multiplier (1.0 on non-RG, slider-driven on RG)."""
        if isinstance(self.current_music, tuple):
            self._refresh_menu_volumes()
            return
        if self.music_channel is not None:
            try: self.music_channel.set_volume(
                self.music_bus.gain * self.master_bus.gain)
            except Exception: pass

    def _apply_dev_display_mode(self):
        """Set up the dev-fullscreen display + render surface for the
        current `self.scale_mode`. Called once from __init__.

        * "vrr": SCALED + FULLSCREEN at the logical 640x480. SDL's
          renderer owns the upscale and (on Windows) takes proper
          exclusive fullscreen so DWM is out of the way and VRR can
          adapt refresh to the present rate. `self.screen IS
          self.display` so `_present()` falls through to a plain flip
          — same shape as the RG mali path. vsync=0 so the present
          returns immediately and VRR drives the cadence.
        * Anything else: own the desktop at native resolution with
          plain FULLSCREEN and render into a logical 640x480 Surface
          that `_present()` scales up. Crisp-integer pixels at the
          cost of going through DWM (no VRR — see v0.9.208 commit).

        Falls back to integer mode if vrr fails (some SDL+driver
        combos can't create the renderer at all). No-op on the
        device (mali) and windowed paths — those set their display
        once in __init__ and never need to re-init.

        NOTE: not callable at runtime to *switch* between vrr and
        non-vrr — pygame can't add or remove an SDL renderer from an
        already-created window via set_mode (the call raises
        "failed to create renderer"). Cycling crosses the boundary
        by persisting the new mode and requiring a relaunch; see
        `cycle_scale_mode`."""
        if self.on_device or self.windowed:
            return
        if self.scale_mode == "vrr":
            try:
                self.display = pygame.display.set_mode(
                    (SCREEN_W, SCREEN_H),
                    pygame.SCALED | pygame.FULLSCREEN, vsync=0)
                self.screen = self.display
                return
            except pygame.error as e:
                print(f"[scale-mode] vrr init failed: {e}; "
                      f"reverting to integer", file=sys.stderr)
                self.scale_mode = "integer"
                SaveData.save_scale_mode(self.scale_mode)
        self.display = pygame.display.set_mode(
            (self._desk_w, self._desk_h), pygame.FULLSCREEN, vsync=0)
        self.screen = pygame.Surface((SCREEN_W, SCREEN_H))

    def cycle_scale_mode(self):
        """Advance to the next entry in SCALE_MODES and persist it. Used
        by the title-screen TAB / Y handler. The grid-mask cache stays
        valid across mode changes (it's keyed by scale+size, not mode).

        Crossing the "vrr" boundary requires the display to be
        renderer-backed (SCALED) or not — pygame can't toggle that on
        an existing window, so we persist the new mode and require a
        relaunch to actually engage. The print to stderr is the
        user-visible signal."""
        prev = self.scale_mode
        idx = SCALE_MODES.index(prev) if prev in SCALE_MODES else 0
        self.scale_mode = SCALE_MODES[(idx + 1) % len(SCALE_MODES)]
        SaveData.save_scale_mode(self.scale_mode)
        if (prev == "vrr") != (self.scale_mode == "vrr"):
            print(f"[scale-mode] '{self.scale_mode}' takes effect on "
                  f"next launch (display flags can't toggle SCALED at "
                  f"runtime)", file=sys.stderr)

    # Per-device FPS override. 0 = auto (re-detect via SDL); other
    # values lock sim + render to that rate. Lives in the save store
    # like `scale_mode` because it's a per-device display setting and
    # Steam Game Mode launch-option env vars don't reach pewpew.py on
    # every wrapper path. Cycled from the title via SEL+east.
    FPS_OVERRIDE_STEPS = (0, 60, 90, 120, 144, 240)

    def cycle_fps_override(self):
        """Step through (auto, 60, 90, 120, 144, 240). 'auto' re-runs
        the SDL detection; the rest lock the global FPS to that
        value. Applied live — pygame.Clock.tick reads the global each
        call so the new rate takes effect on the next frame. Persists
        through SaveData so the choice survives relaunch and gets
        picked up by the App.__init__ detection chain."""
        global FPS
        steps = App.FPS_OVERRIDE_STEPS
        cur = SaveData.load_fps_override()
        try:
            i = steps.index(cur)
        except ValueError:
            i = 0
        nxt = steps[(i + 1) % len(steps)]
        SaveData.save_fps_override(nxt)
        if nxt == 0:
            det = _sdl_query_refresh_rate()
            FPS = det if det is not None else 60
        else:
            FPS = nxt
        print(f"[fps] override → {nxt or 'auto'}, FPS now {FPS} Hz",
              file=sys.stderr)

    def _autoupdate_probe(self):
        """Background-thread worker: hash-compare every managed file
        against the active channel and flip `update_available` so the
        title hint shows up. Silent on failure — we leave the prior
        value in place rather than treat "couldn't check" as "no
        update", which used to false-negative the hint on a flaky link
        (see autoupdate_check_available's docstring). Holds
        update_check_in_flight True for the duration so the title
        version stamp blinks while the boot probe is running."""
        self.last_check_ts = time.monotonic()
        self.update_check_in_flight = True
        try:
            result, rv = autoupdate_check_available(timeout=8)
        except Exception:
            return
        finally:
            self.update_check_in_flight = False
        if result is not None:
            self.update_available = result
            if rv:
                self.latest_release_tag = rv

    def _grid_mask(self, scale, w, h):
        """Build (and cache) a (w, h) RGB mask whose every `scale`-th
        column and row is dimmed. Multiplied onto an integer-scaled
        screen via BLEND_RGB_MULT — gives every source pixel a 1-px dim
        right + bottom edge. scale must be >= 2 (at 1× there's no cell
        to draw an edge in).

        Cached on the App because the mask only changes when the window
        resizes (which also resizes the host display surface — same
        cache key)."""
        if not hasattr(self, "_grid_mask_cache"):
            self._grid_mask_cache = {}
        key = (scale, w, h)
        cached = self._grid_mask_cache.get(key)
        if cached is not None:
            return cached
        mask = pygame.Surface((w, h)).convert()
        mask.fill((255, 255, 255))
        # ~0.70 multiplier (178/255). Tune here if the grid feels too
        # heavy / faint. Same dim for both axes so the corner where they
        # cross ends up ~0.49 — a touch darker still, which reads as the
        # bottom-right corner of the source pixel.
        DIM = (178, 178, 178)
        for x in range(scale - 1, w, scale):
            pygame.draw.line(mask, DIM, (x, 0), (x, h - 1))
        for y in range(scale - 1, h, scale):
            pygame.draw.line(mask, DIM, (0, y), (w - 1, y))
        self._grid_mask_cache[key] = mask
        return mask

    def _present(self):
        """Push self.screen to the actual display + flip.

        Device (fullscreen): self.screen IS self.display, so this is just
        a flip — the mali driver did the upscale.

        Windowed pipeline (per SCALE_MODES):
          1. Always nearest-neighbour upscale to the largest integer
             multiple of 640x480 that fits the window.
          2. If the mode contains "grid", multiply the integer-scaled
             surface by a 1-px-per-cell dim mask (perfectly aligned to
             source pixels).
          3. If the mode contains "fill", nearest-neighbour rescale up
             to the largest aspect-preserving fractional fit.
        Then centre-blit with black bands. Pixels stay hard squares at
        every stage."""
        if self.gpu is not None:
            # GPU mode. PlayState drew natively to the renderer backbuffer
            # (gpu_native). A software screen (menus) rendered to self.screen —
            # upload it as one texture (logical_size scales it to the window).
            g = self.gpu
            if not self.gpu_native:
                g.set_target(None)
                g.begin(BLACK)
                g.blit_dynamic("screen", self.screen,
                               pygame.Rect(0, 0, SCREEN_W, SCREEN_H))
            _shot = os.environ.get("PEWPEW_GPU_SHOT")
            if _shot:
                self._gpu_shot_n = getattr(self, "_gpu_shot_n", 0) + 1
                if self._gpu_shot_n == int(_shot):
                    try:
                        pygame.image.save(g.to_surface(),
                                          os.environ.get("PEWPEW_GPU_SHOT_PATH", "_gpu_run.png"))
                        print("[gpu] shot saved", file=sys.stderr)
                    except Exception as _e:
                        print("[gpu] shot fail:", repr(_e), file=sys.stderr)
                    self._gpu_shot_done = True
            g.present()
            self.gpu_native = False
            return
        if self.touch is not None:
            self._present_touch()
            return
        if self.legend is not None:
            self._present_legend()
            return
        if self.screen is self.display:
            pygame.display.flip()
            return
        win_w, win_h = self.display.get_size()
        mode = self.scale_mode
        wants_grid = mode in ("scaled-grid", "fill-grid")
        wants_fill = mode in ("fill", "fill-grid")

        # Step 1: integer scale.
        int_scale = max(1, min(win_w // SCREEN_W, win_h // SCREEN_H))
        int_w = SCREEN_W * int_scale
        int_h = SCREEN_H * int_scale
        if int_scale == 1:
            stage = self.screen
        else:
            stage = pygame.transform.scale(self.screen, (int_w, int_h))

        # Step 2: grid filter. Only meaningful at >= 2x — at 1x every
        # output column would also be a cell edge, dimming everything.
        if wants_grid and int_scale >= 2:
            if stage is self.screen:
                stage = stage.copy()  # don't dim the source surface
            mask = self._grid_mask(int_scale, int_w, int_h)
            stage.blit(mask, (0, 0), special_flags=pygame.BLEND_RGB_MULT)

        # Step 3: optional fractional rescale up to the fill size.
        if wants_fill:
            fscale = max(1.0, min(win_w / SCREEN_W, win_h / SCREEN_H))
            fill_w = int(SCREEN_W * fscale)
            fill_h = int(SCREEN_H * fscale)
            if (fill_w, fill_h) != (int_w, int_h):
                stage = pygame.transform.scale(stage, (fill_w, fill_h))
            out_w, out_h = fill_w, fill_h
        else:
            out_w, out_h = int_w, int_h

        ox = (win_w - out_w) // 2
        oy = (win_h - out_h) // 2
        if ox > 0 or oy > 0:
            self.display.fill((0, 0, 0))
        self.display.blit(stage, (ox, oy))
        pygame.display.flip()

    @staticmethod
    def _web_viewport(fallback_w, fallback_h):
        """Backing-store size for the canvas, in DEVICE pixels. innerWidth/
        Height are CSS pixels; on a retina screen (iPhone DPR 2-3) a canvas
        sized in CSS px gets blurrily upscaled to the physical screen — and a
        narrow phone even shows the 640px game below its native width. So
        multiply by devicePixelRatio to render at physical resolution (the
        injected CSS pins the canvas to 100vw/100vh, so it still fills the
        screen). Cap the ratio at 2 so a DPR-3 phone doesn't pay 9x the
        per-frame present cost — 2x is already above the game's native 640px
        and visually ~identical for pixel art. Web build only."""
        try:
            import platform as _plat
            w = _plat.window
            vw = int(w.innerWidth)
            vh = int(w.innerHeight)
            dpr = float(getattr(w, "devicePixelRatio", 1) or 1)
            dpr = max(1.0, min(dpr, 2.0))
            if vw >= 64 and vh >= 64:
                return int(vw * dpr), int(vh * dpr)
        except Exception:
            pass
        return max(64, fallback_w), max(64, fallback_h)

    def _sync_web_viewport(self):
        """Keep the display surface matched to the live browser viewport so
        the canvas fills the screen and rotations re-lay-out. Cheap: only
        calls set_mode when the size actually changed."""
        w, h = self.display.get_size()
        vw, vh = self._web_viewport(w, h)
        if (vw, vh) != (w, h):
            self.display = pygame.display.set_mode((vw, vh), pygame.RESIZABLE)

    def _present_touch(self):
        """Web present: scale the 640x480 game into its orientation-aware
        rect and draw the on-screen touch controls in the margins. The
        layout was computed this frame in run(); reuse its game_rect so the
        drawn buttons line up with the hit-testing."""
        disp = self.display
        g = self.touch.game_rect
        disp.fill((0, 0, 0))
        if (g.w, g.h) == (SCREEN_W, SCREEN_H):
            disp.blit(self.screen, (g.x, g.y))
        else:
            disp.blit(pygame.transform.scale(self.screen, (g.w, g.h)), (g.x, g.y))
        self.touch.draw(disp, self.fonts)
        pygame.display.flip()

    def _draw_select_legend(self, screen):
        """Transient gamepad legend drawn on the 640x480 game surface while
        SELECT is held (native peek). Non-modal — gameplay continues under it."""
        hints = _legend_hints(_legend_state(self))
        W, H = screen.get_size()
        bw, bh = min(560, W - 12), min(320, H - 12)
        bx, by = (W - bw) // 2, (H - bh) // 2
        ov = pygame.Surface((bw, bh), pygame.SRCALPHA)
        ov.fill((8, 10, 18, 228))
        pygame.draw.rect(ov, (90, 210, 255), ov.get_rect(), 1, border_radius=8)
        screen.blit(ov, (bx, by))
        _legend_render_device(screen, pygame.Rect(bx + 8, by + 6, bw - 16, bh - 12),
                              2, hints, self.fonts)

    def _present_legend(self):
        """Desktop-web present: centre the game and draw the static bindings
        legend in the margins. No input interception — the mouse reaches the
        game via the normal event path."""
        disp = self.display
        dw, dh = disp.get_size()
        g = self.legend.layout(dw, dh)
        disp.fill((0, 0, 0))
        if (g.w, g.h) == (SCREEN_W, SCREEN_H):
            disp.blit(self.screen, (g.x, g.y))
        else:
            disp.blit(pygame.transform.scale(self.screen, (g.w, g.h)), (g.x, g.y))
        self.legend.draw(disp, self.fonts)
        pygame.display.flip()

    def set_music(self, kind):
        """Switch the music channel to the named non-menu track. For
        the menu kind use `set_menu_music(variant)` instead so the
        caller can choose which progression variant to play (title /
        map / shop each have their own rule)."""
        if kind == "menu":
            # Back-compat shim: someone called set_music("menu") without
            # picking a variant. Pick variant 0 as a safe default. Real
            # callers should use set_menu_music().
            self.set_menu_music(0)
            return
        new_state = kind
        if new_state == self.current_music:
            return
        # Leaving menu music — stop any per-layer channels that might
        # still be looping the layered cumulative mix.
        was_menu = isinstance(self.current_music, tuple)
        self.current_music = new_state
        if self.music_channel is None:
            return
        if was_menu:
            for ch in getattr(self, "menu_layer_channels", ()):
                try: ch.stop()
                except Exception: pass
            # Reset fade state so the next menu entry fades up from
            # silence rather than from whatever stale volumes the
            # layers were last set to.
            n = len(getattr(self, "menu_layer_channels", ()))
            self._menu_layer_current_vols = [0.0] * n
            self._menu_layer_targets = [0.0] * n
        if kind is None:
            self.music_channel.stop()
            return
        track = self.music_tracks.get(kind)
        if track is None:
            return
        # Takeoff and dock are one-shot cues, not loops — the dock
        # track is 4.8 s long and the outro is 4.9 s, so looping it
        # bled ~0.1 s of the next loop into the fade-to-black. Letting
        # them play once and end naturally avoids that. Game / boss /
        # menu still loop because they're real background music.
        loops = 0 if kind in ("takeoff", "dock") else -1
        self.music_channel.play(track, loops=loops)
        self.music_channel.set_volume(
            self.music_bus.gain * self.master_bus.gain)

    def set_menu_music(self, variant, isolated=False):
        """Switch the menu music to the given variant and mode.

        Approach: all six per-layer channels loop their iso PCMs in
        lockstep for the entire menu session. Variant + mode only
        affect which channels are *audible*:

          cumulative (isolated=False) — layers 0..variant audible at
                                        `bus × mult[layer]`
          iso        (isolated=True)  — only layer `variant` audible

        Keeping every layer looping continuously means no channel
        ever restarts mid-loop, so cross-layer sync is preserved
        across variant changes and iso/cumulative toggles. Per-layer
        volumes (and the tuning UI's live mult nudges) apply via a
        cheap set_volume per channel.
        """
        iso_tracks = self.music_tracks.get("menu_iso") or []
        if not iso_tracks:
            return
        n = len(iso_tracks)
        variant = max(0, min(n - 1, int(variant)))
        new_state = (("menu_iso" if isolated else "menu_layered"), variant)
        was_in_menu = isinstance(self.current_music, tuple)
        self.current_music = new_state
        if not was_in_menu:
            # Just arrived at the menu (from gameplay or boot). Stop
            # any other music on the main channel and start all
            # per-layer channels in lockstep — within microseconds of
            # each other so they stay synced for the session. Each
            # slot plays the iso PCM whose ORIGINAL variant is
            # `_layer_slot_to_native(slot)` (identity by default; the
            # dev swap workflow can remap it).
            if self.music_channel is not None:
                try: self.music_channel.stop()
                except Exception: pass
            for slot, ch in enumerate(self.menu_layer_channels):
                if slot >= n:
                    break
                native = self._layer_slot_to_native(slot)
                if 0 <= native < n:
                    try:
                        ch.play(iso_tracks[native], loops=-1)
                        # Start silent — the fade tick is what brings
                        # currents up to their targets. Without this
                        # the channel plays at pygame's default vol
                        # (1.0) for ~1 frame before _tick_menu_layer_fade
                        # runs, so all 6 layers briefly blare full
                        # volume when entering menu from gameplay /
                        # boot.
                        ch.set_volume(0.0)
                    except Exception:
                        pass
        self._refresh_menu_volumes()

    def _layer_slot_to_native(self, slot):
        """Map a display SLOT (the variant the user is currently on)
        to the NATIVE variant index (the iso PCM + mult that should
        play in that slot). Identity unless an order permutation was
        loaded from the tuning JSON."""
        order = self._menu_layer_orders.get(MENU_COMPOSITION)
        if not order or slot < 0 or slot >= len(order):
            return slot
        return order[slot]

    def _refresh_menu_volumes(self):
        """Update the per-layer TARGET volumes from the current menu
        state + tuning mults. The fade tick is what actually moves
        `_menu_layer_current_vols` toward the targets and calls
        Channel.set_volume. No-op outside menu modes.

        Every change — audibility transitions, tuning nudges, master
        bus changes — flows through the fade tick. For tiny target
        deltas (tuning, bus tweaks) the fade catches up in ~1 frame
        anyway (worst-case full-stick nudge moves the target by ~0.02
        per frame, fade step is 0.033/frame), so the UI still feels
        responsive. Audibility transitions take the full ~0.5 s as
        intended.
        """
        cm = self.current_music
        if not isinstance(cm, tuple):
            return
        key, variant = cm
        isolated = (key == "menu_iso")
        # Per-layer target = music_bus.gain × master_bus.gain × layer_mult.
        # Folding the master in here too keeps menu music in lockstep
        # with the rest of the audio when the RG volume keys nudge it.
        bus = self.music_bus.gain * self.master_bus.gain
        mults = getattr(self, "menu_layer_mults", None)
        n = len(self.menu_layer_channels)
        new_targets = [0.0] * n
        for slot in range(n):
            audible = (slot == variant) if isolated else (slot <= variant)
            if audible:
                # Mults are stored at the NATIVE variant index (so a
                # loaded order permutation maps the slot to its PCM).
                native = self._layer_slot_to_native(slot)
                mult = menu_layer_mult(MENU_COMPOSITION, native, mults)
                new_targets[slot] = max(0.0, min(1.0, bus * mult))
        self._menu_layer_targets = new_targets

    def _tick_menu_layer_fade(self, dt):
        """Move `_menu_layer_current_vols` toward `_menu_layer_targets`
        at MENU_LAYER_FADE_RATE per second and push the new values to
        the per-layer channels. Called every frame from App.run; cheap
        no-op when current already equals target."""
        targets = self._menu_layer_targets
        if not targets:
            return
        step = MENU_LAYER_FADE_RATE * dt
        for layer, ch in enumerate(self.menu_layer_channels):
            if layer >= len(targets):
                break
            cur = self._menu_layer_current_vols[layer]
            tgt = targets[layer]
            if cur == tgt:
                continue
            if abs(cur - tgt) <= step:
                cur = tgt
            elif cur < tgt:
                cur += step
            else:
                cur -= step
            self._menu_layer_current_vols[layer] = cur
            try: ch.set_volume(cur)
            except Exception: pass

    def switch_profile(self, name):
        """Switch the active profile slot, load its save into self.save,
        and re-apply the volume/music levels stored on the new profile.

        Only called from the title screen — by then any in-progress
        gameplay has already returned through PlayState's win/loss path
        (which saves), so we do NOT write the current save before
        switching. Writing defaults into a never-touched slot here would
        make every profile look "started" after the user simply cycled
        past it once."""
        name = (name or DEFAULT_PROFILE).upper()
        if name not in PROFILE_NAMES:
            return
        if name == self.profile_name:
            return
        self.profile_name = name
        self.save = SaveData.load(name)
        SaveData.set_current_profile(name)
        global _REWIND_UNLOCKED
        _REWIND_UNLOCKED = bool(getattr(self.save, "rewind_unlocked", False))
        # Per-profile audio prefs: refresh the live buses so the new
        # profile's settings take effect immediately.
        self.sfx_bus.level = self.save.volume
        self.music_bus.level = self.save.music_volume
        self._apply_sfx_volume()
        self._apply_music_volume()

    async def run(self):
        running = True
        perf = self.perf
        # Frame-stall watchdog (HEARTBEAT design): the main loop only stamps a
        # timestamp each frame (near-free); a single long-lived monitor thread
        # checks it every 2 s and, if the loop has been stalled > _WATCHDOG_S
        # (a hang — GPU driver stall, infinite loop, deadlock), dumps every
        # thread's Python stack to stderr (→ last_run.log) so an otherwise
        # invisible freeze pinpoints itself. (The earlier version called
        # faulthandler.dump_traceback_later EVERY frame, which cancels+respawns a
        # timer thread per frame — ~60 thread spawn/joins a second — and that
        # churn itself stuttered the replay on the A53. This spawns ONE thread.)
        # Off on web (Pyodide is single-threaded).
        _watchdog = not EMSCRIPTEN
        _WATCHDOG_S = 10.0
        self._wd_last = time.perf_counter()
        self._wd_run = _watchdog
        if _watchdog:
            faulthandler.enable()

            def _wd_monitor():
                dumped = False
                while self._wd_run:
                    time.sleep(2.0)
                    stalled = (time.perf_counter() - self._wd_last) > _WATCHDOG_S
                    if stalled and not dumped:
                        sys.stderr.write(
                            "\n[watchdog] main loop stalled >%.0fs — thread dump:\n"
                            % _WATCHDOG_S)
                        sys.stderr.flush()
                        faulthandler.dump_traceback(file=sys.stderr)
                        sys.stderr.flush()
                        dumped = True
                    elif not stalled:
                        dumped = False

            threading.Thread(target=_wd_monitor, name="watchdog",
                             daemon=True).start()
        _frame_prof = os.environ.get("PEWPEW_FRAME_PROFILE") == "1"
        while running:
            self._wd_last = time.perf_counter()
            perf.start("frame")
            perf.start("app.tick")
            dt = self.clock.tick(FPS) / 1000.0
            perf.end("app.tick")
            perf.start("app.events")
            events = pygame.event.get()
            # Synthesise JOYHATMOTION events from left-stick crossings so
            # every menu (title / map / shop / pause / etc.) can navigate
            # via the analog stick without each one growing a JOYAXISMOTION
            # branch. EDGE-ONLY: a held stick fires once on the deflection
            # rising past 0.55 and won't refire until it crosses back near
            # neutral (under 0.35), matching the d-pad.
            #
            # ALL joysticks fold into ONE logical stick (strongest deflection
            # per axis) with a SINGLE edge-compare against the shared
            # _stick_dir state. The old code edge-compared + re-assigned that
            # shared state once PER joystick inside the loop — so when the
            # device enumerates more than one pad (common on handhelds), a
            # second, neutral pad reset the state to 0 every frame and the
            # real pad's held deflection re-fired the synth EVERY FRAME =
            # runaway menu nav (and twice as fast at 120 Hz). Taking the max
            # abs deflection means a neutral pad contributes 0 and can't reset
            # the edge.
            STICK_PUSH = 0.55
            STICK_RELEASE = 0.35
            ax_best = ay_best = 0.0
            for j in self.joys:
                try:
                    if j.get_numaxes() < 2:
                        continue
                    ax = j.get_axis(0)
                    ay = j.get_axis(1)
                except pygame.error:
                    continue
                if abs(ax) > abs(ax_best):
                    ax_best = ax
                if abs(ay) > abs(ay_best):
                    ay_best = ay
            if self.joys:
                # X axis: stick right = +1, left = -1
                nx = self._stick_dir_x
                if abs(ax_best) < STICK_RELEASE:
                    nx = 0
                elif ax_best > STICK_PUSH:
                    nx = 1
                elif ax_best < -STICK_PUSH:
                    nx = -1
                # Y axis: stick down (axis>0) → hat down (hy=-1); inverted.
                ny = self._stick_dir_y
                if abs(ay_best) < STICK_RELEASE:
                    ny = 0
                elif ay_best > STICK_PUSH:
                    ny = -1
                elif ay_best < -STICK_PUSH:
                    ny = 1
                if nx != self._stick_dir_x and nx != 0:
                    events.append(pygame.event.Event(
                        pygame.JOYHATMOTION, value=(nx, 0)))
                if ny != self._stick_dir_y and ny != 0:
                    events.append(pygame.event.Event(
                        pygame.JOYHATMOTION, value=(0, ny)))
                self._stick_dir_x = nx
                self._stick_dir_y = ny
            vol_dirs = []  # list of +1 / -1 from keyboard fallbacks
            for ev in events:
                if ev.type == pygame.QUIT:
                    running = False
                if ev.type == pygame.JOYBUTTONDOWN:
                    if ev.button == JOY_MENU:
                        # Hard exit — bypass the post-loop cleanup so the
                        # game closes immediately even if a state has set an
                        # outcome that would otherwise transition.
                        try:
                            self.save.save()
                        except Exception:
                            pass
                        pygame.quit()
                        sys.exit(0)
                if ev.type == pygame.KEYDOWN:
                    if ev.key == pygame.K_F4 and (pygame.key.get_mods() & pygame.KMOD_ALT):
                        running = False
                    if ev.key in (pygame.K_EQUALS, pygame.K_PLUS, pygame.K_KP_PLUS):
                        vol_dirs.append(+1)
                    elif ev.key in (pygame.K_MINUS, pygame.K_KP_MINUS):
                        vol_dirs.append(-1)
                if ev.type == pygame.VIDEORESIZE and self.screen is not self.display:
                    # Dev-machine resize: re-create the window at the new
                    # size. The logical screen Surface stays at SCREEN_W
                    # × SCREEN_H — _present() picks a new integer scale
                    # and recentres on the next frame.
                    self.display = pygame.display.set_mode(
                        (max(SCREEN_W, ev.w), max(SCREEN_H, ev.h)),
                        pygame.RESIZABLE)

            perf.end("app.events")

            # Pump hardware volume events from /dev/input — but only on
            # RG. On non-RG (Steam Deck, dev box) we don't have a
            # VolumeInput instance at all and the master bus is pinned
            # at 1.0; per-bus mix is the only thing players can change.
            if self.on_device and self.volume_input is not None:
                for d in self.volume_input.poll():
                    vol_dirs.append(d)

            for d in vol_dirs:
                if self.master_bus.adjust(d):
                    self._apply_sfx_volume()
                    self._apply_music_volume()
                    SaveData.save_master_volume(self.master_bus.level)
                    # Subtle tick at the new gain so the user can hear
                    # what the adjustment did.
                    try:
                        self.sounds["menu"].play()
                    except Exception:
                        pass
                self.volume_show_t = 1.6
                self.volume_show_bus = self.master_bus

            if self.volume_show_t > 0:
                self.volume_show_t = max(0.0, self.volume_show_t - dt)

            # Touch controls (web): lay out for the current canvas size,
            # fold this frame's finger/mouse events into the panel, then
            # apply on top of the gamepad/keyboard poll so screens read it
            # identically.
            if EMSCRIPTEN:
                self._sync_web_viewport()    # keep display == browser viewport
            if self.touch is not None:
                self.touch.begin_frame()
                _dw, _dh = self.display.get_size()
                self.touch.layout(_dw, _dh)
                for ev in events:
                    self.touch.handle_event(ev, _dw, _dh)
                # Inject the synthesised pad events so both Controls.poll and
                # any screen that scans the raw event list see the touch input.
                if self.touch.synth:
                    events = events + self.touch.synth

            # Pick the keyboard/mouse layout for the active state: PlayState
            # (incl. its pause / banner / replay sub-states) uses the PLAY
            # layout; everything else uses the MENU layout.
            self.controls.context = ("game" if isinstance(self.state, PlayState)
                                     else "menu")
            self.controls.poll(self.joys, events)
            if self.touch is not None:
                self.touch.apply(self.controls)
            perf.start("app.state")
            if self._fx_phase is not None:
                # A screen transition is in flight: the fade/glitch owns the
                # frame. Input is blocked (no state.run), no new transition can
                # start; _fx_tick composes this frame for the _present below.
                self._fx_tick(dt)
                perf.end("app.state")
            else:
                outcome = self.state.run(events, self.controls)
                perf.end("app.state")
                # Memory telemetry — a flushed RSS line every ~3 s so an OOM-kill
                # (exit=137, instant SIGKILL, no traceback/watchdog dump) still
                # leaves a growth curve in last_run.log to pinpoint the consumer.
                # PYTHONUNBUFFERED=1 (launch.sh) flushes each line as it prints.
                self._mem_dbg = getattr(self, "_mem_dbg", 0) + 1
                if self._mem_dbg % 180 == 0:
                    _st = self.state
                    _rb = getattr(_st, "_rewind", None)
                    _rl = len(_rb.snaps) if _rb is not None else 0
                    _gb = len(getattr(_st, "_ghost_branches", ()) or ())
                    _gh = len(getattr(_st, "_active_ghosts", ()) or ())
                    _dyn = len(getattr(self.gpu, "_dyn", ())) if self.gpu else 0
                    print("[mem] %-14s rss=%dMB rewind=%d branches=%d ghosts=%d dyn=%d"
                          % (type(_st).__name__, _proc_rss_mb(), _rl, _gb, _gh, _dyn),
                          file=sys.stderr)
                if outcome is not None:
                    # Don't swap now — start the fade-out. The state swap +
                    # gc/save/screen build happen at full black inside _fx_tick.
                    self._fx_begin(outcome)

            # State-based music selection. Boss intro / outro use the boss
            # track; standard play uses the game track; everything else menu.
            self._update_music_track()
            # Crossfade per-layer menu channel volumes toward their
            # targets — smooth out variant / iso / profile transitions.
            # No-op outside menu modes (targets all zero -> matches
            # current quickly).
            self._tick_menu_layer_fade(dt)

            if self.volume_show_t > 0 and self._show_volume_bar:
                self._draw_volume_indicator()
            # Hold SELECT to peek at the gamepad legend (native only — web
            # desktop already shows the margin legend, web touch has its own
            # UI). Non-modal: we only READ select, so SEL+combos still fire.
            if getattr(self.controls, "select", False) and not EMSCRIPTEN:
                self._draw_select_legend(self.screen)
            perf.start("app.flip")
            self._present()
            perf.end("app.flip")
            # TEMP debug: PEWPEW_GPU_SHOT — _present() saves a readback before
            # the buffer swap (reliable) and flags done; quit here.
            if getattr(self, "_gpu_shot_done", False):
                running = False
            # Opt-in per-frame spike profiler (PEWPEW_FRAME_PROFILE=1): logs any
            # frame whose work exceeded ~30ms with the state + transition phase,
            # so a boot static->title hitch pinpoints its source (prewarm vs
            # title build vs crossfade) in last_run.log.
            if _frame_prof:
                _fms = (time.perf_counter() - self._wd_last) * 1000.0
                if _fms > 30.0:
                    print("[frameprof] %5.0fms state=%-15s fx=%s ready=%s pw=%s"
                          % (_fms, type(self.state).__name__, self._fx_phase,
                             getattr(self, "_boot_assets_ready", None),
                             getattr(self.state, "_prewarmed", None)),
                          file=sys.stderr)
            perf.end("frame")
            perf.frame_end()
            # Yield to the event loop once per frame. On the desktop this is a
            # near-zero no-op; under pygbag/Pyodide it hands control back to
            # the browser so the canvas actually paints and input is pumped —
            # without it the WASM build hangs the tab on a busy loop.
            await asyncio.sleep(0)

        self._wd_run = False   # stop the watchdog monitor thread
        if self.volume_input is not None:
            self.volume_input.close()
        self.save.save()
        pygame.quit()

    def _update_music_track(self):
        """Per-frame music selection.

        Gameplay states (PlayState) cycle through takeoff / boss /
        game / dock as before. Non-gameplay screens all play the
        layered menu theme, but each picks its own variant:

          TitleScreen — variant by overall save progression
                        (number of fully completed areas).
          MapScreen   — variant by the currently viewed sector. If
                        SELECT/SHIFT is held while on the map, the
                        debug audition mode plays instead — only
                        the top layer of the current variant.
          ShopScreen  — variant by the sector of the player's
                        last-played level.
          Anything else (game-over splash, etc.) falls back to
          variant 0 so the music stays muted and lonely.
        """
        s = self.state
        if isinstance(s, BootSplashScreen):
            return  # boot static is silent; music starts with the title
        if isinstance(s, PlayState):
            if getattr(s, "_game_won", False):
                # Game-fully-complete celebration — fully-layered menu
                # theme carries the player into the title-screen
                # handoff. Must be checked BEFORE the takeoff/boss/game
                # branches so the per-frame sync doesn't immediately
                # overwrite the set_menu_music call _begin_game_won
                # made on entry.
                self.set_menu_music(MENU_VARIANT_COUNT - 1, isolated=False)
                return
            if s.intro_t > 0:
                self.set_music("takeoff")
            elif s.outro_t > 0:
                self.set_music("dock")
            elif s.level.has_boss and s.boss_spawned:
                self.set_music("boss")
            else:
                self.set_music("game")
            return
        save = getattr(self, "save", None)
        # Title + shop: variant matches what the map cursor would land
        # on if the player entered the map right now — so all three
        # menu screens agree on entry. The map itself, however, keeps
        # following its LIVE cursor: paging L1/R1 to a richer sector
        # adds layers in real time, paging back removes them.
        if isinstance(s, TitleScreen):
            self.set_menu_music(menu_variant_for_save_unified(save))
        elif isinstance(s, MapScreen):
            self.set_menu_music(menu_variant_for_sector(
                getattr(s, "sector_idx", 0), save))
        elif isinstance(s, ShopScreen):
            self.set_menu_music(menu_variant_for_save_unified(save))
        else:
            self.set_menu_music(0)

    def _draw_volume_indicator(self):
        """Pip-bar showing the bus that was last adjusted."""
        bus = self.volume_show_bus
        is_music = bus is self.music_bus
        w, h = 240, 32
        x = (SCREEN_W - w) // 2
        y = SCREEN_H - h - 16
        alpha = min(1.0, self.volume_show_t / 1.0)
        bg = pygame.Surface((w, h), pygame.SRCALPHA)
        bg.fill((18, 22, 38, int(220 * alpha)))
        self.screen.blit(bg, (x, y))
        border = (200, 160, 110) if is_music else (110, 160, 220)
        pygame.draw.rect(self.screen, border, (x, y, w, h), 1)
        label = self.fonts["tiny"].render(bus.label, False, border)
        self.screen.blit(label, (x + 8, y + h // 2 - label.get_height() // 2))
        cells = 10
        bar_x = x + 52
        bar_w = w - 64
        cell_w = max(2, (bar_w - (cells - 1)) // cells)
        filled = int(round(bus.level * cells))
        fill_col = ORANGE if is_music else CYAN
        for i in range(cells):
            cell = pygame.Rect(bar_x + i * (cell_w + 1), y + 10, cell_w, 12)
            pygame.draw.rect(self.screen, (40, 46, 70), cell)
            if i < filled:
                pygame.draw.rect(self.screen, fill_col, cell.inflate(-2, -2))

    def _restore_save_after_replay(self):
        if hasattr(self, "_replay_save_backup"):
            self.save = self._replay_save_backup
            del self._replay_save_backup
            # The replay path used a default SaveData (ghost_mode=False)
            # while running; rehydrate the runtime gate from the real
            # save the player started the replay from.
            global _REWIND_UNLOCKED
            _REWIND_UNLOCKED = bool(getattr(self.save, "rewind_unlocked", False))

    def _record_play_outcome(self, score, level_key, won, progress,
                              stolen_time=None):
        """Apply the post-play side effects on save (stats, dumnezeu,
        completed list, unlocks) and flush to disk. Mirrors the body
        of the post_play transition handler — used by
        PlayState._begin_game_won to commit the 100%-complete record
        BEFORE the celebration starts, so a force-quit mid-fireworks
        doesn't lose the win.

        stolen_time (optional) is the cumulative seconds of rewind the
        player used during this attempt. Appended to
        stats["stolen_times"] on a won outcome — one entry per
        full-clear completion. The map-details overlay reads the list
        to render the running-min bar chart. Pre-stolen-time saves
        default to an empty list."""
        self.save.high_score = max(self.save.high_score, score)
        stats = self.save.level_stats.setdefault(level_key, {})
        if won:
            stats["wins"] = int(stats.get("wins", 0)) + 1
        else:
            stats["fails"] = int(stats.get("fails", 0)) + 1
        stats["max_clear"] = max(
            float(stats.get("max_clear", 0.0)), float(progress))
        # DMZ adaptive-difficulty knob is permanently disabled —
        # rewind replaces the death-bias safety net. The stored
        # per-level floats are preserved on disk for legacy saves
        # but never updated.
        pending_unlocks = []
        if won:
            if level_key not in self.save.completed:
                self.save.completed.append(level_key)
            for nxt in MAP_GRAPH[level_key].nexts:
                if nxt not in self.save.unlocked:
                    self.save.unlocked.append(nxt)
            pending_unlocks = _apply_boss_unlocks(self.save, level_key)
            if stolen_time is not None:
                times = stats.setdefault("stolen_times", [])
                if not isinstance(times, list):
                    times = []
                    stats["stolen_times"] = times
                times.append(float(stolen_time))
        self.save.save()
        # Returned so the MISSION COMPLETE replay path can carry the unlock
        # celebration into the shop without a second post_play record.
        # _begin_game_won (the other caller) ignores the return value.
        return pending_unlocks

    def _transition(self, kind, payload):
        if kind == "play":
            level = payload
            self.state = PlayState(self, level)
        elif kind == "play_replay":
            # Watch the cursored level's saved mission replay (West on the
            # map). PlayState loads the buffer on a thread (LOADING %) and
            # boots straight into the view-only scrubber; a missing/corrupt
            # file routes back to the map.
            level_key = payload
            self.state = PlayState(self, self.levels[level_key],
                                   replay_load=level_key)
        elif kind == "title":
            self._restore_save_after_replay()
            self.state = TitleScreen(self)
        elif kind == "map":
            self._restore_save_after_replay()
            self.state = MapScreen(self)
        elif kind == "shop":
            self.state = ShopScreen(self)
        elif kind == "shop_win":
            # MISSION COMPLETE replay exit: the win was already recorded to
            # disk at replay entry (_commit_win), so just persist any
            # credits baked on the way out and open the shop with the
            # pending unlock celebration — no second post_play record.
            self.save.save()
            self.state = ShopScreen(self, pending_unlocks=payload or [],
                                    from_level=True)
        elif kind == "abort":
            # Pause-and-bomb abort path. Distinct from "post_play" with
            # won=False because we intentionally do NOT touch the per-
            # level difficulty knob (dumnezeu) and we skip the SHIP LOST
            # GameOverScreen — straight to the map. Save persists any
            # incidental writes (e.g. unlock side-effects), nothing
            # changes on the level-progress side.
            self.save.save()
            self.state = MapScreen(self)
        elif kind == "quit":
            self.save.save()
            pygame.quit()
            sys.exit(0)
        elif kind == "post_play":
            score, level_key, won, progress = payload
            self.save.high_score = max(self.save.high_score, score)
            # Per-level run history. Tracks wins, fails, and the best
            # progress fraction the player has ever reached (1.0 once
            # the level has been won at least once). Surfaced in the
            # map level-details overlay.
            stats = self.save.level_stats.setdefault(level_key, {})
            if won:
                stats["wins"] = int(stats.get("wins", 0)) + 1
            else:
                stats["fails"] = int(stats.get("fails", 0)) + 1
            # Same max() for both branches now — clear % is killed /
            # spawned regardless of outcome, so legacy save entries
            # that stored 1.0 on a sloppy win keep their score (max
            # only goes up), and new attempts record the truth.
            stats["max_clear"] = max(
                float(stats.get("max_clear", 0.0)), float(progress))
            # DMZ adaptive-difficulty knob is permanently disabled —
            # rewind replaces the death-bias safety net. The stored
            # per-level floats are preserved on disk for legacy saves
            # but never updated; spawn logic ignores them.
            if won:
                if level_key not in self.save.completed:
                    self.save.completed.append(level_key)
                for nxt in MAP_GRAPH[level_key].nexts:
                    if nxt not in self.save.unlocked:
                        self.save.unlocked.append(nxt)
                pending_unlocks = _apply_boss_unlocks(self.save, level_key)
                self.save.save()
                self.state = ShopScreen(self, pending_unlocks=pending_unlocks,
                                        from_level=True)
            else:
                # Loss ends like any other level end now — straight to the
                # shop (no SHIP LOST screen). No unlock cascade on a loss, so
                # no pending_unlocks; the player can still spend what they
                # banked and back out to the map.
                self.save.save()
                self.state = ShopScreen(self, from_level=True)
        elif kind == "game_won":
            # All 100 levels cleared on this attempt — the win was
            # already committed inside PlayState._begin_game_won (so a
            # force-quit during the celebration kept the record). The
            # only thing left is to drop back to the title screen,
            # where the 100%-complete save state surfaces the fully-
            # layered menu music + every unlock-driven backdrop tier.
            self.state = TitleScreen(self)
        elif kind == "replay_full":
            profile_name = payload
            path = _find_replay_path(profile_name)
            if path is None:
                print(f"[replay] no replay file for profile {profile_name}")
                return
            # Stash the real save and use a throwaway one so the replay's
            # restore_save calls can't trash player progress.
            self._replay_save_backup = self.save
            self.save = SaveData()
            self.save.save = lambda *a, **kw: None
            self.state = ReplayState(self, path, single_level_key=None,
                                     return_to="title")
        elif kind == "replay_level":
            profile_name, level_key = payload
            path = _find_replay_path(profile_name)
            if path is None:
                print(f"[replay] no replay file for profile {profile_name}")
                return
            self._replay_save_backup = self.save
            self.save = SaveData()
            self.save.save = lambda *a, **kw: None
            self.state = ReplayState(self, path, single_level_key=level_key,
                                     return_to="map")

    # ── Screen-transition fade + glitch ────────────────────────────────────
    def _fx_mktarget(self, attr):
        t = getattr(self, attr)
        if t is None:
            t = self.gpu.make_target((SCREEN_W, SCREEN_H))
            setattr(self, attr, t)
        return t

    def _fx_capture(self, fresh, target):
        """GPU: freeze the current state's frame as a texture — Mali-safe (no
        window `to_surface` readback). Discriminate by SCREEN TYPE, NOT the
        gpu_native flag — that flag is unreliable at capture time on Mali (the
        press-frame draw + _present reset race), and trusting it made a NATIVE
        screen's capture fall back to `self.screen`, which permanently holds the
        last software render = the stale TITLE (Map/Shop/PlayState never write
        self.screen). So: the software TitleScreen lives on self.screen → upload
        it (from_surface, proven path); EVERY other screen renders NATIVE into
        `target`. `fresh` = the incoming screen hasn't drawn yet, so run it once
        first (for the incoming title, so self.screen isn't stale)."""
        g = self.gpu
        if isinstance(self.state, (TitleScreen, BootSplashScreen)):
            if fresh:
                try:
                    self.state.run([], Controls())
                except Exception:
                    pass
            return g.upload_tex(self.screen)
        g.set_target(target)
        g.begin(BLACK)
        try:
            self.state.run([], Controls())
        except Exception:
            pass
        g.set_target(None)
        return target

    def _fx_begin(self, outcome):
        """A transition fired: freeze the current frame and start the crossfade.
        The state swap + gc/build are deferred to _FX_IN_START (hidden under the
        still-opaque old frame, see _fx_tick). Plays the confirm cue so every
        transition has instant audio feedback (the glitch is the instant visual
        feedback). Any failure falls back to an instant transition — never a
        crash."""
        self._fx_pending = outcome
        self._fx_phase = "active"
        self._fx_t = 0.0
        self._fx_frame = 0
        self._fx_constructed = False
        self._fx_swapped = False
        self._fx_new = None
        try:
            if self.gpu is not None:
                self._fx_old = self._fx_capture(False, self._fx_mktarget("_fx_tgt_old"))
            else:
                self._fx_old = self.screen.copy()
            try:
                self.sounds["confirm"].play()
            except Exception:
                pass
        except Exception:
            self._fx_abort()

    def _fx_abort(self):
        """Safety net: a fade step failed — finish the pending transition
        instantly and clear FX state so the game never gets stuck on a garbled
        frame (covers any device-specific GPU surprise)."""
        try:
            if self._fx_pending is not None:
                self._transition(*self._fx_pending)
        except Exception:
            pass
        self._fx_pending = None
        self._fx_phase = None
        self._fx_old = self._fx_new = None
        self.gpu_native = False

    def _fx_scanlines(self):
        if self._fx_scan is None:
            self._fx_scan = _build_crt_scanline_overlay(
                SCREEN_W, SCREEN_H, _FX_CRT_PROFILE)
        return self._fx_scan

    def _fx_capture_new(self):
        """Freeze the (already-swapped) new state as the _fx_new frame."""
        if self.gpu is not None:
            self._fx_new = self._fx_capture(True, self._fx_mktarget("_fx_tgt_new"))
        else:
            self.gpu_native = False
            try:
                self.state.run([], Controls())
            except Exception:
                pass
            self._fx_new = self.screen.copy()

    def _fx_tick(self, dt):
        """Advance the crossfade and COMPOSE this frame (the main loop's
        _present() pushes it). Input is blocked — no live state.run. The two
        heavy steps are SPLIT onto separate fade-out frames so neither single
        frame carries both: the state is BUILT one frame, the new frame is
        CAPTURED the next, and both land while only the opaque OLD frame is
        still composited (invisible) — keeping every transition frame under the
        60Hz budget. Wrapped so any failure falls back to an instant transition."""
        try:
            # Advance by a FIXED 1/FPS step, not the real frame dt — so on a slow
            # device the transition stretches in wall-clock time but never skips
            # effect frames (every glitch/crossfade frame is drawn).
            step = 1.0 / FPS
            self._fx_t += step
            self._fx_frame += 1
            t = self._fx_t
            # Step 1 — build the new state (2 frames before it first shows).
            # Swapping self.state is invisible until _FX_IN_START because only the
            # OLD frozen frame is composited until then. Freeing the old
            # PlayState here drops its rewind-buffer snapshot graph by REFCOUNT
            # (acyclic — see PlayState); NO gc.collect (a gen-2 sweep was ~150 ms).
            if not self._fx_constructed and t >= _FX_IN_START - 2.0 * step:
                if self._fx_pending is not None:
                    self._transition(*self._fx_pending)
                    self._fx_pending = None
                self._fx_constructed = True
            # Step 2 — capture the new frame (1 frame before it first shows).
            elif (self._fx_constructed and not self._fx_swapped
                  and t >= _FX_IN_START - step):
                self._fx_capture_new()
                self._fx_swapped = True
            # Safety net: if the offsets were skipped (tiny _FX_IN_START / odd
            # FPS), make sure build+capture are both done by the swap point.
            if t >= _FX_IN_START and not self._fx_swapped:
                if self._fx_pending is not None:
                    self._transition(*self._fx_pending)
                    self._fx_pending = None
                    self._fx_constructed = True
                self._fx_capture_new()
                self._fx_swapped = True
            if t >= _FX_TOTAL:
                # Final frame: compose the NEW screen ONE more time (clean — at
                # t=TOTAL the glitch/fade/old layer are all zero) so the frame is
                # the new screen, NOT a fall-through to _present uploading the
                # stale self.screen (= the last software render = the TITLE,
                # which flashed at the end of every transition). End the phase
                # AFTER; the next frame runs the new state live.
                self._fx_compose(_FX_TOTAL)
                self._fx_phase = None
                self._fx_old = self._fx_new = None
                return
            self._fx_compose(t)
        except Exception:
            self._fx_abort()

    def _fx_layer(self, tex, intensity, contrast):
        """GPU: draw one frozen frame `tex` into the CURRENT (already-bound +
        cleared) target with the contrast pre-pass + CRT glitch. Darkening is
        NOT applied here — it's a single black overlay composited on TOP of both
        layers in _fx_compose (see _fx_darken_alpha). Seed `random` before
        calling so the OLD and NEW layers tear IDENTICALLY in a frame."""
        g = self.gpu
        rect = (0, 0, SCREEN_W, SCREEN_H)
        rr = pygame.Rect(0, 0, SCREEN_W, SCREEN_H)
        g.blit(tex, rr)
        if contrast > 0.0:
            g.blit(tex, rr, blend=_BLEND_ADD,
                   alpha=int(255 * _FX_CONTRAST_MAX * min(1.0, contrast)))
        # Scanlines are NOT drawn per-layer — they're a single unified pass on
        # their own 0%→100%→0% curve over the whole crossfade (see _fx_compose /
        # _fx_scanline_alpha), so they don't double up or track layer intensity.
        _apply_crt_glitch_gpu(g, tex, rect, intensity,
                              profile=_FX_CRT_PROFILE,
                              scanline_cache=self._fx_scanlines(),
                              draw_base=False, draw_scanlines=False)

    def _fx_darken_alpha(self, t):
        """Opacity (0..255) of the SEPARATE black overlay laid on top of both
        crossfade layers — a symmetric triangle: 0 at t=0, _FX_DARKEN_MAX at the
        midpoint (_FX_TOTAL/2), back to 0 at _FX_TOTAL. Independent of the
        per-layer glitch/opacity curves, so the whole frame dips toward black
        through the middle of the transition then lifts back."""
        half = _FX_TOTAL * 0.5
        if half <= 0.0:
            return 0
        f = (t / half) if t <= half else (_FX_TOTAL - t) / half
        return int(255 * _FX_DARKEN_MAX * max(0.0, min(1.0, f)))

    def _fx_scanline_alpha(self, t):
        """Opacity (0..255) of the UNIFIED CRT scanline overlay during the
        crossfade — a symmetric triangle 0%→100%→0% (peak at the midpoint
        _FX_TOTAL/2), independent of the per-layer glitch intensity. The
        scanlines are a single screen-wide pass on top of both layers (the
        per-layer glitch no longer draws them) so they read as one steady CRT
        grille that breathes in and out across the transition."""
        half = _FX_TOTAL * 0.5
        if half <= 0.0:
            return 0
        f = (t / half) if t <= half else (_FX_TOTAL - t) / half
        return int(255 * max(0.0, min(1.0, f)))

    def _fx_levels(self, t):
        """Per-layer levels for crossfade time `t`. Old glitch ramps up MIN→MAX
        over its first 1/3; new glitch ramps down MAX→0 over its last 1/3 — so
        through the overlap BOTH sit at MAX (identical tearing). Old opacity
        fades 1→0 (ease-in curve) across the overlap. Darkening is handled
        SEPARATELY (see _fx_darken_alpha) — not baked into either layer here.
        Returns (new_active, ni, nc, old_active, oi, oc, old_alpha)."""
        new_active = t >= _FX_IN_START and self._fx_new is not None
        old_active = t < _FX_OUT_DUR and self._fx_old is not None
        ni = nc = oi = oc = 0.0
        old_alpha = 255
        if new_active:
            inp = min(1.0, max(0.0, (t - _FX_IN_START) / _FX_IN_DUR))
            nc = min(1.0, (1.0 - inp) / _FX_RAMP_FRAC)
            ni = _FX_GLITCH_MAX * nc
        if old_active:
            outp = min(1.0, t / _FX_OUT_DUR)
            oc = min(1.0, outp / _FX_RAMP_FRAC)
            oi = _FX_GLITCH_MIN + (_FX_GLITCH_MAX - _FX_GLITCH_MIN) * oc
            if new_active:   # overlap → old fades out over the new
                f = min(1.0, max(0.0, (t - _FX_IN_START) /
                                 (_FX_OUT_DUR - _FX_IN_START)))
                old_alpha = int(255 * (1.0 - f ** _FX_FADE_CURVE))
        return new_active, ni, nc, old_active, oi, oc, old_alpha

    def _fx_compose(self, t):
        """Crossfade compose: NEW frame opaque underneath (glitching), OLD frame
        glitching on top fading its opacity out. Both seeded with the same
        per-frame value so their tears line up. GPU draws to the backbuffer
        (gpu_native handoff to _present); software composites onto self.screen."""
        (new_active, ni, nc,
         old_active, oi, oc, old_alpha) = self._fx_levels(t)
        rect = (0, 0, SCREEN_W, SCREEN_H)
        rr = pygame.Rect(0, 0, SCREEN_W, SCREEN_H)
        seed = self._fx_frame & 0x7fffffff
        dark = self._fx_darken_alpha(t)   # separate black overlay, on top of both
        rng_state = random.getstate()
        try:
            if self.gpu is not None:
                g = self.gpu
                overlap = new_active and old_active and old_alpha < 255
                # Offscreen FIRST (Mali: never switch away from the output once
                # we start drawing it): the fading old layer into the comp target.
                if overlap:
                    comp = self._fx_mktarget("_fx_comp")
                    g.set_target(comp)
                    g.begin(BLACK)
                    random.seed(seed)
                    self._fx_layer(self._fx_old, oi, oc)
                    g.set_target(None)
                # Output backbuffer.
                g.set_target(None)
                g.begin(BLACK)
                if new_active:
                    random.seed(seed)
                    self._fx_layer(self._fx_new, ni, nc)
                if old_active and not overlap:
                    random.seed(seed)            # only OLD (pre-overlap) — opaque
                    self._fx_layer(self._fx_old, oi, oc)
                if overlap:
                    g.blit(comp, rr, alpha=old_alpha)
                if dark > 0:                     # darken pass ON TOP of both layers
                    g.fill_rect(rect, (0, 0, 0, min(255, dark)))
                sa = self._fx_scanline_alpha(t)  # unified CRT scanline grille
                if sa > 0:
                    g.blit(g.tex_for(self._fx_scanlines()), rr, alpha=sa)
                self.gpu_native = True
                return
            # Software: NEW opaque + glitch, then OLD glitched (copy) at
            # old_alpha, then the darken overlay, then the unified scanline
            # grille — both on their own curves, on top of both layers.
            # Scanlines are suppressed per-layer (draw_scanlines=False) so the
            # single pass below is the only one.
            scan = self._fx_scanlines()
            if new_active:
                self.screen.blit(self._fx_new, (0, 0))
                if ni > 0.01:
                    random.seed(seed)
                    _apply_crt_glitch(self.screen, rect, ni,
                                      profile=_FX_CRT_PROFILE,
                                      scanline_cache=scan, draw_scanlines=False)
            if old_active:
                olay = self._fx_old.copy()
                if oi > 0.01:
                    random.seed(seed)
                    _apply_crt_glitch(olay, rect, oi,
                                      profile=_FX_CRT_PROFILE,
                                      scanline_cache=scan, draw_scanlines=False)
                olay.set_alpha(old_alpha if new_active else 255)
                self.screen.blit(olay, (0, 0))
            if dark > 0:
                ov = pygame.Surface((SCREEN_W, SCREEN_H))
                ov.fill(BLACK)
                ov.set_alpha(min(255, dark))
                self.screen.blit(ov, (0, 0))
            sa = self._fx_scanline_alpha(t)
            if sa > 0:
                scan.set_alpha(sa)
                self.screen.blit(scan, (0, 0))
        finally:
            random.setstate(rng_state)


# Tie PlayState outcome back into App transitions
_orig_play_run = PlayState.run


def _play_run(self, events, controls):
    out = _orig_play_run(self, events, controls)
    if out is None:
        return None
    # Hidden test mission: never mutate save / map graph. Restart on L3,
    # otherwise drop back to the title screen.
    if getattr(self.level, "is_test", False):
        if out == "test_restart":
            return ("play", make_test_level())
        return ("title", None)
    # Pause-and-bomb abort: the player chose to bail out. Same "run
    # didn't finish" outcome as a loss, but bypass post_play (no
    # dumnezeu decrement, no GameOverScreen) and head straight to
    # the map. The "abort" transition kind on App handles the save.
    if out == "abort":
        return ("abort", None)
    # Player chose "retry" on the win-hold banner (clear % < 100). Drop
    # straight back into a fresh PlayState for the same level — bypass
    # the post_play handler so this run's stats stay intact and the
    # adaptive-difficulty knob isn't double-bumped.
    if out == "retry":
        return ("play", self.level)
    # YOU WIN dismissed — game-fully-complete celebration is done. The
    # save was already committed inside _begin_game_won; just route to
    # the title transition.
    if out == "game_won":
        return ("game_won", None)
    # Level progress 0..1 — actual enemies killed / enemies spawned this
    # attempt. Feeds the per-level max_clear stat shown in the map
    # details overlay AND the live MISSION COMPLETE banner's CLEAR %.
    # Wins use the held value already computed at outro-end so the
    # post_play stat matches what the player just read on the banner.
    spawned = max(1, self.enemies_spawned)
    progress = max(0.0, min(1.0, self.enemies_killed / spawned))
    if out == "replay_done":
        # View-only saved replay (watched from the map) finished — back to map.
        return ("map", None)
    if out == "win_committed":
        # Win already recorded to the save at MISSION COMPLETE replay entry.
        # Skip post_play (no double wins++/unlock) and open the shop with
        # the stashed unlock celebration.
        return ("shop_win", getattr(self, "_pending_unlocks", []))
    if out == "win":
        return ("post_play", (self.score, self.level.key, True,
                              self._held_progress))
    if out == "loss":
        return ("post_play", (self.score, self.level.key, False, progress))
    return None


PlayState.run = _play_run


# Single-instance guard. The stock OS App Center on the RG35XX Pro scans
# /mnt/mmc/Roms/APPS recursively, so it picks up BOTH the outer Pewpew.sh
# entry and the inner Pewpew/launch.sh as separate launcher entries.
# Without this lock, two python instances can end up running on top of
# each other — exiting one reveals the other, which feels like the first
# exit only goes back to the title screen.
LOCK_PATH = Path(__file__).resolve().parent / ".pewpew.pid"


def _acquire_single_instance_lock():
    # The lock exists to defend against the RG App Center scanning
    # /mnt/mmc/Roms/APPS recursively and double-launching pewpew. No
    # other platform has that hazard:
    #   * Steam Deck / desktop Linux launch the game from a single
    #     shortcut (no recursive scan).
    #   * Windows has no App Center analogue.
    # Worse, on Windows `os.kill(pid, 0)` doesn't have POSIX semantics
    # — it returns success for any PID that's been used in some way,
    # including reused PIDs that belong to unrelated processes. A
    # force-close that left .pewpew.pid behind would then refuse the
    # next launch forever. Skip the lock on win32 entirely.
    if sys.platform == "win32" or EMSCRIPTEN:
        # win32: os.kill(pid, 0) lacks POSIX semantics (see above).
        # emscripten: single tab, no recursive App-Center scan, and
        # os.kill isn't meaningful under Pyodide — nothing to guard.
        return
    try:
        existing = int(LOCK_PATH.read_text().strip())
    except (FileNotFoundError, ValueError, OSError):
        existing = None
    if existing and existing != os.getpid():
        try:
            os.kill(existing, 0)
            # Another live pewpew — bail without touching pygame so the
            # foreground instance is undisturbed.
            print(f"pewpew already running (pid {existing}); exiting.")
            sys.exit(0)
        except (ProcessLookupError, OSError):
            pass  # stale lock — fall through and claim it
    try:
        LOCK_PATH.write_text(str(os.getpid()))
    except OSError:
        pass


def _release_single_instance_lock():
    if sys.platform == "win32":
        return
    try:
        if LOCK_PATH.read_text().strip() == str(os.getpid()):
            LOCK_PATH.unlink()
    except (FileNotFoundError, OSError, ValueError):
        pass


async def main():
    # No auto-update at launch. The title screen surfaces an "UPDATE
    # AVAILABLE" overlay when the active channel has anything newer
    # than the running build; the player presses ability (silk X) on
    # the title to opt in. See `_check_release_update` (force=True
    # path) for the apply side, and TitleScreen's release-notes
    # overlay for the surface.
    if BOT_CLI["bot"]:
        from tuning.bot.session import run_bot_from_cli
        run_bot_from_cli(BOT_CLI)
        return
    if BOT_CLI["replay"]:
        from tuning.bot.replay import play_replay_from_cli
        play_replay_from_cli(BOT_CLI)
        return
    _acquire_single_instance_lock()
    try:
        windowed = "--windowed" in sys.argv
        await App(windowed=windowed).run()
    finally:
        _release_single_instance_lock()


if __name__ == "__main__":
    # pygbag detects and drives `asyncio.run(main())` as the WASM entry point;
    # on the desktop it's the standard way to run an async main.
    asyncio.run(main())
